typedef struct {
    int key;
    long offset;
} record_t;

record_t* allocate_arrays(int num_records) {
    int* keys = NULL;
    long* offsets = NULL;
    record_t* records = NULL;

    // Allocate memory for arrays
    if ((keys = (int*)malloc(num_records * sizeof(int))) == NULL ||
        (offsets = (long*)malloc(num_records * sizeof(long))) == NULL) {
        free(keys);
        return NULL;  // Memory allocation failed, exit
    }

    // Initialize array values
    for (int i = 0; i < num_records; i++) {
        keys[i] = rand() % 100;
        offsets[i] = (long)i * 100 + rand() % 50;
    }

    // Allocate memory for records
    if ((records = (record_t*)malloc(num_records * sizeof(record_t))) == NULL) {
        free(keys);
        free(offsets);
        return NULL;  // Memory allocation failed, exit
    }

    for (int i = 0; i < num_records; i++) {
        records[i].key = keys[i];
        records[i].offset = offsets[i];
    }

    free(keys);
    free(offsets);

    return records;
}
