#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_SIZE 1000
#define INT_MAX_SIZE sizeof(int)

int* read_file(char* filename, int* max_size) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening file\n");
        return NULL;
    }

    int count = 0;
    int* data = (int*)malloc(MAX_SIZE * INT_MAX_SIZE);
    char buffer[INT_MAX_SIZE];

    while (!feof(file)) {
        fscanf(file, "%d", &data[count]);
        if (ferror(file) || fgetpos(file, &buffer) == -1) {
            printf("Error reading file\n");
            free(data);
            return NULL;
        }
        count++;
        if (count >= *max_size) {
            break;
        }
    }

    fclose(file);

    if (count < *max_size) {
        *max_size = count;
    } else {
        free(data);
        data = (int*)malloc(count * INT_MAX_SIZE);
        memcpy(data, &data[0], count * INT_MAX_SIZE);
    }

    return data;
}

int find_largest(int* arr, int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

int main(int argc, char** argv) {
    if (argc != 2) {
        printf("Usage: %s filename\n", argv[0]);
        return -1;
    }

    int max_size = MAX_SIZE;
    int* data = read_file(argv[1], &max_size);

    if (data == NULL) {
        return -1;
    }

    if (*max_size == 0) {
        printf("No valid integers found\n");
    } else {
        int largest = find_largest(data, *max_size);
        printf("Largest integer: %d\n", largest);
        free(data);
    }

    return 0;
}
