#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#include <fcntl.h>
#include <pthread.h>

#define LOG_MAX_SIZE 1024*1024 // 1MB
#define LOG_RETAIN_COUNT 5
#define LOG_ROTATION_POLICY ROTATION_POLICY_ROUND_ROBIN

typedef enum {
    ROTATION_POLICY_ROUND_ROBIN,
    ROTATION_POLICY_LIFO
} log_rotation_policy;

struct log_file {
    int fd;
    char *path;
    off_t size;
};

// Global variables
log_rotation_policy policy = ROTATION_POLICY_ROUND_ROBIN;
int log_count = 0;
int current_log_index = 0;
int total_size = 0;
int retain_count = LOG_RETAIN_COUNT;
struct log_file logs[LOG_RETAIN_COUNT];

// Lock for concurrent access
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void log_write(const char *buffer, size_t len) {
    pthread_mutex_lock(&lock);

    // Check if we have reached the maximum disk space usage
    if (total_size + len > 1024*1024*10) { // 10GB
        // Notify application of disk space issues
        printf("Disk full! Truncating logs.\n");

        // Rotate logs and truncate excess size
        log_rotate();
    }

    // Write to current log file
    int log_index = current_log_index % log_count;
    int fd = logs[log_index].fd;
    off_t pos = lseek(fd, 0, SEEK_END);
    write(fd, buffer, len);
    total_size += len;

    pthread_mutex_unlock(&lock);
}

void log_rotate() {
    pthread_mutex_lock(&lock);

    // Close current log file
    int fd = logs[current_log_index].fd;
    close(fd);
    total_size -= LOG_MAX_SIZE; // account for rotation

    // Update current log index and retain count
    current_log_index = (current_log_index + 1) % log_count;
    if (--retain_count == 0) {
        // Rotate log files, overwriting oldest one
        if (++log_count > LOG_RETAIN_COUNT)
            log_count = LOG_RETAIN_COUNT;
        current_log_index = 0;
    }

    pthread_mutex_unlock(&lock);
}

int main() {
    // Initialize logs array
    for (int i = 0; i < retain_count; i++) {
        char path[256];
        sprintf(path, "log_%d.log", i);
        int fd = open(path, O_RDWR | O_CREAT, 0644);
        if (fd == -1) {
            perror("open");
            return 1;
        }
        logs[i].fd = fd;
        logs[i].path = path;
        logs[i].size = 0;
    }

    // Start writing log messages
    for (int i = 0; i < 10; i++) {
        char buffer[1024];
        sprintf(buffer, "Log message %d\n", i);
        log_write(buffer, strlen(buffer));
    }

    return 0;
}
