typedef struct {
    int algorithm;
    char* key;
} compression_config_t;

void* compress_data(void* data, size_t size, void* config) {
    compression_config_t* conf = (compression_config_t*)config;
    if (conf->algorithm == GZIP_ALGORITHM) {
        return gzip_compress(data, size);
    } else if (conf->algorithm == ZLIB_ALGORITHM) {
        return zlib_compress(data, size);
    } else if (conf->algorithm == BZIP2_ALGORITHM) {
        return bzip2_compress(data, size);
    }
    return NULL;
}

void* encrypt_data(void* data, size_t size, void* config) {
    compression_config_t* conf = (compression_config_t*)config;
    char* key = get_key(conf->key);
    if (key == NULL) {
        // Fallback to default key
        key = default_key();
    }
    return encrypt(data, size, key);
}

int main() {
    void* data = malloc(1024 * 1024);
    size_t size = 1024 * 1024;
    compression_config_t conf = {BZIP2_ALGORITHM, "my_key"};
    void* compressed_data = compress_data(data, size, &conf);
    void* encrypted_data = encrypt_data(compressed_data, size, &conf);
    free(data);
    free(compressed_data);
    return 0;
}
