import yaml
import subprocess
import os
import re
import socket
import requests
from threading import Thread
from queue import Queue

class NetworkConfigurator:
    def __init__(self, yaml_file):
        self.yaml_file = yaml_file
        self.config = None
        self.dns_servers = {}
        self.subnet_api_url = "https://api-subnet-details.com/latest"

    def load_config(self):
        with open(self.yaml_file, 'r') as f:
            self.config = yaml.safe_load(f)

    def validate_config(self):
        # Validate network settings
        if not self.config['interfaces']:
            raise ValueError("No interfaces defined in YAML file")

    def configure_interfaces(self):
        for interface in self.config['interfaces']:
            # Get IP address range and assign unique IPs
            ip_range = socket.inet_ntoa(socket.inet_aton(interface['ip_range']))
            available_ips = []
            for i in range(1, 256):
                available_ips.append(f"{ip_range}.{i}")

            for device in interface['devices']:
                if 'dns' in device and 'env' in device:
                    self.dns_servers[device['env']] = device['dns']

                # Check availability of IP address
                ip = None
                while True:
                    ip = available_ips.pop(0)
                    try:
                        subprocess.run(f"ip addr add {ip}/24 dev {device['name']}", shell=True, check=True)
                        break
                    except subprocess.CalledProcessError as e:
                        if e.returncode == 1:  # interface not found
                            continue
                        else:
                            raise

                # Set DNS servers (conditional)
                if device['env'] in self.dns_servers:
                    subprocess.run(f"ip link set dev {device['name']} dns {self.dns_servers[device['env']]}", shell=True, check=True)

    def monitor_config(self):
        while True:
            # Monitor network configuration
            output = subprocess.check_output(['ip', 'addr'], universal_newlines=True)
            expected_output = self.generate_expected_output()
            if output != expected_output:
                print(f"Configuration discrepancy detected: {output} vs {expected_output}")
                try:
                    subprocess.run('ip addr flush', shell=True, check=False)
                    time.sleep(1)  # wait for changes to propagate
                except subprocess.CalledProcessError as e:
                    raise

    def generate_expected_output(self):
        expected_output = ""
        for interface in self.config['interfaces']:
            for device in interface['devices']:
                expected_output += f"inet {device['ip']}/24 brd {device['ip'].split('.')[3]}' scope link\n"
        return expected_output

def main():
    configurator = NetworkConfigurator('config.yaml')
    configurator.load_config()
    configurator.validate_config()
    configurator.configure_interfaces()

    # Start monitoring thread
    monitor_thread = Thread(target=configurator.monitor_config)
    monitor_thread.daemon = True  # Exit when script finishes
    monitor_thread.start()

if __name__ == "__main__":
    main()
