#define ALGO_MAX 256
#define PARAM_MAX 1024

typedef struct {
    char *name;
    void (*func)(void*, size_t, ...);
    void *params;
    size_t param_size;
} algo_t;

typedef struct node {
    algo_t algo;
    struct node* next;
} algo_node;

typedef struct {
    algo_node* head;
    pthread_mutex_t lock;
} algo_list;

algo_list* algo_init() {
    algo_list* list = (algo_list*)malloc(sizeof(algo_list));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void algo_insert(algo_list* list, algo_t algo) {
    algo_node* new_node = (algo_node*)malloc(sizeof(algo_node));
    new_node->algo = algo;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_lock(&list->lock);
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

void* algo_load_from_config(void* config) {
    // Load algorithms from configuration file
    algo_list* list = algo_init();
    char line[256], param[PARAM_MAX];
    FILE *fp = fopen(config, "r");
    while (fgets(line, sizeof(line), fp)) {
        if (strlen(line) > 2 && line[0] == '#') continue;
        char *param_start = strstr(line, ":");
        algo_t algo = {NULL, NULL, NULL, 0};
        if (param_start) {
            param_start++;
