#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define the structure for semaphore management
typedef struct {
    int value;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} Semaphore;

// Function to create a new semaphore with an initial value and unique ID
Semaphore* sem_create(int init_value, int id) {
    Semaphore* sem = (Semaphore*)malloc(sizeof(Semaphore));
    sem->value = init_value;
    pthread_mutex_init(&sem->lock, NULL);
    pthread_cond_init(&sem->cond, NULL);

    // Assign a unique ID to the semaphore
    sem->id = id;

    return sem;
}

// Function to delete a semaphore
void sem_delete(Semaphore* sem) {
    pthread_mutex_destroy(&sem->lock);
    pthread_cond_destroy(&sem->cond);
    free(sem);
}

// Function to modify the value of a semaphore
void sem_modify(Semaphore* sem, int new_value) {
    // Lock the semaphore for modification
    pthread_mutex_lock(&sem->lock);

    // Modify the value of the semaphore
    sem->value = new_value;

    // Unlock the semaphore
    pthread_mutex_unlock(&sem->lock);
}

// Function to wait for a semaphore with a timeout
void sem_wait(Semaphore* sem, int timeout) {
    // Lock the semaphore for waiting
    pthread_mutex_lock(&sem->lock);

    while (sem->value == 0) {
        if (pthread_cond_timedwait(&sem->cond, &sem->lock, &timeout) != 0) {
            printf("Semaphore timed out!\n");
            return;
        }
    }

    // Unlock the semaphore
    pthread_mutex_unlock(&sem->lock);
}

// Function to signal a semaphore
void sem_signal(Semaphore* sem) {
    // Lock the semaphore for signaling
    pthread_mutex_lock(&sem->lock);

    // Increment the value of the semaphore
    sem->value++;

    // Signal the condition variable
    pthread_cond_signal(&sem->cond);

    // Unlock the semaphore
    pthread_mutex_unlock(&sem->lock);
}

// Function to destroy a semaphore
void sem_destroy(Semaphore* sem) {
    if (pthread_mutex_destroy(&sem->lock) != 0) {
        printf("Mutex destruction failed!\n");
    }

    if (pthread_cond_destroy(&sem->cond) != 0) {
        printf("Condition variable destruction failed!\n");
    }

    free(sem);
}

int main() {
    // Example usage:
    Semaphore* sem = sem_create(0, 1); // Create a new semaphore with an initial value of 0 and unique ID 1
    sem_modify(sem, 5); // Modify the value to 5

    pthread_t thread;
    pthread_create(&thread, NULL, (void*)sem_wait, sem);
    pthread_join(thread);

    sem_destroy(sem);

    return 0;
}
