void updateOrInsert(std::vector<int>& data, int target, int replacement, bool& insertPosition) {
    auto it = std::lower_bound(data.begin(), data.end(), target);
    if (*it == target) {
        *it = replacement;
        insertPosition = false;
    } else {
        data.insert(it, replacement);
        insertPosition = static_cast<int>(it - data.begin());
    }
}
