public class DatabaseQueryExecutor
{
    public async Task<DataTable> ExecuteQuery(DatabaseConfiguration config)
    {
        DataTable result = new DataTable();

        using (var connection = GetConnection(config))
        {
            string query = BuildQuery(config);

            try
            {
                if (config.Transactional)
                {
                    await connection.OpenAsync();
                    connection.BeginTransaction();
                }

                using (var command = new SqlCommand(query, connection))
                {
                    foreach (var parameter in config.Parameters)
                    {
                        command.Parameters.AddWithValue(parameter.Name, parameter.Value);
                    }

                    using (var reader = command.ExecuteReader())
                    {
                        result.Load(reader);
                    }
                }

                if (config.Transactional)
                {
                    connection.CommitTransaction();
                }
            }
            catch (Exception ex)
            {
                await HandleError(config, query, ex);
            }
        }

        return result;
    }

    private IDbConnection GetConnection(DatabaseConfiguration config)
    {
        switch (config.DatabaseType)
        {
            case DatabaseType.SqlServer:
                return new SqlConnection("Data Source=" + config.SqlConnectionString);
            case DatabaseType.PostgreSQL:
                return new NpgsqlConnection("Host=" + config.PostgreSqlConnectionString + ";Username=" + config.PostgreSqlUsername + ";Password=" + config.PostgreSqlPassword + ";Database=" + config.PostgreSqlDatabaseName);
            case DatabaseType.MySQL:
                return new MySqlConnection("server=" + config.MySqlConnectionString + ";user=" + config.MySqlUsername + ";password=" + config.MySqlPassword + ";database=" + config.MySqlDatabaseName);
        }
    }

    private string BuildQuery(DatabaseConfiguration config)
    {
        // construct query based on configuration
        // using parameterized queries for performance and security
    }

    private async Task HandleError(DatabaseConfiguration config, string query, Exception ex)
    {
        // log error details
        await WriteToLogAsync(config, query, ex);

        if (config.Transactional)
        {
            try
            {
                // rollback transaction on error
                using (var connection = GetConnection(config))
                {
                    connection.Open();
                    connection.RollbackTransaction();
                }
            }
            catch
            {
                // ignore any exceptions during rollback
            }
        }
    }

    private async Task WriteToLogAsync(DatabaseConfiguration config, string query, Exception ex)
    {
        // write error details to log file or database
    }
}

