public class Program
{
    public static string FindAndCreateDirWithXPath(string filePath, string xPathExpression, string envVarName, string baseDirPath)
    {
        XmlDocument xmlDoc = new XmlDocument();
        try
        {
            xmlDoc.Load(filePath);
            XmlElement root = xmlDoc.DocumentElement;
            XmlNodeList nodes = root.SelectNodes(xPathExpression);

            if (nodes.Count > 1)
            {
                Console.WriteLine("Warning: More than one element found. Returning null.");
                return null;
            }
            else if (nodes.Count == 0)
            {
                Console.WriteLine("Information: No elements found. Returning null.");
                return null;
            }

            string dirName = nodes[0].InnerText;
            string dirPath = Path.Combine(baseDirPath, dirName);

            try
            {
                Directory.CreateDirectory(dirPath);
            }
            catch (Exception ex)
            {
                Console.WriteLine("Error: Unable to create directory. " + ex.Message);
                return null;
            }

            SetEnvironmentVariable(envVarName, dirPath);
        }
        catch (XmlException ex)
        {
            Console.WriteLine("Error: Invalid XML file. " + ex.Message);
            return null;
        }
        catch (IOException ex)
        {
            Console.WriteLine("Error: Unable to load or parse XML file. " + ex.Message);
            return null;
        }

        return dirPath;
    }

    private static void SetEnvironmentVariable(string envVarName, string value)
    {
        try
        {
            Environment.SetEnvironmentVariable(envVarName, value);
        }
        catch (Exception ex)
        {
            Console.WriteLine("Error: Unable to set environment variable. " + ex.Message);
        }
    }
}
