    public StateLoader(String configPath) throws IOException {
        stateCache = new HashMap<>();
        File configFile = new File(configPath);
        if (!configFile.exists()) {
            throw new FileNotFoundException("Configuration file not found at: " + configPath);
        }
        // Initialize default theme directory
        String themeDir = getConfigValueOrDefault(configFile, DEFAULT_THEME_DIR);
        File themeCacheDir = new File(themeDir);
        if (!themeCacheDir.exists() && !themeCacheDir.mkdirs()) {
            throw new IOException("Failed to create default theme cache directory: " + themeDir);
        }
