    public State loadState(String filePath) throws IOException {
        State state = null;
        try (FileInputStream fis = new FileInputStream(filePath)) {
            ObjectInputStream ois = new ObjectInputStream(fis);
            state = (State) ois.readObject();
            stateCache.put(filePath, state);
        } catch (IOException e) {
            // Log or handle the exception as needed
            System.out.println("Failed to load state from file: " + filePath);
        }
        return state;
    }

    private String getConfigValueOrDefault(File configFile, String defaultValue) throws IOException {
        try (BufferedReader reader = new BufferedReader(new FileReader(configFile))) {
