["```javascript
async function readFiles(dir, extension) {
  try {
    const files = await fs.promises.readdir(dir);
    let concatenatedContent = '';
    for (const file of files) {
      if (!file.includes('.')) continue;
      const filePath = path.join(dir, file);
      try {
        if (!await fs.promises.lstat(filePath).isDirectory()) {
          const fileContent = await fs.promises.readFile(filePath, 'utf8');
          if (path.extname(file) === '.' + extension) {
            concatenatedContent += fileContent;
          }
        } else {
          const filesInDir = await readFiles(filePath, extension);
          for (const f of filesInDir) {
            const fileContent = await fs.promises.readFile(path.join(filePath, f), 'utf8');
            if (path.extname(f) === '.' + extension) {
              concatenatedContent += fileContent;
            }
          }
        }
      } catch (err) {
        console.error(`Error reading file ${filePath}: ${err}`);
      }
    }
    return concatenatedContent;
  } catch (err) {
    console.error(`Error reading directory ${dir}: ${err}`);
  }
}
