function runTests(suiteLabel, modulePath, testCases, dependencies, config, environment) {
  const { testRunner } = require('testrunner');
  const { logger } = require('logger');
  const { aggregator } = require('aggregator');

  // Dynamic resolution of module paths and dependencies
  const resolvedDependencies = resolveDependencies(dependencies);
  const resolvedModulePath = resolveModulePath(modulePath, dependencies);

  // Set up the test environment
  const testEnvironment = setupTestEnvironment(resolvedModulePath, environment);

  // Log execution metrics
  const loggerConfig = {
    logLevel: 'debug',
    output: process.stdout,
  };
  const executionLogger = logger(loggerConfig);
  executionLogger.info(`Starting test suite ${suiteLabel}...`);

  try {
    // Run the tests in parallel using a thread pool
    const testPool = new WorkerPool({
      numWorkers: config.numWorkers,
      workerTimeout: config.workerTimeout,
    });
    const testResults = await Promise.all(
      testCases.map((testCase) => runTestCase(testPool, testCase, resolvedModulePath, environment))
    );

    // Aggregate and log the test results
    const aggregatedResults = aggregator(aggregator.config).aggregate(testResults);
    executionLogger.info(`Test suite ${suiteLabel} completed. Results: ${aggregatedResults}`);

  } catch (error) {
    // Handle unexpected errors gracefully
    executionLogger.error(`Error running test suite ${suiteLabel}: ${error}`);
  } finally {
    // Clean up the test environment
    teardownTestEnvironment(testEnvironment);
  }

  return aggregatedResults;
}

