function constructFooter(scripts) {
  const footer = '<footer>';
  let asyncScripts = [];
  let deferScripts = [];

  for (const script of scripts) {
    if (script.defer) {
      deferScripts.push(script);
    } else if (script.async) {
      asyncScripts.push(script);
    }
  }

  footer += '<div>';

  // Render additional content
  if (scripts[0].content) {
    footer += scripts[0].content;
  }

  for (const script of deferScripts) {
    footer += `<script ${script.charset ? ` charset="${script.charset}"` : ''} defer>${script.src}</script>`;
  }

  for (const script of asyncScripts) {
    footer += `<script ${script.charset ? ` charset="${script.charset}"` : ''} async>${script.src}</script>`;
  }

  // Render other scripts
  for (const script of scripts) {
    if (!script.defer && !script.async) {
      footer += `<script ${script.charset ? ` charset="${script.charset}"` : ''}>${script.src}</script>`;
    }
  }

  footer += '</div></footer>';

  return footer;
}
