void insertStringAfter(const std::string& searchFor, const std::string& insertThis, std::forward_list<std::string>& list) {
  auto it = list.begin();
  while (it != list.end()) {
    if (*it == searchFor) {
      list.insert_after(it, insertThis);
      return;
    }
    ++it;
  }
  list.push_back(insertThis);
}
