    private static final int DEFAULT_SERVICE_DELAY = 1000; // milliseconds
    private static final int MAX_SERVICE_INSTANCES = 5;

    private Map<String, Service> services = new HashMap<>();
    private ScheduledExecutorService scheduler;

    public ServiceManagementFramework() {
        scheduler = Executors.newScheduledThreadPool(MAX_SERVICE_INSTANCES);
    }

    public void startService(String serviceName) {
        Service service = services.get(serviceName);
        if (service == null) {
            // handle error: service not found
        }
        scheduler.schedule(() -> executeService(service), DEFAULT_SERVICE_DELAY, TimeUnit.MILLISECONDS);
    }

    public void stopService(String serviceName) {
        Service service = services.get(serviceName);
        if (service != null) {
            scheduler.shutdownNow();
            notifyExternalMessagingSystem("STOP", serviceName);
        }
    }

    public void pauseService(String serviceName) {
        Service service = services.get(serviceName);
        if (service != null) {
            scheduler.shutdownNow();
            notifyExternalMessagingSystem("PAUSE", serviceName);
        }
    }

    public void resumeService(String serviceName) {
        Service service = services.get(serviceName);
        if (service != null) {
            scheduler.schedule(() -> executeService(service), DEFAULT_SERVICE_DELAY, TimeUnit.MILLISECONDS);
            notifyExternalMessagingSystem("RESUME", serviceName);
