function asyncMergeBuffers(...buffers) {
  const mergedBuffer = [];
  let outstandingBytes = 0;
  let outstandingCallbacks = 0;

  function drain() {
    while (outstandingBytes > 0 || outstandingCallbacks > 0) {
      for (const buffer of buffers) {
        if (!buffer.closed) {
          const chunk = buffer.getChunk();
          if (chunk) {
            mergedBuffer.push(chunk);
            outstandingBytes -= chunk.length;
            outstandingCallbacks--;
          }
        } else {
          break;
        }
      }
    }
  }

  function backpressure() {
    for (const buffer of buffers) {
      if (!buffer.closed && buffer.outstandingBytes + outstandingBytes >= 1024 * 1024) { // adjust this value based on your system's memory constraints
        buffer.pause();
      } else if (buffer.paused) {
        buffer.resume();
      }
    }
  }

  function drainLoop() {
    while (true) {
      try {
        drain();
        backpressure();
      } catch (e) {
        console.error(e);
        for (const buffer of buffers) {
          buffer.close();
        }
        throw e;
      }
      setTimeout(() => {
        drainLoop();
      }, 10); // adjust this value based on your system's processing speed and latency requirements
    }
  }

  function addBuffer(buffer) {
    if (!buffer.getChunk()) {
      buffer.close();
      return false;
    }
    outstandingBytes += buffer.outstandingBytes + buffer.length;
    outstandingCallbacks++;
    drain();
    return true;
  }

  function closeAll() {
    for (const buffer of buffers) {
      buffer.close();
    }
  }

  // Example usage:
  const buffers = [];
  for (let i = 0; i < 5; i++) {
    buffers.push(new Buffer(`Buffer ${i}`));
  }
  asyncMergeBuffers(...buffers);
  closeAll();

  // Integrate the function into an existing pipeline:
  const pipeline = [];
  const processPipeline = () => {
    for (const buffer of buffers) {
      if (!buffer.closed) {
        const chunk = buffer.getChunk();
        if (chunk) {
          pipeline.push(chunk);
        }
      } else {
        break;
      }
    }
  };

  setImmediate(() => {
    while (true) {
      try {
        processPipeline();
      } catch (e) {
        console.error(e);
        closeAll();
        throw e;
      }
      setTimeout(() => {
        processPipeline();
      }, 10); // adjust this value based on your system's processing speed and latency requirements
    }
  });
