function traverseDOM(selector, callback) {
  return new Promise((resolve, reject) => {
    const elements = document.querySelectorAll(selector);
    if (!elements.length) return resolve([]);

    function recursiveTraversal(element) {
      if (element.hasAttribute('data-async')) {
        fetchAsyncData(element.getAttribute('data-url'))
          .then(data => callback(element, data))
          .catch(error => reject(error));
      } else {
        callback(element);
      }

      Array.from(element.children).forEach(recursiveTraversal);
    }

    elements.forEach(recursiveTraversal);

    function fetchAsyncData(url) {
      return new Promise((resolve, reject) => {
        fetch(url)
          .then(response => response.json())
          .then(data => resolve(data))
          .catch(error => reject(error));
      });
    }
  });
}
