import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;

public class SessionAnalyzer {

    private static final int TIME_WINDOW = 5 * 60 * 1000; // 5 minutes in milliseconds
    private static final String METRICS_FILE = "metrics.txt";

    public Map<String, Long> analyzeSessions(String logFile) throws IOException {
        Map<String, Long> actionSequences = new HashMap<>();
        long lastProcessedTime = System.currentTimeMillis();
        int totalActions = 0;

        try (BufferedReader reader = new BufferedReader(new FileReader(logFile))) {
            String line;
            while ((line = reader.readLine()) != null) {
                long currentTime = System.currentTimeMillis();
                if (currentTime - lastProcessedTime >= TIME_WINDOW) {
                    logMetrics(lastProcessedTime, actionSequences);
                    actionSequences.clear();
                    totalActions = 0;
                    lastProcessedTime = currentTime;
                }
                String[] eventParts = line.split(" ");
                int actionIndex = Arrays.asList(eventParts).indexOf("action");
                if (actionIndex != -1) {
                    String action = new String(eventParts, actionIndex + 1);
                    if (!actionSequences.containsKey(action)) {
                        actionSequences.put(action, (long) 1);
                    } else {
                        actionSequences.put(action, actionSequences.get(action) + 1);
                    }
                    totalActions++;
                }
            }
            logMetrics(lastProcessedTime, actionSequences);
        }

        return actionSequences;
    }

    private void logMetrics(long lastProcessedTime, Map<String, Long> actionSequences) {
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(METRICS_FILE, true))) {
            writer.write(String.format("Processing time: %d ms, Action sequences: %d, Total actions: %d%n", 
                    System.currentTimeMillis() - lastProcessedTime, actionSequences.size(), totalActions));
        } catch (IOException e) {
            // handle fault-tolerant mechanism
        }
    }
}
