import requests
import json
from datetime import datetime, timedelta
from concurrent.futures import ThreadPoolExecutor, as_completed
from cachetools import TTLCache
import logging

API_KEY = 'your_api_key_here'
API_CACHE_TTL = 60 * 5  # 5 minutes cache time
MAX_RETRIES = 3
RETRY_BACKOFF_FACTOR = 2

def fetch_weather_data(cities, start_date, end_date, api_key=API_KEY):
    cache = TTLCache(maxsize=len(cities), ttl=API_CACHE_TTL)

    def get_forecasted_data(city, start_date, end_date):
        url = f'https://api.openweathermap.org/data/2.5/forecast?q={city}&units=metric'
        if api_key:
            url += f'&appid={api_key}'
        try:
            response = requests.get(url)
            response.raise_for_status()
            forecasted_data = json.loads(response.content)
            return {f'{i}': {'temperature': data['main']['temp'], 'humidity': data['main']['humidity']} for i, data in enumerate(forecasted_data['list'])}
        except (requests.RequestException, json.JSONDecodeError) as e:
            logging.error(f'Failed to fetch forecasted data for {city}: {e}')
            return {}

    def get_current_weather(city):
        url = f'https://api.openweathermap.org/data/2.5/weather?q={city}&units=metric'
        if api_key:
            url += f'&appid={api_key}'
        try:
            response = requests.get(url)
            response.raise_for_status()
            current_data = json.loads(response.content)
            return {'current_temperature': current_data['main']['temp'], 'humidity': current_data['main']['humidity']}
        except (requests.RequestException, json.JSONDecodeError) as e:
            logging.error(f'Failed to fetch current weather data for {city}: {e}')
            return {}

    def fetch_weather_data_for_city(city):
        if city in cache:
            data = cache.get(city)
        else:
            try:
                forecasted_data = get_forecasted_data(city, start_date, end_date)
                current_data = get_current_weather(city)
                data = {**forecasted_data, **current_data}
                for retry in range(MAX_RETRIES):
                    if not all(data.values()):
                        raise Exception(f'Failed to fetch weather data for {city}')
                    break
            except Exception as e:
                logging.error(f'Failed to fetch weather data for {city}: {e}')
                return {}
        return data

    executor = ThreadPoolExecutor(max_workers=len(cities))
    futures = {executor.submit(fetch_weather_data_for_city, city): city for city in cities}

    results = []
    for future in as_completed(futures):
        city = futures[future]
        try:
            data = future.result()
        except Exception as e:
            logging.error(f'Failed to fetch weather data for {city}: {e}')
            continue
        if not data:
            logging.warning(f'No weather data found for {city}')
            continue
        results.append({city: data})

    return {**{city: data[0] for city, data in zip(cities, [result.get(city) for result in results])}}
