const fs = require('fs');
const crypto = require('crypto');

function asyncOperationHandler(operationName) {
  return new Promise((resolve, reject) => {
    try {
      resolve();
    } catch (error) {
      reject(error);
    }
  });
}

function generateRandomString(length, charSet) {
  return asyncOperationHandler('Generate Random String')
    .then(() => crypto.randomBytes(Math.ceil(length / 2)).toString(charSet))
    .catch((error) => {
      console.error(`Error generating random string: ${error}`);
      throw error;
    });
}

function hashPassword(password, algorithm) {
  return asyncOperationHandler('Hash Password')
    .then(() => crypto.createHmac(algorithm, password).digest())
    .catch((error) => {
      console.error(`Error hashing password: ${error}`);
      throw error;
    });
}

function readFileSync(filePath) {
  return asyncOperationHandler('Read File')
    .then(() => fs.readFileSync(filePath, 'utf8'))
    .catch((error) => {
      console.error(`Error reading file: ${error}`);
      throw error;
    });
}

async function integrateOperations(randomStringLength, password, algorithm, filePath) {
  try {
    const randomString = await generateRandomString(randomStringLength, 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789');
    const hashedPassword = await hashPassword(password, algorithm);
    const fileContent = await readFileSync(filePath);

    return { randomString, hashedPassword: hashedPassword.toString('hex'), fileContent };
  } catch (error) {
    console.error(`Error integrating operations: ${error}`);
    throw error;
  }
}

module.exports = integrateOperations;
