function fetchAndCombineCertificates(request) {
  const { privateKeyName, certificateName } = request;

  async function retrieveCertificate(name) {
    try {
      const response = await fetch(`https://example.com/certificates/${name}`);
      return response.text();
    } catch (error) {
      if (error.name === 'TimeoutError') {
        // Retry with exponential backoff
        setTimeout(() => {
          try {
            return retrieveCertificate(name);
          } catch (error) {
            throw error;
          }
        }, Math.min(2000, Math.pow(2, Math.floor(Math.random() * 3))));
      } else {
        throw error;
      }
    }
  }

  async function retrievePrivateKey(name) {
    try {
      const response = await fetch(`https://example.com/private-keys/${name}`);
      return response.text();
    } catch (error) {
      if (error.name === 'TimeoutError') {
        // Retry with exponential backoff
        setTimeout(() => {
          try {
            return retrievePrivateKey(name);
          } catch (error) {
            throw error;
          }
        }, Math.min(2000, Math.pow(2, Math.floor(Math.random() * 3))));
      } else {
        throw error;
      }
    }
  }

  async function combineCertificates(privateKey, certificate) {
    try {
      const combined = `${privateKey}\n${certificate}`;
      return combined;
    } catch (error) {
      throw error;
    }
  }

  try {
    const privateKey = await retrievePrivateKey(privateKeyName);
    const certificate = await retrieveCertificate(certificateName);
    const combined = await combineCertificates(privateKey, certificate);
    return combined;
  } catch (error) {
    if (error.name === 'ErrorFetchingData') {
      // Use cached or previously stored credentials
      console.log('Using fallback credentials');
      return null;
    } else {
      throw error;
    }
  }
}

// Example usage:
