from typing import Dict

def process_config_file(config_dir: str, config_dict: Dict) -> tuple:
    def custom_sort(line: str) -> int:
        return sum(c < key for c, key in zip(line, config_dict))

    @lru_cache(maxsize=None)
    def read_file(file_name: str) -> list:
        try:
            with open(os.path.join(config_dir, file_name), 'r') as file:
                lines = [line.strip() for line in file.readlines()]
                return sorted(lines, key=custom_sort)
        except (FileNotFoundError, PermissionError):
            return []

    @lru_cache(maxsize=None)
    def extract_sequence_number(file_lines: list) -> int:
        pattern = re.compile(r'\((\d+)\)')
        last_line = file_lines[-1]
        match = pattern.search(last_line)
        if match:
            return int(match.group(1))
        else:
            return -1

    @lru_cache(maxsize=None)
    def detect_changes(file_name: str) -> bool:
        try:
            with open(os.path.join(config_dir, file_name), 'r') as file:
                last_line = file.readlines()[-1].strip()
                if not re.match(r'^#', last_line):
                    return True
        except FileNotFoundError:
            pass
        return False

    def process_file(file_lines: list) -> None:
        try:
            sequence_number = extract_sequence_number(file_lines)
            print(f'Processing file with sequence number {sequence_number}')
        except Exception as e:
            print(f'Error processing file: {e}')

    def update_loop() -> None:
        while True:
            for file in os.listdir(config_dir):
                if detect_changes(file):
                    with ThreadPoolExecutor(max_workers=5) as executor:
                        executor.submit(process_file, read_file(file))
            time.sleep(1)

    try:
        update_loop()
    except KeyboardInterrupt:
        print('Stopping the configuration processing service')
    except Exception as e:
        print(f'Error: {e}')
