#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for a state in the FSA
typedef struct State {
    int id;
    pthread_mutex_t lock;
} State;

// Define the structure for the linked list of states
typedef struct LinkedList {
    State* head;
    State* tail;
    pthread_mutex_t lock;
} LinkedList;

// Function to create a new state and add it to the end of the list
LinkedList* createStateList(int numStates, int lastStateId) {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL; // No memory available

    list->head = (State*)malloc(numStates * sizeof(State));
    if (!list->head) return NULL; // No memory available

    list->tail = &list->head[0];
    for (int i = 1; i < numStates; i++) {
        list->tail->next = &list->head[i];
        list->tail++;
    }

    return list;
}

// Function to insert a new state at the end of the list
void insertState(LinkedList* list, int newStateId) {
    State* newState = (State*)malloc(sizeof(State));
    if (!newState) return; // No memory available

    newState->id = newStateId;

    pthread_mutex_lock(&list->lock);
    list->tail->next = newState;
    list->tail++;
    pthread_mutex_unlock(&list->lock);
}

// Function to remove the last state from the list
void removeState(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    if (list->head == list->tail) {
        free(list->head);
        free(list);
    } else {
        list->tail--;
        free(list->tail->next);
        list->tail->next = NULL;
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to serialize the state list to a binary format
int serializeStateList(LinkedList* list, FILE* file) {
    fwrite(&list->head, sizeof(State), (list->tail - list->head + 1), file);
    return 0;
}

// Function to deserialize the state list from a binary format
int deserializeStateList(LinkedList** list, FILE* file) {
    int numStates = 0;
    fread(&numStates, sizeof(int), 1, file);
    *list = (LinkedList*)malloc(sizeof(LinkedList));
    (*list)->head = (State*)malloc(numStates * sizeof(State));
    fread(&((*list)->head), sizeof(State), numStates, file);
    return 0;
}
