std::unique_ptr<OctreeNode> initializeOctree(int maxLeafNodes) {
    int depth = 0;
    while ((1 << depth) < maxLeafNodes) {
        depth++;
    }

    std::unique_ptr<OctreeNode> root(new OctreeNode());
    std::vector<std::shared_ptr<OctreeNode>> leafNodes(maxLeafNodes);

    for (int i = 0; i < maxLeafNodes; i++) {
        leafNodes[i] = std::make_shared<OctreeNode>();
        // Initialize the node from your external data source here
    }

    int currDepth = 1;
    OctreeNode* currNode = root.get();
    for (int i = 0; i < maxLeafNodes; i++) {
        if ((i & (currDepth - 1)) == 0) {
            currNode->children.push_back(std::make_shared<OctreeNode>());
            currNode = currNode->children.back().get();
        } else if ((i & (currDepth - 1)) == (currDepth - 1)) {
            while (currNode->parent != nullptr && (i & (currDepth - 1)) == (currDepth - 1)) {
                currDepth--;
                currNode = currNode->parent.get();
            }
            if (currNode->parent != nullptr) {
                currNode = currNode->parent.get();
            } else {
                break;
            }
        } else {
            while ((i & (currDepth - 1)) > 0) {
                currDepth--;
                currNode = currNode->children.back().get();
            }
            if (currNode->parent != nullptr) {
                currNode = currNode->parent.get();
            } else {
                break;
            }
        }
    }

    return std::move(root);
