std::mutex mtx;
std::condition_variable cv;
int attackHistory = 0;
bool firstAttackUsed = false;

void selectAttack() {
    std::unique_lock<std::mutex> lock(mtx);

    // Randomly choose an attack
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(1, 3);
    int attackNumber = dis(gen);

    while (attackHistory >= 9 && attackNumber == 1) {
        lock.unlock();
        cv.wait_for(std::this_thread::sleep_for(std::chrono::seconds(9)), cv.now());
        lock.lock();
    }

    while (attackHistory >= 15 && attackNumber == 2) {
        lock.unlock();
        cv.wait_for(std::this_thread::sleep_for(std::chrono::seconds(15)), cv.now());
        lock.lock();
    }

    while (attackHistory >= 25 && attackNumber == 3) {
        lock.unlock();
        cv.wait_for(std::this_thread::sleep_for(std::chrono::seconds(25)), cv.now());
        lock.lock();
    }

    if (!firstAttackUsed && attackNumber != 1) {
        firstAttackUsed = true;
    } else {
        std::cout << "Selected Attack: " << attackNumber << std::endl;
        attackHistory = 0;
    }
}
