using System;
using System.Threading;
using System.Threading.Tasks;

public class DynamicValueGenerator
{
    private Random _random = new Random();
    private double _min;
    private double _max;
    private int _seed;

    public DynamicValueGenerator(int seed = 0)
    {
        _seed = seed;
        ResetRange();
    }

    public void SetRange(double min, double max)
    {
        if (double.IsNaN(min) || double.IsNaN(max))
            throw new ArgumentException("Minimum and maximum values cannot be NaN");

        if (min > max)
            throw new ArgumentException("Maximum value must be greater than or equal to minimum value");

        _min = Math.Min(min, max);
        _max = Math.Max(min, max);
    }

    public void ResetRange()
    {
        _seed = 0;
        SetRange(-1000000.0, 1000000.0);
    }

    public async Task<int> GenerateIntAsync(int count)
    {
        await Task.WhenAll(Enumerable.Range(1, count).Select(_ => GenerateInt()));
        return 0; // placeholder for generated values
    }

    public int GenerateInt()
    {
        return _random.Next((int)_min, (int)_max + 1);
    }

    public async Task<double> GenerateDoubleAsync(int count)
    {
        await Task.WhenAll(Enumerable.Range(1, count).Select(_ => GenerateDouble()));
        return 0.0; // placeholder for generated values
    }

    public double GenerateDouble()
    {
        return _random.NextDouble() * (_max - _min) + _min;
    }

    public async Task<RangeValue[]> GenerateBatchAsync(int count)
    {
        var result = new RangeValue[count];
        await Task.WhenAll(Enumerable.Range(1, count).Select(_ => GenerateRangeValue()));
        return result;
    }

    public RangeValue GenerateRangeValue()
    {
        if (_min > _max) throw new InvalidOperationException("Invalid range");
        double value = _random.NextDouble() * (_max - _min) + _min;
        return new RangeValue(value, _min, _max);
    }

    public override string ToString()
    {
        return $"Range: [{_min}, {_max}]";
    }
}

public class RangeValue
{
    public double Value { get; set; }
    public double Min { get; set; }
    public double Max { get; set; }

    public RangeValue(double value, double min, double max)
    {
        Value = value;
        Min = min;
        Max = max;
    }
}
