class Aggregator {
  constructor(reductionFunctions = [], initialValues = []) {
    this.reductionFunctions = reductionFunctions;
    this.initialValues = initialValues;
    this.streamResults = [];
  }

  async processStreams(streams) {
    const promises = streams.map(async (stream, index) => {
      try {
        let currentValue = this.initialValues[index];
        for await (const value of stream) {
          currentValue = this.reductionFunctions[index](currentValue, value);
        }
        this.streamResults.push({ stream: index, result: currentValue });
      } catch (error) {
        console.error(`Error processing stream ${index}: ${error}`);
      }
    });

    return Promise.all(promises).then(() => {
      const aggregatedResults = {};
      for (const { stream, result } of this.streamResults) {
        aggregatedResults[stream] = result;
      }

      const report = {
        streams: this.streamResults,
        aggregatedResults,
        errors: []
      };

      return { report, aggregatedResults };
    });
  }
}

// Example usage:
const aggregator = new Aggregator((x, y) => x + y, [0, 0]);
const stream1 = [1, 2, 3];
const stream2 = [4, 5, 6];

aggregator.processStreams([stream1, stream2]).then(result => {
  console.log(result.report);
  console.log(result.aggregatedResults);
});
