#define MAX_CONNECTIONS 1024
#define MAX_CONFIGURATION_PATH_LENGTH 256

typedef struct {
    char* host;
    int port;
} Connection;

typedef struct {
    Connection connections[MAX_CONNECTIONS];
    int count;
} NetworkConnections;

NetworkConnections* readConfiguration(const char* path) {
    FILE* file = fopen(path, "r");
    if (!file) return NULL;

    json_object* config = json_object_from_file(file);
    fclose(file);

    if (!config) return NULL;

    NetworkConnections* connections = (NetworkConnections*)malloc(sizeof(NetworkConnections));
    connections->count = 0;

    for (json_object_iter iter = json_object_iter_first(config); iter; iter = json_object_iter_next(iter)) {
        Connection connection;
        connection.host = strdup(json_object_get_string(iter.value));
        connection.port = atoi(json_object_get_string(iter.value));

        if (connections->count >= MAX_CONNECTIONS) {
            printf("Maximum number of connections reached.\n");
            free(connections);
            return NULL;
        }

        connections->connections[connections->count++] = connection;
    }

    json_object_free_config(config);

    return connections;
}

int addConnection(NetworkConnections* connections, const char* host, int port) {
    for (int i = 0; i < connections->count; i++) {
        if (!strcmp(connections->connections[i].host, host) && connections->connections[i].port == port)
            return -1; // Connection already exists
    }

    if (connections->count >= MAX_CONNECTIONS) {
        printf("Maximum number of connections reached.\n");
        return -1;
    }

    connections->connections[connections->count++] = (Connection){host, port};

    return 0;
}

int removeConnection(NetworkConnections* connections, const char* host, int port) {
    for (int i = 0; i < connections->count; i++) {
        if (!strcmp(connections->connections[i].host, host) && connections->connections[i].port == port) {
            memmove(&connections->connections[i], &connections->connections[i + 1], (connections->count - i - 1) * sizeof(Connection));
            connections->count--;
            return 0;
        }
    }

    printf("Connection not found.\n");
    return -1;
}

void retrieveConnections(NetworkConnections* connections) {
    for (int i = 0; i < connections->count; i++) {
        printf("Host: %s, Port: %d\n", connections->connections[i].host, connections->connections[i].port);
    }
}
