function processDOMTree(selector, callback) {
  const result = [];
  (function traverse(node) {
    if (!node) return;
    if (node.nodeType === Node.ELEMENT_NODE) {
      const element = node.querySelector(selector);
      if (element && callback(element)) {
        result.push(element);
      }
    }
    for (const child of Array.from(node.childNodes)) {
      traverse(child);
    }
  })(document);

  async function getMetadata(element, loadSizeLimit) {
    try {
      const response = await fetch(`https://api.example.com/${element.id || element.className}`);
      const data = await response.json();
      if (data.popularity > 0 && data.usage > 0.5) {
        return { text: element.textContent.substring(0, loadSizeLimit) };
      }
    } catch (error) {
      console.error(error);
    }
    return null;
  }

  async function processElement(element) {
    const metadata = await getMetadata(element);
    if (!metadata) return;
    try {
      await Promise.all(
        Array.from(element.querySelectorAll(`.${selector}`)).map((child) =>
          processElement(child, metadata.text.length)
        )
      );
    } catch (error) {
      console.error(error);
    }
  }

  for (const element of result) {
    await processElement(element);
  }

  return result;
}
