#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Structure to represent a theme
typedef struct {
    char* bitmap;
} Theme;

// Structure to represent a cache entry
typedef struct {
    char* key;
    Theme* value;
} CacheEntry;

// Structure to represent the caching mechanism
typedef struct {
    // Map of cache entries by key
    CacheEntry** map;
    int size;
    pthread_mutex_t lock; // Lock for concurrent access
} Cache;

// Function to create a new theme with given bitmap
Theme* create_theme(const char* path) {
    Theme* theme = (Theme*)malloc(sizeof(Theme));
    theme->bitmap = (char*)malloc(strlen(path) + 1);
    strcpy(theme->bitmap, path);
    return theme;
}

// Function to get a cache entry by key
CacheEntry* get_cache_entry(Cache* cache, const char* key) {
    for (int i = 0; i < cache->size; i++) {
        if (strcmp(cache->map[i]->key, key) == 0) {
            return cache->map[i];
        }
    }
    return NULL;
}

// Function to set a theme in the cache
void set_cache_theme(Cache* cache, const char* key, Theme* value) {
    pthread_mutex_lock(&cache->lock);
    for (int i = 0; i < cache->size; i++) {
        if (strcmp(cache->map[i]->key, key) == 0) {
            free(cache->map[i]->value->bitmap);
            cache->map[i]->value = value;
            break;
        }
    }
    pthread_mutex_unlock(&cache->lock);
}

// Function to recycle and set a theme bitmap to null
void recycle_theme_bitmap(Theme* theme) {
    if (theme != NULL && theme->bitmap != NULL) {
        free(theme->bitmap);
        theme->bitmap = NULL;
    }
}

// Function to process a log line, transforming it into comma-separated format
char* process_log_line(const char* line) {
    // Split the line by commas and check for numeric fields
    int num_fields = 0;
    char** fields = malloc((strlen(line) + 1) * sizeof(char*));
    char* token = strtok(line, ",");
    while (token != NULL) {
        if (strtol(token, NULL, 10) != LONG_MIN && strtol(token, NULL, 10) != LONG_MAX) {
            num_fields++;
        }
        fields[num_fields] = token;
        token = strtok(NULL, ",");
    }

    // Replace the last numeric field with the average of the last two
    if (num_fields >= 2) {
        int sum = strtol(fields[num_fields - 1], NULL, 10) + strtol(fields[num_fields - 2], NULL, 10);
        char* new_field = malloc(20);
        sprintf(new_field, "%d", sum / 2);
        free(fields[num_fields - 1]);
        free(fields[num_fields - 2]);
        fields[num_fields - 1] = new_field;
    }

    // Join the fields back into a comma-separated string
    char* result = malloc((num_fields + 1) * sizeof(char));
    sprintf(result, "%s", "");
    for (int i = 0; i < num_fields; i++) {
        strcat(result, fields[i]);
        if (i < num_fields - 1) {
            strcat(result, ",");
        }
    }
    free(fields);
    return result;
}

// Function to parse a PNG file from the cache root directory and integrate it into the theme cache
void cache_png_file(Cache* cache, const char* path) {
    Theme* theme = create_theme(path);
    set_cache_theme(cache, "png", theme);
}

int main() {
    // Create a new cache with an initial size of 10 entries
    Cache* cache = (Cache*)malloc(sizeof(Cache));
    cache->map = malloc(10 * sizeof(CacheEntry*));
    cache->size = 0;
    pthread_mutex_init(&cache->lock, NULL);

    // Process log lines and transform them into comma-separated format
    FILE* file = fopen("log.txt", "r");
    char* line;
    while ((line = fgets(line, 100, file)) != NULL) {
        char* transformed_line = process_log_line(line);
        printf("%s\n", transformed_line);
        free(transformed_line);
    }
    fclose(file);

    // Recycle and set theme bitmap to null
    recycle_theme_bitmap(NULL);

    return 0;
}
