tiff_info process_tiff_file(const char* file_path) {
    TIFF* tif = fopen(file_path, "rb");
    if (!tif) return (tiff_info){0};

    tiff_info info = {0};
    uint16_t bits_per_sample = 0;
    uint16_t samples_per_pixel = 0;
    uint8_t extra_samples = 0;

    // Extract TIFF metadata
    if (!TIFFGetField(tif, "BitsPerSample", &bits_per_sample))
        return (tiff_info){0};
    if (!TIFFGetField(tif, "SamplesPerPixel", &samples_per_pixel))
        return (tiff_info){0};
    if (!TIFFGetField(tif, "ExtraSamples", &extra_samples))
        return (tiff_info){0};

    info.bits_per_sample = bits_per_sample;
    info.samples_per_pixel = samples_per_pixel;
    info.extra_samples = extra_samples;

    // Calculate MD5 hash
    uint8_t* md5_hash = (uint8_t*)malloc(16);
    TIFFClose(tif);
    if (!md5_data(&md5_hash, file_path))
        return (tiff_info){0};

    tiff_info result = {info.bits_per_sample, info.samples_per_pixel, info.extra_samples, md5_hash};
    free(md5_hash);
    return result;
}

