char* generate_new_filename(const char* filename, const char* dir_path) {
    int num_digits = 0;
    while(*filename != '\0' && !isdigit(*filename)) {
        filename++;
        num_digits++;
    }
    size_t len = strlen(filename);
    char* new_name = (char*)malloc(len + 128); // sufficient for worst-case scenario
    sprintf(new_name, "%s-%d%s", dir_path, num_digits, get_file_type(filename));
    return new_name;
}

const char* get_file_type(const char* filename) {
    size_t len = strlen(filename);
    int i = 0;
    while(i < len && !isalnum(*(filename+i))) {
        i++;
    }
    if(strncmp((char*)&*(filename+i), "txt", 3) == 0) return ".txt";
    else if(strncmp((char*)&*(filename+i), "csv", 3) == 0) return ".csv";
    else if(strncmp((char*)&*(filename+i), "json", 4) == 0) return ".json";
    else return "";
}
