// Load dynamic libraries
typedef void (*lib_load_t)(void);

lib_load_t lib_load[] = {
    (lib_load_t) dlopen("libaes.so", RTLD_LAZY),
    (lib_load_t) dlopen("libcamellia.so", RTLD_LAZY),
    (lib_load_t) dlopen("libmd5.so", RTLD_LAZY),
    (lib_load_t) dlopen("libsha256.so", RTLD_LAZY),
    (lib_load_t) dlopen("librsa.so", RTLD_LAZY)
};

// Register cryptographic primitives
void (*aes_init)(void);
void (*camellia_init)(void);
void (*md5_init)(void);
void (*sha256_init)(void);
void (*rsa_init)(void);

static void register_primitives() {
    for (int i = 0; i < sizeof(lib_load) / sizeof(*lib_load); i++) {
        lib_load[i]();
