// Function to initialize AES-256-CBC cipher
AES_KEY* init_aes_cipher(const char* password) {
    // Hash the password using SHA256
    unsigned char* hashed_password = (unsigned char*)malloc(32);
    SHA256_CTX sha256_ctx;
    SHA256_Init(&sha256_ctx);
    SHA256_Update(&sha256_ctx, password, strlen(password));
    SHA256_Final(hashed_password, &sha256_ctx);

    // Derive the encryption key from the hashed password
    AES_KEY* aes_key = (AES_KEY*)malloc(sizeof(AES_KEY));
    int len = 32;  // AES-256 key length
    memcpy(aes_key->rkey, hashed_password, len);
    aes_key->key_len = len;

    // Set up the IV
    unsigned char iv[16];
    RAND_bytes(iv, 16);
    aes_key->iv = iv;
    aes_key->iv_len = 16;

    // Clean up
    free(hashed_password);

    return aes_key;
}

// Function to manage theme caching system
void init_theme_cache() {
    // Initialize the cache directory if necessary
    DIR* dir = opendir("themes");
    if (!dir) {
        mkdir("themes", 0755);
        dir = opendir("themes");
    }
    closedir(dir);

    // Load default theme bitmap
    FILE* file = fopen("themes/default.png", "rb");
    if (file == NULL) {
        // Create a placeholder default theme bitmap
        unsigned char* buffer = (unsigned char*)malloc(1024);
        memset(buffer, 0, 1024);
        fwrite(buffer, 1, 1024, file);
        fclose(file);
        free(buffer);
    } else {
        fclose(file);
    }
}

// Function to optimize PNG file parsing and storage
void cache_theme_bitmap(const char* filename) {
    // Open the PNG file
    FILE* file = fopen(filename, "rb");
    if (file == NULL) return;

    // Read the PNG file
    png_structp png_ptr;
    png_infop info;
    int width, height;
    unsigned char buffer[1024];

    png_ptr = png_create_read_struct(PNG_LIBPNG_VER_UNKNOWN, NULL, NULL, NULL);
    if (!png_ptr)
        return;
    info = png_create_info_struct(png_ptr);
    if (!info) {
        png_destroy_read_struct(&png_ptr, &info, NULL);
        return;
    }

    // Parse the PNG file
    int bytes_to_read = 8; /* 8 bytes for chunk header */
    while (bytes_to_read == 8) {
        unsigned char chunk_type[4];
        fread(chunk_type, 1, 4, file); /* Read chunk type */
        if (ferror(file)) {
            png_error(png_ptr, "Error reading PNG file");
            return;
        }
        int16_t length; /* Read chunk length */
        fread(&length, 2, 1, file);
        bytes_to_read = length + 4; /* 8 bytes for chunk header and length */
        if (ferror(file)) {
            png_error(png_ptr, "Error reading PNG file");
            return;
        }

        // Store the PNG data in cache
        fwrite(buffer, 1, length, file);
    }

    // Clean up
    fclose(file);
}
