#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <sys/stat.h>

#define LOG_FILE "/path/to/log/file.log"

int execute_command(const char *command, const char **envp, const char *config_file) {
    pid_t child_pid;
    FILE *log_file;

    if (strlen(command) == 0 || command[0] == '\0') {
        return -1; // Invalid command input
    }

    if (!envp || !*envp) {
        return -1; // Missing required environment variables
    }

    if (!config_file || strlen(config_file) == 0) {
        return -1; // Missing configuration file or malformed
    }

    child_pid = fork();
    if (child_pid < 0) {
        return -1; // Unexpected error
    } else if (child_pid > 0) {
        // Parent process, wait for the child to finish
        int status;
        waitpid(child_pid, &status, 0);
        if (WEXITSTATUS(status)) {
            return 0; // Command failed
        }
        return 1; // Command succeeded
    } else {
        // Child process

        // Set up signal handling for clean exit on interruptions
        signal(SIGINT, SIG_IGN);

        log_file = fopen(LOG_FILE, "a");
        if (!log_file) {
            perror("Failed to open log file");
            return -1;
        }

        fprintf(log_file, "[PID: %d] [TIMESTAMP: %ld] [USER ID: %d] Command executed: '%s'\n", getpid(), time(NULL), getuid(), command);

        fclose(log_file);

        // Execute the command
        execl("/bin/sh", "sh", "-c", command, NULL);

        // Clean up if an error occurs
        unlink(config_file); // Remove configuration file
        close(0); // Close standard input
        close(1); // Close standard output
        close(2); // Close standard error

        return -1; // Unexpected error
    }
}
