typedef struct {
    char* token;
    struct connection* conn;
    void (*callback)(struct connection*, uint8_t*);
} process_message_params;

int process_message(process_message_params* params) {
    if (!params->token || strlen(params->token) == 0) return EINVAL;
    if (!params->conn || !params->conn->active) return ECONNRESET;
    if (!params->callback) return EBADF;

    // Base64 decoding and AES decryption
    uint8_t* decrypted = cryptolib_decrypt_base64_aes(params->token, params->conn->key, params->conn->iv, params->message);

    // Checksum validation
    uint16_t checksum = checksumlib_calculate_checksum(decrypted);
    if (checksum != params->conn->expected_checksum) return ECHECKSUM;

    // Callback and message processing
    (*params->callback)(params->conn, decrypted);

    free(decrypted); // Decryption memory should be freed

    return 0;
}
