bool validate_config(Config* config) {
    if (!config->service_name || !config->endpoint_url || config->timeout <= 0) {
        return false;
    }

    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    for (int i = 0; i < 3; i++) {
        curl_global_init(CURL_GLOBAL_DEFAULT);
        curl = curl_easy_init();
        if (!curl) {
            continue;
        }

        curl_easy_setopt(curl, CURLOPT_URL, config->endpoint_url);
        res = curl_easy_perform(curl);

        if (res != CURLE_OK) {
            fprintf(stderr, "Failed to ping endpoint (%s)\n", curl_easy_strerror(res));
            sleep(1); // retry after 1 second
            continue;
        }

        curl_easy_cleanup(curl);
        curl_global_cleanup();
    }

    return true;
}

int main() {
