using System;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;

public class TripleDesMessageProcessor
{
    public Dictionary<int, string> ProcessMessages(List<string> base64EncodedMessages, byte[] key, byte[] iv)
    {
        var result = new Dictionary<int, string>();

        foreach (var message in base64EncodedMessages)
        {
            try
            {
                var decryptedBytes = DecryptBase64Message(message, key, iv);
                if (decryptedBytes == null)
                {
                    result[base64EncodedMessages.IndexOf(message)] = "Decryption failed due to invalid input";
                }
                else
                {
                    result[base64EncodedMessages.IndexOf(message)] = Encoding.UTF8.GetString(decryptedBytes);
                }
            }
            catch (CryptographicException ex)
            {
                if (!string.IsNullOrEmpty(ex.Message))
                {
                    result[base64EncodedMessages.IndexOf(message)] = "Decryption failed: " + ex.Message;
                }
                else
                {
                    result[base64EncodedMessages.IndexOf(message)] = "Decryption failed";
                }
            }
        }

        return result;
    }

    private byte[] DecryptBase64Message(string base64Message, byte[] key, byte[] iv)
    {
        try
        {
            var encryptedBytes = Convert.FromBase64String(base64Message);

            using (var tripleDesAlg = TripleDES.Create())
            {
                tripleDesAlg.Key = key;
                tripleDesAlg.IV = iv;

                return DecryptTripleDES(encryptedBytes, tripleDesAlg);
            }
        }
        catch
        {
            return null;
        }
    }

    private byte[] DecryptTripleDES(byte[] encryptedBytes, TripleDESCryptoServiceProvider tripleDesAlg)
    {
        using (var ms = new MemoryStream(encryptedBytes))
        {
            using (var cs = new CryptoStream(ms, tripleDesAlg.CreateDecryptor()))
            {
                var decryptedBytes = new byte[cs.Length];
                cs.Read(decryptedBytes, 0, decryptedBytes.Length);
                return decryptedBytes;
            }
        }
    }
}
