    public static void LoadDataset(string filepath, out CustomDataset dataset)
    {
        // Check if file exists and is not corrupted
        if (!File.Exists(filepath) || IsCorrupted(filepath))
            throw new Exception("Invalid or corrupted file");

        // Try to deserialize using binary format first (faster but less flexible)
        try
        {
            using var fileStream = File.OpenRead(filepath);
            dataset = DeserializeDatasetBinary(fileStream);
        }
        catch (Exception ex)
        {
            // If primary deserialization fails, fallback to JSON format
            try
            {
                using var fileStream = File.OpenRead(filepath);
                dataset = DeserializeDatasetJson(fileStream);
            }
            catch (Exception ex2)
            {
                // If secondary deserialization also fails, raise an error
                throw new Exception("Failed to deserialize dataset", ex2);
            }
        }
    }

    private static bool IsCorrupted(string filepath)
    {
        using var fileStream = File.OpenRead(filepath);
        return !GetChecksum(fileStream) == GetExpectedChecksum(filepath);
    }

    private static long GetChecksum(Stream stream)
    {
        using var md5 = MD5.Create();
        var checksumBytes = md5.ComputeHash(stream);
        return BitConverter.ToInt64(checksumBytes, 0);
    }

