             DataInputStream dis = new DataInputStream(bais)) {
            return clazz.getConstructor(DataInput.class).newInstance(dis).cast(clazz);
        } catch (IOException | InstantiationException | IllegalAccessException e) {
            throw new DataProcessingException("Error deserializing data: " + e.getMessage());
        }
    }

    public static class DataProcessingException extends Exception {
        public DataProcessingException(String message) {
