const { exec } = require('child_process');
const axios = require('axios');

function executeShellCommands(commands) {
  return new Promise((resolve, reject) => {
    const results = [];

    (async () => {
      for await (const command of commands) {
        try {
          const result = await exec(command);
          results.push({ command, output: result.stdout });
        } catch (error) {
          reject(error);
        }
      }

      resolve(results);
    })();
  });

  function fetchSystemMetrics() {
    return executeShellCommands([
      'top -b -n 1 | grep Cpu',
      'free -m',
      'iotop -d 1'
    ]);
  }

  async function updateDashboard(data) {
    const dashboardData = {};

    for (const { command, output } of data) {
      if (command.includes('top')) {
        const cpuUsage = output.split('\n')[0].trim().split(' ')[4];
        dashboardData.cpuUsage = cpuUsage;
      } else if (command.includes('free')) {
        const memoryUsage = output
          .split('\n')
          .map((line) => line.trim())
          .filter((line) => line.startsWith('Mem:'))
          .shift()
          .trim()
          .replace('Mem:', '');
        dashboardData.memoryUsage = memoryUsage;
      } else if (command.includes('iotop')) {
        const diskIO = output
          .split('\n')
          .map((line) => line.trim())
          .filter((line) => line.startsWith('Ti'))
          .shift()
          .trim()
          .replace('Ti:', '');
        dashboardData.diskIO = diskIO;
      }
    }

    // Call external APIs for extended monitoring
    const response = await axios.get(
      'https://example.com/api/extended-metrics'
    );

    Object.assign(dashboardData, response.data);

    // Update the dashboard with the new data
    console.log(dashboardData);
  }

  fetchSystemMetrics().then((data) => updateDashboard(data));
