    let mut buffer = [0; 1024];
    let format_str = format!("{:02} [{level}] {message}", level, message);
    let bytes_written = format_str.encode_utf8(&mut buffer).unwrap_or(0);

    String::from_utf8_lossy(&buffer[..bytes_written]).to_string()
}

