import json
import logging
from abc import ABCMeta, abstractmethod
from collections import defaultdict
from functools import wraps

class DataHandler(metaclass=ABCMeta):
    def __init__(self):
        self._registered_factories = {}
        self._logger = logging.getLogger(__name__)

    @abstractmethod
    def to_json(self) -> dict:
        pass

    @abstractmethod
    def from_json(self, json_data: dict) -> None:
        pass

class FactoryRegister:
    def __init__(self):
        self._factories = defaultdict(dict)

    def register_factory(self, factory_name: str, factory_func):
        self._factories[factory_name] = factory_func

    def create_instance(self, factory_name: str, json_data: dict) -> DataHandler:
        return self._factories[factory_name](json_data)

class JSONDataHandler(DataHandler):
    def __init__(self, data):
        super().__init__()
        self.data = data

    def to_json(self) -> dict:
        return {'data': self.data}

    def from_json(self, json_data: dict) -> None:
        self.data = json_data['data']

class DataPipeline(DataHandler):
    def __init__(self):
        super().__init__()
        self.stages = []

    def add_stage(self, stage):
        self.stages.append(stage)

    def to_json(self) -> dict:
        result = {}
        for stage in self.stages:
            result.update(stage.to_json())
        return result

    def from_json(self, json_data: dict) -> None:
        for stage in self.stages:
            stage.from_json(json_data)
            if not stage.valid:
                raise ValueError(f"Stage {stage.__class__.__name__} failed validation")

def validate_data(data):
    # implement your data validation logic here
    return True

def deserialize_nested_json(nested_json: dict) -> DataHandler:
    for key, value in nested_json.items():
        if isinstance(value, dict):
            yield from deserialize_nested_json(value)
        elif 'factory_name' in value and 'json_data' in value:
            factory = FactoryRegister().create_instance(value['factory_name'], value['json_data'])
            yield factory

def serialize_nested_json(data_handler: DataHandler) -> dict:
    result = {}
    for key, value in data_handler.__dict__.items():
        if isinstance(value, DataHandler):
            result[key] = {'factory_name': value.__class__.__name__, 'json_data': serialize_nested_json(value)}
        elif hasattr(value, 'to_json'):
            result[key] = value.to_json()
    return result

def main():
    logging.basicConfig(level=logging.INFO)

    json_data = {
        "stage1": {"data": "Hello"},
        "stage2": {"factory_name": "JSONDataHandler", "json_data": '{"data": "World"}'}
    }

    data_handler = DataPipeline()
    for stage in deserialize_nested_json(json.loads(json.dumps(json_data))):
        data_handler.add_stage(stage)

    if not validate_data(data_handler.to_json()):
        raise ValueError("Invalid data")

    serialized_data = serialize_nested_json(data_handler)
    print(serialized_data)

if __name__ == "__main__":
    main()
