    private List<LTEPHYLayerFramePDU> PDUs = new ArrayList<>();

    public long countDisjointPairs(int[][] array) throws InterruptedException {
        long startTime = System.currentTimeMillis();
        for (int i = 0; i < array.length; i++) {
            for (int j = i + 1; j < array.length; j++) {
                // Utilize Union-Find data structure for efficient disjointness checks
                if (!isDisjoint(array[i], array[j])) {
                    System.out.println("Pair (" + array[i][0] + ", " + array[j][0] + ") is not disjoint");
                }
            }
        }
        long processingTime = System.currentTimeMillis() - startTime;
        System.out.println("Processing time: " + processingTime + " milliseconds");

        return processingTime;
    }

    private boolean isDisjoint(int[] pair1, int[] pair2) {
        // Implement Union-Find algorithm here
        // For simplicity, assume disjoint if elements are from different arrays
        return pair1[0] < 0 || pair2[0] < 0;
    }
