import yaml
import json
from kubernetes import client
from kubernetes.config import Config

def load_config_file(config_path):
    with open(config_path, 'r') as f:
        config = json.load(f)
    return config

def generate_manifest(service_name, config):
    manifest = {
        "apiVersion": "apps/v1",
        "kind": "Deployment",
        "metadata": {"name": service_name},
        "spec": {
            "replicas": 1,
            "selector": {"matchLabels": {"app": service_name}},
            "template": {
                "metadata": {},
                "spec": {}
            }
        }
    }

    for env_var, value in config['env_vars'].items():
        if 'resources' in config and 'limits' in config['resources'] and 'cpu' in config['resources']['limits']:
            manifest['spec']['template']['spec']['containers'][0]['resources']['limits']['cpu'] = str(value)
        if 'resources' in config and 'requests' in config['resources'] and 'memory' in config['resources']['requests']:
            manifest['spec']['template']['spec']['containers'][0]['resources']['requests']['memory'] = str(value)

    return yaml.dump(manifest, default_flow_style=False)

def check_service_availability(config):
    for service_name, service_config in config['services'].items():
        if 'availability' in service_config and not service_config['availability']:
            raise Exception(f"Service {service_name} is unavailable")

def enforce_resource_limits(config):
    for service_name, service_config in config['services'].items():
        if 'resources' in service_config:
            for resource, limit in service_config['resources'].items():
                if float(limit) > 1000:
                    raise Exception(f"Resource limit {resource} for service {service_name} exceeds the threshold")

def deploy_service(config):
    config.load_kubeconfig()

    for service_name, service_config in config['services'].items():
        manifest = generate_manifest(service_name, service_config)
        try:
            api_instance = client.AppsV1Api()
            api_response = api_instance.create_namespaced_deployment(body=manifest, namespace='default')
            print(f"Deployment {service_name} created successfully")
        except Exception as e:
            raise e

def main():
    config_path = 'config.json'
    config = load_config_file(config_path)
    check_service_availability(config)
    enforce_resource_limits(config)
    deploy_service(config)

if __name__ == "__main__":
    main()
