#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <pthread.h>

typedef struct state {
    int id;
    char* name;
    pthread_mutex_t lock;
} State;

typedef struct linked_list {
    State* head;
    int size;
    pthread_mutex_t lock;
} LinkedList;

void add_state(LinkedList* list, State* state) {
    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = state;
    } else {
        State* temp = list->head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = state;
    }
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

void serialize_state_list(LinkedList* list, FILE* file) {
    pthread_mutex_lock(&list->lock);
    fwrite(&list->size, sizeof(int), 1, file);
    State* temp = list->head;
    while (temp != NULL) {
        fwrite(&temp->id, sizeof(int), 1, file);
        fwrite(temp->name, strlen(temp->name)+1, 1, file);
        temp = temp->next;
    }
    pthread_mutex_unlock(&list->lock);
}

int execute_background_command(char* command) {
    pid_t pid = fork();
    if (pid == -1) {
        return 0; // fork failed
    } else if (pid > 0) {
        wait(NULL); // parent process waits for child to finish
        return 1;
    } else {
        system(command);
        return 0;
    }
}

int manage_linked_list(int* states, int num_states, struct FSA* fsa, int last_state, char* command) {
    LinkedList list = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};
    for (int i = 0; i < num_states; i++) {
        State state = {states[i], (char*)malloc(100), PTHREAD_MUTEX_INITIALIZER};
        pthread_mutex_lock(&state.lock);
        // validation and consistency checks go here
        add_state(&list, &state);
        pthread_mutex_unlock(&state.lock);
    }
    serialize_state_list(&list, stdout);
    execute_background_command(command);
    return 1; // success
}
