typedef struct {
    int state;
    int next_state;
} Transition;

void construct_subset(int* states, int num_states, Transition* fsa, int (*filter)(int), int last_state, int** subset) {
    *subset = (int*)malloc((num_states + 1) * sizeof(int));

    for (int i = 0; i < num_states; i++) {
        if (filter(states[i])) {
            (*subset)[i] = states[i];
        } else {
            (*subset)[i] = -1;
        }
    }

    (*subset)[num_states] = last_state;

    // Validate transitions within the subset
    for (int i = 0; i < num_states; i++) {
        for (int j = 0; fsa[i].state != (*subset)[i]; j++) {
            if (fsa[j].next_state == (*subset)[i]) {
                printf("Transition from state %d to %d is invalid.\n", fsa[i].state, (*subset)[i]);
                free(*subset);
                *subset = NULL;
                return;
            }
        }
    }

    // Update the 'next' pointer of the last state
    for (int i = 0; i < num_states; i++) {
        if ((*subset)[i] == -1) {
            (*subset)[num_states] = i;
        } else if (fsa[i].state == (*subset)[num_states]) {
            fsa[i].next_state = (*subset)[i];
        }
    }
}

