void add_to_dynamic_list(LTE_PHY_Layer_Frame_PDU **list, int *size, LTE_PHY_Layer_Frame_PDU *new_entry) {
    // Implement dynamic buffer management for new entry
    if (*size == 0 || *size < size_t(size)) {
        *list = (LTE_PHY_Layer_Frame_PDU **)realloc(*list, sizeof(LTE_PHY_Layer_Frame_PDU *) * (*size + 1));
    }

    // Add new entry to the list
    (*list)[*size] = new_entry;
    (*size)++;
}

void remove_from_dynamic_list(LTE_PHY_Layer_Frame_PDU **list, int *size, LTE_PHY_Layer_Frame_PDU *old_entry) {
    // Search for old_entry in the list
    int i;
    for (i = 0; i < *size; i++) {
        if ((*list)[i] == old_entry) break;
    }

    // Remove old_entry from the list
    if (i < *size) {
        memmove(&(*list)[i], &(*list)[i + 1], sizeof(LTE_PHY_Layer_Frame_PDU *) * (*size - i));
        (*size]--;
    }
}

void free_dynamic_list(LTE_PHY_Layer_Frame_PDU **list, int *size) {
    // Free individual entries in the list
    for (int i = 0; i < *size; i++) {
        free((*list)[i]);
    }

    // Free the list itself
