```c
#include <semaphore.h>
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

sem_t *semaphore;
NFAPI_CRC_INDICATION_PDU_T *list;
int list_size;
int list_capacity;

void init_semaphore(int value) {
    sem_init(semaphore, 0, value);
}

void critical_section_operation() {
    // Perform operations within the critical section
    printf("Critical section operation performed\n");
}

void cleanup_and_delete_semaphore() {
    sem_destroy(semaphore);
}

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void manage_list(int n) {
    int i;
    srand(time(NULL)); // Initialize random seed

    list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        printf("Memory allocation failed\n");
        return;
    }

    for (i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* entry = &list[i];
        entry->RX_UE_INFORMATION_TAG = rand() % 100 + 1;
        entry->RNTI = rand() % 256;
        entry->CRC_INDICATION_REL8_TAG = rand() % 255;

        // Perform thread-safe memory allocation for CRCFLAG
        int* crc_flag = (int*)malloc(sizeof(int));
        if (!crc_flag) {
            printf("Memory allocation failed\n");
            return;
        }
        *crc_flag = rand() % 2; // Randomly set CRCFLAG

        entry->CRCFLAG = crc_flag;
    }

    list_size = n;
    list_capacity = n;

    // Perform thread-safe memory deallocation for CRCFLAG
    for (i = 0; i < n; i++) {
        free(list[i].CRCFLAG);
    }
}

int main() {
    int num_entries = 10;

    semicolon = sem_open("/my_semaphore", O_CREAT | O_EXCL, 0644, 1);
    if (semicolon == SEM_FAILED) {
        printf("Semaphore creation failed\n");
        return -1;
    }

    manage_list(num_entries);

    // Perform critical section operations
    for (int i = 0; i < num_entries; i++) {
        sem_wait(semicolon);
        critical_section_operation();
        sem_post(semicolon);
    }

    cleanup_and_delete_semaphore();

    return 0;
}
