void* manage_list(void* data) {
    NFAPI_CRC_INDICATION_PDU_T* nfapi_data = (NFAPI_CRC_INDICATION_PDU_T*)data;

    pthread_mutex_lock(&mutex);
    if (nfapi_list == NULL || list_size >= MAX_ELEMENTS) {
        // Dynamically resize the list if necessary
        nfapi_list = realloc(nfapi_list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list_size + 1));

        if (nfapi_list == NULL) {
            // Handle memory allocation failure gracefully
            printf("Memory allocation failed. Aborting.\n");
            pthread_exit(NULL);
        }
    }

    int rnti_valid = 0;

    while (!rnti_valid) {
        if (list_size >= MAX_ELEMENTS - 1) {
            // Handle the case where MAX_ELEMENTS is reached
            printf("List size exceeded. Waiting for available space.\n");
            pthread_cond_wait(&cond, &mutex);
            list_size = 0; // Reset the list size to prevent unnecessary resizing
        }

        nfapi_data->RX_UE_INFORMATION_TAG = // Set your desired tag value
        nfapi_data->RNTI = (rand() % (MAX_RNTI - MIN_RNTI + 1)) + MIN_RNTI;
        nfapi_data->CRC_INDICATION_REL8_TAG = // Set your desired tag value
        nfapi_data->CRCFLAG = rand() % 2; // Randomly set CRC flag

        pthread_mutex_lock(&mutex);

        for (int i = 0; i < list_size; i++) {
            if (nfapi_list[i].RNTI == nfapi_data->RNTI) {
                rnti_valid = 1;
                printf("Ignoring duplicate RNTI.\n");
                pthread_cond_signal(&cond);
                break;
            }
        }

        if (!rnti_valid) {
            list_size++;
            pthread_cond_broadcast(&cond);
            // Log the successfully processed element
            printf("Processed %dth element.\n", list_size - 1);
        }
    }

    pthread_mutex_unlock(&mutex);

    return NULL;
}

int main() {
    pthread_t thread;
    NFAPI_CRC_INDICATION_PDU_T* nfapi_data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&mutex, NULL);
    pthread_cond_init(&cond, NULL);

    // Initialize and start the thread
    int result = pthread_create(&thread, NULL, manage_list, nfapi_data);

    if (result) {
        printf("pthread_create failed: %d\n", result);
        return -1;
    }

    pthread_join(thread, NULL);

    free(nfapi_data);
    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&cond);

    return 0;
}
