#define MAX_NFAPDUS 1000

typedef struct {
    uint8_t RX_UE_INFORMATION_TAG;
    int RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *nfapdus = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int nfapdu_count = 0;

void addNFAPDU(NFAPI_CRC_INDICATION_PDU_T* new_nfapdu) {
    pthread_mutex_lock(&lock);
    if (nfapdu_count < MAX_NFAPDUS) {
        nfapdus[nfapdu_count++] = *new_nfapdu;
    } else {
        printf("List full, cannot add more NFAPDUs.\n");
    }
    pthread_mutex_unlock(&lock);
}

void updateNFAPDU(int index, NFAPI_CRC_INDICATION_PDU_T* updated_nfapdu) {
    pthread_mutex_lock(&lock);
    if (index < nfapdu_count) {
        memcpy(&nfapdus[index], updated_nfapdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    } else {
        printf("Index out of range.\n");
    }
    pthread_mutex_unlock(&lock);
}

void removeNFAPDU(int index) {
    pthread_mutex_lock(&lock);
    if (index < nfapdu_count) {
        memmove(&nfapdus[index], &nfapdus[index + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (nfapdu_count - index - 1));
        nfapdu_count--;
    } else {
        printf("Index out of range.\n");
    }
    pthread_mutex_unlock(&lock);
}

void printNFAPDUS() {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < nfapdu_count; i++) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %hu, CRCFLAG: %s\n", 
               nfapdus[i].RX_UE_INFORMATION_TAG, nfapdus[i].RNTI, nfapdus[i].CRC_INDICATION_REL8_TAG, 
               (nfapdus[i].CRCFLAG ? "true" : "false"));
    }
    pthread_mutex_unlock(&lock);
}

