#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    long timestamp;
    int status_code;
    double value;
} record_t;

typedef struct {
    int size;
    int capacity;
    record_t* records;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} collection_t;

collection_t* create_collection() {
    collection_t* coll = (collection_t*)malloc(sizeof(collection_t));
    if (!coll) return NULL;
    coll->size = 0;
    coll->capacity = 10; // Initial capacity
    coll->records = (record_t*)calloc(coll->capacity, sizeof(record_t));
    pthread_mutex_init(&coll->mutex, NULL);
    pthread_cond_init(&coll->cond, NULL);
    return coll;
}

void add_record(collection_t* coll, long timestamp, int status_code, double value) {
    if (coll->size == coll->capacity) {
        // Resize collection
        coll->capacity *= 2; // Increase capacity by 50%
        record_t* new_records = (record_t*)realloc(coll->records, sizeof(record_t) * coll->capacity);
        coll->records = new_records;
    }
    pthread_mutex_lock(&coll->mutex);
    if (find_timestamp(coll, timestamp)) {
        // Duplicate timestamp detected
        pthread_mutex_unlock(&coll->mutex);
        return;
    }
    record_t* record = &coll->records[coll->size];
    record->timestamp = timestamp;
    record->status_code = status_code;
    record->value = value;
    coll->size++;
    pthread_cond_signal(&coll->cond);
    pthread_mutex_unlock(&coll->mutex);
}

int find_status(collection_t* coll, int status_code) {
    for (int i = 0; i < coll->size; i++) {
        if (coll->records[i].status_code == status_code)
            return 1;
    }
    return 0;
}

void free_collection(collection_t* coll) {
    pthread_mutex_lock(&coll->mutex);
    free(coll->records);
    coll->records = NULL;
    pthread_cond_destroy(&coll->cond);
    pthread_mutex_unlock(&coll->mutex);
    free(coll);
}
