void* nfapi_pdu_array_manage(int* num_pdus, int max_size) {
    // Allocate memory for dynamic array with initial size and maximum allowed size
    *num_pdus = 0; // Initialize number of PDUs to zero
    void** pdu_array = (void**)malloc(max_size * sizeof(void*));
    if (!pdu_array) return NULL;

    // Function implementations:
    // Add new PDU:
    int add_pdu(NFAPI_L2_PDU_T* pdu) {
        if (*num_pdus >= max_size / 2) { // Check if half of the maximum size is reached
            printf("Warning: Array almost full. Consider increasing the maximum size.\n");
        }
        if (*num_pdus < max_size) {
            pdu_array[*num_pdus] = (void*)pdu;
            (*num_pdus)++;
            return 1; // PDU added successfully
        } else {
            printf("Error: Array is full. Cannot add more PDUs.\n");
            return 0; // PDU addition failed due to array being full
        }
    }

    // Remove specified PDU by index:
    int remove_pdu(int idx) {
        if (idx >= *num_pdus || idx < 0) {
            printf("Error: Invalid PDU index.\n");
            return -1; // Invalid index
        }
        for (int i = idx; i < *num_pdus - 1; i++) {
            pdu_array[i] = pdu_array[i + 1];
        }
        (*num_pdus)--;
        return 0; // PDU removed successfully
    }

    // Retrieve total number of PDUs currently stored:
    int get_num_pdus() { return *num_pdus; }

    return pdu_array;
}
