typedef struct {
    int id;
    char* key;
    char* value;
    time_t timestamp;
} network_config_entry;

typedef struct {
    pthread_mutex_t lock;
    int size;
    network_config_entry** entries;
} network_config_hash_table;

network_config_hash_table* init_network_config_hash_table(int initial_size) {
    network_config_hash_table* table = (network_config_hash_table*)malloc(sizeof(network_config_hash_table));
    table->size = initial_size;
    table->entries = (network_config_entry**)malloc(table->size * sizeof(network_config_entry*));

    for (int i = 0; i < table->size; i++) {
        table->entries[i] = NULL;
    }

    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void insert_network_config_hash_table(network_config_hash_table* table, int id, char* key, char* value) {
    pthread_mutex_lock(&table->lock);

    for (int i = 0; i < table->size; i++) {
        if (table->entries[i] == NULL || strcmp(table->entries[i]->key, key) != 0) {
            int j;
            for (j = 0; j < i; j++) {
                if (table->entries[j] == NULL) {
                    table->entries[i] = table->entries[j];
                    table->entries[j] = NULL;
                    break;
                }
            }

            network_config_entry* entry = (network_config_entry*)malloc(sizeof(network_config_entry));
            entry->id = id;
            entry->key = key;
            entry->value = value;
            entry->timestamp = time(NULL);

            table->entries[i] = entry;

            pthread_mutex_unlock(&table->lock);
            return;
        }
    }

    pthread_mutex_unlock(&table->lock);
}

void delete_network_config_hash_table(network_config_hash_table* table, int id) {
    pthread_mutex_lock(&table->lock);

    for (int i = 0; i < table->size; i++) {
        if (table->entries[i] != NULL && table->entries[i]->id == id) {
            free(table->entries[i]);
            table->entries[i] = NULL;
            break;
        }
    }

    pthread_mutex_unlock(&table->lock);
}

network_config_entry* get_network_config_hash_table(network_config_hash_table* table, int id) {
    pthread_mutex_lock(&table->lock);

    for (int i = 0; i < table->size; i++) {
        if (table->entries[i] != NULL && table->entries[i]->id == id) {
            network_config_entry* entry = table->entries[i];
            pthread_mutex_unlock(&table->lock);
            return entry;
        }
    }

    pthread_mutex_unlock(&table->lock);
    return NULL;
}

void free_network_config_hash_table(network_config_hash_table* table) {
    pthread_mutex_lock(&table->lock);

    for (int i = 0; i < table->size; i++) {
        if (table->entries[i] != NULL) {
            free(table->entries[i]);
        }
    }

    free(table->entries);
    free(table);
}

