#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>

#define MAX_DATA_LENGTH 1000
#define UNIQUE_ARRAY_SIZE 10000

typedef struct {
    int data[MAX_DATA_LENGTH];
    int size;
} DataBlock;

void* readData(void* arg) {
    pthread_setcancelstate(PTHREAD_CANCEL_DISABLE, NULL);
    pthread_setcanceltype(PTHREAD_CANCEL_ASYNCHRONOUS, NULL);

    int fd = *((int*)arg);
    DataBlock* block = (DataBlock*)malloc(sizeof(DataBlock));
    block->size = 0;

    while (1) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);

        int new_fd = accept(fd, (struct sockaddr*)&client_addr, &client_len);
        if (new_fd < 0) {
            perror("accept");
            close(new_fd);
            continue;
        }

        char buffer[MAX_DATA_LENGTH];
        memset(buffer, 0, MAX_DATA_LENGTH);

        read(new_fd, buffer, MAX_DATA_LENGTH);

        int* data = (int*)buffer;
        for (int i = 0; i < MAX_DATA_LENGTH / sizeof(int); i++) {
            if (data[i] >= -1000 && data[i] <= 1000) {
                block->data[block->size++] = data[i];
            }
        }

        close(new_fd);
    }

    pthread_exit(NULL);
}

void printLargest(DataBlock* block) {
    int max = INT_MIN;
    for (int i = 0; i < block->size; i++) {
        if (block->data[i] > max) {
            max = block->data[i];
        }
    }

    printf("Largest integer: %d\n", max);
}

void* findUniques(void* arg) {
    pthread_setcancelstate(PTHREAD_CANCEL_DISABLE, NULL);
    pthread_setcanceltype(PTHREAD_CANCEL_ASYNCHRONOUS, NULL);

    DataBlock* block = (DataBlock*)arg;
    int* uniqueArray = (int*)malloc(sizeof(int) * UNIQUE_ARRAY_SIZE);
    int uniqueSize = 0;

    for (int i = 0; i < block->size; i++) {
        int found = 0;
        for (int j = 0; j < uniqueSize; j++) {
            if (uniqueArray[j] == block->data[i]) {
                found = 1;
                break;
            }
        }

        if (!found) {
            uniqueArray[uniqueSize++] = block->data[i];
        }
    }

    free(block);
    pthread_exit((void*)uniqueArray);
}

int main() {
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        perror("socket");
        return 1;
    }

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &(server_addr.sin_addr));

    if (bind(fd, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("bind");
        close(fd);
        return 1;
    }

    listen(fd, 3);

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        int* new_fd = malloc(sizeof(int));
        *new_fd = accept(fd, NULL, NULL);
        pthread_create(&threads[i], NULL, readData, new_fd);
        free(new_fd);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    DataBlock* block = malloc(sizeof(DataBlock));
    for (int i = 0; i < 10; i++) {
        int* data = (int*)malloc(sizeof(int) * UNIQUE_ARRAY_SIZE);
        pthread_create(&threads[i], NULL, findUniques, block);
        pthread_join(threads[i], (void**)&data);

        int maxSize = INT_MIN;
        for (int j = 0; j < UNIQUE_ARRAY_SIZE; j++) {
            if (data[j] > maxSize) {
                maxSize = data[j];
            }
        }

        printf("Largest integer: %d\n", maxSize);
        free(data);
    }

    return 0;
}
