#define MAX_PDU 1000
#define BUFFER_SIZE 1024

typedef struct {
    int pcGroup;
    int tcId;
    char rnti[16];
    int crcFlag;
} Pdu;

Pdu* pduPool = NULL;
int poolSize = 0;
int currentBufferSize = BUFFER_SIZE;
int historicalTrafficBuffer = 0;
int bufferAdjustmentThreshold = 500; // adjust this value based on your traffic patterns

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void* pduPoolThread(void* arg) {
    while (1) {
        pthread_mutex_lock(&mutex);
        Pdu* currentPdu = &pduPool[poolSize];
        if (currentPdu->pcGroup > 0) {
            // process the PDU
            printf("Processing PDU: pcGroup %d, tcId %d\n", currentPdu->pcGroup, currentPdu->tcId);
            poolSize--;
        }
        pthread_mutex_unlock(&mutex);

        if (poolSize < bufferAdjustmentThreshold) {
            int newBufferSize = BUFFER_SIZE * 2;
            if (newBufferSize > MAX_PDU) {
                newBufferSize = MAX_PDU;
            }
            currentBufferSize = newBufferSize;
            printf("Increasing buffer size to %d\n", newBufferSize);
        } else if (poolSize > MAX_PDU) {
            int newBufferSize = BUFFER_SIZE / 2;
            if (newBufferSize < BUFFER_SIZE / 4) {
                newBufferSize = BUFFER_SIZE / 4;
            }
            currentBufferSize = newBufferSize;
            printf("Decreasing buffer size to %d\n", newBufferSize);
        }

        pthread_cond_signal(&cond);

        // simulate processing time
        sleep(1);
    }
}

int main() {
    srand(time(NULL));

    poolSize = 0;

    while (1) {
        Pdu* pdu = malloc(sizeof(Pdu));
        if (!pdu) break;
        pdu->pcGroup = rand() % 256;
        pdu->tcId = rand() % 1024;
        strcpy(pdu->rnti, "RNTI");
        pdu->crcFlag = rand() & 1;

        pthread_mutex_lock(&mutex);
        poolSize++;
        if (poolSize > currentBufferSize) {
            int newBufferSize = currentBufferSize * 2;
            if (newBufferSize > MAX_PDU) {
                newBufferSize = MAX_PDU;
            }
            currentBufferSize = newBufferSize;
            printf("Increasing buffer size to %d\n", newBufferSize);
        }
        pthread_mutex_unlock(&mutex);

        // simulate processing time
        sleep(1);
    }

    return 0;
}
