void manage_frame_list(LTE_PHY_FRAME_INFO** frames, int* frame_count) {
    // Initialize a dynamic list to store frames
    *frames = (LTE_PHY_FRAME_INFO**)malloc(sizeof(LTE_PHY_FRAME_INFO*) * 10);
    *frame_count = 0;

    pthread_mutex_init(&mutex, NULL); // Initialize mutex for concurrent access

    while (1) {
        // Receive new frame configuration updates from external data source
        LTE_PHY_FRAME_INFO* new_frame = receive_frame_config();

        // Validate TX power level against predefined limits
        if (new_frame->tx_power_level < 0 || new_frame->tx_power_level > 100) {
            printf("Invalid TX power level: %d\n", new_frame->tx_power_level);
            continue;
        }

        // Check for duplicate frames and skip if necessary
        int found = 0;
        for (int i = 0; i < *frame_count; i++) {
            if (frames[i]->sequence_number == new_frame->sequence_number) {
                found = 1;
                break;
            }
        }
        if (found) {
            printf("Duplicate frame ignored: sequence number %d\n", new_frame->sequence_number);
            continue;
        }

        // Add the new frame to the list
        *frame_count = (*frame_count + 1) % 10; // Implement a sliding window of recent frames
        if (*frame_count == 0) {
            // Reallocate memory for the dynamic list when it's full
            *frames = (LTE_PHY_FRAME_INFO**)realloc(*frames, sizeof(LTE_PHY_FRAME_INFO*) * (*frame_count + 5));
        }
        frames[*frame_count - 1] = new_frame;

        // Log frame processing statistics
        printf("Processed %d frames, ignored %d duplicates\n", *frame_count - found, found);
    }
}
