    // Conversion to PDF
    system("converter_tool input_file output_pdf");

    // Logging
    FILE *log = fopen(log_file, "a+");
    if (log == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }
    if (!fprintf(log, "DNS resolution successful: %s\n", hostname)) {
        fclose(log);
        return -1;
    }
    if (!fprintf(log, "Conversion to PDF successful: %s -> %s\n", input_file, output_pdf)) {
        fclose(log);
        return -1;
    }

    fclose(log);

    return ret;
}
