    char CRC_INDICATION_REL8_TAG[16];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *nfaPiList = NULL;
pthread_mutex_t listMutex = PTHREAD_MUTEX_INITIALIZER;
int nfaPiListCount = 0;
int nfaPiListSize = 0;

void* periodicUpdateThread(void* arg) {
    while (1) {
        // Periodic update from external service
        // ...

        // Update UE information and RNTI ranges in the list
        pthread_mutex_lock(&listMutex);
        // ...
        pthread_mutex_unlock(&listMutex);

        sleep(60); // Wait for 1 minute before next update
    }
}

int processNFAPI_CRC_INDICATION_PDU_T(NFAPI_CRC_INDICATION_PDU_T* nfaPi) {
    pthread_mutex_lock(&listMutex);

    if (nfaPiListCount >= nfaPiListSize) {
        nfaPiListSize *= 2;
        nfaPiList = realloc(nfaPiList, nfaPiListSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    int i;
    for (i = 0; i < nfaPiListCount; i++) {
        if (strcmp(nfaPi->RX_UE_INFORMATION_TAG, nfaPiList[i].RX_UE_INFORMATION_TAG) == 0 &&
            nfaPi->RNTI == nfaPiList[i].RNTI) {
            // Duplicate entry found
            printf("Duplicate RNTI %d ignored.\n", nfaPi->RNTI);
            pthread_mutex_unlock(&listMutex);
            return 1; // Ignore duplicate and continue processing
        }
    }

    if (nfaPiListCount < MAX_ELEMENTS) {
        memcpy(nfaPiList + nfaPiListCount, nfaPi, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        nfaPiListCount++;

        printf("Successfully processed RNTI %d.\n", nfaPi->RNTI);
    } else {
        printf("Maximum number of elements reached. Ignoring RNTI %d.\n", nfaPi->RNTI);
    }

    pthread_mutex_unlock(&listMutex);
    return 0;
}

int main() {
    // Initialize periodic update thread
    pthread_t periodicUpdateThreadHandle;
    pthread_create(&periodicUpdateThreadHandle, NULL, periodicUpdateThread, NULL);

    while (1) {
        NFAPI_CRC_INDICATION_PDU_T* nfaPi = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Validate RX_UE_INFORMATION_TAG and RNTI range
        if (!validateRX_UETAG(nfaPi->RX_UE_INFORMATION_TAG) ||
            !isRNTIRangeValid(nfaPi->RNTI)) {
            free(nfaPi);
            continue;
        }

        // Process NFAPI CRC indication PDU T structure
        processNFAPI_CRC_INDICATION_PDU_T(nfaPi);

        free(nfaPi);
    }

    return 0;
}

