```csharp
using System;
using System.Threading;
using UnityEngine;

public class DynamicRandomValueGenerator
{
    private float minFloatValue;
    private float maxFloatValue;
    private int? minIntValue;
    private int? maxIntValue;
    private uint seed;
    private bool isSeedSet = false;
    private readonly object locker = new object();
    private readonly ConcurrentDictionary<(bool, bool), (float, int)> cache = new ConcurrentDictionary<(bool, bool), (float, int)>();

    public void SetMinFloatValue(float minValue)
    {
        minFloatValue = minValue;
    }

    public void SetMaxFloatValue(float maxValue)
    {
        maxFloatValue = maxValue;
    }

    public void SetMinIntValue(int minValue)
    {
        minIntValue = minValue;
    }

    public void SetMaxIntValue(int maxValue)
    {
        maxIntValue = maxValue;
    }

    public void SetSeed(uint seed)
    {
        this.seed = seed;
        isSeedSet = true;
    }

    public float GetRandomFloat(bool exclusive, bool isNegativeAllowed = false)
    {
        if (!isSeedSet) UnityEngine.Random.InitState((int)DateTime.Now.Ticks);
        lock (locker)
        {
            return cache.GetOrAdd((exclusive, isNegativeAllowed), _ =>
            {
                if (minFloatValue < maxFloatValue && !exclusive)
                    return new float(Mathf.Lerp(minFloatValue, maxFloatValue, (float)UnityEngine.Random.value));
                else
                    return exclusive ? minFloatValue : (isNegativeAllowed ? -maxFloatValue : maxFloatValue);
            });
        }
    }

    public int GetRandomInt(bool exclusive, bool isNegativeAllowed = false)
    {
        if (!isSeedSet) UnityEngine.Random.InitState((int)DateTime.Now.Ticks);
        lock (locker)
        {
            return cache.GetOrAdd((exclusive, isNegativeAllowed), _ =>
            {
                if (minFloatValue < maxFloatValue && !exclusive)
                    return new int(Mathf.RoundToInt(minFloatValue + (maxFloatValue - minFloatValue) * (float)UnityEngine.Random.value));
                else
                    return exclusive ? (isNegativeAllowed ? -(maxIntValue ?? 0) : (minIntValue ?? 0)) : (isNegativeAllowed ? -1 : 1);
            });
        }
    }

    public override string ToString()
    {
        return $"Min Float Value: {minFloatValue}, Max Float Value: {maxFloatValue}, " +
               $"Min Int Value: {(minIntValue ?? 0)}, Max Int Value: {(maxIntValue ?? 0)}, Seed: {(isSeedSet ? seed : "Not Set")}";
    }
}
