#include <stdio.h>
#include <stdlib.h>
#include <math.h>

int* readDataset(int maxSize) {
    int* dataset = (int*)malloc((maxSize + 1)*sizeof(int));
    int size = 0;

    while(1) {
        int val = getchar();

        if(val == -1) break; // Sentinel value for end of input

        else if(isdigit(val) || val == '-') { // Ignore non-integer values
            dataset[size++] = val - '0';

            if(size > maxSize) {
                free(dataset);
                return NULL;
            }
        }

        else continue;
    }

    dataset[size] = -1; // Add sentinel value for end of input
    return dataset;
}

void printAverage(int* dataset, int size) {
    double sum = 0.0;

    for(int i = 0; i < size; i++) {
        if(dataset[i] != -1) // Ignore non-integer values
            sum += (double)dataset[i];
    }

    printf("%s%.0lf%s\n", size > 0 ? "" : "No data ", fmax(sum / size, 0.0), size > 0 ? "\n" : "\n");
}

int main() {
    int maxSize = 100; // Predefined maximum size limit

    while(1) {
        printf("Enter dataset (type -1 to end): ");
        int* dataset = readDataset(maxSize);

        if(dataset == NULL) {
            printf("Input overflow\n");
            continue;
        }

        int size = 0;

        for(int i = 0; i < maxSize; i++) {
            if(dataset[i] == -1) break;

            else if(dataset[i] != -1) size++;
        }

        printAverage(dataset, size);

        free(dataset);
    }

    return 0;
}
