void init_memory(int offset_size, int key_size, int record_count, int min_value, int max_value) {
    // Allocate memory for and initialize arrays
    long* offsets = (long*)malloc(offset_size * sizeof(long));
    int* keys = (int*)malloc(key_size * sizeof(int));

    // Initialize arrays with default values
    for (int i = 0; i < offset_size; i++) {
        offsets[i] = i;
    }
    for (int i = 0; i < key_size; i++) {
        keys[i] = i;
    }

    // Allocate memory for and initialize array of record structures
    struct Record {
        int value;
    } *records = (struct Record*)malloc(record_count * sizeof(struct Record));

    // Initialize records with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < record_count; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    // Implement memory budget constraint
    if (offset_size * sizeof(long) + key_size * sizeof(int) + record_count * sizeof(struct Record) > /*memory_budget*/) {
        // Adjust array sizes or record count to stay within the budget
        offset_size = (int)(/*memory_budget*/ / sizeof(long));
        key_size = (int)(/*memory_budget*/ / sizeof(int));
        record_count = (int)(/*memory_budget*/ / sizeof(struct Record));
    }

    // Serialize state of function to file
    FILE* file = fopen("state.txt", "wb");
    fwrite(&offsets, offset_size * sizeof(long), 1, file);
    fwrite(&keys, key_size * sizeof(int), 1, file);
    fwrite(records, record_count * sizeof(struct Record), 1, file);

    fclose(file);

    // Log information about memory allocations and random number generation
    FILE* log_file = fopen("log.txt", "wb");
    fprintf(log_file, "Memory allocated: %lu bytes\n", offset_size * sizeof(long) + key_size * sizeof(int) + record_count * sizeof(struct Record));
    fprintf(log_file, "Random values generated within range [%d, %d]\n", min_value, max_value);
    fclose(log_file);

    // Free memory
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    init_memory(1000, 500, 2000, 1, 1000);
    return 0;
}
