    if (!pdu_list) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < n; i++) {
        pdu_list[i].RX_UE_INFORMATION_TAG = i;
        pdu_list[i].RNTI = ints[i] % 32;
        srand(time(NULL));
        pdu_list[i].CRC_INDICATION_REL8_TAG = rand() & ((1 << CRC_INDICATION_REL8_TAG_SIZE) - 1);
    }

    return pdu_list;
}

int main() {
    int* ints = NULL;
    int n = 0;

    // Read integers from standard input
    while (scanf("%d", &n) == 1 && n <= MAX_INTS) {
        int* temp = realloc(ints, (n + 1) * sizeof(int));
        if (!temp) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }
        ints = temp;
        for (int i = n; i > 0; i--) {
            scanf("%d", &ints[i - 1]);
        }
    }

    // Find the maximum value in the array
    int max_val = ints[0];
    for (int i = 1; i < n; i++) {
        if (ints[i] > max_val) {
            max_val = ints[i];
        }
    }

