// Define the record structure
typedef struct {
    int id;
    double value;
    char *description;
} record;

// Function to dynamically allocate memory for an array of record structures
record **allocate_records(int num_records) {
    record **records = (record **)malloc(num_records * sizeof(record *));

    // Initialize each record with default values and handle allocation errors
    for (int i = 0; i < num_records; i++) {
        records[i] = (record *)malloc(sizeof(record));
        if (!records[i]) {
            free(records);
            return NULL;
        }

        records[i]->id = -1;
        records[i]->value = 0.0;
        records[i]->description = NULL;
    }

    return records;
}

// Function to write the array of record structures to a file in binary format
void write_records_to_file(record **records, int num_records, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        // Handle file opening error
        printf("Error opening file: %s\n", filename);
        return;
    }

    for (int i = 0; i < num_records; i++) {
        fwrite(&records[i]->id, sizeof(int), 1, file);
        fwrite(&records[i]->value, sizeof(double), 1, file);
        size_t description_len = strlen(records[i]->description) + 1;
        fwrite(&description_len, sizeof(size_t), 1, file);
        fwrite(records[i]->description, 1, description_len, file);
    }

    fclose(file);
}

int main() {
    int num_records = 10;
    record **records = allocate_records(num_records);

    // Initialize records with actual data
    for (int i = 0; i < num_records; i++) {
        records[i]->id = i;
        records[i]->value = (double)i;
        records[i]->description = (char *)malloc((strlen("Record ") + 10) * sizeof(char));
        sprintf(records[i]->description, "Record %d", i);
    }

