```rust
use tokio::net::{TcpStream, TcpListener};
use tokio::sync::mpsc;
use tokio::time::{sleep, timeout};

#[derive(Debug)]
struct HttpResponse {
    status_code: u16,
    body: Vec<u8>,
}

async fn make_request(url: &str, timeout_ms: u64) -> Result<HttpResponse, reqwest::Error> {
    let client = reqwest::ClientBuilder::new().timeout(timeout_ms as u64).build()?;
    let res = client.get(url).send().await?;
    Ok(HttpResponse {
        status_code: res.status().as_u16(),
        body: res.bytes().collect(),
    })
}

async fn send_request<T>(url: &str, timeout_ms: u64, max_retries: usize) -> Result<T, reqwest::Error>
where
    T: Send + 'static,
{
    let mut backoff = std::time::Duration::from_millis(100);
    for _ in 0..max_retries {
        match make_request(url, timeout_ms).await {
            Ok(body) => return Ok(body),
            Err(err) if err.is_timeout() => {
                // exponential backoff
                sleep(backoff).await;
                backoff *= 2;
            }
            Err(_) => {
                // max retries reached or unexpected error
                return Err(reqwest::Error::new("max_retries_reached", None));
            }
        }
    }

    Err(reqwest::Error::new("request_timeout", None))
}

#[tokio::main]
async fn main() {
    let url = "https://example.com/api/endpoint";
    let timeout_ms = 5000;
    let max_retries = 3;

    // test the client
    match send_request::<HttpResponse>(&url, timeout_ms, max_retries).await {
        Ok(response) => println!("Received response: {}", response),
        Err(err) => eprintln!("Error: {}", err),
    }
}
