        // Serialize the populated data structures into a binary format for efficient storage and retrieval
        FILE* bin_file = fopen("data.bin", "wb");
        fwrite(timestamps, sizeof(long), lineCount, bin_file);
        fwrite(temperatures, sizeof(double), lineCount, bin_file);

        // Write the events to the binary file
        for (int i = 0; i < lineCount; i++) {
            event_t* current_event = events[i];
            fwrite(&current_event->timestamp, sizeof(long), 1, bin_file);
            fwrite(&current_event->temperature, sizeof(double), 1, bin_file);
            fwrite(&current_event->status, sizeof(int), 1, bin_file);
        }

        fclose(bin_file);

        // Free the allocated memory
        for (int i = 0; i < lineCount; i++) {
            free(events[i]);
        }
        free(events);
    } else {
        fprintf(stderr, "Failed to read file\n");
        return -1;
    }

    return 0;
}
