#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a record structure to store key-value pair and metadata
typedef struct {
    int key;
    void *value; // Use a pointer to accommodate varying metadata sizes
    size_t value_size;
} Record;

// Implement a hash function using FNV-1a algorithm for uniform distribution
unsigned long hash_function(void *key, size_t key_size) {
    unsigned long hash = 0x811C9DC5;
    const uint8_t *k = (const uint8_t *)key;
    for (size_t i = 0; i < key_size; i++) {
        hash ^= k[i];
        hash *= 0x12345678;
    }
    return hash;
}

// Define a hash table structure with fixed-size buckets
typedef struct {
    Record **buckets;
    size_t bucket_count;
    size_t record_count;
} HashTable;

// Initialize the hash table with a specified number of buckets
HashTable *hash_table_init(size_t bucket_count) {
    HashTable *table = (HashTable *)malloc(sizeof(HashTable));
    table->bucket_count = bucket_count;
    table->record_count = 0;
    table->buckets = (Record **)calloc(bucket_count, sizeof(Record *));
    return table;
}

// Free the hash table and its contents
void hash_table_free(HashTable *table) {
    for (size_t i = 0; i < table->bucket_count; i++) {
        if (table->buckets[i] != NULL) {
            free(table->buckets[i]);
        }
    }
    free(table->buckets);
    free(table);
}

// Insert a record into the hash table
void hash_table_insert(HashTable *table, Record *record) {
    unsigned long index = hash_function(&record->key, sizeof(record->key)) % table->bucket_count;
    record->value = (void *)malloc(record->value_size);
    memcpy(record->value, &record->value[0], record->value_size);
    if (table->buckets[index] == NULL) {
        table->buckets[index] = (Record *)malloc(sizeof(Record));
    } else {
        Record *existing = table->buckets[index];
        while (existing->key != record->key && existing->next != NULL) {
            existing = existing->next;
        }
        if (existing->key == record->key) {
            // Update the value if a duplicate key is found
            free(existing->value);
            memcpy(existing->value, &record->value[0], record->value_size);
        } else {
            existing->next = (Record *)malloc(sizeof(Record));
            existing->next = record;
        }
    }
    table->record_count++;
}

// Retrieve a record from the hash table
Record *hash_table_lookup(HashTable *table, int key) {
    unsigned long index = hash_function(&key, sizeof(key)) % table->bucket_count;
    Record *current = table->buckets[index];
    while (current != NULL && current->key != key) {
        current = current->next;
    }
    return current;
}

// Delete a record from the hash table
void hash_table_delete(HashTable *table, int key) {
    unsigned long index = hash_function(&key, sizeof(key)) % table->bucket_count;
    Record *current = table->buckets[index];
    if (current != NULL && current->key == key) {
        free(current->value);
        free(current);
        table->record_count--;
    } else {
        while (current != NULL && current->key != key) {
            Record *next = current->next;
            free(current);
            current = next;
        }
        if (current != NULL) {
            free(current->value);
            free(current);
            table->record_count--;
        }
    }
}
