    for (int i = 0; i < 1000; i++) {
        if (!binary_search(unique_ints, unique_count, data)) {
            unique_ints[unique_count++] = data;
        }
    }

    // Find the largest integer in the unique array
    int largest_int = find_largest_int(unique_ints, unique_count);

    // Print the largest integer and close resources
    printf("The largest integer is: %d\n", largest_int);
    for (int i = 0; i < 1000; i++) {
        free(records[i]);
    }
    free(records);
    free(keys);
    free(offsets);
    close(sockfd);

    return 0;
}

// Helper function to find the largest integer in an array
int find_largest_int(int* arr, int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

// Helper function to perform binary search
int binary_search(int* arr, int size, int target) {
    int low = 0;
    int high = size - 1;

    while (low <= high) {
        int mid = (low + high) / 2;
        if (arr[mid] == target) {
            return 1; // Found
        }
        else if (arr[mid] < target) {
            low = mid + 1;
        }
        else {
            high = mid - 1;
        }
    }

    return 0; // Not found
}
