#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the record structure
typedef struct {
    long timestamp;
    int status_code;
    double value;
} Record;

// Define a struct to represent the dynamic collection of records
typedef struct {
    Record** records;
    size_t capacity;
    size_t size;
} RecordCollection;

// Function to create a new record collection
RecordCollection* record_collection_create(size_t initial_capacity) {
    RecordCollection* collection = (RecordCollection*) malloc(sizeof(RecordCollection));
    collection->records = (Record**) calloc(initial_capacity, sizeof(Record*));
    collection->capacity = initial_capacity;
    collection->size = 0;
    return collection;
}

// Function to free the record collection
void record_collection_free(RecordCollection* collection) {
    for(size_t i = 0; i < collection->size; i++) {
        if(collection->records[i] != NULL) {
            free(collection->records[i]);
        }
    }
    free(collection->records);
    free(collection);
}

// Function to add a new record to the collection
void record_collection_add(RecordCollection* collection, long timestamp, int status_code, double value) {
    if(collection->size >= collection->capacity) {
        // Double the capacity and reallocate memory
        Record** new_records = (Record**) realloc(collection->records, 2 * collection->capacity * sizeof(Record*));
        collection->capacity *= 2;
        collection->records = new_records;
    }

    if(find_record(collection, timestamp) != NULL) {
        // Timestamp already exists, do not add the record
        return;
    }

    Record* new_record = (Record*) malloc(sizeof(Record));
    new_record->timestamp = timestamp;
    new_record->status_code = status_code;
    new_record->value = value;
    collection->records[collection->size] = new_record;
    collection->size++;
}

// Function to find a record by its timestamp
Record* find_record(RecordCollection* collection, long target_timestamp) {
    for(size_t i = 0; i < collection->size; i++) {
        if(collection->records[i]->timestamp == target_timestamp) {
            return collection->records[i];
        }
    }
    return NULL;
}

// Function to update the status code of a record by its timestamp
void record_collection_update_status_code(RecordCollection* collection, long target_timestamp, int new_status_code) {
    Record* found_record = find_record(collection, target_timestamp);

    if(found_record != NULL) {
        found_record->status_code = new_status_code;
    } else {
        printf("No record found with timestamp %ld\n", target_timestamp);
    }
}

// Function to retrieve all records within a time window
void record_collection_retrieve_records(RecordCollection* collection, long start_timestamp, long end_timestamp) {
    for(size_t i = 0; i < collection->size; i++) {
        Record* current_record = collection->records[i];

        if(current_record->timestamp >= start_timestamp && current_record->timestamp <= end_timestamp) {
            printf("Timestamp: %ld, Status Code: %d, Value: %.2lf\n", 
                   current_record->timestamp, current_record->status_code, current_record->value);
        }
    }
}
