typedef struct record {
    float value;
    char *id;
    metadata *meta;
} record;

typedef struct batch {
    record **records;
    size_t capacity;
    size_t size;
} batch;

batch* create_batch(size_t initial_capacity) {
    batch *b = (batch*)malloc(sizeof(batch));
    b->records = (record**)calloc(initial_capacity, sizeof(record*));
    b->capacity = initial_capacity;
    b->size = 0;
    return b;
}

void resize_batch(batch *b, size_t new_size) {
    record **new_records = (record**)realloc(b->records, new_size * sizeof(record*));
    if (!new_records) {
        printf("Error: unable to resize batch\n");
        exit(1);
    }
    b->capacity = new_size;
    free(b->records);
    b->records = new_records;
}

void add_record(batch *b, record *r) {
    if (b->size >= b->capacity) {
        size_t new_capacity = b->capacity * 2;
        resize_batch(b, new_capacity);
    }
    b->records[b->size] = r;
    b->size++;
}

void free_batch(batch *b) {
    for (int i = 0; i < b->size; i++) {
        record *r = b->records[i];
        if (r->id)
            free(r->id);
        if (r->meta)
            free(r->meta);
        free(r);
    }
    free(b->records);
    free(b);
}

int main() {
    batch *b = create_batch(10);
    for (int i = 0; i < 5; i++) {
        record *r = (record*)malloc(sizeof(record));
        r->value = (float)i;
        r->id = strdup("record");
        r->meta = (metadata*)malloc(sizeof(metadata));
        r->meta->timestamp = i;
        r->meta->ref_count = 1;
        add_record(b, r);
    }
    free_batch(b);
    return 0;
}
