typedef struct {
    double value;
    int timestamp;
    char within_normal_limits;
} TemperatureMeasurement;

double sum = 0.0, squared_sum = 0.0;
int count = 0, max_temp = INT_MIN, min_temp = INT_MAX;

TemperatureMeasurement* measurements = NULL;
int measurement_count = 0;

void process_temperature(double temp) {
    if (temp < -50.0 || temp > 50.0) {
        // invalid temperature
        return;
    }

    if (measurement_count >= 100000) {
        // maximum number of measurements reached, stop processing
        return;
    }

    for (int i = 0; i < measurement_count; i++) {
        if (temp == measurements[i].value) {
            // duplicate temperature found, skip it
            return;
        }
    }

    measurements[measurement_count].value = temp;
    measurements[measurement_count].timestamp = rand();
    measurements[measurement_count].within_normal_limits = 'Y';  // assuming all temperatures are within normal limits for demonstration purposes

    if (temp > max_temp) {
        max_temp = temp;
    } else if (temp < min_temp) {
        min_temp = temp;
    }

    sum += temp;
    squared_sum += temp * temp;
    count++;

    measurement_count++;
}

void print_statistics() {
    printf("Smallest temperature: %.2f°C\n", min_temp);
    printf("Largest temperature: %.2f°C\n", max_temp);
    printf("Mean temperature: %.2f°C ± %.2f°C\n", sum / count, sqrt((squared_sum / count) - (sum / count) * (sum / count)));
}

int main() {
    // read temperatures from standard input and process them
    for (double temp; scanf("%lf", &temp) == 1; ) {
        process_temperature(temp);
    }

    print_statistics();

    return 0;
}
