typedef struct {
    long timestamp;
    int id;
    float measurement;
    struct {
        int value;
        struct node *next;
    } *node_ptr;
} event_t;

event_t *event_alloc(int id, float measurement) {
    event_t *event = (event_t *)malloc(sizeof(event_t));
    if (!event) return NULL;
    event->timestamp = time(NULL);
    event->id = id;
    event->measurement = measurement;
    return event;
}

void process_events(event_t **events, int num_events) {
    for (int i = 0; i < num_events; i++) {
        // Initialize the node
        struct node *node = malloc(sizeof(struct node));
        if (!node) perror("Memory allocation failed");
        node->value = rand();
        node->next = NULL;

        event_t *event = event_alloc(i, (float)(rand() / RAND_MAX));
        if (!event) continue;
        event->node_ptr = &node;
    }
}

int main(int argc, char **argv) {
    // Initialize random number generator
    srand(time(NULL));

    int num_events = 1000; // Number of events to process
    event_t *events = NULL;

    for (int i = 0; i < num_events; i++) {
        event_t *event = event_alloc(i, (float)(rand() / RAND_MAX));
        if (!event) continue;
        // Add the event to the array
        events = realloc(events, (num_events + 1) * sizeof(event_t *));
        if (!events) perror("Memory allocation failed");
        events[num_events++] = event;
    }

    process_events(&events, num_events);

    return 0;
}
