#include <iostream>
#include <string>
#include <memory>
#include <vector>
#include <map>
#include <boost/property_tree/ptree.hpp>
#include <boost/property_tree/xml_parser.hpp>

void initStructures(std::map<std::string, std::shared_ptr<std::map<std::string, std::any>>>& structures) {
    structures["strings"] = std::make_shared<std::map<std::string, std::string>>();
    structures["vectors"] = std::make_shared<std::map<std::string, std::shared_ptr<std::vector<int>>>>();
    structures["unique_ptrs"] = std::make_shared<std::map<std::string, std::unique_ptr<CustomData>>>();
    structures["pairs"] = std::make_shared<std::map<std::string, std::pair<int, std::string>>>();

    for (int i = 0; i < 10; ++i) {
        auto stringId = "string_" + std::to_string(i);
        structures["strings"]->emplace(stringId, "unique_identifier_" + std::to_string(i));

        auto vectorId = "vector_" + std::to_string(i);
        std::shared_ptr<std::vector<int>> randomVector = std::make_shared<std::vector<int>>();
        for (int j = 0; j < 10; ++j) {
            randomVector->emplace_back(rand() % 100);
        }
        structures["vectors"]->emplace(vectorId, randomVector);

        auto uniquePtrId = "unique_ptr_" + std::to_string(i);
        std::unique_ptr<CustomData> customData = std::make_unique<CustomData>();
        for (int j = 0; j < 10; ++j) {
            customData->floatVector.emplace_back(rand() % 100.0f);
        }
        structures["unique_ptrs"]->emplace(uniquePtrId, std::move(customData));

        auto pairId = "pair_" + std::to_string(i);
        structures["pairs"]->emplace(pairId, std::make_pair(i, "string_value_" + std::to_string(i)));
    }
}

class CustomData {
public:
    std::vector<float> floatVector;
};

int main() {
    std::map<std::string, std::shared_ptr<std::map<std::string, std::any>>> structures;

    initStructures(structures);

    // serialize the map to a property tree
    boost::property_tree::ptree pt;
    for (const auto& pair : *structures["strings"]) {
        pt.put(pair.first, pair.second.as<std::string>());
    }
    for (const auto& pair : *structures["vectors"]) {
        boost::property_tree::ptree vectorPt;
        for (int i = 0; i < pair.second->size(); ++i) {
            vectorPt.add("value", std::to_string(pair.second->at(i)));
        }
        pt.put(pair.first, vectorPt);
    }
    for (const auto& pair : *structures["unique_ptrs"]) {
        boost::property_tree::ptree uniquePtrPt;
        for (float f : pair.second->floatVector) {
            uniquePtrPt.add("value", std::to_string(f));
        }
        pt.put(pair.first, uniquePtrPt);
    }
    for (const auto& pair : *structures["pairs"]) {
        pt.put(pair.first, pair.second.first);
        pt.put("string_value_" + std::to_string(pair.second.first), pair.second.second);
    }

    // write the property tree to an XML file
