#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long timestamp;
    int status_code;
    double value;
} Record;

Record* records = NULL;
int record_count = 0;
int capacity = 0;

void insert_record(long timestamp, int status_code, double value) {
    if (record_count >= capacity) {
        capacity *= 2;
        records = realloc(records, sizeof(Record) * capacity);
    }
    Record new_record;
    new_record.timestamp = timestamp;
    new_record.status_code = status_code;
    new_record.value = value;
    for (int i = record_count; i > 0; i--) {
        records[i] = records[i - 1];
    }
    records[0] = new_record;
    record_count++;
}

void retrieve_records(long start, long end) {
    printf("Records inserted within time window [%ld, %ld]:\n", start, end);
    for (int i = 0; i < record_count; i++) {
        if (start <= records[i].timestamp && records[i].timestamp <= end) {
            printf("Timestamp: %ld, Status Code: %d, Value: %f\n", 
                   records[i].timestamp, records[i].status_code, records[i].value);
        }
    }
}

void update_status(long timestamp, int new_status_code) {
    for (int i = 0; i < record_count; i++) {
        if (records[i].timestamp == timestamp) {
            records[i].status_code = new_status_code;
            break;
        }
    }
}

void reverse_iterate() {
    printf("Records in reverse order of insertion:\n");
    for (int i = record_count - 1; i >= 0; i--) {
        printf("Timestamp: %ld, Status Code: %d, Value: %f\n", 
               records[i].timestamp, records[i].status_code, records[i].value);
    }
}

void free_records() {
    free(records);
    record_count = 0;
    capacity = 0;
}

int main() {
    // Initialize messaging system
    printf("Initializing messaging system...\n");
    //...

    while (1) {
        int choice;
        printf("Choose an option:\n1. Insert Record\n2. Retrieve Records\n3. Update Status\n4. Reverse Iterate\n5. Exit\n");
        scanf("%d", &choice);
        switch (choice) {
            case 1:
                long timestamp;
                int status_code;
                double value;
                printf("Enter timestamp, status code, and value: ");
                scanf("%ld %d %lf", &timestamp, &status_code, &value);
                insert_record(timestamp, status_code, value);
                break;
            case 2:
                long start, end;
                printf("Enter time window start and end timestamps: ");
                scanf("%ld %ld", &start, &end);
                retrieve_records(start, end);
                break;
            case 3:
                long timestamp_update;
                int new_status_code;
                printf("Enter timestamp to update and new status code: ");
                scanf("%ld %d", &timestamp_update, &new_status_code);
                update_status(timestamp_update, new_status_code);
                break;
            case 4:
                reverse_iterate();
                break;
            case 5:
                free_records();
                return 0;
        }
    }

    return 0;
}
