typedef struct {
    int key;
    float value;
    char* description;
} Record;

Record** records = NULL;
int record_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int memory_limit = 1024 * 1024; // 1MB

void create_record(int key, float value, char* description) {
    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        printf("Memory allocation failed!\n");
        return;
    }
    new_record->key = key;
    new_record->value = value;
    new_record->description = description;
    records = realloc(records, (record_count + 1) * sizeof(Record*));
    if (!records) {
        printf("Memory allocation failed!\n");
        free(new_record);
        return;
    }
    records[record_count] = new_record;
    record_count++;
}

void load_records_from_file(const char* file_path) {
    FILE* file = fopen(file_path, "rb");
    if (!file) {
        printf("Failed to open file!\n");
        return;
    }

    Record* temp_records = (Record*)malloc(record_count * sizeof(Record));
    int read_bytes = fread(temp_records, sizeof(Record), record_count, file);
    fclose(file);

    for (int i = 0; i < record_count; i++) {
        records[i] = &temp_records[i];
    }
    free(temp_records);
}

void print_records() {
    for (int i = 0; i < record_count; i++) {
        printf("Key: %d, Value: %.2f, Description: %s\n", records[i]->key, records[i]->value, records[i]->description);
    }
}

void* monitor_memory_and_disk_usage(void*) {
    while (1) {
        // Monitor memory usage
        if (getpagesize() * getrusage(RUSAGE_SELF).ru_maxrss > memory_limit) {
            printf("Memory usage exceeded the limit!\n");
            break;
        }

        // Monitor disk space
        struct statfs statbuf;
        fstatfs(STDIN_FILENO, &statbuf);
        if (statbuf.f_blocks * statbuf.f_bsize < memory_limit) {
            printf("Disk space exceeded the limit!\n");
            break;
        }
    }
}

int main() {
    pthread_t thread;
    pthread_create(&thread, NULL, monitor_memory_and_disk_usage, NULL);

    // Create records
    create_record(1, 2.5f, "Record 1");
    create_record(2, 3.7f, "Record 2");
    create_record(3, 4.9f, "Record 3");

    // Load records from file
    load_records_from_file("records.bin");

    // Print records
    print_records();

    pthread_join(thread, NULL);

    for (int i = 0; i < record_count; i++) {
        free(records[i]->description);
        free(records[i]);
    }
    free(records);

    return 0;
}
