#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Node {
    int value;
    char* identifier;
    struct Node* next;
} Node;

Node* createLinkedList(int rangeStart, int rangeEnd) {
    srand(time(NULL));
    Node* head = NULL;
    Node* current = NULL;

    for (int i = 0; i < 10; i++) { // Create a linked list with 10 nodes
        Node* newNode = malloc(sizeof(Node));
        if (!newNode) {
            free(newNode);
            printf("Memory allocation failed!\n");
            return NULL;
        }

        int randValue = (rand() % (rangeEnd - rangeStart + 1)) + rangeStart;
        char identifier[10];
        sprintf(identifier, "ID_%d", i);

        newNode->value = randValue;
        newNode->identifier = strdup(identifier);
        newNode->next = NULL;

        if (!head) {
            head = current = newNode;
        } else {
            current->next = newNode;
            current = newNode;
        }
    }

    return head;
}

void freeLinkedList(Node* head) {
    Node* current = head;
    Node* next = NULL;

    while (current) {
        next = current->next;
        free(current->identifier);
        free(current);
        current = next;
    }
}
