use reqwest::blocking::{get, post};
use reqwest::header;
use std::sync::Arc;
use std::thread;

// Define a struct to hold request and response data
struct Request {
    url: String,
    method: String,
    headers: Vec<(String, String)>,
}

impl Request {
    fn new(url: &str, method: &str) -> Self {
        Request {
            url: url.to_string(),
            method: method.to_string(),
            headers: vec![],
        }
    }

    fn send(&self) -> Result<String, reqwest::Error> {
        match self.method.as_str() {
            "GET" => get(&self.url),
            "POST" => post(&self.url).body("{}"),
            _ => Err(reqwest::Error::new("Invalid method")),
        }
    }
}

// Define a struct to hold response data
struct Response {
    status_code: u16,
    body: String,
}

impl Response {
    fn new(status_code: u16, body: &str) -> Self {
        Response {
            status_code,
            body: body.to_string(),
        }
    }

    fn from_request(request: Request) -> Result<Self, reqwest::Error> {
        let response = request.send()?;
        Ok(Response::new(response.status(), response.text()?))
    }
}

// Define a struct to hold configuration options
struct Config {
    timeout: u16,
    backoff_strategy: String,
}

impl Config {
    fn new(timeout: u16, backoff_strategy: &str) -> Self {
        Config {
            timeout,
            backoff_strategy: backoff_strategy.to_string(),
        }
    }
}

// Define a struct to hold retry options
struct RetryOptions {
    max_attempts: u16,
    initial_delay: u16,
}

impl RetryOptions {
    fn new(max_attempts: u16, initial_delay: u16) -> Self {
        RetryOptions { max_attempts, initial_delay }
    }
}
