void add_task(Task* task) {
    pthread_mutex_lock(&lock);
    if (num_tasks >= MAX_TASKS) {
        fprintf(stderr, "Error: Maximum number of tasks exceeded.\n");
        return;
    }

    // Check memory limit
    size_t total_memory_usage = 0;
    for (int i = 0; i < num_tasks; i++) {
        total_memory_usage += sizeof(Task) + task[i].schedule->duration * sizeof(time_t);
    }
    if (total_memory_usage > MEMORY_LIMIT) {
        fprintf(stderr, "Error: Total memory usage exceeds the limit.\n");
        return;
    }

    tasks[num_tasks++] = task;
    pthread_mutex_unlock(&lock);
}

void remove_task(Task* task) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < num_tasks; i++) {
        if (tasks[i] == task) {
            // Release resources
            free(task->name);
            free(task->schedule);
            tasks[i] = tasks[--num_tasks];
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

void* schedule_tasks(void*) {
    while (1) {
        pthread_mutex_lock(&lock);
        for (int i = 0; i < num_tasks; i++) {
            if (!tasks[i]->schedule->active) {
                // Execute task
                printf("Executing task: %s\n", tasks[i]->name);
                sleep(tasks[i]->schedule->duration);
                break;
            }
        }
        pthread_mutex_unlock(&lock);
    }
    return NULL;
}

int main() {
    pthread_t thread;

    Task* task1 = (Task*)malloc(sizeof(Task));
    task1->name = strdup("Task 1");
    task1->priority = 3;
    task1->schedule = (Schedule*)malloc(sizeof(Schedule));
    task1->schedule->start_time = time(NULL);
    task1->schedule->duration = 5;
    task1->schedule->active = true;

    Task* task2 = (Task*)malloc(sizeof(Task));
    task2->name = strdup("Task 2");
    task2->priority = 2;
    task2->schedule = (Schedule*)malloc(sizeof(Schedule));
    task2->schedule->start_time = time(NULL) + 3;
    task2->schedule->duration = 7;
    task2->schedule->active = true;

    add_task(task1);
    add_task(task2);

    pthread_create(&thread, NULL, &schedule_tasks, NULL);
    pthread_join(thread, NULL);

    for (int i = 0; i < num_tasks; i++) {
        remove_task(tasks[i]);
    }

    return 0;
}
