typedef struct {
    double avg;
    char data[256];
} DataStruct;

void* thread_func(void* arg) {
    // parse file and calculate average
    FILE* file = fopen((char*)arg, "r");
    if (!file) return NULL;

    DataStruct* result = (DataStruct*)malloc(sizeof(DataStruct));
    double sum = 0;
    int count = 0;
    char buffer[256];
    while (fgets(buffer, sizeof(buffer), file)) {
        double val = atof(strtok(buffer, ","));
        sum += val;
        count++;
    }
    fclose(file);

    if (count > 0) {
        result->avg = sum / count;
    } else {
        result->avg = 0.0;
    }

    free(arg);
    return result;
}

DataStruct* process_requests(int num_requests, char** files) {
    pthread_t threads[num_requests];
    DataStruct results[num_requests];

    for (int i = 0; i < num_requests; i++) {
        int ret = pthread_create(&threads[i], NULL, thread_func, (void*)files[i]);
        if (ret != 0) {
            // handle error
            return NULL;
        }
    }

    for (int i = 0; i < num_requests; i++) {
        void* result = pthread_join(threads[i], NULL);
        DataStruct* res = (DataStruct*)result;
        results[i] = *res;
        free(res);
    }

    DataStruct* response = (DataStruct*)malloc(sizeof(DataStruct) * num_requests);
    for (int i = 0; i < num_requests; i++) {
        response[i] = results[i];
    }

    return response;
}

int main() {
    int num_requests = 5;
    char** files = {"file1.txt", "file2.txt", ..., "file5.txt"};

    DataStruct* response = process_requests(num_requests, files);
    // handle response
    return 0;
}
