// Node structure definition
typedef struct node {
    int value;
    char* id;
    struct node* next;
} Node;

// Dynamic allocation and initialization of linked list nodes
Node* create_node(int value, char* id) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        printf("Memory allocation failed!\n");
        return NULL;
    }
    new_node->value = value;
    new_node->id = id;
    new_node->next = NULL;
    return new_node;
}

// Linked list operations
void insert_node(Node** head, int value, char* id) {
    Node* new_node = create_node(value, id);
    if (*head == NULL || strcmp((*head)->id, id) > 0) {
        new_node->next = *head;
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next && strcmp(current->next->id, id) < 0) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
}

void delete_node(Node** head, char* id) {
    Node* current = *head;
    Node* prev = NULL;
    while (current && strcmp(current->id, id) != 0) {
        prev = current;
        current = current->next;
    }
    if (current) {
        if (prev) {
            prev->next = current->next;
        } else {
            *head = current->next;
        }
        free(current);
    }
}

void traverse_list(Node* head) {
    Node* current = head;
    while (current) {
        printf("Value: %d, ID: %s\n", current->value, current->id);
        current = current->next;
    }
}

// Main C function
int main() {
    // Initialize linked list
    Node* head = NULL;

    // Create nodes and perform operations
    insert_node(&head, 1, "node1");
    insert_node(&head, 2, "node2");
    delete_node(&head, "node1");
    traverse_list(head);

    return 0;
}
