import asyncio
import logging

# Network service definition
class NetworkService:
    def __init__(self):
        self.loop = asyncio.get_event_loop()
        self.connections = {}

    async def handle_request(self, request_id):
        await asyncio.sleep(1)  # Simulate processing time
        if request_id in self.connections:
            del self.connections[request_id]
        else:
            logging.warning(f"Unknown request ID: {request_id}")

    def start(self):
        self.loop.run_until_complete(self.listen())

    async def listen(self):
        while True:
            try:
                request_id = await self.loop.sock_accept()
                if request_id:
                    self.connections[request_id] = asyncio.create_task(self.handle_request(request_id))
            except Exception as e:
                logging.error(f"Error handling request: {e}")

# Main Python function
if __name__ == "__main__":
    network_service = NetworkService()
    network_service.start()
