typedef struct {
    long offset;
    int key;
    double value;
} record_t;

record_t* create_record() {
    record_t* rec = (record_t*)malloc(sizeof(record_t));
    if(rec == NULL) return NULL; // handle memory allocation failure
    rec->offset = rand() % 1000000 + 1;
    rec->key = rand() % 1000 + 1;
    rec->value = (double)rand() / RAND_MAX;
    return rec;
}

void update_record(record_t* rec, long offset, int key, double value) {
    if(rec == NULL || rec->offset != offset || rec->key != key)
        return; // handle invalid input
    rec->value = value;
}

void delete_record(record_t** records, int count, record_t* rec) {
    int i;
    for(i = 0; i < count; i++) {
        if(records[i] == rec) {
            free(rec);
            *records = realloc(records, (count - 1)*sizeof(record_t));
            for(int j = i; j < count - 1; j++)
                records[j] = &records[j+1];
            return;
        }
    }
}

record_t* get_record(record_t** records, int count, long offset) {
    int i;
    for(i = 0; i < count; i++) {
        if(records[i]->offset == offset)
            return records[i];
    }
    return NULL;
}
