Record** allocateRecords(int count) {
    Record** records = (Record**)malloc(count * sizeof(Record*));
    if (!records) {
        return NULL; // memory allocation failure
    }
    for (int i = 0; i < count; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) {
            free(records);
            return NULL; // memory allocation failure
        }
        int random_integer = rand() % 100;
        long* offset = (long*)malloc(sizeof(long));
        *offset = rand();
        records[i]->integer = random_integer;
        records[i]->offset = offset;
        double dataPoint = ((double)rand()) / RAND_MAX;
        records[i]->dataPoint = dataPoint;
    }
    return records;
}

void deallocateRecords(Record** records, int count) {
    for (int i = 0; i < count; i++) {
        free(records[i]->offset);
        free(records[i]);
    }
    free(records);
}

pthread_mutex_t recordMutex = PTHREAD_MUTEX_INITIALIZER;

void updateRecord(Record* record) {
    pthread_mutex_lock(&recordMutex);
    // update record fields
    pthread_mutex_unlock(&recordMutex);
}

int main() {
    int count = 1000;
    Record** records = allocateRecords(count);
    if (!records) {
        printf("Memory allocation failed.\n");
        return -1; // error handling
    }

    FILE* file = fopen("data.bin", "wb");
    if (file == NULL) {
        printf("Error opening file for writing.\n");
        deallocateRecords(records, count);
        return -1; // error handling
    }

    fwrite(&records[0], sizeof(Record), count, file);

    fclose(file);

    deallocateRecords(records, count);

    return 0;
}
