        return 1;
    }

    struct entry** char_status = malloc(sizeof(struct entry*) * NUM_ENTRIES);
    if(char_status == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(float_values);
        return 1;
    }

    pthread_create(&thread, NULL, init_entries, (void*)float_values);

    // Synchronize with remote server
    pthread_join(thread, NULL);

    for(int i = 0; i < NUM_ENTRIES; i++) {
        free(float_values[i]);
        free(char_status[i]);
    }

    free(float_values);
    free(char_status);

    return 0;
}
