#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <string.h>

#define MAX_RECORDS 1000
#define MAX_STRING_LENGTH 50
#define MIN_INT_VALUE 0
#define MAX_INT_VALUE 1000
#define STRING_BUFFER_SIZE (MAX_STRING_LENGTH + 1)

typedef struct {
    int value;
    char* string;
} Record;

Record** records;
int* offsets;
int* keys;
char** strings;

void allocateMemory(int size) {
    if (!records) {
        records = malloc(size * sizeof(Record*));
    }
    if (!offsets) {
        offsets = malloc(size * sizeof(int));
    }
    if (!keys) {
        keys = malloc(size * sizeof(int));
    }
    if (!strings) {
        strings = malloc(size * sizeof(char*));
    }

    for (int i = 0; i < size; i++) {
        records[i] = malloc(sizeof(Record));
        char buffer[STRING_BUFFER_SIZE];
        sprintf(buffer, "record_%d", i);
        strings[i] = malloc(strlen(buffer) + 1);
        strcpy(strings[i], buffer);
    }
}

void initializeRecords(int size) {
    for (int i = 0; i < size; i++) {
        records[i]->value = rand() % (MAX_INT_VALUE - MIN_INT_VALUE + 1) + MIN_INT_VALUE;
    }
}

void serializeToFile(char* filename, int size) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        printf("Error opening file: %s\n", filename);
        return;
    }

    for (int i = 0; i < size; i++) {
        fwrite(&records[i]->value, sizeof(int), 1, file);
        size_t stringLen = strlen(strings[i]);
        fwrite(&stringLen, sizeof(size_t), 1, file);
        fwrite(strings[i], sizeof(char), stringLen + 1, file);
    }

    fclose(file);
}

void deserializeFromFile(char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        printf("Error opening file: %s\n", filename);
        return;
    }

    int size;
    fread(&size, sizeof(int), 1, file);

    for (int i = 0; i < size; i++) {
        Record* record = &records[i];
        fread(&record->value, sizeof(int), 1, file);
        size_t stringLen;
        fread(&stringLen, sizeof(size_t), 1, file);
        char buffer[stringLen + 1];
        fread(buffer, sizeof(char), stringLen + 1, file);
        record->string = malloc(stringLen + 1);
        strcpy(record->string, buffer);
    }

    fclose(file);
}

int main() {
    srand(time(NULL));

    allocateMemory(MAX_RECORDS);

    initializeRecords(MAX_RECORDS);

    char* filename = "records.dat";
    serializeToFile(filename, MAX_RECORDS);

    deserializeFromFile(filename);

    // Clean up allocated memory
    for (int i = 0; i < MAX_RECORDS; i++) {
        free(records[i]->string);
        free(records[i]);
    }
    free(strings);
    free(keys);
    free(offsets);
    free(records);

    return 0;
}
```']

