    time_t timestamp = time(NULL);
    char timestampStr[20];
    strftime(timestampStr, sizeof(timestampStr), "%Y%m%d_%H%M%S", localtime(&timestamp));

    for(int i=strlen(originalFile)-1; i>=0; i--) {
