typedef struct {
    long offset;
    int key;
} record;

record* generateRecords(int numElements, int rangeStart, int rangeEnd, unsigned seed) {
    if (numElements <= 0) {
        return NULL;
    }

    record* records = malloc(numElements * sizeof(record));
    if (!records) {
        return NULL; // memory allocation failed
    }

    srand(seed);

    for (int i = 0; i < numElements; i++) {
        records[i].offset = (long)(rand() % (rangeEnd - rangeStart + 1)) + rangeStart;
        records[i].key = rand() % (rangeEnd - rangeStart + 1) + rangeStart;
    }

    return records;
}

int verifyUniqueness(record* records, int numElements) {
    for (int i = 0; i < numElements; i++) {
        for (int j = i + 1; j < numElements; j++) {
            if (records[i].offset == records[j].offset || records[i].key == records[j].key) {
                return 0; // duplicate found
            }
        }
    }
    return 1; // unique values found
}

void freeRecords(record* records, int numElements) {
    for (int i = 0; i < numElements; i++) {
        free((void*)&records[i]);
    }
    free(records);
}
