    for (int i = 0; i < num_tasks; i++) {
        tasks[i] = malloc(sizeof(task));
        if (!tasks[i]) {
            fprintf(stderr, "Error allocating memory\n");
            return NULL;
        }
        tasks[i]->priority = rand() % (max_priority - min_priority + 1) + min_priority;
        // Validate syntax and allocate the command string
        size_t cmd_len = strlen(command_list[i]);
        if (cmd_len > max_cmd_len) {
            cmd_len = max_cmd_len;
        }
        tasks[i]->command = malloc(cmd_len + 1);
        if (!tasks[i]->command) {
            fprintf(stderr, "Error allocating memory\n");
            return NULL;
