#include <stdlib.h>
#include <stdio.h>
#include <string.h>

typedef enum {
    PENDING,
    RUNNING,
    COMPLETED,
    FAILED
} task_state;

typedef struct {
    int priority;
    char* command;
    int* argument;
    task_state state;
} task;

task** create_tasks(int num_tasks, int min_priority, int max_priority) {
    task** tasks = (task**)malloc(num_tasks * sizeof(task*));
    for (int i = 0; i < num_tasks; i++) {
        tasks[i] = (task*)malloc(sizeof(task));
        tasks[i]->priority = rand() % (max_priority - min_priority + 1) + min_priority;
        tasks[i]->command = malloc(strlen("Command ") + 10);
        strcpy(tasks[i]->command, "Command ");
        sprintf((char*)(tasks[i]->argument), "%d", i);
        tasks[i]->state = PENDING;
    }
    return tasks;
}

void update_task_status(task** tasks, task_state new_state) {
    // Implement dependency resolution algorithm
    for (int i = 0; i < num_tasks; i++) {
        if (tasks[i]->state == PENDING && new_state != FAILED) {
            tasks[i]->state = new_state;
        }
    }
}

