#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

// Define the task structure
typedef struct {
    char* description;
    time_t timestamp;
    int priority;
} Task;

// Define the linked list node structure
typedef struct Node {
    Task task;
    struct Node* next;
} Node;

// Function to dynamically allocate memory for and initialize an array of 'task' structures
Task** allocateTasks(int numTasks) {
    Task** tasks = (Task**)malloc(numTasks * sizeof(Task*));
    for (int i = 0; i < numTasks; i++) {
        tasks[i] = (Task*)malloc(sizeof(Task));
    }
    return tasks;
}

// Function to create a new linked list node
Node* newNode(Task task) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->task = task;
    node->next = NULL;
    return node;
}

// Function to add a new task to the linked list
void addTask(Node** head, Task task) {
    Node* newNode = newNode(task);
    if (*head == NULL) {
        *head = newNode;
    } else {
        Node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
}

// Function to print the linked list
void printTasks(Node* head) {
    Node* current = head;
    while (current != NULL) {
        printf("Description: %s, Timestamp: %lu, Priority: %d\n", current->task.description, current->task.timestamp, current->task.priority);
        current = current->next;
    }
}

int main() {
    int numTasks = 5; // Example number of tasks
    Task** tasks = allocateTasks(numTasks);

    // Initialize the linked list
    Node* head = NULL;

    // Add tasks to the linked list
    for (int i = 0; i < numTasks; i++) {
        addTask(&head, *(tasks + i));
    }

    // Print the linked list
    printTasks(head);

    return 0;
}
