// Dynamic memory allocation function
record* allocate_record(int num_events) {
    record* new_record = (record*)malloc(sizeof(record));
    if (!new_record) return NULL; // Handle malloc error

    new_record->offset = 0;
    new_record->key = 0;
    strcpy(new_record->timestamp, "");
    strcpy(new_record->status, "");
    strcpy(new_record->reference, "");

    // Allocate memory for the linked list of events
    event* events = (event*)malloc(sizeof(event) * num_events);
    if (!events) return NULL; // Handle malloc error

    new_record->events = &events[0];
    return new_record;
}

// Initialize the record structure with timestamp, status, and reference information
void init_record(record* r, const char* timestamp, const char* status, const char* reference) {
    strcpy(r->timestamp, timestamp);
    strcpy(r->status, status);
    strcpy(r->reference, reference);
}

// Insert a new event into the record's linked list
void add_event(record* r, int id, const char* description) {
    // Create a new event structure and initialize its attributes
    event* new_event = (event*)malloc(sizeof(event));
    if (!new_event) return; // Handle malloc error

    new_event->id = id;
    strcpy(new_event->description, description);

    // Add the new event to the linked list
    event* current = r->events;
    while (current && current->next) {
        current = current->next;
    }
    current->next = new_event;
}

// Remove an event from the record's linked list
void remove_event(record* r, int id) {
    // Find the event with matching ID and remove it from the linked list
    event* current = r->events;
    while (current && current->next) {
        if (current->id == id) {
            event* temp = current->next;
            free(current);
            current = temp;
        } else {
            current = current->next;
        }
    }
}

// Deallocate memory for a record and its events
void deallocate_record(record* r) {
    // Free the linked list of events
    event* current = r->events;
    while (current && current->next) {
        event* temp = current->next;
        free(current);
        current = temp;
    }
    free(r);
}

// Thread-safe locking mechanism for concurrent access
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* data_manager(void* arg) {
