    record* r = allocate_record(10);
    init_record(r, "2022-01-01", "READY", "REF-001");

    // Insert new events into the record's linked list
    add_event(r, 1, "Event 1");
    add_event(r, 2, "Event 2");
    add_event(r, 3, "Event 3");

    // Remove an event from the record's linked list
    remove_event(r, 2);

    // Deallocate memory for the record and its events
    deallocate_record(r);

    return NULL;
}
