#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct record {
    int key;
    int offset;
    int ref_count;
} Record;

void* mem_manager(int num_records, int max_offset) {
    // Initialize a lock for thread-safe access
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    void* pool = malloc(num_records * sizeof(Record));
    if (!pool) return NULL;  // Allocation failed

    // Initialize each record's fields to random values
    srand(time(NULL));
    Record* records = (Record*)pool;
    for (int i = 0; i < num_records; i++) {
        records[i].key = rand() % 10000;
        records[i].offset = rand() % max_offset;
        records[i].ref_count = 0;
    }

    // Define a function to increment and decrement the reference count
    void ref_counter(Record* record, int delta) {
        pthread_mutex_lock(&lock);
        record->ref_count += delta;
        pthread_mutex_unlock(&lock);
    }

    // Define a function to search for records by key
    Record* find_record(int key) {
        Record* result = NULL;
        pthread_mutex_lock(&lock);
        for (int i = 0; i < num_records; i++) {
            if (records[i].key == key) {
                result = &records[i];
                break;
            }
        }
        pthread_mutex_unlock(&lock);
        return result;
    }

    // Define a function to flush unused records
    void flush_unused(int threshold) {
        int count = 0;
        Record* it = pool;
        for (int i = 0; i < num_records; i++) {
            if (it[i].ref_count <= threshold) {
                count++;
            } else {
                break;
            }
        }

        // Deallocate unused records
        memmove(pool, it + count, (num_records - count) * sizeof(Record));
        pool = realloc(pool, (num_records - count) * sizeof(Record));

        // Update the number of records and maximum offset
        num_records -= count;
        max_offset -= (it[count - 1].offset > max_offset ? max_offset : it[count - 1].offset);
    }

    return &records;
}
