int allocateDataStructures(int numOffsets, int numKeys, int capacity) {
    long* offsets = malloc(numOffsets * sizeof(long));
    if (!offsets) return -1;
    for (int i = 0; i < numOffsets; ++i) {
        offsets[i] = i; // initialize with sequential values
    }

    int* keys = malloc(numKeys * sizeof(int));
    if (!keys) return -2;

    record** records = malloc(capacity * sizeof(record*)); // linked list capacity
    if (!records) return -3;

    for (int i = 0; i < capacity; ++i) {
        records[i] = createRecord(rand() % 100, "record_name"); // random values and names
    }

    // Custom pool allocator implementation
    void* poolBase = malloc(1024 * 1024); // assume a 1MB initial allocation
    size_t poolSize = 1024 * 1024;
    size_t poolFree = poolSize;

    // initialize the linked list
    record* head = NULL;
    for (int i = 0; i < capacity; ++i) {
        record* r = records[i];
        if (!head) {
            head = r;
        } else {
            record* prev = head;
            while (prev->next) prev = prev->next;
            prev->next = r;
        }
    }

    // cleanup
    free(offsets);
    free(keys);
    free(records);
    free(poolBase);

    return 0; // success
}
