    auto start = std::chrono::high_resolution_clock::now();

    // Initialize SDR modules
    std::vector<std::shared_ptr<SdrModule>> sdrModules;
    for (int i = 0; i < 5000; ++i) {
        sdrModules.push_back(std::make_shared<SdrModule>());
