        coll->values[i] = item->value;
        coll->items[i] = item;
    }

    return coll;
}

void free_collection(collection* coll) {
    for (int i = 0; i < coll->size; i++) {
        free(coll->items[i]->id);
        free(coll->items[i]);
    }
    free(coll->values);
