record** manage_memory(int size, int key_range, int offset_range, int resizeable) {
    // Initialize arrays
    long* offsets = (long*)malloc(size * sizeof(long));
    int* keys = (int*)malloc(size * sizeof(int));
    record* records = (record*)malloc(size * sizeof(record));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Initialize arrays
    for (int i = 0; i < size; i++) {
        offsets[i] = rand() % offset_range;
        keys[i] = rand() % key_range;
    }

    for (int i = 0; i < size; i++) {
        records[i].integer = 0;
        char* string = (char*)malloc(65);
        if (!string) {
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }
        // Initialize random strings
        for (int j = 0; j < 64; j++) {
            string[j] = 'a' + rand() % 26;
        }
        string[64] = '\0';
        records[i].string = string;
    }

    // Update record values
    for (int i = 0; i < size; i++) {
        if (!update_value(&records[i], offsets[i], keys[i])) {
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }
    }

    // Resize records if necessary
    if (resizeable) {
        record** resized_records = resize_records(size, &records);

        if (!resized_records) {
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        } else {
            for (int i = 0; i < size; i++) {
                records[i] = resized_records[i][0];
                free(resized_records[i]);
            }
            free(resized_records);
        }
    }

    // Deallocate temporary arrays
    free(offsets);
    free(keys);

    return &records;
}

int update_value(record* record, long offset, int key) {
    if (!record) {
        return 0; // Return failure for invalid input
    }
    // Update value using a predefined function that may fail
    record->integer = get_sum(offset, key);
    return 1; // Return success
}

// Function to resize records based on dynamic allocation requirements
record** resize_records(int size, record** original) {
    if (!original || !size) {
        return NULL;
    }
    int new_size = size * 2;
    record* resized_records = (record*)malloc(new_size * sizeof(record));

    if (!resized_records) {
        return NULL; // Return failure for memory allocation
    }

    for (int i = 0; i < size; i++) {
        resized_records[i] = original[i];
    }

    free(original);
    return &resized_records;
}
