Node* init_node_list(int max_nodes);
void add_child(Node** head, Node* new_child);

int main() {
    // Initialize the node list
    int max_nodes = 1000; // adjust according to your needs
    Node* root = init_node_list(max_nodes);

    return 0;
}

Node* init_node_list(int max_nodes) {
    Node* head = NULL;
    Node** nodes = (Node**)malloc((max_nodes + 1) * sizeof(Node*));
    for (int i = 0; i <= max_nodes; i++) {
        nodes[i] = NULL;
    }

    // Populate the node list with random data from a CSV file
    FILE* file = fopen("data.csv", "r");
    if (!file) {
        perror("Error opening file");
        return head;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        // Read ID from CSV
        int id = atoi(strtok(line, ",")); 
        new_node->id = id;
        // Generate random value and name for demonstration purposes
        srand(time(NULL));
        float value = rand() / (float)RAND_MAX;
        char* name = malloc(32 * sizeof(char));
        sprintf(name, "Task %d", id);
        new_node->value = value;
        strcpy(new_node->name, name);
        new_node->priority = rand() % 10; 

        add_child(&head, new_node);

        free(name);
    }

    fclose(file);

    return head;
}

void add_child(Node** head, Node* new_child) {
    if (!*head) {
        *head = new_child;
    } else {
        // Find the last child node
        Node* current = *head;
        while (current->child) {
            current = current->child;
        }
        // Add the new child to the end of the list
        current->child = new_child;
    }
}
