void initialize_record_task_system(int num_records, int max_cmd_len, int min_priority, int max_priority) {
    record_task* record_tasks = NULL;
    status* statuses = NULL;

    while (1) {
        record_tasks = (record_task*)malloc(num_records * sizeof(record_task));
        if (!record_tasks) {
            // Handle memory allocation failure
            fprintf(stderr, "Failed to allocate memory for record tasks.\n");
            return;
        }

        statuses = (status*)malloc(num_records * sizeof(status));
        if (!statuses) {
            // Handle memory allocation failure
            free(record_tasks);
            fprintf(stderr, "Failed to allocate memory for task statuses.\n");
            return;
        }

        break;
    }

    int* priorities = (int*)malloc(num_records * sizeof(int));
    if (!priorities) {
        // Handle memory allocation failure
        free(record_tasks);
        free(statuses);
        fprintf(stderr, "Failed to allocate memory for task priorities.\n");
        return;
    }

    char** command_lists = (char**)malloc(num_records * sizeof(char*));
    if (!command_lists) {
        // Handle memory allocation failure
        free(record_tasks);
        free(statuses);
        free(priorities);
        fprintf(stderr, "Failed to allocate memory for task command lists.\n");
        return;
    }

    int i = 0;
    while (i < num_records) {
        record_task* record_task_ptr = &record_tasks[i];

        // Initialize priority
        int priority_value = rand() % (max_priority - min_priority + 1) + min_priority;
        while (find_duplicate(priorities, i)) {
            priority_value = rand() % (max_priority - min_priority + 1) + min_priority;
        }
        priorities[i] = priority_value;

        // Initialize command list
        char* command_list = NULL;
        int cmd_len = 0;
        while ((cmd_len < max_cmd_len && (command_list = realloc(command_list, ++cmd_len * sizeof(char)))) && fgets(command_list, cmd_len, stdin)) {
            // Validate and parse command
            if (!validate_command(command_list)) {
                free(record_tasks);
                free(statuses);
                free(priorities);
                for (int j = 0; j < i + 1; j++) {
                    free(command_lists[j]);
                }
                free(command_lists);
                return;
            }

            command_lists[i] = command_list;

            // Initialize task
            record_task_ptr->task.priority = priorities[i];
            strcpy(record_task_ptr->task.command, command_list);

            break;
        }

        if (!cmd_len) {
            i--;
            continue;
        }

        i++;
    }

    for (int i = 0; i < num_records; i++) {
        record_tasks[i].status = statuses[i];
    }
}

