typedef struct sensor_data {
    float temperature;
    char sensor_id;
    time_t timestamp;
} sensor_data;

sensor_data* allocate_sensor_data_array(size_t count) {
    sensor_data* array = (sensor_data*)malloc(count * sizeof(sensor_data));
    if (!array) {
        return NULL; // Memory allocation failed
    }
    for (size_t i = 0; i < count; i++) {
        array[i].temperature = 0.0f;
        array[i].sensor_id = '\0';
        array[i].timestamp = time(NULL);
    }
    return array;
}

int main() {
    // Connect to MySQL database
    MYSQL *conn;
    conn = mysql_init(NULL);
    if (!mysql_real_connect(conn, "localhost", "username", "password", "database_name", 3306, NULL, 0)) {
        printf("Error connecting: %s\n", mysql_error(conn));
        return -1;
    }

    // Prepare statement for inserting data
    MYSQL_STMT *stmt = mysql_stmt_init(conn);
    if (!stmt) {
        printf("Error preparing statement: %s\n", mysql_error(conn));
        return -2;
    }
    mysql_stmt_prepare(stmt, "INSERT INTO sensor_data (temperature, sensor_id, timestamp) VALUES (?, ?, ?)");

    // Allocate and initialize array of sensor data
    size_t count = 1000; // adjust as needed
    sensor_data* sensor_array = allocate_sensor_data_array(count);

    // Process and insert data into database
    for (size_t i = 0; i < count; i++) {
        // ... process sensor data ...
        int result = mysql_stmt_bind_param(stmt, "?", &sensor_array[i].temperature);
        if (result != 0) {
            printf("Error binding parameters: %s\n", mysql_error(conn));
            break;
        }
        result = mysql_stmt_execute(stmt);
        if (result != 0) {
            printf("Error executing statement: %s\n", mysql_error(conn));
            break;
        }
    }

    // Clean up
    mysql_stmt_free_result(stmt);
    mysql_close(conn);

    return 0;
}

