// Define a structure to represent key-value pairs
typedef struct {
    int id;
    char* key;
    char* value;
    time_t timestamp;
} kv_pair;

// Create a thread-safe hash table
typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t size;
    kv_pair** data;
} hash_table;

// Initialize the hash table
void init_hash_table(hash_table* ht, size_t capacity) {
    ht->capacity = capacity;
    ht->size = 0;
    ht->data = (kv_pair**)malloc(capacity * sizeof(kv_pair*));
}

// Add a key-value pair to the hash table
void add_kv_pair(hash_table* ht, kv_pair* pair) {
    pthread_mutex_lock(&ht->lock);
    size_t index = pair->id % ht->capacity;
    for(size_t i = 0; i < ht->size; i++) {
        if(strcmp(ht->data[index][i].key, pair->key) == 0) {
            // Handle duplicate key
            free(pair->key);
            free(pair->value);
            pthread_mutex_unlock(&ht->lock);
            return;
        }
    }
    ht->data[index] = (kv_pair*)realloc(ht->data[index], (ht->size + 1) * sizeof(kv_pair));
    ht->data[index][ht->size++] = pair;
    pthread_mutex_unlock(&ht->lock);
}

// Read data from CSV file and populate the hash table
void read_csv_file(hash_table* ht, const char* filename) {
    FILE* file = fopen(filename, "r");
    if(file == NULL) {
        printf("Error opening file\n");
        return;
    }
    size_t capacity = 16; // Initial capacity of the hash table
    init_hash_table(ht, capacity);
    char line[256];
    while(fgets(line, sizeof(line), file)) {
        kv_pair* pair = (kv_pair*)malloc(sizeof(kv_pair));
        sscanf(line, "%d %s %s", &pair->id, pair->key, pair->value);
        pair->timestamp = time(NULL);
        add_kv_pair(ht, pair);
    }
    fclose(file);
}

// Write the hash table to a CSV file
void write_csv_file(const char* filename) {
    FILE* file = fopen(filename, "w");
    if(file == NULL) {
        printf("Error opening file\n");
        return;
    }
    size_t i = 0;
    for(size_t j = 0; j < ht->size; j++) {
        fprintf(file, "%d %s %s\n", ht->data[i][j].id, ht->data[i][j].key, ht->data[i][j].value);
    }
    fclose(file);
}

