record* allocate_data_structures(int size1, int size2, int min_val, int max_val) {
    if (size1 <= 0 || size2 <= 0) {
        fprintf(stderr, "Invalid size parameters. Allocation failed.\n");
        return NULL;
    }

    // Allocate memory for offsets and keys
    long* offsets = malloc(size1 * sizeof(long));
    int* keys = malloc(size1 * sizeof(int));

    if (offsets == NULL || keys == NULL) {
        free(offsets);
        free(keys);
        fprintf(stderr, "Memory allocation failed. Allocation failed.\n");
        return NULL;
    }

    // Initialize offsets and keys
    for (int i = 0; i < size1; i++) {
        offsets[i] = i * 2 + 5;
        keys[i] = i % 10;
    }

    // Allocate memory for record structures
    record* records = malloc(size2 * sizeof(record));

    if (records == NULL) {
        free(offsets);
        free(keys);
        fprintf(stderr, "Memory allocation failed. Allocation failed.\n");
        return NULL;
    }

    // Initialize record structures with random values and timestamp
    srand(time(NULL));
    for (int i = 0; i < size2; i++) {
        records[i].val = rand() % (max_val - min_val + 1) + min_val;
        records[i].timestamp = time(NULL);
        records[i].status = 'A'; // default status
    }

    return records;
}

void free_allocated_memory(record* allocated, int size1, int size2) {
    if (allocated == NULL) {
        return;
    }

    // Free record structures
    free(allocated);

    // Free offsets and keys
    free((long*) allocated);
}
