int maxRecords = 0;
int uniqueKeyCount = 0;
int* keyMap = NULL;

// Custom memory pool
void* my_malloc(size_t size) {
    return malloc(size);
}

void my_free(void* ptr) {
    free(ptr);
}

void init_data_structures(int max_size, int max_records) {
    if (max_size > max_records) {
        printf("Error: Max size exceeds configured limit.\n");
        return;
    }

    // Initialize arrays
    offsets = (long*)my_malloc(max_size * sizeof(long));
    keys = (int*)my_malloc(max_size * sizeof(int));

    // Initialize records
    records = (record**)my_malloc(max_records * sizeof(record*));
    for (int i = 0; i < max_records; i++) {
        records[i] = (record*)my_malloc(sizeof(record));
        records[i]->offset = offsets;
    }

    // Track unique keys
    keyMap = (int*)my_malloc(max_size * sizeof(int));
    for (int i = 0; i < max_size; i++) {
        keyMap[i] = -1; // Initialize to invalid value (-1)
    }
}

void deallocate_data_structures() {
    // Deallocate arrays
    free(offsets);
    free(keys);

    // Deallocate records
    for (int i = 0; i < numRecords; i++) {
        free(records[i]);
    }
    free(records);

    // Deallocate key map
    free(keyMap);
}

// Function to check if a key is already assigned
int is_key_assigned(int key) {
    for (int i = 0; i < uniqueKeyCount; i++) {
        if (keyMap[i] == key) {
            return 1;
        }
    }
    return 0;
}

