import java.util.*;

public class PduProcessor {
    private Map<Integer, Integer> pcGroupToTcId;
    private Map<Integer, UnionFind> pduToUnionFind;

    public PduProcessor() {
        pcGroupToTcId = new HashMap<>();
        pduToUnionFind = new HashMap<>();
    }

    public void processPdus(int[][] pdus) throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        List<Future<?>> futures = new ArrayList<>();

        for (int[] pdu : pdus) {
            int pcGroup = pdu[0];
            int tcId = pdu[1];

            UnionFind uf = pduToUnionFind.computeIfAbsent(pcGroup, k -> new UnionFind(k));
            uf.makeSet(tcId);

            Callable<Void> task = () -> {
                try {
                    Thread.sleep(10); // simulate processing time
                    System.out.println("Processing PDU: " + Arrays.toString(pdu) + " - Disjoint pairs: " + uf.countSets());
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    return;
                }
            };
            futures.add(executor.submit(task));
        }

        for (Future<?> future : futures) {
            try {
                future.get();
            } catch (InterruptedException | ExecutionException e) {
                System.out.println("Error processing PDU: " + e.getMessage());
            }
        }
    }

    public void initPdu(Pdu pdu) {
        int pcGroup = pdu.get PcGroup();
        int tcId = pdu.getTcId();

        pcGroupToTcId.put(pcGroup, tcId);
    }

    private class UnionFind {
        Map<Integer, Integer> parent;

        public UnionFind(int size) {
            parent = new HashMap<>();
            for (int i = 0; i < size; i++) {
                parent.put(i, i);
            }
        }

        public void makeSet(int x) {
            parent.put(x, x);
        }

        public int find(int x) {
            return parent.get(x);
        }

        public boolean union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);

            if (rootX == rootY) {
                return false;
            }

            parent.put(rootY, rootX);
            return true;
        }

        public int countSets() {
            Set<Integer> sets = new HashSet<>();

            for (int x : parent.keySet()) {
                sets.add(find(x));
            }

            return sets.size();
        }
    }
}
