#define MAX_CONNECTIONS 1000

typedef struct {
    char ip[16];
    int port;
    int status; // 0: disconnected, 1: connected
} Connection;

Connection* connections = NULL;
int num_connections = 0;

// Function to add a new connection
void add_connection(char* ip, int port) {
    if (num_connections >= MAX_CONNECTIONS) {
        printf("Maximum number of connections reached\n");
        return;
    }

    // Allocate memory for the new connection
    Connection* new_conn = (Connection*) malloc(sizeof(Connection));
    strcpy(new_conn->ip, ip);
    new_conn->port = port;
    new_conn->status = 0; // Initial status: disconnected

    // Insert the new connection at the end of the list
    connections = (Connection*) realloc(connections, (num_connections + 1) * sizeof(Connection));
    connections[num_connections] = *new_conn;

    num_connections++;
}

// Function to remove a connection
void remove_connection(int port) {
    int i;
    for (i = 0; i < num_connections; i++) {
        if (connections[i].port == port) {
            // Remove the connection from the list
            for (; i < num_connections - 1; i++) {
                connections[i] = connections[i + 1];
            }
            num_connections--;

            free(&connections[i]);
            return;
        }
    }
}

// Function to iterate over the connections
void iterate_connections() {
    int i;
    for (i = 0; i < num_connections; i++) {
        printf("IP: %s, Port: %d, Status: %d\n", connections[i].ip, connections[i].port, connections[i].status);
    }
}

int main() {
    // Initialize the list of connections
    connections = (Connection*) malloc(sizeof(Connection) * MAX_CONNECTIONS);

    // Add some example connections
    add_connection("192.168.1.100", 8080);
    add_connection("192.168.1.101", 8081);
    add_connection("192.168.1.102", 8082);

    // Iterate over the connections
    iterate_connections();

    return 0;
}
