#include <forward_list>
#include <string>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <future>

class ForwardListManager {
public:
    void insertAfter(const std::string& target, const std::string& replacement) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = list_.begin();
        bool found = false;
        while (it != list_.end() && !found) {
            if (*it == target) {
                found = true;
                list_.insert_after(it++, replacement);
            }
            else {
                ++it;
            }
        }
        if (!found) {
            list_.emplace_after(list_.end(), replacement);
        }
    }

private:
    std::forward_list<std::string> list_;
    mutable std::mutex mutex_;
    mutable std::condition_variable cv_;

    void asyncInsertAfter(const std::string& target, const std::string& replacement) {
        std::unique_lock<std::mutex> lock(mutex_);
        auto it = list_.begin();
        bool found = false;
        while (it != list_.end() && !found) {
            if (*it == target) {
                found = true;
                list_.insert_after(it++, replacement);
            }
            else {
                ++it;
            }
        }
        if (!found) {
            list_.emplace_after(list_.end(), replacement);
        }
        cv_.notify_all();
    }

public:
    void asyncRun() {
        std::vector<std::future<void>> futures;
        for (int i = 0; i < numThreads_; ++i) {
            auto future = std::async(std::launch::async, &ForwardListManager::asyncInsertAfter,
                this, targetStrings_[i], replacementStrings_[i]);
            futures.push_back(future);
        }
        for (auto& future : futures) {
            future.get();
        }
    }

private:
    int numThreads_ = 4;
    std::vector<std::string> targetStrings_;
    std::vector<std::string> replacementStrings_;
};

int main() {
    ForwardListManager manager;
    // Initialize the list, target strings and replacement strings...
    manager.asyncRun();
    return 0;
}
