typedef struct {
    int i;
    float f;
    char *s;
} Record;

void initRecords(Record **records, size_t count) {
    if (!records || !count) return;

    for (size_t i = 0; i < count; i++) {
        records[i] = (Record *)malloc(sizeof(Record));

        if (!records[i]) {
            printf("Memory allocation failed.\n");
            exit(EXIT_FAILURE);
        }

        records[i]->i = rand() % 100;
        records[i]->f = ((float)rand()) / RAND_MAX;

        size_t len = rand() % 10 + 1;
        char *str = (char *)malloc(len);

        if (!str) {
            printf("Memory allocation failed.\n");
            exit(EXIT_FAILURE);
        }

        for (size_t j = 0; j < len; j++) {
            str[j] = (char)(rand() % 26 + 'a');
        }
        str[len] = '\0';
        records[i]->s = str;
    }
}

void freeRecords(Record **records, size_t count) {
    if (!records || !count) return;

    for (size_t i = 0; i < count; i++) {
        free(records[i]->s);
        free(records[i]);
    }
}

void writeRecordsToFile(const Record *records, size_t count) {
    FILE *file = fopen("data.txt", "w");

    if (!file) {
        printf("Failed to open file.\n");
        return;
    }

    for (size_t i = 0; i < count; i++) {
        fprintf(file, "%d %f %s\n", records[i]->i, records[i]->f, records[i]->s);
    }
}

void readRecordsFromFile(Record **records, size_t *count) {
    FILE *file = fopen("data.txt", "r");

    if (!file) {
        printf("Failed to open file.\n");
        return;
    }

    while (fscanf(file, "%d %f %s\n", &records[*count]->i, &records[*count]->f, records[*count]->s) != 3) {
        free(records[*count]->s);
        free(records[*count]);
        (*count)--;
    }
}
