#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_SIZE 100
#define SENTINEL -1

typedef struct {
    int* data;
    int size;
} dataset_t;

dataset_t read_dataset() {
    int count = 0, sum = 0;
    char c;
    dataset_t ds = { NULL, 0 };

    while ((c = getchar()) != '\n' && c != SENTINEL) {
        if (isdigit(c)) {
            int num = c - '0';
            sum += num;
            count++;
            if (ds.data == NULL && count > MAX_SIZE) {
                ds.size = 0;
                return ds;
            }
            ds.data = realloc(ds.data, (count + 1) * sizeof(int));
            ds.data[count-1] = num;
        }
    }

    if (c != '\n' || c == SENTINEL) {
        ds.size = count;
        return ds;
    } else {
        free(ds.data);
        ds.size = 0;
        return ds;
    }
}

void print_dataset(dataset_t ds) {
    if (ds.size > 0) {
        int avg = (int)round((double)sum / ds.size);
        printf("Average: %d\n", avg);
    } else {
        printf("No data\n");
    }
}
