// Define struct data_container
typedef struct {
    char* id;
    double value;
} record_t;

// Define struct data_container
typedef struct {
    int size;
    record_t** records;
} data_container_t;

data_container_t* data_container_create(int size) {
    data_container_t* container = (data_container_t*)malloc(sizeof(data_container_t));
    if (!container) return NULL; // Handle allocation error
    container->size = size;
    container->records = (record_t**)calloc(size, sizeof(record_t*));
    for (int i = 0; i < size; i++) {
        record_t* record = (record_t*)malloc(sizeof(record_t));
        if (!record) return NULL; // Handle allocation error
        record->id = (char*)malloc(strlen("unique_id") + 1);
        sprintf(record->id, "unique_id_%d", i);
        record->value = rand() / (double)RAND_MAX;
        container->records[i] = record;
    }
    return container;
}

int data_container_destroy(data_container_t* container) {
    for (int i = 0; i < container->size; i++) {
        free(container->records[i]->id);
        free(container->records[i]);
    }
    free(container->records);
    free(container);
}

// Define API for interacting with the C library
extern "C" {

void* data_container_new(int size) {
    return (void*)data_container_create(size);
}

int data_container_free(void* container) {
    return data_container_destroy((data_container_t*)container);
}
}
