**Rust Client (libclient.rs)**

```rust
use reqwest;
use tokio::sync::{mpsc, mpsc::channel};
use tokio::task;

async fn send_request(url: &str, timeout: u64) -> reqwest::Result<reqwest::Response> {
    let client = reqwest::blocking::Client::new();
    let response = client.get(url)
        .timeout(std::time::Duration::from_millis(timeout))
        .send()
        .await?;
    Ok(response)
}

async fn retry_request(url: &str, timeout: u64, max_attempts: u32) -> reqwest::Result<reqwest::Response> {
    let (tx, rx) = channel(0);
    task::spawn(async move {
        for _ in 0..max_attempts {
            match send_request(url, timeout).await {
                Ok(response) => tx.send(response).await.unwrap(),
                Err(err) => {
                    if err.is_timeout() {
                        break;
                    }
                },
            }
        }
        tx.close().await;
    });
    rx.recv().await
}

#[tokio::main]
async fn main() {
    let url = "https://example.com/api";
    let timeout = 1000; // Milliseconds
    let max_attempts = 3;

    loop {
        match retry_request(url, timeout, max_attempts).await {
            Ok(response) => {
                println!("Received response: {}", response.status());
                break;
            },
            Err(err) => {
                eprintln!("Error: {}", err);
            }
        }
    }
}
```

