use reqwest::get;
use tokio::time::{sleep, timeout};

async fn make_request(url: &str) -> Result<(), reqwest::Error> {
    let client = reqwest::Client::new();
    let response = timeout(timeout(Duration::from_secs(5)), client.get(url)).await?;
    Ok(response.text().await?)
}

async fn main() {
    while let Err(err) = make_request("https://example.com").await {
        match err.kind() {
            reqwest::ErrorKind::Timeout => {
                println!("Timeout error");
                sleep(Duration::from_millis(1000)).await;
                continue;
            }
            _ => return Err(err),
        }
    }
}
