#include <time.h>
#include <string.h>

typedef struct {
    long offset;
    int key;
    double data;
    char* label;
} record;

record* init_records(int count) {
    record* records = (record*)malloc(count * sizeof(record));
    if (!records) return NULL;

    for (int i = 0; i < count; i++) {
        records[i].offset = rand();
        records[i].key = rand() % 2001 - 1000;
        records[i].data = (double)rand() / RAND_MAX;
        int id_len = snprintf(NULL, 0, "id_%d", i);
        char* label = (char*)malloc(id_len + 1);
        sprintf(label, "id_%d", i);
        records[i].label = label;
    }

    return records;
}

void free_records(record* records) {
    for (int i = 0; i < count; i++) {
        if (records[i].label) free(records[i].label);
    }
    free(records);
}

record* process_data(int* data, int count) {
    record* unique_data = NULL;
    int unique_count = 0;

    for (int i = 0; i < count; i++) {
        if (data[i] >= -1000 && data[i] <= 1000) {
            int found = 0;
            for (int j = 0; j < unique_count; j++) {
                if (unique_data[j].key == data[i]) {
                    found = 1;
                    break;
                }
            }

            if (!found) {
                unique_data = (record*)realloc(unique_data, ++unique_count * sizeof(record));
                unique_data[unique_count - 1].offset = rand();
                unique_data[unique_count - 1].key = data[i];
                unique_data[unique_count - 1].data = (double)rand() / RAND_MAX;
                int id_len = snprintf(NULL, 0, "id_%d", unique_count - 1);
                char* label = (char*)malloc(id_len + 1);
                sprintf(label, "id_%d", unique_count - 1);
                unique_data[unique_count - 1].label = label;
            }
        }
    }

    return unique_data;
}

int find_largest(record* records, int count) {
    int largest = records[0].key;

    for (int i = 1; i < count; i++) {
        if (records[i].key > largest) {
            largest = records[i].key;
        }
    }

    return largest;
}

int main() {
    srand(time(NULL));
    int data[] = {1, 2, -3, 4, 5, -6, 7};
    record* unique_data = process_data(data, sizeof(data) / sizeof(data[0]));
    printf("Largest integer in the unique array: %d\n", find_largest(unique_data, sizeof(unique_data) / sizeof(unique_data[0])));

    return 0;
}
