typedef struct {
    int key;
    double data;
} Record;

Record* init_records(int num_records) {
    long* offsets = NULL;
    int* keys = NULL;
    double* data_values = NULL;

    Record* records = NULL;

    int i, key = 1;

    srand(time(NULL)); // seed random number generator

    try {
        // allocate memory for arrays
        offsets = (long*)malloc(sizeof(long) * num_records);
        keys = (int*)malloc(sizeof(int) * num_records);
        data_values = (double*)malloc(sizeof(double) * num_records);

        records = (Record*)malloc(sizeof(Record) * num_records);

        for (i = 0; i < num_records; i++) {
            // initialize record fields
            records[i].key = key++;
            records[i].data = (double)(rand() / (double)RAND_MAX);
        }
    } catch (std::bad_alloc& e) {
        // handle allocation failure gracefully
        printf("Memory allocation failed: %s\n", e.what());

        if (offsets != NULL)
            free(offsets);
        if (keys != NULL)
            free(keys);
        if (data_values != NULL)
            free(data_values);
        if (records != NULL)
            free(records);

        return NULL;
    }

    // handle memory deallocation upon failure
    catch (...) {
        printf("Memory allocation failed: unknown error\n");

        if (offsets != NULL)
            free(offsets);
        if (keys != NULL)
            free(keys);
        if (data_values != NULL)
            free(data_values);
        if (records != NULL)
            free(records);

        return NULL;
    }

    // handle successful allocation
    return records;
}
