    new_batch->size = initial_size;
    new_batch->ready = false;
    strcpy(new_batch->log_config, "default");

    return new_batch;
}

void add_record(batch* batch, record* rec) {
    if (batch->records == NULL || batch->size <= 0) return;

    for (int i = 0; i < batch->size; i++) {
        if (!batch->records[i]) break;
    }

    if (i >= batch->size) {
        batch->records = (record**)realloc(batch->records, (batch->size + initial_size) * sizeof(record*));
        if (!batch->records) return;

        batch->size += initial_size;
    }

    batch->records[i] = rec;
}

void free_batch(batch* batch) {
    for (int i = 0; i < batch->size; i++) {
        if (batch->records[i]) {
            free(batch->records[i]->meta);
            free(batch->records[i]);
        }
    }

    free(batch->records);
    free(batch);
}

void log_memory_usage() {
    // configure logging mechanism
    printf("Memory Usage: %d MB\n", get_memory_usage());
}
