    dataset* ds = (dataset*)malloc(sizeof(dataset));
    ds->data = 0.0;
    ds->name = strdup(name);
    ds->elements = NULL;
    return ds;
}

void add_element(dataset* ds, char* id, float value) {
    element* e = (element*)malloc(sizeof(element));
    e->value = value;
    e->id = strdup(id);
    ds->elements = realloc(ds->elements, sizeof(element*) * (ds->elements != NULL ? strlen((char*)ds->elements) : 0) + 1);
    ds->elements[ds->elements != NULL ? strlen((char*)ds->elements) : 0] = &e;
}

void free_dataset(dataset* ds) {
    if (ds == NULL)
        return;
    for (int i = 0; i < strlen((char*)ds->elements); i++) {
        element* e = ds->elements[i];
        free(e->id);
        free(e);
    }
    free(ds->name);
    free(ds);
}

