#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define a struct element with float value and char* string
typedef struct {
    float value;
    char* str;
} Element;

// Define a data_set struct containing double, char*, and Element*
typedef struct {
    double dval;
    char* cstr;
    Element* elem;
} DataSet;

// Function to dynamically manage memory for and initialize arrays of 'double', 'char' strings, and 'struct element' objects
DataSet* init_data_set(int n) {
    DataSet* data_sets = (DataSet*)malloc(n * sizeof(DataSet));
    if (!data_sets) {
        return NULL;
    }

    srand(time(NULL));  // Seed the random number generator

    for (int i = 0; i < n; i++) {
        data_sets[i].dval = rand() / (double)RAND_MAX;

        char* str = (char*)malloc(16 * sizeof(char));
        if (!str) {
            free(data_sets);
            return NULL;
        }
        sprintf(str, "element_%d", i);

        Element* elem = (Element*)malloc(sizeof(Element));
        if (!elem) {
            free(data_sets);
            return NULL;
        }
        elem->value = rand() / (float)RAND_MAX;
        elem->str = str;

        data_sets[i].cstr = str;
        data_sets[i].elem = elem;
    }

    return data_sets;
}

// Free the memory allocated for a data_set array
void free_data_set(DataSet* data_sets, int n) {
    if (!data_sets) return;

    for (int i = 0; i < n; i++) {
        free(data_sets[i].elem->str);
        free(data_sets[i].elem);
    }

    free(data_sets);
}

// Function to add a random number of vertices and edges to the graph
void add_random_vertices_and_edges(Graph* graph) {
    int num_vertices = rand() % 10 + 1;
    for (int i = 0; i < num_vertices; i++) {
        Vertex* vertex = create_vertex();
        set_vertex_property(vertex, "id", rand());
        set_vertex_property(vertex, "label", rand_str());

        int num_edges = rand() % 5 + 1;
        for (int j = 0; j < num_edges; j++) {
            Edge* edge = create_edge(vertex);
            set_edge_property(edge, "weight", rand());
            set_edge_property(edge, "label", rand_str());
        }
    }

    // Add edges between vertices
    int num_edges_to_add = graph->num_vertices * 2;
    for (int i = 0; i < num_edges_to_add; i++) {
        Vertex* source = get_random_vertex(graph);
        Vertex* target = get_random_vertex(graph);

        if (source && target) {
            Edge* edge = create_edge(source, target);
            set_edge_property(edge, "weight", rand());
            set_edge_property(edge, "label", rand_str());
        }
    }
}

int main() {
    // Initialize graph database
    Graph* graph = init_graph();

    // Add random vertices and edges to the graph
    add_random_vertices_and_edges(graph);

    return 0;
}
