#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_INTS 10000
#define MAX_SETS 5
#define STRING_LENGTH 16
#define FLOAT_VALUE_RANGE 10.0f

typedef struct {
    float value;
    char* identifier;
} element_t;

typedef struct {
    double metadata_double;
    char metadata_string[STRING_LENGTH];
    element_t* elements;
} data_set_t;

typedef struct {
    int rnti;
    CRC_INDICATION_REL8_TAG crc_tag;
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
} NFAPI_CRC_INDICATION_PDU_T;

void manage_memory_and_data(int** ints, size_t* num_ints,
                             long** offsets, size_t* num_offsets,
                             int** keys, size_t* num_keys,
                             element_t*** elements_sets, size_t* num_elements_sets,
                             data_set_t*** data_sets, size_t* num_data_sets,
                             NFAPI_CRC_INDICATION_PDU_T*** crc_indications_pdu_ts, size_t* num_crc_indications_pdu_ts) {
    // Initialize memory for arrays
    *ints = (int*)malloc(MAX_INTS * sizeof(int));
    *num_ints = 0;

    *offsets = (long*)malloc(MAX_SETS * sizeof(long));
    *num_offsets = 0;

    *keys = (int*)malloc(MAX_SETS * sizeof(int));
    *num_keys = 0;

    // Initialize memory for element sets
    *elements_sets = (element_t**)malloc(MAX_SETS * sizeof(element_t*));
    for (size_t i = 0; i < MAX_SETS; i++) {
        (*elements_sets)[i] = (element_t*)malloc(10 * sizeof(element_t));
    }
    *num_elements_sets = 0;

    // Initialize memory for data sets
    *data_sets = (data_set_t**)malloc(MAX_SETS * sizeof(data_set_t*));
    for (size_t i = 0; i < MAX_SETS; i++) {
        (*data_sets)[i] = (data_set_t*)malloc(sizeof(data_set_t));
        (*data_sets)[i]->elements = (element_t*)malloc(10 * sizeof(element_t));
    }
    *num_data_sets = 0;

    // Initialize memory for crc indications
    *crc_indications_pdu_ts = (NFAPI_CRC_INDICATION_PDU_T**)malloc(MAX_INTS * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    for (size_t i = 0; i < MAX_INTS; i++) {
        (*crc_indications_pdu_ts)[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    *num_crc_indications_pdu_ts = 0;

    // Read integers from standard input
    while (scanf("%d", &(*ints)[*num_ints]) == 1) {
        (*num_ints)++;
        if (*num_ints >= MAX_INTS) {
            break;
        }
    }

    // Initialize CRC indications
    for (size_t i = 0; i < *num_ints; i++) {
        (*crc_indications_pdu_ts)[i]->rnti = (*ints)[i] % 32;
        (*crc_indications_pdu_ts)[i]->rx_ue_info_tag = i;
        (*crc_indications_pdu_ts)[i]->crc_tag = (CRC_INDICATION_REL8_TAG)rand();
    }

    // Handle memory errors
    if (!*ints || !*offsets || !*keys || !*elements_sets || !*data_sets || !*crc_indications_pdu_ts) {
        fprintf(stderr, "Memory allocation failure. Exiting.\n");
        for (size_t i = 0; i < MAX_SETS; i++) {
            free((*elements_sets)[i]);
        }
        for (size_t i = 0; i < MAX_INTS; i++) {
            free((*crc_indications_pdu_ts)[i]);
        }
        for (size_t i = 0; i < MAX_SETS; i++) {
            free((*data_sets)[i]->elements);
            free((*data_sets)[i]);
        }
        free(*elements_sets);
        free(*keys);
        free(*offsets);
        free(*data_sets);
        free(*crc_indications_pdu_ts);
        exit(EXIT_FAILURE);
    }
}
