#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/types.h>
#include <pthread.h>

#define MAX_RECORDS 10000
#define RECORD_SIZE sizeof(struct Record)
#define FILE_BUFFER_SIZE 1024
#define LATENCY_THRESHOLD 10

typedef struct {
    int key;
    long offset;
} Record;

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        printf("Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

int populate_records(Record** records, int num_records) {
    // Initialize records
    for (int i = 0; i < num_records; i++) {
        Record* record = (Record*)malloc(RECORD_SIZE);
        if (record == NULL) {
            printf("Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        record->key = rand() % 100;
        record->offset = (long)rand();
        records[i] = record;
    }
    return num_records;
}

void free_resources(Record** records, int num_records) {
    // Free allocated memory
    for (int i = 0; i < num_records; i++) {
        if (records[i] != NULL) {
            free(records[i]);
        }
    }
    free(records);
}

int write_to_file(FILE* file, Record** records, int num_records) {
    // Write records to file
    for (int i = 0; i < num_records; i++) {
        fwrite(&records[i]->key, sizeof(int), 1, file);
        fwrite(&records[i]->offset, sizeof(long), 1, file);
    }
    return 0;
}

int main() {
    // Initialize clock synchronization library
    clock_gettime(CLOCK_REALTIME, NULL);

    int num_records = populate_records(NULL, MAX_RECORDS);
    FILE* file = fopen("output.txt", "wb");
    if (file == NULL) {
        printf("File opening failed\n");
        exit(EXIT_FAILURE);
    }

    // Write records to file
    write_to_file(file, NULL, num_records);

    fclose(file);

    return 0;
}

