typedef struct {
    int key;
    long offset;
} record_t;

record_t* allocate_records(int n) {
    record_t *records = (record_t*)calloc(n, sizeof(record_t));

    if (!records) {
        return NULL;
    }

    for (int i = 0; i < n; i++) {
        records[i].key = rand() % (10000 - 1 + 1) + 1;
        records[i].offset = rand() % (2147483647 - 1 + 1) + 1;

        char *buf = (char*)malloc(256);
        if (!buf) {
            free(records);
            return NULL;
        }

        for (int j = 0; j < 256; j++) {
            buf[j] = rand() % (255 - 1 + 1) + 1;
        }

        records[i].offset = (long)buf;
    }

    return records;
