typedef struct record {
    int key;
    long offset;
    int ref_count;
} record;

void init_and_manage_memory(int num_records, int max_offset) {
    // Initialize arrays
    long *offsets = (long *)malloc(num_records * sizeof(long));
    int *keys = (int *)malloc(num_records * sizeof(int));
    record *records = (record *)malloc(num_records * sizeof(record));

    // Initialize offsets and keys
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % max_offset;
        keys[i] = i;
    }

    // Initialize records with random values within the specified range
    for (int i = 0; i < num_records; i++) {
        record *r = &records[i];
        r->key = rand() % max_offset;
        r->offset = offsets[i];
        r->ref_count = 0;
    }

    // Manage memory pools and avoid fragmentation
    for (int i = 0; i < num_records; i++) {
        record *r = &records[i];
        if (r->ref_count > 0) {
            // Reuse existing memory block
            r->key = rand() % max_offset;
            r->offset = offsets[i];
            r->ref_count--;
        }
    }

    // Implement robust deallocation strategy to prevent memory leaks
    for (int i = num_records - 1; i >= 0; i--) {
        if (records[i].ref_count == 0) {
            free(&records[i]);
        } else {
            records[i].ref_count--;
        }
    }

    // Free remaining memory blocks
    free(offsets);
    free(keys);
    free(records);

    return;
}
