typedef struct Record {
    long timestamp;
    int status;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

Node* list = NULL;
int num_records = 0;
int min_timestamp = 0;
int max_timestamp = 0;
double prob_success = 0.5; // default probability

void initialize(int n, int min_t, int max_t, double p) {
    srand(time(NULL));
    num_records = n;
    min_timestamp = min_t;
    max_timestamp = max_t;
    prob_success = p;

    for (int i = 0; i < n; i++) {
        Record record;
        long timestamp = min_timestamp + rand() % ((max_timestamp - min_timestamp) + 1);
        int status = (rand() < (int)(prob_success * RAND_MAX)) ? 1 : 0;

        Node* node = malloc(sizeof(Node));
        if (!node) {
            printf("Memory allocation failed\n");
            exit(-1);
        }
        record.timestamp = timestamp;
        record.status = status;
        node->record = record;
        node->next = list;
        list = node;
    }
}

void add_record(long timestamp, int status) {
    Node* node = malloc(sizeof(Node));
    if (!node) {
        printf("Memory allocation failed\n");
        exit(-1);
    }

    Record record;
    record.timestamp = timestamp;
    record.status = status;

    node->record = record;
    node->next = list;
    list = node;
}

void remove_record() {
    if (list == NULL) return;

    Node* prev = NULL;
    Node* curr = list;

    while (curr && curr->next) {
        prev = curr;
        curr = curr->next;
    }

    free(curr);
    if (prev) {
        prev->next = NULL;
    } else {
        list = NULL;
    }
}

void deallocate() {
    Node* curr = list;
    while (curr) {
        Node* next = curr->next;
        free(curr);
        curr = next;
    }
    list = NULL;
}
