#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define structures
typedef struct {
    float x, y;
} Point;

typedef struct {
    double value;
    char identifier;
    Point point;
} Record;

// Hash table and map data structures
typedef struct {
    int size;
    void **keys;
    void **values;
} HashMap;

HashMap* createHashMap(int size) {
    HashMap* hashTable = (HashMap*)malloc(sizeof(HashMap));
    hashTable->size = size;
    hashTable->keys = (void**)malloc(size * sizeof(void*));
    hashTable->values = (void**)malloc(size * sizeof(void*));
    return hashTable;
}

int getHash(const void* key, int tableSize) {
    const char* k = key;
    unsigned long hash = 0;
    while (*k != '\0') {
        hash = (hash << 5) + *k;
        k++;
    }
    return hash % tableSize;
}

void insertHashMap(HashMap* table, void* key, void* value) {
    int index = getHash(key, table->size);
    if (!table->keys[index]) {
        table->keys[index] = key;
        table->values[index] = value;
    } else {
        // Handle collision
        int nextIndex = (index + 1) % table->size;
        while (table->keys[nextIndex]) {
            index = nextIndex;
            nextIndex = (nextIndex + 1) % table->size;
        }
        table->keys[index] = key;
        table->values[index] = value;
    }
}

void* searchHashMap(HashMap* table, void* key) {
    int index = getHash(key, table->size);
    if (table->keys[index] == key) {
        return table->values[index];
    } else {
        // Handle collision
        int nextIndex = (index + 1) % table->size;
        while (table->keys[nextIndex] != key) {
            index = nextIndex;
            nextIndex = (nextIndex + 1) % table->size;
        }
        return table->values[index];
    }
}

// Initialize maps and hash tables
HashMap* createMaps(int numInitialRecords, int minX, int maxX, int minY, int maxY, char* identifiers) {
    HashMap* doubleMap = createHashMap(10000);
    HashMap* charMap = createHashMap(10000);
    HashMap* pointMap = createHashMap(10000);
    HashMap* recordMap = createHashMap(200000);

    // Initialize maps with specified parameters
    for (int i = 0; i < numInitialRecords; i++) {
        double value = rand() / (double)RAND_MAX * (maxX - minX) + minX;
        char identifier = identifiers[rand() % strlen(identifiers)];
        Point point = {rand() / (float)RAND_MAX * (maxY - minY) + minY, rand() / (float)RAND_MAX * (maxY - minY) + minY};
        Record record = {value, identifier, point};

        // Insert records into maps
        insertHashMap(doubleMap, &record.value, &record);
        insertHashMap(charMap, &identifier, &record);
        insertHashMap(pointMap, &point, &record);
        insertHashMap(recordMap, &record, NULL);

    }

    return recordMap;
}

int main() {
    // Initialize random number generator
    srand(time(NULL));

    int numInitialRecords = 10000;
    int minX = 0, maxX = 10;
    int minY = 0, maxY = 10;
    char* identifiers = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";

    HashMap* recordMap = createMaps(numInitialRecords, minX, maxX, minY, maxY, identifiers);

