#define MAX_READINGS 50000
#define PROBABILITY_THRESHOLD 0.5

typedef enum {
    OPERATIONAL,
    WARNING,
    ERROR
} status_enum;

struct sensor_reading {
    float temperature;
    int humidity;
    time_t timestamp;
};

typedef struct {
    float value;
    char identifier[16];
} float_sensor_value;

// Hash table structure
typedef struct {
    size_t capacity;
    size_t size;
    void **keys;
    void **values;
    pthread_mutex_t mutex;
} hash_table;

hash_table *initialize_hash_table(size_t capacity) {
    hash_table *table = (hash_table *)malloc(sizeof(hash_table));
    table->capacity = capacity;
    table->size = 0;
    table->keys = (void **)calloc(capacity, sizeof(void *));
    table->values = (void **)calloc(capacity, sizeof(void *));
    pthread_mutex_init(&table->mutex, NULL);
    return table;
}

int hash_function(const void *key, size_t capacity) {
    // Simple hash function using modulo operation
    size_t hash = 0;
    const char *str = key;
    while (*str != '\0') {
        hash += (size_t)*str;
        str++;
    }
    return hash % capacity;
}

void insert_hash_table(hash_table *table, void *key, void *value) {
    pthread_mutex_lock(&table->mutex);
    size_t index = hash_function(key, table->capacity);
    while (table->keys[index] != NULL) {
        index = (index + 1) % table->capacity;
    }
    table->keys[index] = key;
    table->values[index] = value;
    table->size++;
    pthread_mutex_unlock(&table->mutex);
}

void *get_from_hash_table(hash_table *table, void *key) {
    pthread_mutex_lock(&table->mutex);
    size_t index = hash_function(key, table->capacity);
    while (table->keys[index] != key) {
        index = (index + 1) % table->capacity;
        if (table->keys[index] == NULL) {
            break;
        }
    }
    void *value = table->values[index];
    pthread_mutex_unlock(&table->mutex);
    return value;
}

void free_hash_table(hash_table *table) {
    pthread_mutex_lock(&table->mutex);
    for (size_t i = 0; i < table->capacity; i++) {
        if (table->keys[i] != NULL) {
            free(table->keys[i]);
            free(table->values[i]);
        }
    }
    free(table->keys);
    free(table->values);
    pthread_mutex_unlock(&table->mutex);
}

void *random_reading(void) {
    // Generate random reading
    struct sensor_reading *reading = (struct sensor_reading *)malloc(sizeof(struct sensor_reading));
    reading->temperature = (float)rand() / RAND_MAX;
    reading->humidity = rand() % 100;
    time_t timestamp = time(NULL);
    reading->timestamp = timestamp - (rand() % (int)(time(NULL) - timestamp));
    return reading;
}

void initialize_data_structures(size_t num_readings, int min_timestamp, int max_timestamp, float temperature_calibration, int humidity_calibration, double probability_distribution[]) {
    // Initialize data structures
    hash_table *table = initialize_hash_table(MAX_READINGS);

    for (size_t i = 0; i < num_readings; i++) {
        struct sensor_reading *reading = random_reading();
        float_sensor_value *value = (float_sensor_value *)malloc(sizeof(float_sensor_value));
        strcpy(value->identifier, "Sensor Identifier");
        value->value = reading->temperature * temperature_calibration + rand() % 10;

        status_enum state = PROBABILITY_THRESHOLD > rand() / RAND_MAX ? OPERATIONAL : WARNING;
        status_enum operational_state = (status_enum)rand() % (int)(PROBABILITY_THRESHOLD * 2);

        // Populate hash table with readings
        insert_hash_table(table, &reading->timestamp, value);
    }

    free_hash_table(table);
}

int main() {
    size_t num_readings = 100;
    int min_timestamp = time(NULL) - 3600;
    int max_timestamp = time(NULL);
    float temperature_calibration = 1.5;
    int humidity_calibration = 80;
