    Record* records = (Record*)malloc(numRecords * sizeof(Record));
    if (records == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    srand(time(NULL)); // Seed random number generator

    for (int i = 0; i < numRecords; i++) {
        records[i].key = rand() % 100;
        records[i].offset = (long)rand() * 1000L;
        records[i].data = (double)rand() / RAND_MAX;
    }

    return records;
}

void writeRecordsToFile(const char* filename, Record* records, int numRecords) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        printf("Error writing to file.\n");
        return;
    }

    for (int i = 0; i < numRecords; i++) {
        fwrite(&records[i], sizeof(Record), 1, file);
    }

    fclose(file);
}

void readRecordsFromFile(const char* filename, Record** records, int* numRecords) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        printf("Error reading from file.\n");
        return;
    }

    fseek(file, 0, SEEK_END);
    *numRecords = ftell(file) / sizeof(Record);

    *records = (Record*)malloc(*numRecords * sizeof(Record));
    if (*records == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    for (int i = 0; i < *numRecords; i++) {
        fread(&(*records)[i], sizeof(Record), 1, file);
    }

    fclose(file);
}

int main() {
    int numRecords = 1000;
    Record* records = initRecords(numRecords);

    if (records == NULL) {
        return 1;
    }

    writeRecordsToFile("data.bin", records, numRecords);

    readRecordsFromFile("data.bin", &records, &numRecords);

    free(records);
    return 0;
}
