#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_QUEUE_SIZE 1000
#define NUM_THREADS 4

typedef struct {
    int priority;
    char* command;
    struct timespec time_constraint;
} task_t;

task_t* queue[MAX_QUEUE_SIZE];
int front = 0, rear = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void* worker_thread(void* arg) {
    int i = *(int*)arg;
    while (1) {
        task_t* task;
        pthread_mutex_lock(&lock);
        while (rear - front <= 0) {
            pthread_cond_wait(&cond, &lock);
        }
        task = queue[front++];
        pthread_mutex_unlock(&lock);

        // execute the task
        printf("Worker %d: Executing task with priority %d\n", i, task->priority);
        free(task->command);
        free(task);

        if (i == NUM_THREADS - 1) {
            break;
        }
    }
    return NULL;
}

int enqueue(int priority, char* command, struct timespec time_constraint) {
    pthread_mutex_lock(&lock);
    while ((rear + 1) % MAX_QUEUE_SIZE == front) {
        pthread_cond_wait(&cond, &lock);
    }

    task_t* task = (task_t*)malloc(sizeof(task_t));
    if (!task) {
        perror("Memory allocation failed");
        return -1;
    }
    task->priority = priority;
    task->command = command;
    task->time_constraint = time_constraint;
    queue[rear] = task;
    rear = (rear + 1) % MAX_QUEUE_SIZE;

    if (front == rear) {
        pthread_cond_signal(&cond);
    }

    pthread_mutex_unlock(&lock);

    return 0;
}

int dequeue() {
    pthread_mutex_lock(&lock);
    while (rear - front <= 0) {
        pthread_cond_wait(&cond, &lock);
    }
    task_t* task = queue[front];
    if (!task) {
        perror("Task not found in the queue");
        return -1;
    }
    queue[front] = NULL;
    front = (front + 1) % MAX_QUEUE_SIZE;

    pthread_mutex_unlock(&lock);

    // execute the task
    printf("Dequeued task with priority %d\n", task->priority);
    free(task->command);
    free(task);

    return 0;
}

int main() {
    int i, thread_ids[NUM_THREADS];
    pthread_t threads[NUM_THREADS];

    for (i = 0; i < NUM_THREADS; i++) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, worker_thread, &thread_ids[i]);
    }

    // enqueue and dequeue tasks
    int priority = rand() % 10;
    char* command = malloc(100);
    strcpy(command, "Command string");
    struct timespec time_constraint = {0};
    clock_gettime(CLOCK_REALTIME, &time_constraint);

    for (i = 0; i < NUM_THREADS; i++) {
        enqueue(priority + i, command, time_constraint);
    }

    for (i = 0; i < NUM_THREADS; i++) {
        dequeue();
    }

    for (i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
