void initArrays(int* offsetArray, long** keysArray, double** valuesArray, int numRecords) {
    // Allocate memory for offset array
    offsetArray = (int*)malloc(numRecords * sizeof(int));

    // Initialize offset array with random values
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        offsetArray[i] = rand() % 100;
    }

    // Allocate memory for keys and values arrays
    *keysArray = (long*)malloc(numRecords * sizeof(long));
    *valuesArray = (double*)malloc(numRecords * sizeof(double));

    // Initialize keys and values arrays with random values
    for (int i = 0; i < numRecords; i++) {
        (*keysArray)[i] = rand() % 100;
        (*valuesArray)[i] = (double)offsetArray[i] + (double)(*keysArray)[i];
    }
}

// Function to dynamically allocate memory for and initialize record array
void initRecordArray(Record** records, int numRecords) {
    // Allocate memory for record array
    *records = (Record*)malloc(numRecords * sizeof(Record));

    // Initialize record array with random values
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        (*records)[i].intField = rand() % 100;
        (*records)[i].longPointer = &offsetArray[i];
        (*records)[i].doubleField = (double)(*records)[i].intField + (double)&offsetArray[i] - (double)offsetArray[0];
    }
}

// Function to write records to file
void writeRecordsToFile(Record* records, int numRecords) {
    // Open file for writing
    FILE* file = fopen("records.txt", "w");

    // Write records to file
    for (int i = 0; i < numRecords; i++) {
        fprintf(file, "%d %ld %f\n", records[i].intField, records[i].longPointer, records[i].doubleField);
    }

    // Close file
    fclose(file);
}

// Function to read records from file
void readRecordsFromFile(Record* records, int numRecords) {
    // Open file for reading
    FILE* file = fopen("records.txt", "r");

    // Read records from file
    for (int i = 0; i < numRecords; i++) {
        fscanf(file, "%d %ld %f\n", &records[i].intField, &records[i].longPointer, &records[i].doubleField);
    }

    // Close file
    fclose(file);
}

int main() {
    int numRecords = 100;
    Record* records = NULL;

    // Initialize arrays and record array
    int offsetArray[numRecords];
    long* keysArray = NULL;
    double* valuesArray = NULL;
    initArrays(offsetArray, &keysArray, &valuesArray, numRecords);
    free(keysArray);
    free(valuesArray);

    // Write records to file
    writeRecordsToFile(records, numRecords);

    return 0;
}
