    double memUsage = getMemUsage();
    double fragPercentage = getFragPercentage();

    // Log the memory stats to the external logging system
    logMessage("Memory Usage: %.2f%%", memUsage);
    logMessage("Fragmentation: %.2f%%", fragPercentage);
}

// Release all previously allocated resources and return an appropriate error status in case of allocation failure
int cleanup() {
    // Release the memory pool
    munmap(mp->memory, mp->capacity);

    // Free any dynamically allocated memory blocks
    free(offsets);
    free(keys);
    free(records);

    // Log a message indicating the clean-up operation was successful
    logMessage("Memory pool released successfully.");

