typedef struct {
    int* data;
    int size;
    int capacity;
} IntStream;

IntStream* init_stream() {
    IntStream* stream = malloc(sizeof(IntStream));
    stream->data = malloc(INITIAL_SIZE * sizeof(int));
    stream->size = 0;
    stream->capacity = INITIAL_SIZE;
    return stream;
}

void free_stream(IntStream* stream) {
    free(stream->data);
    free(stream);
}

int process_int(IntStream* stream, int new_int) {
    if (new_int < 0) {
        printf("Invalid integer: %d\n", new_int);
        return -1;
    }

    if (stream->size == stream->capacity) {
        stream->data = realloc(stream->data, (stream->capacity * 2 + INITIAL_SIZE) * sizeof(int));
        stream->capacity *= 2;
    }

    if (stream->size < stream->capacity) {
        stream->data[stream->size++] = new_int;
    }

    return 0;
}

void reset_stream(IntStream* stream) {
    free(stream->data);
    stream->data = malloc(INITIAL_SIZE * sizeof(int));
    stream->size = 0;
    stream->capacity = INITIAL_SIZE;
}

int get_largest_int(IntStream* stream) {
    int max = -1;

    for (int i = 0; i < stream->size; i++) {
        if (stream->data[i] > max)
            max = stream->data[i];
    }

    return max;
}

int main() {
    IntStream* stream = init_stream();

    while (1) {
        int new_int;
        scanf("%d", &new_int);

        process_int(stream, new_int);

        if (stream->size >= 10000)
            break;
    }

    int max = get_largest_int(stream);
    printf("Largest integer in the stream: %d\n", max);

    free_stream(stream);

    return 0;
}
