#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define record structure
typedef struct {
    int id;
    double value;
    struct metadata* meta;
} record;

// Define metadata structure
typedef struct {
    time_t timestamp;
    int status_flags;
    record* related_records;
} metadata;

// Function to allocate and initialize array of records with random values
record** generateRecords(int numRecords) {
    // Allocate memory for the array of records
    record** records = (record**)malloc(numRecords * sizeof(record*));

    if (!records) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < numRecords; i++) {
        // Allocate memory for the current record
        record* r = (record*)malloc(sizeof(record));

        if (!r) {
            printf("Error: Memory allocation failed.\n");
            return NULL;
        }

        // Initialize random values for the record
        r->id = rand() % 1000;
        r->value = (double)rand() / RAND_MAX;

        // Allocate memory for metadata and initialize it with timestamps and flags
        metadata* meta = (metadata*)malloc(sizeof(metadata));

        if (!meta) {
            printf("Error: Memory allocation failed.\n");
            return NULL;
        }

        meta->timestamp = time(NULL);
        meta->status_flags = rand() % 100;

        // Initialize linked list of related records
        record* prev = r, *next = NULL;
        while (1) {
            metadata* prev_meta = meta;
            next = (record*)malloc(sizeof(record));

            if (!next) {
                printf("Error: Memory allocation failed.\n");
                return NULL;
            }

            // Initialize random values for the next record
            next->id = rand() % 1000;
            next->value = (double)rand() / RAND_MAX;

            // Link records together
            prev->meta->related_records = next;
            prev = next;
        }

    }

    return records;
}

// Thread-safe function to write array of records to file
void writeRecordsToFile(record** records, int numRecords) {
    FILE* file = fopen("records.txt", "w");

    if (!file) {
        printf("Error: Could not open file.\n");
        return;
    }

    for (int i = 0; i < numRecords; i++) {
        // Write record data to file
        fprintf(file, "%d %lf\n", records[i]->id, records[i]->value);

        // Recursively write related records
        metadata* meta = records[i]->meta;
        while (meta) {
            fprintf(file, "%ld %d\n", meta->timestamp, meta->status_flags);
            meta = meta->related_records;
        }
    }

    fclose(file);
}

// Function to read array of records from file and free allocated resources
record** readRecordsFromFile(int numRecords) {
    FILE* file = fopen("records.txt", "r");

    if (!file) {
        printf("Error: Could not open file.\n");
        return NULL;
    }

    record** records = (record**)malloc(numRecords * sizeof(record*));

    for (int i = 0; i < numRecords; i++) {
        // Read record data from file
        int id, flag;
        double value;
        fscanf(file, "%d %lf", &id, &value);

        // Initialize new record and metadata
        record* r = (record*)malloc(sizeof(record));
        metadata* meta = (metadata*)malloc(sizeof(metadata));

        r->id = id;
        r->value = value;
        meta->timestamp = time(NULL);
        meta->status_flags = flag;

        // Read linked list of related records
        record* prev = r, *next = NULL;
        while (1) {
            next = (record*)malloc(sizeof(record));

            if (!next) {
                printf("Error: Memory allocation failed.\n");
                return NULL;
            }

            fscanf(file, "%ld %d", &meta->timestamp, &flag);
            meta = next;
            prev->meta->related_records = next;
        }
    }

    fclose(file);

    return records;
}

int main() {
    // Initialize random seed
    srand(time(NULL));

    int numRecords = 1000; // Adjust as needed

    record** records = generateRecords(numRecords);

    if (!records) {
        printf("Error: Memory allocation failed.\n");
        return -1;
    }

    writeRecordsToFile(records, numRecords);

    freeRecords(records, numRecords);

    return 0;
}

