    if (*records == NULL) {
        free(*keys);
        free(*offsets);
        printf("Memory allocation for records failed.\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_records; i++) {
        (*records)[i] = (record_t*)malloc(sizeof(record_t));
        if ((*records)[i] == NULL) {
            free(*keys);
            free(*offsets);
            printf("Memory allocation for record %d failed.\n", i);
