// Thread-safe hash table for concurrent data access
typedef struct {
    pthread_mutex_t mutex;
    void** data;
    size_t size;
} t_hash_table;

void* t_init_hash_table(size_t size) {
    t_hash_table* ht = (t_hash_table*)malloc(sizeof(t_hash_table));
    ht->size = size;
    ht->data = (void**)calloc(size, sizeof(void*));
    pthread_mutex_init(&ht->mutex, NULL);
    return ht;
}

int t_insert_hash_table(t_hash_table* ht, void* key, void* value) {
    pthread_mutex_lock(&ht->mutex);
    size_t i = 0;
    while (i < ht->size) {
        if (!ht->data[i]) {
            ht->data[i] = value;
            break;
        }
        i++;
    }
    pthread_mutex_unlock(&ht->mutex);
    return 0;
}

int t_delete_hash_table(t_hash_table* ht, void* key) {
    pthread_mutex_lock(&ht->mutex);
    size_t i = 0;
    while (i < ht->size) {
        if (!ht->data[i]) continue;
        if (!keycmp(key, ht->data[i])) {
            ht->data[i] = NULL;
            break;
        }
        i++;
    }
    pthread_mutex_unlock(&ht->mutex);
    return 0;
}

