    pthread_t threads[100];
    for (int i = 0; i < 100; i++) {
        pthread_create(&threads[i], NULL, thread_func, NULL);
    }

    // Wait for all threads to finish
    for (int i = 0; i < 100; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
