#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define record structure
typedef struct {
    int value;
    long offset;
    int key;
    double data;
} Record;

// Function to initialize and manage records
Record* initRecords(int capacity, pthread_mutex_t* mutex) {
    // Allocate memory for the record array
    Record* records = (Record*)malloc(capacity * sizeof(Record));

    if (!records) {
        return NULL;  // Handle memory allocation failure
    }

    // Initialize all records with default values
    memset(records, 0, capacity * sizeof(Record));

    return records;
}

// Function to query records by their unique keys
Record* queryRecords(int key, Record** records, int capacity) {
    for (int i = 0; i < capacity; i++) {
        if (records[i]->key == key) {
            // Exact match found
            return &records[i];
        }
    }

    // No record found with the given key
    return NULL;
}

// Function to query records within a specific range
Record** queryRecordsRange(int startKey, int endKey, Record** records, int capacity) {
    Record** matchingRecords = (Record**)malloc((endKey - startKey + 1) * sizeof(Record*));

    if (!matchingRecords) {
        return NULL;  // Handle memory allocation failure
    }

    for (int i = 0; i < capacity; i++) {
        if (records[i]->key >= startKey && records[i]->key <= endKey) {
            matchingRecords[records[i]->key - startKey] = &records[i];
        }
    }

    return matchingRecords;
}

// Function to free allocated memory
void freeRecords(Record** records, int capacity) {
    if (!records) {
        return;  // Handle null pointer
    }

    for (int i = 0; i < capacity; i++) {
        free(&records[i]);
    }

    free(records);
}

// Function to track memory usage and monitor thresholds
void monitorMemoryUsage(int totalRecords, int allocatedRecords) {
    if (totalRecords > allocatedRecords * 2) {
        printf("Memory usage exceeds threshold! (Total: %d, Allocated: %d)\n", totalRecords, allocatedRecords);
    }
}
