            strategies.push_back(strategy);
        }
        cv.notify_all();
    }

    void selectStrategy() {
        if (isCooldownActive) {
            return;
        }

        isCooldownActive = true;

        int selectedStrategyIndex = rand() % strategies.size();
        Strategy* selectedStrategy = strategies[selectedStrategyIndex];

        std::cout << "Selected strategy: " << selectedStrategy->key << std::endl;

        // Wait for cooldown period
        std::this_thread::sleep_for(std::chrono::seconds(9));
        isCooldownActive = false;
    }

    void queryStrategies(int key, int lowerBound, int upperBound) {
