long *timestamps = NULL;
double *temperatures = NULL;
int num_events = 0, num_timestamps = 0, num_temperatures = 0;

void init_arrays() {
    events = (event_t *)malloc(EVENTS_PER_PACKET * sizeof(event_t));
    timestamps = (long *)malloc(EVENTS_PER_PACKET * sizeof(long));
    temperatures = (double *)malloc(EVENTS_PER_PACKET * sizeof(double));
}

void free_arrays() {
    if (events) {
        free(events);
        events = NULL;
    }
    if (timestamps) {
        free(timestamps);
        timestamps = NULL;
    }
    if (temperatures) {
        free(temperatures);
        temperatures = NULL;
    }
}

int get_events_from_csv(int sockfd, FILE *file) {
    char buffer[BUFFER_SIZE];
    size_t bytes_read;

    while ((bytes_read = fread(buffer, 1, BUFFER_SIZE, file)) > 0) {
        // Parse CSV data and store in events array
        int packet_size = (bytes_read / sizeof(event_t)) + 1;
        event_t *packet_events = &events[num_events];
        for (int i = 0; i < packet_size; ++i) {
            packet_events[i].timestamp = strtol(&buffer[i * sizeof(long)], NULL, 10);
            packet_events[i].temperature = strtod(&buffer[(i + 1) * sizeof(double)], NULL);
            packet_events[i].status = (int)buffer[(i + 2) * sizeof(int)];
        }
        num_events += packet_size;
    }

    fclose(file);

    return 0;
}

void handle_file_operations(int sockfd, int file_desc) {
    FILE *file = fopen("remote_data.csv", "r");
    if (!file) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }

    get_events_from_csv(sockfd, file);

    fclose(file);

    return 0;
}

int connect_to_server(int sockfd) {
    struct sockaddr_in server_addr;
    int conn;

    // Establish connection with remote server
    if ((conn = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("Error creating socket");
        exit(EXIT_FAILURE);
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(8080);

    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

    if (connect(conn, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Error connecting to server");
        exit(EXIT_FAILURE);
    }

    return conn;
}

int main() {
    int sockfd = connect_to_server(sockfd);

    handle_file_operations(sockfd, file_desc);

    free_arrays();

    return 0;
}
