```c
#include <stdlib.h>
#include <stdio.h>

// Define the size of the record structure
typedef struct {
    int value;
} Record;

// Define the custom memory pool structure
typedef struct {
    void **blocks;
    int num_blocks;
    int block_size;
} MemoryPool;

// Initialize the memory pool with a specified number and size of blocks
void init_memory_pool(MemoryPool *pool, int num_blocks, int block_size) {
    pool->num_blocks = num_blocks;
    pool->block_size = block_size;
    pool->blocks = (void **)malloc(num_blocks * sizeof(void *));
}

// Allocate memory from the pool using best-fit strategy
void* best_fit_alloc(MemoryPool *pool, size_t size) {
    void *best_block = NULL;
    int best_diff = -1;

    for (int i = 0; i < pool->num_blocks; i++) {
        if ((size_t)(pool->blocks[i]) >= size && (size_t)(pool->blocks[i]) - size > best_diff) {
            best_block = pool->blocks[i];
            best_diff = (size_t)(pool->blocks[i]) - size;
        }
    }

    return best_block;
}

// Deallocate memory from the pool using worst-fit strategy
void best_fit_dealloc(MemoryPool *pool, void* block) {
    int worst_diff = -1;

    for (int i = 0; i < pool->num_blocks; i++) {
        if ((size_t)(pool->blocks[i]) > (size_t)block + best_fit_alloc(pool, (size_t)block + best_fit_dealloc(pool, NULL)) && (size_t)(pool->blocks[i]) - (size_t)block > worst_diff) {
            worst_diff = (size_t)(pool->blocks[i]) - (size_t)block;
        }
    }

    free(block);
}

// Initialize the record array
Record* init_records(MemoryPool *pool, int num_records) {
    Record *records = (Record *)malloc(num_records * sizeof(Record));
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 100;
    }
    return records;
}

// Implement the function that dynamically manages memory
