import java.util.*;

public class Main {
    public static int countDisjointPairs(int[][] array) {
        UnionFind uf = new UnionFind(array.length);
        long startTime = System.nanoTime();
        for (int i = 0; i < array.length; i++) {
            for (int j = i + 1; j < array.length; j++) {
                if (!uf.find(i, j)) {
                    System.out.println("Disjoint pair: " + i + ", " + j);
                    long endTime = System.nanoTime();
                    System.out.println("Execution time: " + (endTime - startTime) / 1000000.0 + " ms");
                }
            }
        }
        return uf.count();
    }

    static class UnionFind {
        int[] parent;
        int[] rank;

        public UnionFind(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        public boolean find(int x, int y) {
            if (parent[x] == parent[y]) return true;
            if (rank[x] > rank[y]) {
                parent[y] = x;
            } else if (rank[y] > rank[x]) {
                parent[x] = y;
            } else {
                parent[x] = y;
                rank[y]++;
            }
            return false;
        }

        public int count() {
            int count = 0;
            for (int i = 0; i < parent.length; i++) {
                if (parent[i] == i) count++;
            }
            return count;
        }
    }
}
