// Function to initialize the collection
collection* collection_init() {
    collection* c = (collection*)malloc(sizeof(collection));
    c->size = 0;
    c->capacity = 10; // Initial capacity
    c->items = (data_item*)malloc(c->capacity * sizeof(data_item));
    pthread_mutex_init(&c->lock, NULL);
    return c;
}

// Function to add a new item to the collection
void collection_insert(collection* c, data_item* item) {
    int pos = binary_search(c, item);
    if (pos < 0) {
        // Insert at the end of the array
        if (c->size == c->capacity) {
            // Resize the array if it's full
            c->capacity *= 2;
            c->items = (data_item*)realloc(c->items, c->capacity * sizeof(data_item));
        }
        c->items[c->size] = *item;
        c->size++;
    } else {
        // Item already exists in the collection, update its position
        for (int i = c->size - 1; i > pos; i--) {
            c->items[i] = c->items[i-1];
        }
        c->items[pos] = *item;
        c->size++;
    }
}

// Binary search function to find the correct insertion point
int binary_search(collection* c, data_item* item) {
    int low = 0;
    int high = c->size - 1;
    while (low <= high) {
        int mid = (low + high) / 2;
        if (c->items[mid].timestamp == item->timestamp)
            return mid;
        else if (c->items[mid].timestamp < item->timestamp)
            low = mid + 1;
        else
            high = mid - 1;
    }
    return low; // Return the position to insert the new item
}

// Function to remove an item from the collection based on its timestamp
void collection_remove(collection* c, int timestamp) {
    int pos = binary_search(c, &(data_item){timestamp, '\0', 0});
    if (pos >= 0 && c->items[pos].timestamp == timestamp) {
        // Move all items after the removed item to fill the gap
        for (int i = pos; i < c->size - 1; i++) {
            c->items[i] = c->items[i+1];
        }
        c->size--;
    }
}

// Function to get an item from the collection based on its timestamp
data_item* collection_get(collection* c, int timestamp) {
    int pos = binary_search(c, &(data_item){timestamp, '\0', 0});
    if (pos >= 0 && c->items[pos].timestamp == timestamp)
        return &c->items[pos];
    return NULL; // Item not found
}

// Function to free the collection resources
void collection_free(collection* c) {
    pthread_mutex_destroy(&c->lock);
    free(c->items);
    free(c);
}
