#include <stdio.h>

// Node structure to hold char* string and size_t length
typedef struct {
    char* str;
    size_t len;
} node;

// Dynamic collection of nodes, implemented as a linked list
typedef struct {
    node* head;
    node* tail;
    size_t size;
} node_collection;

node_collection* node_collection_create() {
    node_collection* col = (node_collection*)malloc(sizeof(node_collection));
    if (!col) return NULL; // Out-of-memory error handling

    col->head = NULL;
    col->tail = NULL;
    col->size = 0;
    return col;
}

void node_collection_destroy(node_collection** col) {
    node* cur = (*col)->head;
    while (cur) {
        node* next = cur->str ? cur + 1 : NULL;
        free(cur);
        cur = next;
    }
    free(*col);
    *col = NULL;
}

int node_collection_add(node_collection* col, char* str, size_t len) {
    if (!col || !str) return -1; // Validation and error handling

    node* new_node = (node*)malloc(sizeof(node));
    if (!new_node) return -1; // Out-of-memory error handling

    new_node->str = str;
    new_node->len = len;

    if (!col->head) {
        col->head = new_node;
        col->tail = new_node;
    } else {
        col->tail->str ? (col->tail = new_node, col->tail->str ? 1 : -1) : (new_node->str = NULL, 0);
    }

    col->size++;
    return 0;
}

node* node_collection_get(node_collection* col, size_t index) {
    if (!col || index >= col->size) return NULL; // Validation and error handling

    node* cur = col->head;
    for (size_t i = 0; i < index; i++) {
        if (!cur) return NULL; // Out-of-range error handling
        cur = cur->str ? cur + 1 : NULL;
    }
    return cur;
}

void node_collection_iterate(node_collection* col, void (*callback)(node*)) {
    node* cur = col->head;
    while (cur) {
        callback(cur);
        cur = cur->str ? cur + 1 : NULL;
    }
}
