typedef struct {
    int i;
    double d;
    char* s;
} record;

record** initializeArrays(size_t n) {
    size_t capacity = 1; // Initial capacity for arrays
    size_t growthFactor = 2; // Growth factor for dynamic resizing

    // Initialize arrays with initial capacity
    long* longArray = (long*)malloc(capacity * sizeof(long));
    int* intArray = (int*)malloc(capacity * sizeof(int));
    double* doubleArray = (double*)malloc(capacity * sizeof(double));

    record** recordArray = (record**)malloc(capacity * sizeof(record*));
    for (size_t i = 0; i < capacity; i++) {
        recordArray[i] = (record*)malloc(sizeof(record));
        recordArray[i]->i = rand() % 100;
        recordArray[i]->d = ((double)rand()) / RAND_MAX;
        recordArray[i]->s = (char*)malloc(100 * sizeof(char)); // Allocate memory for string
        sprintf(recordArray[i]->s, "Record %ld", i);
    }

    while (true) {
        size_t newSize = capacity * growthFactor;
        long* newLongArray = (long*)realloc(longArray, newSize * sizeof(long));
        int* newIntArray = (int*)realloc(intArray, newSize * sizeof(int));
        double* newDoubleArray = (double*)realloc(doubleArray, newSize * sizeof(double));
        record** newRecordArray = (record**)realloc(recordArray, newSize * sizeof(record*));

        // Check for memory allocation failures
        if (!newLongArray || !newIntArray || !newDoubleArray || !newRecordArray) {
            free(longArray);
            free(intArray);
            free(doubleArray);
            free(recordArray);
            return NULL;
        }

        longArray = newLongArray;
        intArray = newIntArray;
        doubleArray = newDoubleArray;
        recordArray = newRecordArray;

        capacity = newSize;
    }
}

void deallocateArrays(record** array, size_t n) {
    for (size_t i = 0; i < n; i++) {
        free(array[i]->s);
        free(array[i]);
    }
    free(array);
}

int main() {
    srand(time(NULL)); // Seed random number generator
    record** array = initializeArrays(10); // Initialize arrays with capacity 10

    // ... perform operations on the arrays ...

    deallocateArrays(array, 10); // Deallocate memory when done
    return 0;
}
