        records[i].timestamp = minTimestamp + rand() % ((maxTimestamp - minTimestamp) + 1);
        records[i].key = rand() % (maxValue - minValue + 1) + minValue;
        records[i].value = (double)rand() / RAND_MAX;
    }

    return records;
}

int writeRecordsToFile(const char* filename, MetricRecord* records, int numRecords) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        return -1; // Handle file opening failure
    }

    for (int i = 0; i < numRecords; i++) {
        fwrite(&records[i], sizeof(MetricRecord), 1, file);
