    for (int i = 0; i < numRecords; i++) {
        records[i].offset = rand() % 10000;
        records[i].key = rand() % 100;
        records[i].data = (double)rand() / RAND_MAX;
    }

    return records;
}

// Define a function to store the generated records in a file using a custom binary format
void writeRecordsToFile(const char* filename, Record* records, int numRecords) {
    FILE* file = fopen(filename, "wb");

    // Check if file open operation failed
    if (file == NULL) {
        printf("File opening failed.\n");
        return;  // Return in case of failure
    }

    // Write the number of records to the file
    fwrite(&numRecords, sizeof(int), 1, file);

    // Write each record to the file
    for (int i = 0; i < numRecords; i++) {
        fwrite(&records[i], sizeof(Record), 1, file);
    }

    fclose(file);
}

// Function to read records from a file using a custom binary format
Record* readRecordsFromFile(const char* filename) {
    Record* records = NULL;
    int numRecords = 0;  // Initialize number of records

    // Open the file in binary mode for reading
    FILE* file = fopen(filename, "rb");

    // Check if file open operation failed
    if (file == NULL) {
        printf("File opening failed.\n");
        return NULL;  // Return null in case of failure
    }

    // Read the number of records from the file
    fread(&numRecords, sizeof(int), 1, file);

    // Allocate memory for the records array
    if ((records = (Record*)malloc(numRecords * sizeof(Record))) == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;  // Return null in case of failure
    }

    // Read each record from the file and initialize it
    for (int i = 0; i < numRecords; i++) {
        fread(&records[i], sizeof(Record), 1, file);
    }

    fclose(file);

    return records;
}

// Function to serialize and store a record in a persistent storage (e.g., database or file)
void persistRecord(const char* filename, Record record) {
    // Open the file in binary mode for writing
    FILE* file = fopen(filename, "ab");

    // Check if file open operation failed
    if (file == NULL) {
        printf("File opening failed.\n");
        return;  // Return in case of failure
    }

    // Write the record to the file
    fwrite(&record, sizeof(Record), 1, file);

    fclose(file);
}

