    Record* records = generateRecords(numRecords);

    if (records == NULL) {
        printf("Failed to generate records.\n");
        return -1;  // Return error code
    }

    writeRecordsToFile("records.dat", records, numRecords);

    free(records);  // Free the allocated memory

    return 0;
}
