// Hash table for storing 'double' as keys and 'char*' strings as values
typedef struct {
    size_t size;
    uint32_t* hash;
    MemPool* pool;
    Entry** entries;
} DoubleHash;

// Hash table for 'unsigned long' integers as keys and 'bool' flags as values
typedef struct {
    size_t size;
    uint32_t* hash;
    MemPool* pool;
    bool** entries;
} ULBoolHash;

// Custom memory allocation function using memory pool
void* mem_alloc(MemPool* pool, size_t size) {
    // Allocate memory from the pool
    void* ptr = NULL;
    if (pool->used + size <= pool->capacity) {
        ptr = realloc(pool->mem, (pool->used + size));
        if (!ptr) {
            printf("Memory allocation failed!\n");
            return NULL;  // Handle error and exit program
        }
    } else {
        printf("Out of memory! Cannot allocate %zu bytes.\n", size);
        return NULL;
    }
    pool->mem = ptr;
    pool->used += size;
    return ptr;
}

// Custom memory deallocation function using memory pool
void mem_free(MemPool* pool, void* ptr) {
    // Deallocate memory from the pool
    if (ptr) {
        free(ptr);
        pool->used -= sizeof(void*);
    }
}

// Initialize custom memory pool with initial capacity and maximum usage
MemPool* mem_pool_init(size_t init_cap, size_t max_usage) {
    MemPool* pool = malloc(sizeof(MemPool));
    if (!pool) {
        printf("Memory allocation failed for pool!\n");
        return NULL;
    }
    pool->mem = malloc(init_cap);
    if (!pool->mem) {
        printf("Memory allocation failed for pool memory!\n");
        free(pool);
        return NULL;
    }
    pool->capacity = init_cap;
    pool->used = 0;
    return pool;
}

// Free custom memory pool
void mem_pool_free(MemPool* pool) {
    if (pool) {
        mem_free(pool, pool->mem);
        free(pool);
    }
}

// Initialize double hash table with initial size and memory pool
DoubleHash* double_hash_init(size_t init_size, MemPool* pool) {
    DoubleHash* hash = malloc(sizeof(DoubleHash));
    if (!hash) {
        printf("Memory allocation failed for hash!\n");
        return NULL;
    }
    hash->size = init_size;
    hash->hash = malloc(sizeof(uint32_t) * init_size);
    if (!hash->hash) {
        printf("Memory allocation failed for hash array!\n");
        free(hash);
        return NULL;
    }
    hash->entries = malloc(sizeof(Entry*) * init_size);
    if (!hash->entries) {
        printf("Memory allocation failed for entries array!\n");
        free(hash->hash);
        free(hash);
        return NULL;
    }
    hash->pool = pool;
    return hash;
}

// Initialize unsigned long integer hash table with initial size and memory pool
ULBoolHash* ulbool_hash_init(size_t init_size, MemPool* pool) {
    ULBoolHash* hash = malloc(sizeof(ULBoolHash));
    if (!hash) {
        printf("Memory allocation failed for hash!\n");
        return NULL;
    }
    hash->size = init_size;
    hash->hash = malloc(sizeof(uint32_t) * init_size);
    if (!hash->hash) {
        printf("Memory allocation failed for hash array!\n");
        free(hash);
        return NULL;
    }
    hash->entries = malloc(sizeof(bool*) * init_size);
    if (!hash->entries) {
        printf("Memory allocation failed for entries array!\n");
        free(hash->hash);
        free(hash);
        return NULL;
    }
    hash->pool = pool;
    return hash;
}

// Initialize doubly linked list with initial size and memory pool
Entry* entry_init(size_t init_size, MemPool* pool) {
    Entry* head = malloc(sizeof(Entry));
    if (!head) {
