}

// Insert entry into doubly linked list
void entry_insert(Entry** head, double key, char* value) {
    Entry* new_entry = malloc(sizeof(Entry));
    if (!new_entry) {
        printf("Memory allocation failed for new entry!\n");
        return;  // Handle error and exit program
    }
    new_entry->key = key;
    new_entry->value = value;
    new_entry->prev = NULL;
    new_entry->next = *head;
    if (*head) {
        (*head)->prev = &new_entry;
    } else {
        *head = &new_entry;
    }
}

// Retrieve entry from doubly linked list
