// Periodic memory report function
void mem_report(MemPool* pool) {
    printf("Memory used: %zu bytes\n", pool->used);
    printf("Memory capacity: %zu bytes\n", pool->capacity);
    printf("Memory fragmentation ratio: (%zu/%zu)\n", pool->used, pool->capacity);
}

// Concurrency-safe wrapper function for memory allocation
void* mem_alloc_concurrent(MemPool* pool, size_t size) {
    pthread_mutex_lock(&pool->mutex);  // Acquire lock
    void* ptr = mem_alloc(pool, size);
    pthread_mutex_unlock(&pool->mutex);  // Release lock
    return ptr;
}

// Concurrency-safe wrapper function for memory deallocation
void mem_free_concurrent(MemPool* pool, void* ptr) {
    pthread_mutex_lock(&pool->mutex);  // Acquire lock
    mem_free(pool, ptr);
    pthread_mutex_unlock(&pool->mutex);  // Release lock
}

