#include <stdlib.h>
#include <pthread.h>

// Define the structure for network packet headers
typedef struct {
    size_t size;
    char* data;
} PacketHeader;

// Initialize the pool with a specified initial capacity
PacketHeader** initialize_packet_pool(size_t initial_capacity) {
    PacketHeader** pool = (PacketHeader**)calloc(initial_capacity, sizeof(PacketHeader*));
    return pool;
}

// Allocate memory for a new packet header of given size
PacketHeader* allocate_packet_header(size_t size) {
    PacketHeader* packet = (PacketHeader*)malloc(sizeof(PacketHeader));
    packet->size = size;
    packet->data = malloc(size);
    return packet;
}

// Deallocate the resources associated with a packet header
void deallocate_packet_header(PacketHeader* packet) {
    free(packet->data);
    free(packet);
}

// Manage the dynamic pool of packet headers, handling allocation and deallocation efficiently
int manage_packet_pool(PacketHeader** pool, size_t initial_capacity, size_t capacity_increment) {
    // Handle concurrent access from multiple threads (thread-safe)
    pthread_mutex_lock();

    // Check if the pool needs to be resized
    if (pool->size + capacity_increment > initial_capacity) {
        // Resize the pool and re-initialize the array
        pool = (PacketHeader**)realloc(pool, sizeof(PacketHeader*) * (pool->size + capacity_increment));
        initial_capacity += capacity_increment;
    }

    // Allocate memory for a new packet header of given size
    PacketHeader* packet = allocate_packet_header(size);

    // Add the packet to the pool
    pool->size++;
    pool[pool->size - 1] = packet;

    // Update the mutex and return the updated capacity
    pthread_mutex_unlock();
    return initial_capacity;
}

// Example usage:
int main() {
    size_t initial_capacity = 10;
    PacketHeader** packet_pool = initialize_packet_pool(initial_capacity);

    // Manage the dynamic pool of packet headers under various conditions
    for (size_t i = 0; i < 100; i++) {
        int updated_capacity = manage_packet_pool(packet_pool, initial_capacity, i % 2 == 0 ? 10 : 5);
        if (updated_capacity > initial_capacity) {
            printf("Updated capacity: %zu\n", updated_capacity);
        }
    }

    // Clean up and deallocate memory
    for (size_t i = 0; i < packet_pool->size; i++) {
        deallocate_packet_header(packet_pool[i]);
    }
    free(packet_pool);

    return 0;
}
