typedef struct transaction_node {
    time_t timestamp;
    bool status;
    double amount;
    struct transaction_node* next;
} transaction_node_t;

transaction_node_t* create_transaction(time_t timestamp, bool status, double amount) {
    transaction_node_t* node = (transaction_node_t*)malloc(sizeof(transaction_node_t));
    if (!node) {
        return NULL; // allocation failed
    }
    node->timestamp = timestamp;
    node->status = status;
    node->amount = amount;
    node->next = NULL;
    return node;
}

void add_transaction(transaction_node_t** head, time_t timestamp, bool status, double amount) {
    transaction_node_t* new_node = create_transaction(timestamp, status, amount);
    if (*head == NULL || new_node->timestamp < (*head)->timestamp) {
        new_node->next = *head;
        *head = new_node;
    } else {
        transaction_node_t* curr = *head;
        while (curr->next && curr->next->timestamp >= timestamp) {
            curr = curr->next;
        }
        new_node->next = curr->next;
        curr->next = new_node;
    }
}

void free_transactions(transaction_node_t** head) {
    transaction_node_t* curr = *head;
    while (curr) {
        transaction_node_t* next = curr->next;
        free(curr);
        curr = next;
    }
    *head = NULL;
}
