// Define a structure for task data
typedef struct {
    int priority;
    char due_date[20];
    char status[10];
} Task;

// Define the dynamic list of tasks
Task **task_list = NULL;
int task_count = 0;

// Function to add a new task
void add_task(int priority, const char *due_date, const char *status) {
    // Allocate memory for the new task structure
    Task *new_task = (Task *)malloc(sizeof(Task));
    if (!new_task) return;  // Handle out-of-memory error

    new_task->priority = priority;
    strcpy(new_task->due_date, due_date);
    strcpy(new_task->status, status);

    // Add the new task to the list
    task_list = (Task **)realloc(task_list, sizeof(Task *) * ++task_count);
    task_list[task_count - 1] = new_task;
}

// Function to remove a task by priority
void remove_task(int priority) {
    for (int i = 0; i < task_count; i++) {
        if (task_list[i]->priority == priority) {
            free(task_list[i]);
            memmove(&task_list[i], &task_list[i + 1], sizeof(Task *) * (task_count - i));
            task_count--;
            return;
        }
    }
}

// Function to update a task
void update_task(int priority, const char *due_date, const char *status) {
    for (int i = 0; i < task_count; i++) {
        if (task_list[i]->priority == priority) {
            strcpy(task_list[i]->due_date, due_date);
            strcpy(task_list[i]->status, status);
            return;
        }
    }
}

// Function to retrieve tasks by priority or due date
void get_tasks_by(int type, const char *query) {
    if (type == 1) { // Priority
        for (int i = 0; i < task_count; i++) {
            if (task_list[i]->priority >= atoi(query)) {
                printf("Priority: %d Due Date: %s Status: %s\n", 
                       task_list[i]->priority, task_list[i]->due_date, task_list[i]->status);
            }
        }
    } else { // Due Date
        for (int i = 0; i < task_count; i++) {
            if (strcmp(task_list[i]->due_date, query) == 0) {
                printf("Priority: %d Due Date: %s Status: %s\n", 
                       task_list[i]->priority, task_list[i]->due_date, task_list[i]->status);
            }
        }
    }
}

// Function to handle external API updates
void update_tasks_from_api(void) {
    // Simulate network call and data processing
    sleep(2);  // Wait for 2 seconds

    // Update tasks list ( assume success )
    for (int i = 0; i < task_count; i++) {
        // Process updated task data
        printf("Updated Task: Priority: %d Due Date: %s Status: %s\n", 
               task_list[i]->priority, task_list[i]->due_date, task_list[i]->status);
    }
}

// Function to handle transient failures and retries
void handle_api_failure(int retries) {
    if (retries > 5) { // Maximum retries exceeded
        printf("Maximum retries exceeded. Aborting API updates.\n");
        return;
    }

    // Simulate network call failure
    sleep(1);  // Wait for 1 second

    // Retry updating tasks from API
    update_tasks_from_api();
}

// Function to load configuration settings from JSON file
void load_config(void) {
    FILE *file = fopen("config.json", "r");
    if (!file) return;  // Handle missing or corrupt file error

    // Load and process configuration data

    fclose(file);
}

int main() {
    pthread_t thread;

    // Initialize task list
    add_task(1, "2024-01-01", "Not Started");

    // Start a separate thread to handle API updates
    pthread_create(&thread, NULL, update_tasks_from_api, NULL);

    // Simulate user interactions and updates
    printf("Task Manager: ");
    int choice;
    scanf("%d", &choice);
    switch (choice) {
        case 1:
            add_task(2, "2024-01-05", "In Progress");
            break;
        case 2:
            remove_task(1);
            break;
        case 3:
            update_task(2, "2024-01-10", "Completed");
            break;
        default:
            printf("Invalid choice. Exiting...\n");
            pthread_cancel(thread);  // Cancel API update thread
            exit(EXIT_FAILURE);
    }

    return 0;
}

