#include <stdlib.h>
#include <stdio.h>

typedef struct node {
    int key;
    struct node* next;
} node;

node* create_node(int key) {
    node* new_node = (node*)malloc(sizeof(node));
    if (!new_node) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    new_node->key = key;
    new_node->next = NULL;
    return new_node;
}

void insert_node(node** head, int key, node* new_node) {
    if (*head == NULL || (*head)->key > key) {
        new_node->next = *head;
        *head = new_node;
    } else {
        node* current = *head;
        while (current->next && current->next->key <= key) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
}

void print_list(node* head) {
    while (head) {
        printf("%d ", head->key);
        head = head->next;
    }
    printf("\n");
}

node* insert_at_position(node** head, int position, int key) {
    if (!*head) {
        *head = create_node(key);
        return *head;
    }

    node* new_node = create_node(key);

    if (position == 0) {
        new_node->next = *head;
        *head = new_node;
        return *head;
    }

    int i = 1;
    node* current = *head;
    while (current && i < position) {
        current = current->next;
        i++;
    }
    if (!current) {
        printf("Position out of range\n");
        return *head;
    }
    new_node->next = current->next;
    current->next = new_node;
    return *head;
}

int main() {
    node* head = NULL;

    // Example usage
    head = insert_at_position(&head, 0, 5);
    head = insert_at_position(&head, 1, 2);
    head = insert_at_position(&head, 2, 8);
    print_list(head);

    return 0;
}
