    if (fd < 0) return -1;
    for (int i = 0; i < count; i++) {
        record r = records[i];
        size_t len = RECORD_SIZE;
        char *buf = alloca(len);
        memcpy(buf, &r, len);
        write(fd, buf, len);
    }
    close(fd);
    return 0;
}

int read_records_from_file(record **records, int *count, char *filename) {
    int fd = open(filename, O_RDONLY);
    if (fd < 0) return -1;
