    fstat(fd, &sb);
    size_t len = sb.st_size / RECORD_SIZE;
    *count = len;
    *records = alloca(len * RECORD_SIZE);
    record *r = *records;
    for (int i = 0; i < len; i++) {
        read(fd, r++, RECORD_SIZE);
    }
    close(fd);
    return 0;
}

