#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
    double data_point;
} record;

record* create_dataset(int num_records) {
    // Initialize memory allocation flags
    int success = 0;
    record* records = NULL;

    // Allocate memory for the array of records
    while (!success) {
        records = (record*)malloc(num_records * sizeof(record));
        if (records == NULL) {
            printf("Memory allocation failed!\n");
            free(records); // Release allocated resources on failure
            return NULL;
        }
        success = 1;
    }

    // Initialize and populate each record with random data
    srand(time(NULL)); // Seed the random number generator
    for (int i = 0; i < num_records; i++) {
        records[i].key = rand() % 10000; // Random integer within a range of 10,000
        records[i].offset = rand(); // Random long offset
        records[i].data_point = ((double)rand()) / RAND_MAX; // Random double-precision floating-point number
    }

    return records;
}

int persist_dataset(record* records, int num_records) {
    FILE* file = fopen("dataset.txt", "w"); // Open the output file

    if (file == NULL) {
        printf("Failed to open the file for writing!\n");
        return -1; // Indicate failure
    }

    // Write each record to the file, using thread-safe operations
    for (int i = 0; i < num_records; i++) {
        fprintf(file, "%d %ld %f\n", records[i].key, records[i].offset, records[i].data_point);
    }

    fclose(file); // Close the output file

    return 0; // Indicate success
}

int main() {
    int num_records = 10000000; // Desired number of records (10 million)
    record* dataset = create_dataset(num_records);

    if (dataset == NULL) {
        printf("Failed to create the dataset!\n");
        return -1;
    }

    persist_dataset(dataset, num_records);

    free(dataset); // Release allocated resources

    return 0; // Indicate success
}
