#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <string.h>
#include <pthread.h>

// Define a record structure to hold integer, long, double, and enum values
typedef struct {
    int value;
    long* ptr;
    double data;
    enum state status;
} Record;

// Enum for record states
enum state { NEW, MODIFIED, DELETED };

// Function to dynamically allocate memory and initialize an array of records
Record** generateRecords(int numRecords, int seed) {
    srand(seed);

    Record** records = (Record**)malloc(numRecords * sizeof(Record*));

    if (!records) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < numRecords; i++) {
        records[i] = (Record*)malloc(sizeof(Record));

        if (!records[i]) {
            printf("Memory allocation failed.\n");

            // Free previously allocated memory
            for (int j = 0; j < i; j++) {
                free(records[j]);
            }

            free(records);
            return NULL;
        }

        records[i]->value = rand() % 100;
        records[i]->ptr = (long*)malloc(sizeof(long));
        *records[i]->ptr = rand();
        records[i]->data = (double)rand() / RAND_MAX;
        records[i]->status = NEW;

        printf("Generated record: value=%d, ptr=0x%lx, data=%.2lf, status=%s\n", 
               records[i]->value, *records[i]->ptr, records[i]->data, get_state_string(records[i]->status));
    }

    return records;
}

// Function to convert enum state to string
const char* get_state_string(enum state state) {
    switch (state) {
        case NEW:
            return "NEW";
        case MODIFIED:
            return "MODIFIED";
        case DELETED:
            return "DELETED";
        default:
            return "Unknown";
    }
}

// Example application to demonstrate record generation and storage
int main() {
    int numRecords = 10;
    int seed = time(NULL);

    Record** records = generateRecords(numRecords, seed);

    // Write records to file for persistence
    FILE* file = fopen("records.txt", "wb");

    if (file) {
        fwrite(&numRecords, sizeof(int), 1, file);
        fwrite(seed, sizeof(int), 1, file);

        for (int i = 0; i < numRecords; i++) {
            fwrite(&records[i]->value, sizeof(int), 1, file);
            fwrite(records[i]->ptr, sizeof(long), 1, file);
            fwrite(&records[i]->data, sizeof(double), 1, file);
            fwrite(&records[i]->status, sizeof(enum state), 1, file);
        }

        fclose(file);

    } else {
        printf("Failed to open file.\n");
    }

    // Read and display records from file
    file = fopen("records.txt", "rb");

    if (file) {
        int numRecordsRead;
        fread(&numRecordsRead, sizeof(int), 1, file);
        fread(&seed, sizeof(int), 1, file);

        printf("Number of records: %d\n", numRecordsRead);
        printf("Seed: %d\n", seed);

        for (int i = 0; i < numRecordsRead; i++) {
            int value;
            long ptrValue;
            double dataValue;
            enum state status;

            fread(&value, sizeof(int), 1, file);
            fread(&ptrValue, sizeof(long), 1, file);
            fread(&dataValue, sizeof(double), 1, file);
            fread(&status, sizeof(enum state), 1, file);

            printf("Record: value=%d, ptr=0x%lx, data=%.2lf, status=%s\n", 
                   value, ptrValue, dataValue, get_state_string(status));
        }

        fclose(file);
    } else {
        printf("Failed to open file.\n");
    }

    return 0;
}

