// Predefined set of log messages with duplicates
char *logMessages[] = {"Message 1", "Error occurred", "System failure", "Message 3", "Warning: Possible crash", "System up and running", "Message 5", "Message 6"};

typedef struct {
    int errorCode;
    int status;
    struct logEntry *prev; // Back reference to previous entry
} info;

typedef struct logEntry {
    double timestamp;
    char message[257]; // +1 for null-terminator
    info details;
    struct logEntry *next;
} logEntry;

// Function to add a new log entry to the list
logEntry *addLogEntry(logEntry **head) {
    logEntry *newEntry = (logEntry *)malloc(sizeof(logEntry));
    if (!newEntry) return NULL; // Error: Memory allocation failed

    // Initialize random timestamp and log message
    srand(time(NULL)); // Seed for reproducibility
    newEntry->timestamp = (double)rand() / RAND_MAX;
    char *message = logMessages[rand() % sizeof(logMessages) / sizeof(logMessages[0])];
    strcpy(newEntry->message, message);

    // Initialize error code and status
    newEntry->details.errorCode = 0;
    newEntry->details.status = rand() % 6;

    // Set back reference to NULL initially
    newEntry->details.prev = NULL;

    logEntry *current = *head;
    if (current) {
        while (current->next) current = current->next; // Find last entry in list
        current->next = newEntry;
    } else {
        *head = newEntry;
    }

    return newEntry;
}

// Function to detect and handle circular references
int isCircular(logEntry *entry, logEntry **head) {
    if (!entry) return 0; // Not circular

    logEntry *current = entry;
    while (1) {
        if (current->details.prev == current || current->next == current) {
            freeLogEntries(head); // Handle circular reference
            return -1; // Circular reference detected
        }
        current = current->next;
        if (!current) break; // Not circular
    }
    return 0; // No circular reference
}

// Function to free memory allocated for log entries
void freeLogEntries(logEntry **head) {
    logEntry *current = *head, *next;
    while (current) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}
