    conn1->data_packets = (void**)malloc(sizeof(void*) * 10);
    conn1->data_packets[0] = packet1;

    uint8_t payload2[] = "Goodbye, World!";
    time_t timestamp2 = time(NULL) + 1000;
    data_packet_t* packet2 = create_data_packet(payload2, timestamp2);
    conn2->data_packets = (void**)malloc(sizeof(void*) * 10);
    conn2->data_packets[0] = packet2;

    // Create connection sessions and attach them to the connections
    config_t config1 = {"default_config"};
    monitoring_t metrics1 = {{"metric1", "value1"}, {"metric2", "value2"}};
    connection_session_t* session1 = create_connection_session(1, config1, metrics1);
    conn1->session = session1;

    config_t config2 = {"custom_config"};
    monitoring_t metrics2 = {{"metric3", "value3"}, {"metric4", "value4"}};
