    char* id;
} Node;

typedef struct DistributedNodeSystem {
    int* integerArray;
    Node* linkedList;
    Node*** arrayOfLinkedLists;
} DistributedNodeSystem;

DistributedNodeSystem* allocateAndInitializeDistributedNodeSystem(int size) {
    DistributedNodeSystem* system = (DistributedNodeSystem*)malloc(sizeof(DistributedNodeSystem));
    if (!system) return NULL; // handle allocation failure

    system->integerArray = (int*)calloc(size, sizeof(int));
    if (!system->integerArray) {
        free(system);
        return NULL;
    }

    system->linkedList = (Node*)malloc(size * sizeof(Node));
    if (!system->linkedList) {
        free(system->integerArray);
        free(system);
        return NULL;
    }

    system->arrayOfLinkedLists = (Node***)calloc(size, sizeof(Node*));
    if (!system->arrayOfLinkedLists) {
        free(system->integerArray);
        free(system->linkedList);
        free(system);
        return NULL;
    }

    // populate nodes with random values and unique IDs
    for (int i = 0; i < size; i++) {
        system->integerArray[i] = rand() % 100;
        system->linkedList[i].value = rand() % 100;
        system->linkedList[i].id = malloc(16);
        sprintf(system->linkedList[i].id, "node-%d", i);

        for (int j = 0; j < size / 2; j++) {
            Node* node = (Node*)malloc(sizeof(Node));
            node->value = rand() % 100;
            system->arrayOfLinkedLists[i][j] = node;
        }
    }

    return system;
}

void freeDistributedNodeSystem(DistributedNodeSystem* system) {
    for (int i = 0; i < system->size; i++) {
        if (system->integerArray[i]) free(system->integerArray[i]);
        if (system->linkedList[i].id) free(system->linkedList[i].id);
        for (int j = 0; j < system->size / 2; j++) {
            Node* node = system->arrayOfLinkedLists[i][j];
            if (node) free(node);
        }
    }

    free(system->integerArray);
    free(system->linkedList);
    free(system->arrayOfLinkedLists);
    free(system);
}
