TemperatureMeasurement* initialize_temperature_measurements(int num_measurements) {
    // Dynamically allocate memory for the array
    TemperatureMeasurement* measurements = (TemperatureMeasurement*)malloc(num_measurements * sizeof(TemperatureMeasurement));

    // Initialize each measurement with a timestamp and within_normal_limits flag
    for (int i = 0; i < num_measurements; i++) {
        measurements[i].timestamp = time(NULL);
        measurements[i].within_normal_limits = 0;
    }

    return measurements;
}

// Function to detect and handle duplicate temperature entries
void remove_duplicates(TemperatureMeasurement* measurements, int num_measurements) {
    // Create a semaphone for thread safety
    sem_t sem;
    if (sem_init(&sem, 0, 1) != 0) {
        perror("Semaphone initialization failed");
        exit(EXIT_FAILURE);
    }

    // Iterate through the measurements and remove duplicates
    for (int i = 0; i < num_measurements; i++) {
        for (int j = i + 1; j < num_measurements; j++) {
            if (measurements[i].temperature == measurements[j].temperature) {
                free(&measurements[j]);
                num_measurements--;
                break;
            }
        }
    }

    // Destroy the semaphone
    sem_destroy(&sem);
}

