typedef struct {
    size_t block_size;
    size_t cache_line_alignment;
} AllocatorConfig;

// Custom memory allocator function
void* my_malloc(size_t size, AllocatorConfig config) {
    // Allocate memory using malloc()
    void* ptr = malloc(size);

    // Apply alignment if necessary
    if ((size % config.cache_line_alignment) != 0) {
        ptr = (void*)((size_t)ptr + (config.cache_line_alignment - (size % config.cache_line_alignment)));
    }

    return ptr;
}

// Define record structure with unique integer key, offset value, and initialized random field
typedef struct Record {
    int key;
    long offset;
    int field;
} Record;

// Lock for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to manage dynamic collection of records
void* record_manager(void* ptr) {
    // Initialize record with unique integer key, offset value, and initialized random field
    Record* record = (Record*)my_malloc(sizeof(Record), (AllocatorConfig){64, 16});
    record->key = rand();
    record->offset = rand();
    record->field = rand() % 100;

    // Lock for thread safety during write operation
    pthread_mutex_lock(&lock);

    // Write record to file and update current offset value
    FILE* file = fopen("records.bin", "ab");
    fwrite(record, sizeof(Record), 1, file);
    fclose(file);

    // Release lock after successful write
    pthread_mutex_unlock(&lock);

    return NULL;
}

// Function to serialize record collection to file format optimized for fast sequential reads and writes
void serialize_records() {
    FILE* file = fopen("records.bin", "rb");
    Record* record;
    while (fread(&record, sizeof(Record), 1, file) == 1) {
        // Serialize data types: integers, pointers, and custom structures
        fwrite(&record->key, sizeof(int), 1, file);
        fwrite(&record->offset, sizeof(long), 1, file);
        fwrite(&record->field, sizeof(int), 1, file);
    }
    fclose(file);
}

// Function to implement checkpointing mechanism for persistent storage
void checkpoint_records() {
    FILE* file = fopen("records.checkpoint", "wb");
    Record* record;
    while (fread(&record, sizeof(Record), 1, file) == 1) {
        // Serialize data types: integers, pointers, and custom structures
        fwrite(&record->key, sizeof(int), 1, file);
        fwrite(&record->offset, sizeof(long), 1, file);
        fwrite(&record->field, sizeof(int), 1, file);
    }
    fclose(file);
}

// Function to monitor memory usage and provide timely notifications when thresholds are approached or exceeded
void* memory_monitor(void* ptr) {
    // Monitor memory usage and notify application when thresholds are reached
    while (1) {
        // Check soft constraints (e.g., 80% full)
        if (mem_usage() > 0.8) {
            printf("Memory usage exceeds soft threshold (80%).\n");
        }

        // Check hard constraints (e.g., 90% full)
        if (mem_usage() > 0.9) {
            printf("Memory usage exceeds hard threshold (90%). Notify the application.\n");
            break;
        }
    }
    return NULL;
}

int main() {
    pthread_t thread;

    // Create and start record manager thread
    pthread_create(&thread, NULL, record_manager, NULL);

    // Implement checkpointing mechanism to periodically save record collection state
    while (1) {
        serialize_records();
        sleep(10); // Update every 10 seconds
        checkpoint_records();
    }

    return 0;
}
