        records[i]->id = rand() % (maxValue - minValue + 1) + minValue;
        records[i]->weight = (float)rand() / RAND_MAX;
        char name[16];
        sprintf(name, "Record-%d", i);
        records[i]->name = strdup(name);
    }
    return records;
}

// Function to persistently store records in a file using a custom binary format
void storeRecords(Record **records, int size, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) return; // File access failure

    for (int i = 0; i < size; i++) {
        fwrite(&records[i]->id, sizeof(int), 1, fp);
        fwrite(&records[i]->weight, sizeof(float), 1, fp);
        int len = strlen(records[i]->name) + 1;
        fwrite(&len, sizeof(int), 1, fp);
        fwrite(records[i]->name, 1, len, fp);
    }
    fclose(fp);
}

// Function to read records from a file and free allocated memory
void loadRecords(Record ***records, int *size, const char *filename) {
    FILE *fp = fopen(filename, "rb");
    if (!fp) return; // File access failure

    Record **tmpRecords = (Record **)malloc(*size * sizeof(Record *));
    if (!tmpRecords) return; // Memory allocation failure

    for (int i = 0; i < *size; i++) {
        fread(&tmpRecords[i]->id, sizeof(int), 1, fp);
        fread(&tmpRecords[i]->weight, sizeof(float), 1, fp);
        int len;
        fread(&len, sizeof(int), 1, fp);
        tmpRecords[i]->name = (char *)malloc(len);
        if (!tmpRecords[i]->name) return; // Memory allocation failure
        fread(tmpRecords[i]->name, 1, len, fp);
    }
    fclose(fp);

    *records = tmpRecords;
}

int main() {
    int size = 1000000; // Initialize with a large dataset for demonstration
    int minValue = 1;
    int maxValue = 1000;

    Record **records = initRecords(size, minValue, maxValue);
    if (!records) printf("Memory allocation failure\n");
    else {
        storeRecords(records, size, "records.bin");

        Record ***loadedRecords;
        int loadedSize;
        loadRecords(&loadedRecords, &loadedSize, "records.bin");

        for (int i = 0; i < loadedSize; i++) {
            printf("Record-%d: ID=%d, Weight=%.2f, Name=%s\n", i, records[i]->id, records[i]->weight, records[i]->name);
        }

        // Free allocated memory
        for (int i = 0; i < size; i++) {
            free(records[i]->name);
            free(records[i]);
        }
        free(records);

        for (int i = 0; i < loadedSize; i++) {
            free(loadedRecords[i]->name);
            free(loadedRecords[i]);
        }
        free(loadedRecords);
    }

    return 0;
}
