// Thread-safe record management function
void* manage_records(int key, long offset) {
    // Allocate a new block if necessary
    mem_block* block = (mem_block*)malloc(sizeof(mem_block));
    block->base = mmap(NULL, sizeof(struct record), PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    block->size = sizeof(struct record);

