    struct record* rec = (struct record*)block->base;
    rec->key = key;
    rec->offset = offset;
    rec->field = rand() % 100;  // Randomly initialized field

    return block;
}

// Thread-safe garbage collection mechanism
void gc(void* mem_block_ptr) {
    mem_block* block = (mem_block*)mem_block_ptr;

    // Check for unused blocks and reclaim memory if necessary
    if (block->size == 0) {
        munmap(block->base, block->size);
        free(block);
    }
}

// Custom serialization function for record management
int serialize(void* mem_block_ptr, FILE* file) {
    mem_block* block = (mem_block*)mem_block_ptr;

    // Write the record to the file
    fwrite(block->base, block->size, 1, file);

    return 0;
}

// Custom deserialization function for record management
int deserialize(void* mem_block_ptr, FILE* file) {
    mem_block* block = (mem_block*)mem_block_ptr;

    // Read the record from the file
    fread(block->base, block->size, 1, file);

    return 0;
}

