#define MAX_RECORDS 1000
#define MIN_KEY 1
#define MAX_KEY 10000
#define FIXED_BUFFER_SIZE 32
#define DYNAMIC_BUFFER_MAX_SIZE 2048

typedef struct {
    int key;
    char fixed_buffer[FIXED_BUFFER_SIZE];
    char* dynamic_buffer;
} record;

void init_records(record* records, int num_records, int min_key, int max_key) {
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].key = rand() % (max_key - min_key + 1) + min_key;
        strcpy(records[i].fixed_buffer, "Predefined_string");
    }
}

record* create_memory_pool(int num_records) {
    record* pool = (record*)malloc(num_records * sizeof(record));
    for (int i = 0; i < num_records; i++) {
        pool[i].dynamic_buffer = NULL;
    }
    return pool;
}

void delete_memory_pool(record* pool, int num_records) {
    for (int i = 0; i < num_records; i++) {
        if (pool[i].dynamic_buffer != NULL) {
            free(pool[i].dynamic_buffer);
        }
    }
    free(pool);
}

record* allocate_record(record* pool, int record_index) {
    record* record_ptr = &pool[record_index];
    // Allocate dynamic buffer
    char* dyn_buf = malloc(DYNAMIC_BUFFER_MAX_SIZE);
    if (dyn_buf == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    record_ptr->dynamic_buffer = dyn_buf;
    return pool;
}

void deallocate_record(record* pool, int record_index) {
    record* record_ptr = &pool[record_index];
    // Deallocate dynamic buffer
    free(record_ptr->dynamic_buffer);
    record_ptr->dynamic_buffer = NULL;
}

void insert_record(record* records, int num_records, int key, const char* data) {
    // Find the first empty slot in the pool
    for (int i = 0; i < num_records; i++) {
        if (records[i].key == 0) {
            // Insert new record with unique key and data
            records[i].key = key;
            strcpy(records[i].fixed_buffer, "Predefined_string");
            char* dyn_data = malloc(strlen(data) + 1);
            strcpy(dyn_data, data);
            records[i].dynamic_buffer = dyn_data;
            return;
        }
    }
}

void delete_record(record* pool, int record_index) {
    // Deallocate dynamic buffer
    deallocate_record(pool, record_index);
}

// Log memory usage and operations
void log_memory_usage(int num_records, int total_allocated_bytes) {
    printf("Memory Usage: %d records, Total Allocated Bytes: %d\n", num_records, total_allocated_bytes);
}
