#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Integer counter structure
typedef struct {
    int count;
} integer_counter_t;

// Linked list node structure
typedef struct node {
    void* data;
    struct node* next;
} node_t;

// Graph structure
typedef struct graph {
    node_t* nodes;
    int num_nodes;
} graph_t;

graph_t* graph_init() {
    graph_t* g = malloc(sizeof(graph_t));
    g->nodes = NULL;
    g->num_nodes = 0;
    return g;
}

int node_insert(graph_t* g, void* data) {
    node_t* new_node = malloc(sizeof(node_t));
    new_node->data = data;
    new_node->next = g->nodes;
    g->nodes = new_node;
    g->num_nodes++;
    return 0;
}

void graph_free(graph_t* g) {
    node_t* current = g->nodes;
    while (current != NULL) {
        node_t* next = current->next;
        free(current);
        current = next;
    }
    free(g);
}
