use std::io;
use std::time::{Duration, Instant};
use reqwest;

struct GraphClient {
    graph: *mut graph_t,
    timeout: u64,
}

impl GraphClient {
    fn new(graph_init: *mut graph_t) -> Self {
        GraphClient {
            graph: graph_init,
            timeout: 5000, // Default timeout
        }
    }

    async fn insert_node(&self, data: &str) -> Result<(), reqwest::Error> {
        let start = Instant::now();
        let res = reqwest::get("http://graph-api/insert")
            .timeout(Duration::from_millis(self.timeout as u128))
            .send()
            .await?;
        if res.status().is_success() {
            node_insert(self.graph, data.as_ptr());
        }
        println!("Inserted node in {}ms", start.elapsed().as_millis());
        Ok(())
    }

    async fn get_graph(&self) -> Result<String, reqwest::Error> {
        let start = Instant::now();
        let res = reqwest::get("http://graph-api/graph")
            .timeout(Duration::from_millis(self.timeout as u128))
            .send()
            .await?;
        if res.status().is_success() {
            let graph_json = String::from_utf8_lossy(&res.bytes_to_string());
            println!("Received graph in {}ms", start.elapsed().as_millis());
            Ok(graph_json.to_string())
        } else {
            Err(res.error_for_status().unwrap())
        }
    }
}
