    pthread_mutex_lock(&mutex);
    media_streams = (media_stream**)realloc(media_streams, sizeof(media_stream*) * ++num_media_streams);
    media_streams[num_media_streams - 1] = stream;
    pthread_mutex_unlock(&mutex);
}

