    long long sum = 0;

    while (fscanf(file, "%d", &entries[unique_entries]->value) == 1) {
        if (entries[unique_entries]->value < 0 || entries[unique_entries]->value > 2147483647) continue;

        for (int i = 0; i < unique_entries; i++) {
            if (entries[i]->value == entries[unique_entries]->value) break;
        }

        if (i == unique_entries) {
            entries[unique_entries] = (NumberEntry*)malloc(sizeof(NumberEntry));
