    if (!list) {
        return NULL; // memory allocation failed
    }

    for (int i = 0; i < size; i++) {
        list[i].key = malloc(strlen("default_key") + 1); // allocate enough space for the key
        strcpy(list[i].key, "default_key");
        list[i].value = 0.0;
    }

    return list;
}

void free_item_list(item* list) {
    if (!list) return; // nothing to free

    for (int i = 0; i < sizeof(list)/sizeof(list[0]); i++) {
        free(list[i].key);
    }

    free(list);
}

// Example usage:
int main() {
    int size = 10;
    item* list = init_item_list(size);
    if (!list) {
        printf("Memory allocation failed.\n");
    } else {
        // use the item list
        for (int i = 0; i < size; i++) {
            printf("Key: %s, Value: %.2f\n", list[i].key, list[i].value);
        }

        free_item_list(list);
    }

    return 0;
