        // Memory allocation failed, free allocated resources
        free(*floatArray);
        free(*charArray);
        free(*structArray);
        return;
    }

    // Initialize struct objects and set timestamps
    for (int i = 0; i < 3; i++) {
        (*structArray)[i] = (StructData*)malloc(sizeof(StructData));
        if ((*structArray)[i] == NULL) {
            // Memory allocation failed, free allocated resources
            for (int j = 0; j <= i; j++) {
                free((*structArray)[j]);
            }
            free(*floatArray);
            free(*charArray);
            return;
        }

        (*structArray)[i]->id = i;
        (*structArray)[i]->timestamp = (double)time(NULL); // Set timestamp to current system time
        (*structArray)[i]->label = (char*)malloc((strlen("Label") + 1) * sizeof(char));
        strcpy((*structArray)[i]->label, "Label");
    }
}
