#include <time.h>

typedef struct {
    int value;
} record;

int manage_memory(int offset_size, int max_memory_limit) {
    if (offset_size <= 0 || max_memory_limit <= 0) return -1; // Error: Invalid input

    int long_array_size = offset_size;
    int int_array_size = (long_array_size >> 1);
    int record_array_size = ((long_array_size >> 1) + 1);

    if (record_array_size * sizeof(record) > max_memory_limit) {
        return -2; // Error: Exceeded memory limit
    }

    long* offsets;
    int* keys;
    record* records;

    offsets = malloc(long_array_size * sizeof(long));
    if (!offsets) return -3; // Memory allocation error for offsets

    keys = malloc(int_array_size * sizeof(int));
    if (!keys) {
        free(offsets);
        return -4; // Memory allocation error for keys
    }

    records = malloc(record_array_size * sizeof(record));
    if (!records) {
        free(keys);
        free(offsets);
        return -5; // Memory allocation error for records
    }

    srand(time(NULL)); // Initialize random number generator

    int key_index = 0;
    for (int i = 0; i < long_array_size; i++) {
        offsets[i] = i;

        if (i % 2 == 1) {
            keys[key_index++] = i;
        }
    }

    for (int i = 0; i < record_array_size; i++) {
        records[i].value = rand() % 1001; // Random value between 0 and 1000

        if (i < record_array_size - 1) {
            while ((records[i].value == records[i + 1].value)) {
                records[i].value = rand() % 1001;
            }
        }
    }

    free(keys);
    free(offsets);

    return record_array_size;
}
