typedef struct {
    long offset;
    int key;
    struct record* next;
} record;

record* manage_memory(long num_offsets, long num_keys, int min_key, int max_key, size_t threshold) {
    // Calculate total memory required
    size_t total_size = (num_offsets * sizeof(long)) + (num_keys * sizeof(int)) + ((num_offsets + 1) * sizeof(record));

    if (total_size > threshold) return NULL;

    record* records = (record*)malloc(num_offsets * sizeof(record));
    long* offsets = (long*)malloc(num_offsets * sizeof(long));
    int* keys = (int*)malloc(num_keys * sizeof(int));

    // Initialize random seed
