#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    int key;
    float weight;
} Record;

Record* initRecords(int n, int min_value, int max_value) {
    Record* records = (Record*)malloc(n * sizeof(Record));
    if (!records) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < n; i++) {
        records[i].value = rand() % ((max_value + 1) - min_value) + min_value;
        records[i].key = i;
        records[i].weight = (float)(rand() % 201 - 100.0) / 50.0;
    }

    return records;
}

// Custom binary format for record storage
struct RecordHeader {
    int value;
    int key;
    float weight;
    uint16_t checksum; // Algorithm: Adler-32
};

void writeRecordsToFile(Record* records, int n, FILE* file) {
    struct RecordHeader header;

    for (int i = 0; i < n; i++) {
        header.value = records[i].value;
        header.key = records[i].key;
        header.weight = records[i].weight;

        // Adler-32 checksum algorithm
        uint16_t adler = 0;
        for (int j = 0; j < sizeof(struct RecordHeader); j++) {
            adler += ((uint8_t*)&header)[j];
            adler = (adler << 1) | (adler >> 31);
        }
        header.checksum = adler;

        fwrite(&header, sizeof(struct RecordHeader), 1, file);
    }
}

int main() {
    int n = 1000; // Number of records
    int min_value = 0;
    int max_value = 100;

    Record* records = initRecords(n, min_value, max_value);

    FILE* file = fopen("records.bin", "wb");
    if (!file) {
        printf("File opening failed.\n");
        return -1;
    }

    writeRecordsToFile(records, n, file);
    fclose(file);

    free(records);

    return 0;
}
