// Define node structure
typedef struct {
    double temp;
    time_t timestamp;
} Node;

// Define linked list structure
typedef struct {
    Node* head;
    int size;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_linked_list() {
    LinkedList* ll = (LinkedList*)malloc(sizeof(LinkedList));
    ll->head = NULL;
    ll->size = 0;
    pthread_mutex_init(&ll->lock, NULL);
    return ll;
}

void destroy_linked_list(LinkedList* ll) {
    Node* curr = ll->head;
    while (curr != NULL) {
        Node* next = curr->next;
        free(curr);
        curr = next;
    }
    free(ll);
    pthread_mutex_destroy(&ll->lock);
}

void insert_node(LinkedList* ll, double temp, time_t timestamp) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->temp = temp;
    new_node->timestamp = timestamp;
    new_node->next = NULL;

    if (ll->head == NULL || timestamp < ll->head->timestamp) {
        new_node->next = ll->head;
        ll->head = new_node;
    } else {
        Node* curr = ll->head;
        while (curr->next != NULL && curr->next->timestamp >= timestamp)
            curr = curr->next;
        new_node->next = curr->next;
        curr->next = new_node;
    }

    pthread_mutex_lock(&ll->lock);
    ll->size++;
    pthread_mutex_unlock(&ll->lock);
}

void print_linked_list(LinkedList* ll) {
    Node* curr = ll->head;
    while (curr != NULL) {
        printf("Temp: %.2f, Timestamp: %ld\n", curr->temp, curr->timestamp);
        curr = curr->next;
    }
}
