#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define a structure to represent a graph vertex (user profile)
typedef struct GraphVertex {
    int id;
    int followers; // number of followers for this user
    pthread_mutex_t lock; // mutex for thread safety
} GraphVertex;

// Define a function to dynamically allocate and initialize the graph data structure
GraphVertex* create_graph(int num_vertices) {
    // Allocate memory for the graph vertices array
    GraphVertex* graph = (GraphVertex*)malloc(num_vertices * sizeof(GraphVertex));

    // Initialize each vertex with a unique ID, 0 followers, and a mutex
    for (int i = 0; i < num_vertices; i++) {
        graph[i].id = i;
        graph[i].followers = 0;
        pthread_mutex_init(&graph[i].lock, NULL);
    }

    return graph;
}

// Define a function to add an edge between two vertices (follower relationship)
void add_edge(GraphVertex* graph, int src_id, int dest_id) {
    // Lock the source vertex's mutex
    pthread_mutex_lock(&graph[src_id].lock);

    // Increment the destination vertex's follower count
    graph[dest_id].followers++;

    // Unlock the source vertex's mutex
    pthread_mutex_unlock(&graph[src_id].lock);
}

// Define a function to retrieve the number of followers for a given user profile
int get_followers(GraphVertex* graph, int id) {
    // Lock the vertex's mutex
    pthread_mutex_lock(&graph[id].lock);

    // Retrieve and return the follower count
    int followers = graph[id].followers;

    // Unlock the vertex's mutex
    pthread_mutex_unlock(&graph[id].lock);

    return followers;
}

// Define a function to batch process follower relationships (concurrent insertion)
void process_follower_relationships(GraphVertex* graph, int num_edges) {
    // Create a separate thread for each edge to be processed
    pthread_t threads[num_edges];
    for (int i = 0; i < num_edges; i++) {
        int src_id, dest_id;
        // Get the source and destination IDs from the batch data...
        pthread_create(&threads[i], NULL, add_edge_thread, &graph);
        pthread_join(threads[i], NULL);
    }
}

// Define a thread function to process a single follower relationship edge
void* add_edge_thread(void* arg) {
    GraphVertex* graph = (GraphVertex*)arg;
    int src_id, dest_id;
    // Get the source and destination IDs from the batch data...
    pthread_mutex_lock(&graph[src_id].lock);
    graph[dest_id].followers++;
    pthread_mutex_unlock(&graph[src_id].lock);
}

int main() {
    int num_vertices = 100; // number of user profiles
    GraphVertex* graph = create_graph(num_vertices);

    // Add edges to the graph (follower relationships)
    process_follower_relationships(graph, 500); // process 500 follower relationships

    // Retrieve and print the number of followers for each user profile
    for (int i = 0; i < num_vertices; i++) {
        int followers = get_followers(graph, i);
        printf("User %d has %d followers.\n", i, followers);
    }

    return 0;
}
