        records[i]->key = rand() % 20;
        records[i]->value = rand() % 10;
    }
}

void freeArrays(int* offsetValues, int** keys, Record** records, int n) {
    // Free allocated memory
    for (int i = 0; i < n; i++) {
        free((char*)records[i]);
    }
    free(keys);
    free(offsetValues);
}

// Define file operations
void writeRecords(Record* records, int n) {
    FILE* file = fopen("records.txt", "w");
    for (int i = 0; i < n; i++) {
        fprintf(file, "%d %d\n", records[i]->key, records[i]->value);
    }
    fclose(file);
}

void readRecords(Record** records, int* n) {
    FILE* file = fopen("records.txt", "r");
    if (file == NULL) {
        return;
    }

    // Read and store records
    while (fscanf(file, "%d %d\n", &records[*n]->key, &records[*n]->value) == 2) {
        (*n)++;
    }
    fclose(file);
}

int main() {
    int n = 100; // Initial number of records

    // Initialize arrays
    int* offsetValues = (int*)malloc(n * sizeof(int));
    int** keys = (int**)malloc(n * sizeof(int*));
    Record** records = (Record**)malloc(n * sizeof(Record*));
    for (int i = 0; i < n; i++) {
        keys[i] = (int*)malloc(sizeof(int));
        records[i] = (Record*)malloc(sizeof(Record));
    }

    initArrays(offsetValues, keys, records, n);

    // Write records to file
    writeRecords(*records, n);

    // Periodically flush records to disk
    while (1) {
        sleep(10);
        writeRecords(*records, n);
    }
}
