Record** manage_records(int* num_records, pthread_mutex_t* mutex) {
    *num_records = 0;

    // Allocate memory for the array of records
    void* ptr = malloc(sizeof(Record*) * 2);
    if (!ptr) return NULL; // Handle memory allocation failure

    Record** records = (Record**)ptr;
    Record** keys = (Record**)((char*)records + sizeof(Record*) * (*num_records));

    // Initialize the secondary array of pointers
    for (int i = 0; i < *num_records; i++) {
        records[i] = &((Record){});
        keys[i] = &((Record){});
    }

    pthread_mutex_init(mutex, NULL);

    return records;
}

void insert_record(Record** records, int key, long offset) {
    // Acquire the lock to ensure thread safety
    pthread_mutex_lock(records[0]->mutex);

    // Allocate a new record and update the secondary array of pointers
    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) return; // Handle memory allocation failure

    new_record->key = key;
    new_record->offset = offset;

    // Insert the new record into the records array
    *records = realloc(*records, sizeof(Record*) * (*num_records + 1));
    records[*num_records] = &new_record;

    // Update the secondary array of pointers
    keys = realloc(keys, sizeof(Record*) * (*num_records + 1));
    keys[*num_records] = &new_record;

    pthread_mutex_unlock(records[0]->mutex);
}

void delete_record(Record** records, int key) {
    // Acquire the lock to ensure thread safety
    pthread_mutex_lock(records[0]->mutex);

    // Find the record with the given key and remove it from the arrays
    for (int i = 0; i < *num_records; i++) {
        if (records[i]->key == key) {
            free(records[i]);
            records[i] = NULL;

            *keys = realloc(*keys, sizeof(Record*) * (*num_records - 1));
            keys[*num_records - 1] = &((Record){});
            break;
        }
    }

    pthread_mutex_unlock(records[0]->mutex);
}

void update_record(Record** records, int key, long offset) {
    // Acquire the lock to ensure thread safety
    pthread_mutex_lock(records[0]->mutex);

    // Find the record with the given key and update its offset value
    for (int i = 0; i < *num_records; i++) {
        if (records[i]->key == key) {
            records[i]->offset = offset;
            break;
        }
    }

    pthread_mutex_unlock(records[0]->mutex);
}

void deallocate_memory(Record** records, int* num_records) {
    // Acquire the lock to ensure thread safety
    pthread_mutex_lock(records[0]->mutex);

    // Deallocate all allocated memory
    for (int i = 0; i < *num_records; i++) {
        free(records[i]);
    }

    free(records);
    free(keys);

    pthread_mutex_unlock(records[0]->mutex);
}

