#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

// Define a custom record structure
typedef struct {
    int value;
} Record;

// Define a custom memory pool allocator structure
typedef struct {
    void** blocks;  // Array of pointers to memory blocks
    size_t* sizes;  // Array of block sizes
    uint32_t num_blocks;  // Number of allocated blocks
    uint32_t total_size;  // Total memory usage
    pthread_mutex_t lock;  // Mutex for thread safety
} MemoryPool;

// Initialize the memory pool allocator
MemoryPool* initialize_memory_pool(size_t num_records) {
    MemoryPool* mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->num_blocks = 0;
    mp->total_size = 0;
    mp->blocks = (void**)malloc(num_records * sizeof(void*));
    mp->sizes = (size_t*)malloc(num_records * sizeof(size_t));
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

// Allocate a new block in the memory pool
void* allocate_memory_block(MemoryPool* mp) {
    void* block = NULL;

    // Check if there are available blocks
    for (uint32_t i = 0; i < mp->num_blocks; i++) {
        if (!mp->blocks[i]) {
            block = mp->blocks[i];
            break;
        }
    }

    // If not, allocate a new block and update the pool
    if (!block) {
        size_t block_size = sizeof(Record);
        block = malloc(block_size);

        // Update the pool with the new block
        mp->blocks[mp->num_blocks] = block;
        mp->sizes[mp->num_blocks] = block_size;
        mp->num_blocks++;
        mp->total_size += block_size;
    }

    return block;
}

// Deallocate a block in the memory pool
void deallocate_memory_block(MemoryPool* mp, void* block) {
    pthread_mutex_lock(&mp->lock);

    // Find the corresponding block in the pool
    for (uint32_t i = 0; i < mp->num_blocks; i++) {
        if (mp->blocks[i] == block) {
            mp->blocks[i] = NULL;
            break;
        }
    }

    pthread_mutex_unlock(&mp->lock);
}

// Compact the memory allocation to improve cache locality
void compact_memory(MemoryPool* mp) {
    // Find the smallest available block
    size_t min_size = SIZE_MAX;
    void* min_block = NULL;

    for (uint32_t i = 0; i < mp->num_blocks; i++) {
        if (!mp->blocks[i]) continue;

        size_t block_size = mp->sizes[i];
        if (block_size < min_size) {
            min_size = block_size;
            min_block = mp->blocks[i];
        }
    }

    // If a suitable block is found, move the records to it
    if (min_block && min_size > 0) {
        Record* record = (Record*)min_block;

        // Move the records and update the pool
        for (uint32_t i = 0; i < mp->num_blocks; i++) {
            if (!mp->blocks[i]) continue;

            size_t block_size = mp->sizes[i];
            if (block_size > min_size) {
                memcpy(record, (Record*)mp->blocks[i], min_size);
                record += min_size / sizeof(Record);
                memmove((void*)min_block + min_size, mp->blocks[i], block_size - min_size);
            }
        }

        // Update the pool with the new blocks
        for (uint32_t i = 0; i < mp->num_blocks; i++) {
            if (!mp->blocks[i]) continue;

            size_t block_size = mp->sizes[i];
            if (block_size > min_size) {
                deallocate_memory_block(mp, mp->blocks[i]);
            }
        }
    }
}

// Print the memory pool statistics
void print_memory_pool_stats(MemoryPool* mp) {
    printf("Memory Pool Statistics:\n");
    printf("Number of Blocks: %u\n", mp->num_blocks);
    printf("Total Memory Usage: %zu bytes\n", mp->total_size);
    printf("\n");
}

int main() {
    // Initialize the memory pool
    size_t num_records = 100;
    MemoryPool* mp = initialize_memory_pool(num_records);

    // Allocate and deallocate blocks in the memory pool
    for (uint32_t i = 0; i < 10; i++) {
        void* block = allocate_memory_block(mp);
        Record* record = (Record*)block;

        // Initialize the record with a random value
        record->value = rand();

        printf("Allocated Block %u: Size = %zu bytes\n", i, sizeof(Record));

        sleep(1);  // Simulate some work

        deallocate_memory_block(mp, block);
        printf("Deallocated Block %u\n", i);
    }

    // Compact the memory allocation
    compact_memory(mp);

    // Print the memory pool statistics
    print_memory_pool_stats(mp);

    return 0;
}

