    // Allocate memory for array of 'long' offset values
    long* offsets = (long*)malloc(100 * sizeof(long));

    // Check if allocation failed
    if (!offsets) {
        printf("Error: Unable to allocate memory for offset values.\n");
        return NULL;
    }

    // Initialize offset values with random numbers within a given range
    srand(time(NULL));
    for (int i = 0; i < 100; i++) {
        offsets[i] = (long)rand() % 10000000;
    }

    // Allocate memory for array of 'int' keys
    int* keys = (int*)malloc(100 * sizeof(int));

    // Check if allocation failed
    if (!keys) {
        printf("Error: Unable to allocate memory for keys.\n");
        free(offsets);
        return NULL;
    }

    // Initialize key values with random numbers within a given range
    for (int i = 0; i < 100; i++) {
        keys[i] = (int)rand() % 100;
    }

    // Allocate memory for array of 'record' structures
    Record* records = (Record*)malloc(100 * sizeof(Record));

    // Check if allocation failed
    if (!records) {
        printf("Error: Unable to allocate memory for records.\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Set value of each record's int field to a random value within a given range
    for (int i = 0; i < 100; i++) {
        records[i].key = (int)rand() % 100;
    }

    // Free allocated memory upon success
    free(offsets);
    free(keys);

    return (void*)records;
}

