#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_ELEMENTS 1000
typedef struct {
    double temp;
    time_t timestamp;
} Node;

Node* ll_head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int elements_count = 0;

void* insert_node(void* val) {
    Node* node = (Node*)val;
    pthread_mutex_lock(&lock);
    Node* new_node = malloc(sizeof(Node));
    *new_node = *node;
    if(ll_head == NULL || ll_head->temp < node->temp){
        new_node->next = ll_head;
        ll_head = new_node;
    } else {
        Node* current = ll_head;
        while(current->next && current->next->temp >= node->temp) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
    elements_count++;
    pthread_mutex_unlock(&lock);
    return NULL;
}

void* remove_node(void* val) {
    Node* node = (Node*)val;
    pthread_mutex_lock(&lock);
    Node* prev = NULL;
    Node* current = ll_head;
    while(current && current->temp != node->temp){
        prev = current;
        current = current->next;
    }
    if(current){
        if(prev) {
            prev->next = current->next;
        } else {
            ll_head = current->next;
        }
        free(current);
        elements_count--;
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}

int get_temperature_sum(void* start, void* end) {
    int sum = 0;
    Node* node = (Node*)start;
    while(node && node->temp <= ((Node*)end)->temp){
        sum += node->temp;
        node = node->next;
    }
    return sum;
}

void print_temperature_list() {
    pthread_mutex_lock(&lock);
    Node* node = ll_head;
    int i = 0;
    while(node) {
        printf("Temperature: %f, Timestamp: %ld\n", node->temp, node->timestamp);
        node = node->next;
        i++;
    }
    pthread_mutex_unlock(&lock);
}

int main() {
    // Create and insert nodes
    for(int i = 0; i < MAX_ELEMENTS; i++) {
        Node node;
        node.temp = (double)i / 10.0;
        node.timestamp = time(NULL);
        pthread_create(NULL, NULL, &insert_node, &node);
    }

    print_temperature_sum();

    // Remove nodes
    for(int i = MAX_ELEMENTS-1; i >= 0; i--) {
        Node node;
        node.temp = (double)i / 10.0;
        node.timestamp = time(NULL);
        pthread_create(NULL, NULL, &remove_node, &node);
    }

    print_temperature_list();

    return 0;
}
