use tokio::http;
use async_timeout;

struct HttpClient {
    timeout: u64,
}

impl HttpClient {
    fn new(timeout: u64) -> Self {
        HttpClient { timeout }
    }

    async fn request(&self, url: &str) -> Result<String, http::Error> {
        let client = http::Client::new();
        let resp = client.get(url).timeout(self.timeout).send().await?;
        let body = resp.body().await?;
        Ok(String::from_utf8(body.to_vec()).unwrap())
    }
}

fn main() {
    let client = HttpClient::new(1000);
    let url = "https://example.com";
    async_timeout::timeout(client.request(url)).await.unwrap();
}
