#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    char* key;
    void* value;
    time_t timestamp;
} cache_entry;

typedef enum {
    TIME_AGGRESSIVE,
    ACCESS_AGGRESSIVE
} eviction_policy;

cache_entry** cache = NULL;
int cache_size = 0;
eviction_policy policy = TIME_AGGRESSIVE;

void init_cache(int capacity) {
    cache_size = capacity;
    cache = (cache_entry**)malloc(cache_size * sizeof(cache_entry*));
    for (int i = 0; i < cache_size; i++) {
        cache[i] = NULL;
    }
}

int allocate_cache_entry(void** data, char* key, int size) {
    cache_entry* entry = (cache_entry*)malloc(sizeof(cache_entry));
    entry->key = malloc(strlen(key) + 1);
    strcpy(entry->key, key);
    entry->value = data;
    time_t timestamp = time(NULL);
    entry->timestamp = timestamp;

    for (int i = 0; i < cache_size; i++) {
        if (!cache[i]) {
            cache[i] = entry;
            return 1;
        }
    }

    // handle cache full
    return -1;
}

void evict_cache_entry() {
    int max_timestamp = 0;
    int oldest_entry_index = -1;

    for (int i = 0; i < cache_size; i++) {
        if (!cache[i]) continue;

        time_t timestamp = cache[i]->timestamp;
        if (policy == TIME_AGGRESSIVE && timestamp > max_timestamp) {
            max_timestamp = timestamp;
            oldest_entry_index = i;
        } else if (policy == ACCESS_AGGRESSIVE && timestamp < max_timestamp) {
            max_timestamp = timestamp;
            oldest_entry_index = i;
        }
    }

    if (oldest_entry_index != -1) {
        cache_entry* entry = cache[oldest_entry_index];
        free(entry->key);
        free(entry);
        cache[oldest_entry_index] = NULL;
    }
}

void* get_cache_entry(char* key) {
    for (int i = 0; i < cache_size; i++) {
        if (!cache[i]) continue;

        cache_entry* entry = cache[i];
        if (strcmp(entry->key, key) == 0) {
            return entry->value;
        }
    }

    // handle miss
    return NULL;
}

void put_cache_entry(char* key, void* value) {
    for (int i = 0; i < cache_size; i++) {
        if (!cache[i]) continue;

        cache_entry* entry = cache[i];
        if (strcmp(entry->key, key) == 0) {
            entry->value = value;
            return;
        }
    }

    // handle miss
    allocate_cache_entry(&value, key, sizeof(value));
}

void dump_cache() {
    for (int i = 0; i < cache_size; i++) {
        if (!cache[i]) continue;

        cache_entry* entry = cache[i];
        printf("%s: %p (timestamp: %ld)\n", entry->key, entry->value, entry->timestamp);
    }
}

void free_cache() {
    for (int i = 0; i < cache_size; i++) {
        if (!cache[i]) continue;

        cache_entry* entry = cache[i];
        free(entry->key);
        free(entry);
    }

    free(cache);
}

int main() {
    init_cache(100);

    // simulate data
    int data_sizes[] = {10, 20, 30};
    char* keys[] = {"k1", "k2", "k3"};

    for (int i = 0; i < sizeof(data_sizes) / sizeof(data_sizes[0]); i++) {
        void* data = malloc(data_sizes[i]);
        put_cache_entry(keys[i], data);
        free(data);
    }

    // simulate eviction
    evict_cache_entry();

    dump_cache();

    free_cache();

    return 0;
}
