        fwrite(&data[i]->i, sizeof(int), 1, f);
        size_t str_len = strlen(data[i]->s);
        fwrite(&str_len, sizeof(size_t), 1, f); // Write string length
        fwrite(data[i]->s, sizeof(char), str_len + 1, f); // Write string
    }

    fclose(f);
}

int main() {
    size_t len = 10;
    int seed = 42;

    initArrays(len, seed);

    data_t** data = (data_t**)malloc(len * sizeof(data_t*));
    for (size_t i = 0; i < len; i++) {
        data[i] = malloc(sizeof(data_t));
    }

    serialize(data, len, "data.bin");

    // Clean up
    for (size_t i = 0; i < len; i++) {
        free(data[i]->s);
        free(data[i]);
    }
    free(data);

    return 0;
}
