typedef struct {
    double d;
    int i;
    char* c;
    time_t t;
    resource_id rid;
} data;

void init_data(data** structs, size_t count) {
    srand(time(NULL)); // Initialize random seed for reproducibility
    for (size_t i = 0; i < count; i++) {
        (*structs)[i].d = (double)(rand() / (RAND_MAX / 1.0));
        (*structs)[i].i = rand();
        (*structs)[i].c = malloc(10);
        if (!(*structs)[i].c) { // Handle memory allocation error
            printf("Memory allocation failed for struct %lu\n", i);
            exit(EXIT_FAILURE);
        }
        strcpy((*structs)[i].c, "random_string");
        (*structs)[i].t = time(NULL);
        (*structs)[i].rid = (resource_id)(rand() / (RAND_MAX / 1.0));
    }
}

int main() {
    int file_fd;
    void* mmapped_file;

    // Initialize the data structures
    data* structs[MAX_STRUCTS];
    init_data(&structs, MAX_STRUCTS);

    // Serialize the struct data into a binary file for storage and retrieval
    file_fd = open("data.bin", O_RDWR | O_CREAT, S_IRUSR | S_IWUSR);
    if (file_fd == -1) {
        printf("Failed to open file\n");
        exit(EXIT_FAILURE);
    }

    mmapped_file = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, file_fd, 0);
    if (mmapped_file == MAP_FAILED) {
        printf("Memory mapping failed\n");
        close(file_fd);
        exit(EXIT_FAILURE);
    }

    // Write the serialized data to the memory-mapped file
    for (size_t i = 0; i < MAX_STRUCTS; i++) {
        fwrite(&structs[i], sizeof(data), 1, mmapped_file);
    }
    munmap(mmapped_file, BUFFER_SIZE); // Unmap the memory
    close(file_fd);

    return 0;
}
