void initArrays(int* keys, long* offsets, Record* records, int keySize, int offsetSize, int recordCount) {
    // Allocate memory for arrays and records
    keys = (int*)malloc(keySize * sizeof(int));
    offsets = (long*)malloc(offsetSize * sizeof(long));
    records = (Record*)malloc(recordCount * sizeof(Record));

    // Initialize arrays and records
    for (int i = 0; i < keySize; i++) {
        keys[i] = i;
    }
    for (int j = 0; j < offsetSize; j++) {
        offsets[j] = j;
    }
    for (int k = 0; k < recordCount; k++) {
        records[k].value = rand() % 100;
    }

    // Deallocate memory
    free(keys);
    free(offsets);
    free(records);
}

// Function to set the value of each record's int field to a random value within a specified range
void setRecordValues(Record* records, int min, int max) {
    for (int i = 0; i < recordCount; i++) {
        records[i].value = rand() % ((max - min + 1)) + min;
    }
}

// Function to handle potential integer overflow during random value generation
void handleOverflow(int* value) {
    if (*value > max || *value < min) {
        // Handle potential integer overflow
        *value = rand() % ((max - min + 1)) + min;
    }
}

