#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a custom record structure
typedef struct {
    int id;
    double value;
    char* str;
} Record;

// Define the dynamic array type
typedef struct {
    void** data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

// Initialize a new dynamic array
DynamicArray* dyn_array_init(size_t initial_capacity) {
    DynamicArray* arr = (DynamicArray*)malloc(sizeof(DynamicArray));
    arr->data = (void**)calloc(initial_capacity, sizeof(void*));
    arr->capacity = initial_capacity;
    arr->size = 0;
    pthread_mutex_init(&arr->mutex, NULL);
    return arr;
}

// Destroy a dynamic array
void dyn_array_destroy(DynamicArray* arr) {
    for (size_t i = 0; i < arr->size; i++) {
        free(arr->data[i]);
    }
    free(arr->data);
    pthread_mutex_destroy(&arr->mutex);
    free(arr);
}

// Resize a dynamic array
void dyn_array_resize(DynamicArray* arr, size_t new_capacity) {
    void** newData = (void**)calloc(new_capacity, sizeof(void*));
    if (newData) {
        memcpy(newData, arr->data, arr->size * sizeof(void*));
        free(arr->data);
        arr->data = newData;
        arr->capacity = new_capacity;
    }
}

// Add an element to a dynamic array
void dyn_array_add(DynamicArray* arr, void* elem) {
    pthread_mutex_lock(&arr->mutex);
    if (arr->size >= arr->capacity) {
        dyn_array_resize(arr, arr->capacity * 2);
    }
    arr->data[arr->size] = elem;
    arr->size++;
    pthread_mutex_unlock(&arr->mutex);
}

// Get an element from a dynamic array
void* dyn_array_get(DynamicArray* arr, size_t index) {
    pthread_mutex_lock(&arr->mutex);
    if (index >= arr->size) {
        return NULL;
    }
    void* elem = arr->data[index];
    pthread_mutex_unlock(&arr->mutex);
    return elem;
}

// Stress test framework
void stress_test(DynamicArray* arr, size_t num_elements, size_t growth_factor) {
    for (size_t i = 0; i < num_elements; i++) {
        Record* record = (Record*)malloc(sizeof(Record));
        record->id = i;
        record->value = i * 1.5;
        char buffer[32];
        sprintf(buffer, "Element %zu", i);
        record->str = strdup(buffer);
        dyn_array_add(arr, record);
    }
}

int main() {
    DynamicArray* arr = dyn_array_init(16);

    // Perform stress testing
    stress_test(arr, 10000, 2);

    // Print array contents
    for (size_t i = 0; i < arr->size; i++) {
        Record* record = (Record*)dyn_array_get(arr, i);
        printf("ID: %d, Value: %f, Str: %s\n", record->id, record->value, record->str);
    }

    // Destroy the dynamic array
    dyn_array_destroy(arr);

    return 0;
}
