}

// Structure to store record data
typedef struct {
    int intField;
    double doubleField;
    char *stringField;
} Record;

// Function to dynamically allocate memory for and initialize arrays of various types
void* allocateArrays(size_t longArraySize, size_t intArraySize, size_t doubleArraySize) {
    // Allocate memory for 'long' offset values
    long* longArray = (long*)malloc(longArraySize * sizeof(long));

    // Initialize array with random values
    for(int i = 0; i < longArraySize; i++) {
        longArray[i] = generateRandomValue(1, 100);
