```rust
use tokio::prelude::*;

struct Record {
    int: i32,
    long: i64,
    double: f64,
}

async fn main() {
    let args: Vec<String> = std::env::args().collect();
    let func_name = &args[1];

    match func_name.as_str() {
        "init_records" => init_records(),
        _ => println!("Invalid function name!"),
    }
}

async fn init_records() {
    // Initialize arrays
    let mut int_keys: Vec<i32> = Vec::new();
    let mut long_offsets: Vec<i64> = Vec::new();
    let mut double_values: Vec<f64> = Vec::new();

    for _ in 0..1000 {
        int_keys.push(std::thread_rng().gen_range(1, 101));
        long_offsets.push(std::thread_rng().gen_range(-10000, 10001));
        double_values.push(std::f64::consts::PI * std::thread_rng().gen_range(1.0, 2.0));
    }

    let mut records: Vec<Record> = Vec::new();

    for (int_key, long_offset, double_value) in int_keys.iter().zip(long_offsets.iter()).zip(double_values.iter()) {
        let record = Record { int: *int_key, long: *long_offset, double: *double_value };
        records.push(record);
    }

    // Log memory allocation failures and total number of records
    println!("Total number of records: {}", records.len());
}
