#include <unistd.h>

// Define constants for memory management and logging
#define MEMORY_THRESHOLD 1024 * 1024 * 2 // 2MB
#define IOWRITE_RETRIES 5

typedef struct {
    int key;
    long offset;
} record_t;

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL && errno != ENOMEM) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

int initialize_data_structures(int num_records, int* keys, long* offsets, record_t** records) {
    // Initialize arrays and dynamic memory for records
    *records = (record_t**) allocate_memory(num_records * sizeof(record_t*));
    if (*records == NULL)
        return -1;

    for (int i = 0; i < num_records; i++) {
        (*records)[i] = (record_t*) allocate_memory(sizeof(record_t));
        if ((*records)[i] == NULL)
            return -1;
        // Initialize record values
        (*(*records)[i]).key = rand() % 100; // random key value
        (*(*records)[i]).offset = i; // offset value
    }
    return 0;
}

void log_memory_usage(size_t total, size_t failed) {
    printf("Memory usage: %zu bytes (successful allocations: %zu, failed allocations: %zu)\n", total, total - failed);
}

int write_to_file(record_t** records, int num_records, const char* file_path) {
    // Open file for writing
    FILE* fp = fopen(file_path, "wb");
    if (fp == NULL) {
        perror("Failed to open file for writing");
        return -1;
    }

    // Write record data
    for (int i = 0; i < num_records; i++) {
        fwrite(&((*records)[i]), sizeof(record_t), 1, fp);
    }

    fclose(fp); // close the file
}

void compact_file(const char* file_path) {
    // Read existing records from file
    FILE* fp = fopen(file_path, "rb");
    if (fp == NULL)
        return; // no file to compact

    // Iterate through record data and remove unused entries
    fseek(fp, 0L, SEEK_END);
    size_t file_size = ftell(fp);
    rewind(fp);

    // Perform compaction logic here...

    fclose(fp); // close the file
}

int main() {
    int num_records = 100;
    int* keys = (int*) allocate_memory(num_records * sizeof(int));
    long* offsets = (long*) allocate_memory(num_records * sizeof(long));
    record_t** records = NULL;

    if (initialize_data_structures(num_records, keys, offsets, &records) < 0)
        return -1;

    // Write records to file
    write_to_file(records, num_records, "records.bin");

    // Compact the stored records periodically
    compact_file("records.bin");

    free(keys);
    free(offsets);
    for (int i = 0; i < num_records; i++)
        free(records[i]);
    free(records);

    return 0;
}
