#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Node {
    double value;
    struct Node* next;
} Node;

Node* head = NULL;
Node* tail = NULL;
unsigned int size = 0;
unsigned int max_size = 100000;
Node** lru = NULL;

void insert(double value) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return; // Handle memory allocation failure
    node->value = value;
    node->next = NULL;

    if (!head) {
        head = node;
        tail = node;
    } else {
        tail->next = node;
        tail = node;
    }
    size++;

    // LRU eviction policy
    lru[size - 1] = &node->value;
}

void traverse() {
    Node* current = head;
    while (current) {
        printf("%f\n", current->value);
        current = current->next;
    }
}

void free_list() {
    Node* temp = head;
    while (temp) {
        Node* next = temp->next;
        free(temp);
        temp = next;
    }
    head = NULL;
    tail = NULL;
    size = 0;
}

int main() {
    // Initialize memory-mapped file for persistent storage
    int fd = open("list.mm", O_RDWR | O_CREAT, S_IRUSR | S_IWUSR);
    if (fd < 0) return -1; // Handle file opening failure

    // Initialize LRU array and allocate space for nodes
    lru = (Node**)malloc(sizeof(Node*) * max_size);

    // Example usage: insert values and traverse the list
    for (int i = 0; i < 10; i++) {
        insert(i);
    }
    traverse();

    // Close file descriptor and free resources
    close(fd);
    free_list();

    return 0;
}
