record_t* init_records(int num_records) {
    record_t *records = NULL;
    long *offsets = NULL;
    int *keys = NULL;
    int i, rc, max_records = 10000000; // Maximum number of records
    size_t record_size = sizeof(record_t);

    if (num_records > max_records) {
        printf("Number of records exceeds maximum limit.\n");
        return NULL;
    }

    // Allocate memory for offsets and keys
    if ((offsets = malloc(num_records * sizeof(long))) == NULL ||
        (keys = malloc(num_records * sizeof(int))) == NULL) {
        fprintf(stderr, "Memory allocation failed for offsets or keys.\n");
        rc = 1;
        goto cleanup;
    }

    // Initialize offset values and keys
    for (i = 0; i < num_records; i++) {
        offsets[i] = i * 1000;
        keys[i] = rand() % 100;
    }

    // Allocate memory for records
    if ((records = malloc(num_records * record_size)) == NULL) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        rc = 1;
        goto cleanup;
    }

    // Initialize record values
    for (i = 0; i < num_records; i++) {
        records[i].key = keys[i];
    }

cleanup:
    if (rc) {
        // Free allocated memory upon failure
        free(offsets);
        free(keys);
        free(records);
    }
    return records;
}
