    }

    int* keys = (int*)malloc(*keysCount * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL;
    }

    record_t** records = (record_t**)malloc((*offsetsCount + *keysCount) * sizeof(record_t*));

    // Initialize offsets array
    for (int i = 0; i < *offsetsCount; i++) {
        offsets[i] = (long)rand();
    }

    // Initialize keys array
    for (int i = 0; i < *keysCount; i++) {
        keys[i] = rand() % 100;
    }

    // Initialize records array
    for (int i = 0; i < *offsetsCount + *keysCount; i++) {
        record_t* record = (record_t*)malloc(sizeof(record_t));
        if (!record) {
            free(offsets);
            free(keys);
            return NULL;
        }
        record->value = rand() % 100;
        // Assign random offset and key
        record->offset = offsets[i % *offsetsCount];
        record->key = keys[i % *keysCount];
        records[i] = record;
    }

    return records;
}

void freeArrays(record_t** records, int* offsetsCount, int* keysCount) {
    for (int i = 0; i < *offsetsCount + *keysCount; i++) {
        free(records[i]);
    }
    free(records);
    free((long*)malloc(*offsetsCount * sizeof(long)));
    free((int*)malloc(*keysCount * sizeof(int)));
}
