// Define the HTTP client
pub struct HttpClient {
    pub timeout: u64,
    pub retries: u32,
}

impl HttpClient {
    // Initialize the HTTP client with default settings
    pub fn new() -> Self {
        HttpClient {
            timeout: 5000,
            retries: 3,
        }
    }

    // Send an asynchronous request to a given URL
    pub async fn send_request(&self, url: &str) -> Result<String, hyper::error::Error> {
        let mut client = Client::new();
        let resp = client.get(url).timeout(self.timeout).send().await?;
        let body = hyper::body::to_bytes(resp.into_body()).await?;
        Ok(String::from_utf8_lossy(&body).to_string())
    }
