#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int value;
    long offset;
} record;

record* initializeModule(int* keys, long* offsets, int recordSize) {
    // Allocate memory for 'long' integers (offsets)
    long* offsetsArray = (long*)malloc(10000 * sizeof(long));
    if (!offsetsArray) return NULL;

    // Allocate memory for 'int' keys
    int* keysArray = (int*)malloc(5000 * sizeof(int));
    if (!keysArray) {
        free(offsetsArray);
        return NULL;
    }

    // Initialize array of 'record' structures
    record* recordsArray = (record*)malloc(2000 * sizeof(record));
    if (!recordsArray) {
        free(offsetsArray);
        free(keysArray);
        return NULL;

    for (int i = 0; i < recordSize; i++) {
        // Populate each record's integer field with a random value
        recordsArray[i].value = rand() % 2000001 - 1000000;
        // Initialize offset randomly
        recordsArray[i].offset = rand();
    }

    // Ensure no two records share the same key (if collision, increment until unique)
    for (int i = 0; i < recordSize; i++) {
        int collisionFound = 0;
        for (int j = i + 1; j < recordSize; j++) {
            if (keysArray[i] == keysArray[j]) {
                collisionFound = 1;
                break;
            }
        }

        if (collisionFound) {
            keysArray[i]++;
            while (collisionFound) {
                for (int k = i + 1; k < recordSize; k++) {
                    if (keysArray[k] == keysArray[i]) {
                        collisionFound = 1;
                        break;
                    }
                }

                if (collisionFound) {
                    keysArray[i]++;
                } else {
