void sortNodes(Node** nodes, int size) {
    // Use a sorting algorithm of your choice (e.g., quicksort or mergesort)
    for (int i = 0; i < size - 1; i++) {
        for (int j = i + 1; j < size; j++) {
            if (nodes[i]->priority > nodes[j]->priority) {
                Node* temp = nodes[i];
                nodes[i] = nodes[j];
                nodes[j] = temp;
            }
        }
