// Define the structure for entry
typedef struct {
    char* str;
    int timestamp;
    double value;
} entry;

// Function to manage an array of custom entries
entry** manageEntries(int numEntries, int maxLenStr, double minVal, double maxVal) {
    // Dynamically allocate memory for the array
    entry** entries = (entry**)malloc(numEntries * sizeof(entry*));
    if (!entries) return NULL;  // Handle memory allocation failure

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    for (int i = 0; i < numEntries; i++) {
        // Initialize each entry with a randomly generated ASCII string, current system time, and random float
        entry* e = (entry*)malloc(sizeof(entry));
        if (!e) return NULL;  // Handle memory allocation failure

        pthread_mutex_lock(&mutex);
        size_t len = rand() % maxLenStr + 1;
        char* str = (char*)malloc(len * sizeof(char));
        if (!str) return NULL;  // Handle memory allocation failure
        for (size_t j = 0; j < len; j++) {
            str[j] = 'a' + rand() % 26;
        }
        str[len] = '\0';
        e->str = str;

        time_t now = time(NULL);
        e->timestamp = now;

        double val = minVal + (maxVal - minVal) * (double)rand() / RAND_MAX;
        e->value = val;
        pthread_mutex_unlock(&mutex);

        entries[i] = e;
    }

    return entries;
}

// Function to persist the entries in a binary file format
void saveEntries(entry** entries, int numEntries) {
    FILE* file = fopen("entries.bin", "wb");
    if (!file) return;  // Handle file I/O failure

    for (int i = 0; i < numEntries; i++) {
        entry* e = entries[i];
        fwrite(&e->timestamp, sizeof(int), 1, file);
        fwrite(e->str, strlen(e->str), 1, file);
        fwrite(&e->value, sizeof(double), 1, file);
        free(e->str);  // Free the allocated memory
        free(e);
    }

    fclose(file);
}

// Function to retrieve and validate the entries from a binary file format
entry** loadEntries() {
    FILE* file = fopen("entries.bin", "rb");
    if (!file) return NULL;  // Handle file I/O failure

    int numEntries;
    fread(&numEntries, sizeof(int), 1, file);

    entry** entries = (entry**)malloc(numEntries * sizeof(entry*));
    if (!entries) return NULL;  // Handle memory allocation failure

    for (int i = 0; i < numEntries; i++) {
        int timestamp;
        char* str;
        double value;

        fread(&timestamp, sizeof(int), 1, file);
        str = (char*)malloc(sizeof(char));  // Dynamically allocate memory for the string
        fread(str, sizeof(char), 1, file);  // Read the string
        size_t len = strlen(str);
        for (size_t j = 0; j < len; j++) {
            if (str[j] != 'a' && str[j] != 'b') {  // Validate the string contents
                free(entries[i]);
                return NULL;
            }
        }
        value = *((double*)malloc(sizeof(double)));  // Dynamically allocate memory for the value
        fread(value, sizeof(double), 1, file);  // Read the value

        entry* e = (entry*)malloc(sizeof(entry));
        if (!e) return NULL;  // Handle memory allocation failure
        e->str = str;
        e->timestamp = timestamp;
        e->value = *value;

        entries[i] = e;
    }

    fclose(file);
    return entries;
}

int main() {
    int numEntries = 10;
    int maxLenStr = 32;
    double minVal = 0.0, maxVal = 100.0;

    entry** entries = manageEntries(numEntries, maxLenStr, minVal, maxVal);
    if (!entries) return -1;  // Handle error

    saveEntries(entries, numEntries);

    entry** loadedEntries = loadEntries();
    if (!loadedEntries) return -1;  // Handle error

    for (int i = 0; i < numEntries; i++) {
        printf("%s: %d, %.2f\n", loadedEntries[i]->str, loadedEntries[i]->timestamp, loadedEntries[i]->value);
    }

    for (int i = 0; i < numEntries; i++) {
        free(loadedEntries[i]->str);  // Free the allocated memory
        free(loadedEntries[i]);
    }
    free(loadedEntries);

    return 0;
}
