#include <string.h>
#include <pthread.h>

typedef struct {
    char* str;
    int priority;
    unsigned long metadata;
} Node;

NodeManager(int max_nodes, int memory_limit) {
    this->max_nodes = max_nodes;
    this->memory_limit = memory_limit;
    this->nodes = (Node*)malloc(max_nodes * sizeof(Node));
    this->num_nodes = 0;
    pthread_mutex_init(&this->mutex, NULL);
}

int add_node(char* str, int priority) {
    if (this->num_nodes >= this->max_nodes || 
        (str != NULL && strlen(str) > memory_limit)) 
        return -1;

    Node new_node;
    new_node.str = str;
    new_node.priority = priority;
    // Initialize metadata
    new_node.metadata = 0;

    if (pthread_mutex_lock(&this->mutex) != 0)
        return -2; 

    this->nodes[this->num_nodes++] = new_node;
    pthread_mutex_unlock(&this->mutex);
    return 0;
}

int remove_node(int index) {
    if (index < 0 || index >= this->num_nodes)
        return -1;

    if (pthread_mutex_lock(&this->mutex) != 0)
        return -2; 

    if (this->nodes[index].str == NULL) {
        free(this->nodes[index].str);
    }

    memmove(&this->nodes[index], &this->nodes[index + 1], 
            (this->num_nodes - index - 1) * sizeof(Node));
    this->num_nodes--;
    pthread_mutex_unlock(&this->mutex);
    return 0;
}

int sort_nodes() {
    qsort(this->nodes, this->num_nodes, sizeof(Node), node_compare);
    return 0;
}

void persist_nodes() {
    // Write nodes to disk
    FILE* file = fopen("nodes.txt", "wb");
    fwrite(&this->nodes[0], sizeof(Node), this->num_nodes, file);
    fclose(file);
}

int main() {
    NodeManager manager(100, 1024);

    for (int i = 0; i < 50; i++) {
        char* str = malloc(10);
        sprintf(str, "Node %d", i);
        if (manager.add_node(str, i) != 0)
            printf("Error adding node\n");
        free(str);
    }

    manager.sort_nodes();
    manager.persist_nodes();

    return 0;
}

int compare(const void* a, const void* b) {
    Node* na = (Node*)a;
    Node* nb = (Node*)b;

    if (na->priority > nb->priority)
        return -1;
    else if (na->priority < nb->priority)
        return 1;
    else
        return 0;
}

void log_performance() {
