record* manage_memory_allocation(int n) {
    // Allocate memory for array of offset values
    long* offsets = (long*)malloc(n * sizeof(long));
    if (!offsets) return NULL;

    // Initialize offset values
    for (int i = 0; i < n; i++) {
        offsets[i] = i;
    }

    // Allocate memory for array of keys
    int* keys = (int*)malloc(n * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL;
    }

    // Populate and verify prime numbers in the keys array
    srand(time(NULL));
    int key_index = 0;
    for (int i = 2; i < 100; i++) {
        if (is_prime(i)) {
            keys[key_index++] = i;
            if (key_index == n) break;
        }
    }

    // Allocate memory for array of record structures
    record* records = (record*)malloc(n * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize and populate the records array
    for (int i = 0; i < n; i++) {
        records[i].offset = offsets[i];
        records[i].key = keys[i % key_index]; // Ensure each record has a unique key
        records[i].value = ((double)rand() / RAND_MAX) * 1000 / (records[i].key + 1); // Mitigate integer overflow
    }

    // Free dynamically allocated memory when done
    free(offsets);
    free(keys);

    return records;
}

int is_prime(int num) {
    if (num <= 1) return 0;
    for (int i = 2; i * i <= num; i++) {
        if (num % i == 0) return 0;
    }
    return 1;
