        new_packet->src_ip.s_addr = inet_addr("192.168.0.");
        new_packet->dst_ip.s_addr = inet_addr("10.");

        // Ensure valid IP addresses and common protocols
        if ((rand() % 2) && new_packet->protocol == ICMP) {
            new_packet->protocol = (protocol_type)(rand() % 2 + 1);
