        // Ensure payload length is within reasonable range
        new_packet->payload_length = rand() % 1500 + 64;

        if (!packets) {
            packets = new_packet;
        } else {
            packet_header* current_packets = packets;

            while (current_packets) {
                packet_header* next_packet = current_packets->next;

                current_packets->next = new_packet;
                new_packet = current_packets;
                current_packets = next_packet;
            }

            new_packet->next = NULL;
        }
    }

    return packets;
}

void deallocate_packet_headers(packet_header* packets) {
    packet_header* current_packet = packets;

    while (current_packet) {
        packet_header* next_packet = current_packet->next;

        free(current_packet);
        current_packet = next_packet;
    }
