        records[i].key = key;
        double value = ((double)rand() / RAND_MAX * 1000 + 1) / (double)key;  // Calculate the value by dividing a random integer between 1 and 1000 by the key
        records[i].value = value;
    }

    return records;
}

// Generate prime numbers less than 100
int getPrimeNumber() {
    int num = 2;

    while (num < 100) {
        if (isPrime(num)) {
            return num;
        }
        num++;
    }

    return -1;  // No prime number found
}

// Check if a number is prime
int isPrime(int n) {
    if (n <= 1)
        return 0;

    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0)
            return 0;
    }

    return 1;
}

// Free the allocated memory
void freeRecords(record* records, int n) {
    for (int i = 0; i < n; i++) {
        free(&records[i]);
    }
    free(records);
}
