typedef struct {
    int key;
    long offset;
} Record;

// Function to create hash table using separate chaining
void* create_hash_table(int size) {
    void *hash_table = calloc(size, sizeof(void *));
    if (!hash_table) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    return hash_table;
}

void insert_record(Record* record, Record** records, int* num_records, void** hash_table) {
    // Insert the record into the array
    *num_records = (*num_records + 1);
    records[*num_records - 1] = record;

    // Update the hash table
    int key = record->key;
    size_t index = key % sizeof(*hash_table);
    ((Record**)hash_table)[index] = record;
}

void delete_record(int key, Record** records, int* num_records, void** hash_table) {
    // Find the record to be deleted
    for (int i = 0; i < *num_records; i++) {
        if (records[i]->key == key) {
            // Remove the record from the array
            memmove(&records[i], &records[i + 1], (*num_records - i) * sizeof(Record));
            *num_records -= 1;

            // Update the hash table
            size_t index = key % sizeof(*hash_table);
            ((Record**)hash_table)[index] = records[*num_records];
            break;
        }
    }
}

void print_records(Record** records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        printf("Key: %d Offset: %ld\n", records[i]->key, records[i]->offset);
    }
}
