Record* createRecords(int numRecords, size_t maxMemory) {
    if (maxMemory == 0 || numRecords > (maxMemory / sizeof(Record)) || !numRecords) return NULL;

    Record* records = (Record*)malloc((numRecords + 1) * sizeof(Record));
    if (!records) return NULL;

    int offsetIndex = rand() % maxMemory;
    for (int i = 0; i < numRecords; i++) {
        Record* currentRecord = &records[i];
        currentRecord->offset = offsetIndex++;
        int key = rand() % ((maxMemory / sizeof(Record)) - 1);
        int value = rand() % (maxMemory / sizeof(int));
        currentRecord->key = key;
        currentRecord->value = value;
    }

    return records;
}

void freeRecords(Record* records) {
    if (!records) return;

    free(records);
}
