#define MAX_TASKS 1000
#define JSON_FILE "config.json"

typedef struct {
    time_t timestamp;
    float measurement;
    int id;
    int priority;
} sensor_task;

sensor_task *tasks[MAX_TASKS];
int task_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_task(sensor_task* task) {
    pthread_mutex_lock(&lock);
    tasks[task_count] = task;
    task_count++;
    pthread_mutex_unlock(&lock);
}

void remove_task(int id) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < task_count; i++) {
        if (tasks[i]->id == id) {
            tasks[i] = tasks[task_count - 1];
            task_count--;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

void update_task(int id, sensor_task* new_task) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < task_count; i++) {
        if (tasks[i]->id == id) {
            *tasks[i] = *new_task;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

sensor_task* get_task(int id) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < task_count; i++) {
        if (tasks[i]->id == id) {
            sensor_task* result = tasks[i];
            pthread_mutex_unlock(&lock);
            return result;
        }
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}

sensor_task* get_tasks_by_priority(int priority) {
    pthread_mutex_lock(&lock);
    sensor_task* result = NULL;
    for (int i = 0; i < task_count; i++) {
        if (tasks[i]->priority == priority) {
            if (result == NULL) {
                result = tasks[i];
            } else {
                int j;
                for (j = 0; j < i; j++) {
                    if (tasks[j]->priority == priority) {
                        break;
                    }
                }
                if (j != i) {
                    sensor_task* temp = tasks[i];
                    for (; i > j; i--) {
                        tasks[i] = tasks[i - 1];
                    }
                    tasks[j] = temp;
                } else {
                    result = realloc(result, (i - j + 1) * sizeof(sensor_task));
                    memcpy(result + j, &tasks[i], (i - j) * sizeof(sensor_task));
                }
            }
        }
    }
    pthread_mutex_unlock(&lock);
    return result;
}

sensor_task* get_tasks_by_timestamp(time_t timestamp) {
    pthread_mutex_lock(&lock);
    sensor_task* result = NULL;
    for (int i = 0; i < task_count; i++) {
        if (tasks[i]->timestamp <= timestamp) {
            if (result == NULL) {
                result = tasks[i];
            } else {
                int j;
                for (j = 0; j < i; j++) {
                    if (tasks[j]->timestamp <= timestamp) {
                        break;
                    }
                }
                if (j != i) {
                    sensor_task* temp = tasks[i];
                    for (; i > j; i--) {
                        tasks[i] = tasks[i - 1];
                    }
                    tasks[j] = temp;
                } else {
                    result = realloc(result, (i - j + 1) * sizeof(sensor_task));
                    memcpy(result + j, &tasks[i], (i - j) * sizeof(sensor_task));
                }
            }
        }
    }
    pthread_mutex_unlock(&lock);
    return result;
}

