// Define a structure to hold an integer value as a record
typedef struct {
    int value;
} Record;

// Define a hash table with initial size 1024 and load factor 0.7
#define HASH_SIZE 1024
#define LOAD_FACTOR 0.7

// Hash table with 'long' key, 'int' value and 'Record*' data
typedef struct {
    long key;
    int value;
    Record* record;
} HashEntry;

HashEntry** hashTable = NULL;

// Initialize the hash table with a specified size
void initHashTable(int size) {
    if (hashTable != NULL)
        return; // Only initialize once

    hashTable = (HashEntry**)malloc(size * sizeof(HashEntry*));
    for (int i = 0; i < size; i++)
        hashTable[i] = NULL;
}

// Insert a record into the hash table
void insertRecord(int key, int value) {
    initHashTable(HASH_SIZE);
    HashEntry* entry = (HashEntry*)malloc(sizeof(HashEntry));
    entry->key = key;
    entry->value = value;
    Record* record = (Record*)malloc(sizeof(Record));
    record->value = value; // Use the provided value

    int hash = key % HASH_SIZE;
    if (hashTable[hash] == NULL) {
        hashTable[hash] = (HashEntry*)malloc(sizeof(HashEntry));
        hashTable[hash]->key = -1; // Mark as empty
    }

    entry->record = record;
    hashTable[hash] = entry;
}

// Get the value for a given key from the hash table
int getRecordValue(int key) {
    int hash = key % HASH_SIZE;
    HashEntry* entry = hashTable[hash];
    while (entry != NULL && entry->key != -1) {
        if (entry->key == key)
            return entry->value;

        // Move to the next slot
        entry = entry->next;
    }
}

// Iterate over all records in the hash table and perform an action
void iterateRecords(void (*action)(Record*)) {
    for (int i = 0; i < HASH_SIZE; i++) {
        HashEntry* entry = hashTable[i];
        while (entry != NULL) {
            Record* record = entry->record;
            action(record);
            entry = entry->next;
        }
    }
}

// Generate a random integer within a specified range
int randInRange(int min, int max) {
    if (min > max)
        return -1; // Invalid range

    int range = max - min + 1;
    return rand() % range + min;
}
