#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define RECORD_SIZE 64
#define BATCH_SIZE 1000
#define MAX_RECORDS 1000000

typedef struct {
    int value;
    long offset;
    int key;
    char timestamp[16];
    char status[8];
} Record;

Record *record_array[MAX_RECORDS];
int record_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void init_record_array() {
    for (int i = 0; i < MAX_RECORDS; i++) {
        record_array[i] = malloc(RECORD_SIZE);
        if (!record_array[i]) {
            printf("Memory allocation failed\n");
            exit(1);
        }
        memset(record_array[i], 0, RECORD_SIZE);
    }
}

void insert_record(int value) {
    pthread_mutex_lock(&lock);
    Record *new_record = &record_array[record_count];
    new_record->value = value;
    int random_key = rand() % INT_MAX;
    new_record->key = random_key;
    // Generate timestamp and status
    strftime(new_record->timestamp, 16, "%Y-%m-%d-%H-%M-%S", localtime(NULL));
    strcpy(new_record->status, "NEW");
    record_count++;
    pthread_mutex_unlock(&lock);
}

void delete_record(int key) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < record_count; i++) {
        if (record_array[i]->key == key) {
            memset(record_array[i], 0, RECORD_SIZE);
            record_array[i] = NULL;
            for (int j = i + 1; j < record_count; j++) {
                record_array[j - 1] = &record_array[j];
            }
            record_count--;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

void process_batch(int start, int end) {
    pthread_mutex_lock(&lock);
    for (int i = start; i <= end; i++) {
        // Process records in batch
        printf("Processing record %d\n", i);
    }
    pthread_mutex_unlock(&lock);
}

void persist_records() {
    FILE *file = fopen("records.txt", "wb");
    if (!file) {
        printf("Error opening file\n");
        return;
    }
    for (int i = 0; i < record_count; i++) {
        fwrite(record_array[i], RECORD_SIZE, 1, file);
    }
    fclose(file);
}

void load_records() {
    FILE *file = fopen("records.txt", "rb");
    if (!file) {
        printf("Error opening file\n");
        return;
    }
    record_count = 0;
    while (fread(record_array[record_count], RECORD_SIZE, 1, file)) {
        record_count++;
    }
    fclose(file);
}

int main() {
    srand(time(NULL));
    init_record_array();
    for (int i = 0; i < BATCH_SIZE; i++) {
        insert_record(rand() % INT_MAX);
    }
    // Process records in batches
    int start = 0;
    int end = BATCH_SIZE - 1;
    process_batch(start, end);
    persist_records();
    load_records();
    return 0;
}
