typedef enum {
    RUNNING,
    BLOCKED,
    DONE
} status_t;

typedef struct task {
    pid_t pid;
    time_t timestamp;
    status_t *status;
    struct task* next;
} task_t;

task_t* create_task(pid_t pid) {
    task_t* task = (task_t*)malloc(sizeof(task_t));
    if (!task) {
        return NULL;
    }
    task->pid = pid;
    task->timestamp = time(NULL);
    task->status = &RUNNING;
    task->next = NULL;
    return task;
}

void delete_task(task_t** head, task_t* node) {
    if (*head == node) {
        *head = node->next;
    }
    free(node);
}
