typedef struct {
    int value;
    char identifier;
} record_t;

void manage_memory(int num_records, int min_value, int max_value) {
    long* offset_values = NULL;
    int* keys = NULL;
    record_t** records = NULL;

    if (num_records > 0 && num_records <= 10000000) {
        // Allocate memory
        offset_values = (long*)malloc(num_records * sizeof(long));
        keys = (int*)malloc(num_records * sizeof(int));
        records = (record_t**)malloc(num_records * sizeof(record_t*));

        if (offset_values && keys && records) {
            // Initialize arrays
            srand(time(NULL));
            for (int i = 0; i < num_records; i++) {
                offset_values[i] = rand() % 100000;
                keys[i] = rand() % (max_value - min_value + 1) + min_value;

                record_t* record = (record_t*)malloc(sizeof(record_t));
                if (!record) {
                    // Handle memory allocation failure
                    free(offset_values);
                    free(keys);
                    free_records(records, num_records);
                    return;
                }

                record->value = keys[i];
                char c = 'a' + rand() % 26; // Randomly select a character
                record->identifier = c;

                records[i] = record;
            }
        } else {
            // Handle memory allocation failure
            free_records(records, num_records);
            return;
        }

        // Free allocated memory
        free(offset_values);
        free(keys);
    }

    void free_records(record_t** records, int num_records) {
        for (int i = 0; i < num_records; i++) {
            if (records[i]) {
                free(records[i]);
            }
        }

        free(records);
    }
}
