    *logs = (event_log**)malloc(num_logs * sizeof(event_log*));
    for (int i = 0; i < num_logs; i++) {
        (*logs)[i] = (event_log*)malloc(sizeof(event_log));
        (*logs)[i]->timestamp = i;
        (*logs)[i]->event_type = i % 10;
        sprintf((*logs)[i]->message, "Event %d at timestamp %.2f", i, (*logs)[i]->timestamp);
    }
}

void write_logs(const event_log** logs, int num_logs) {
    FILE* file = fopen("log.txt", "wb");
    if (!file) {
        printf("Error opening log file\n");
        return;
    }

    for (int i = 0; i < num_logs; i++) {
        fwrite(&((*logs)[i]->timestamp), sizeof(float), 1, file);
        fwrite(&((*logs)[i]->event_type), sizeof(short), 1, file);
        size_t written = fwrite((*logs)[i]->message, 1, strlen((*logs)[i]->message), file);
        if (written != strlen((*logs)[i]->message)) {
            printf("Error writing to log file\n");
            fclose(file);
            return;
        }
    }

    fclose(file);
}

int main() {
    int num_logs = 1000;
    event_log** logs = NULL;

    log_events(&logs, num_logs);

    write_logs(logs, num_logs);

    for (int i = 0; i < num_logs; i++) {
        free(logs[i]);
    }

    free(logs);
    return 0;
}
