```c
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int* buffer;
    int value;
} Record;

void* alloc_array(size_t size, int bufferSize) {
    void* arr = calloc(1, sizeof(void*) * size);
    if (arr == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < size; i++) {
        Record* record = (Record*) malloc(sizeof(Record));
        if (record == NULL) {
            free(arr);
            printf("Memory allocation failed\n");
            return NULL;
        }

        record->buffer = calloc(bufferSize, sizeof(char));
        if (record->buffer == NULL) {
            free(record);
            free(arr);
            printf("Memory allocation failed\n");
            return NULL;
        }

        record->value = 0;
        ((int*)arr)[i] = (void*)record;
    }

    return arr;
}

void dealloc_array(void* arr, int size, int bufferSize) {
    for (int i = 0; i < size; i++) {
        Record* record = (Record*)((int*)arr)[i];
        if (record != NULL) {
            free(record->buffer);
            free(record);
        }
    }

    free(arr);
}

void init_array(void* arr, int size, int minValue, int maxValue, int bufferSize) {
    srand(time(NULL));

    Record** records = (Record**)arr;
    for (int i = 0; i < size; i++) {
        Record* record = records[i];
        record->value = rand() % (maxValue - minValue + 1) + minValue;
    }
}

void free_all(void* arr, int size, int bufferSize) {
    dealloc_array(arr, size, bufferSize);
}
