#define MAX_KEY 1000 // Define the maximum number of keys
#define OFFSET_SIZE (sizeof(long) * MAX_KEY)
#define RECORD_SIZE sizeof(record_t)

typedef struct {
    int value;
} record_t;

void manage_arrays(int seed, int num_keys, int total_memory, long** offsets, int** keys, record_t** records) {
    // Allocate and initialize the offset array
    *offsets = (long*)malloc(OFFSET_SIZE);
    for (int i = 0; i < MAX_KEY; i++) {
        (*offsets)[i] = i;
    }

    // Initialize the key array with unique values
    *keys = (int*)malloc(num_keys * sizeof(int));
    for (int i = 0; i < num_keys; i++) {
        while (1) {
            int random_key = rand() % MAX_KEY;
            bool is_unique = true;
            for (int j = 0; j < i; j++) {
                if ((*keys)[j] == random_key) {
                    is_unique = false;
                    break;
                }
            }
            if (is_unique) {
                (*keys)[i] = random_key;
                break;
            }
        }
    }

    // Allocate and initialize the record array
    *records = (record_t*)malloc((num_keys + 1) * RECORD_SIZE);
    for (int i = 0; i < num_keys; i++) {
        (*records)[i].value = rand_r(&seed) % (MAX_KEY - 1) + 1;
    }

    // Search for a key in the key array
    int search_key(int target_key, long* offset) {
        for (int i = 0; i < num_keys; i++) {
            if ((*keys)[i] == target_key) {
                *offset = (*offsets)[i];
                return 1;
            }
        }
        return -1;
    }

    // Function to search for a specific key in the key array and return the corresponding offset
    int search(int target_key, long* offset) {
        int result = search_key(target_key, offset);
        if (result == -1) {
            printf("Key not found!\n");
        }
        return result;
    }

    // Free dynamically allocated memory
    free(*offsets);
    free(*keys);
    free(*records);
}
