        log_records[i]->timestamp = timestamps[i];
        log_records[i]->type = types[i];
        sprintf(log_records[i]->message, "Event %d at time %f", i, timestamps[i]);
    }

    // Write records to file using buffered I/O
    FILE *file = fopen("event_log.txt", "wb");
