#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    time_t timestamp;
    int in_range;
} NumberEntry;

NumberEntry* initialize_array(int capacity) {
    NumberEntry* arr = (NumberEntry*)malloc(sizeof(NumberEntry) * capacity);
    return arr;
}

int main() {
    int capacity = 10000000; // up to 10 million unique entries
    int num_entries = 0;
    int max_value = INT_MIN, min_value = INT_MAX;

    NumberEntry* array = initialize_array(capacity);

    int current_timestamp = time(NULL);
    int range_start = 0, range_end = 2147483647; // 0 to 2,147,483,647

    while (scanf("%d", &array[num_entries].value) == 1 && num_entries < capacity) {
        if (array[num_entries].value < 0 || array[num_entries].value > range_end) {
            printf("Invalid value: %d. Skipping...\n", array[num_entries].value);
            continue;
        }
        array[num_entries].timestamp = current_timestamp++;
        if (array[num_entries].value < min_value)
            min_value = array[num_entries].value;
        if (array[num_entries].value > max_value)
            max_value = array[num_entries].value;

        num_entries++;
    }

    printf("Number of entries: %d\n", num_entries);
    printf("Minimum value: %d\n", min_value);
    printf("Maximum value: %d\n", max_value);

    // Calculate mean and standard deviation
    double sum = 0;
    for (int i = 0; i < num_entries; i++) {
        sum += array[i].value;
    }
    double mean = sum / num_entries;

    double variance = 0;
    for (int i = 0; i < num_entries; i++) {
        variance += (array[i].value - mean) * (array[i].value - mean);
    }
    double std_dev = sqrt(variance / num_entries);

    printf("Mean: %f\n", mean);
    printf("Standard deviation: %f\n", std_dev);

    free(array);

    return 0;
}
