#include <stdlib.h>
#include <stdio.h>

typedef struct Record {
    int value;
    long* offset;
} Record;

Record** allocateRecords(int size) {
    Record** records = (Record**)malloc(size * sizeof(Record*));
    if (!records) {
        return NULL; // Handle memory allocation failure
    }
    for (int i = 0; i < size; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) {
            freeRecords(records, i);
            return NULL;
        }
    }
    return records;
}

void freeRecords(Record** records, int size) {
    for (int i = 0; i < size; i++) {
        free(records[i]->offset);
        free(records[i]);
    }
    free(records);
}

long* allocateOffsets(int size) {
    long* offsets = (long*)malloc(size * sizeof(long));
    if (!offsets) {
        return NULL; // Handle memory allocation failure
    }
    for (int i = 0; i < size; i++) {
        // Initialize offset values here
        offsets[i] = i;
    }
    return offsets;
}

// Assuming random_in_range is a provided function that returns a random value within the given range
void populateRecords(int keyCount, Record** records) {
    for (int i = 0; i < keyCount; i++) {
        records[i]->value = random_in_range(1, 100); // Set the record's int field to a random value
        records[i]->offset = &offsets[i]; // Update the record's offset pointer
    }
}

Record** manageMemory(int keyCount) {
    Record** records = NULL;
    long* offsets = allocateOffsets(keyCount);
    if (!offsets) return NULL;

    int size = 1; // Start with an initial capacity
    for (int i = 0; i < keyCount; i++) {
        if (i >= size) {
            size *= 2; // Resize the array when necessary
            records = reallocateRecords(size);
            if (!records) {
                free(offsets); // Handle memory allocation failure
                return NULL;
            }
        }
    }

    populateRecords(keyCount, records);

    return records;
}

// Reallocate and resize the records array based on the given size
Record** reallocateRecords(int newSize) {
    Record** newRecords = (Record**)realloc(NULL, newSize * sizeof(Record*));
    if (!newRecords) {
        return NULL; // Handle memory allocation failure
    }
    for (int i = 0; i < newSize; i++) {
        newRecords[i] = (Record*)malloc(sizeof(Record));
        if (!newRecords[i]) {
            freeRecords(newRecords, i);
            return NULL;
        }
    }
    return newRecords;
}
