    char* filename = "data.bin";
    serialize_data(records, num_records, filename, 'b'); // Binary format

    // Deserialize and print data
    deserialize_data(filename, 'b');

    return 0;
}

record_t** allocate_records(int num_records, long min_offset, long max_offset, int min_key, int max_key, int min_record_value, int max_record_value) {
    record_t** records = (record_t**)malloc(num_records * sizeof(record_t*));
    for (int i = 0; i < num_records; i++) {
        int key = rand() % (max_key - min_key + 1) + min_key;
        int offset = rand() % (max_offset - min_offset + 1) + min_offset;
        int value = rand() % (max_record_value - min_record_value + 1) + min_record_value;

        while (find_key(records, i, key)) {
            // Handle collision
            key = (key + 1) % (max_key - min_key + 1) + min_key;
        }

        records[i] = (record_t*)malloc(sizeof(record_t));
        records[i]->key = key;
        records[i]->value = value;
    }

    return records;
}

int find_key(record_t** records, int i, int key) {
    for (int j = 0; j < i; j++) {
        if (records[j]->key == key) {
            return 1;
        }
    }
    return 0;
}

void serialize_data(record_t** records, int num_records, char* filename, char format) {
    FILE* file;
    switch (format) {
        case 'b':
            file = fopen(filename, "wb");
            break;
        case 't':
            file = fopen(filename, "wt");
            break;
        default:
            printf("Invalid format. Only binary ('b') or text ('t') formats are supported.\n");
            return;
    }

    if (!file) {
        printf("Error opening file.\n");
        return;
    }

    // Serialize data
    for (int i = 0; i < num_records; i++) {
        fwrite(&records[i]->key, sizeof(int), 1, file);
        fwrite(&records[i]->value, sizeof(int), 1, file);
    }

    fclose(file);
}

void deserialize_data(char* filename, char format) {
    FILE* file;
    switch (format) {
        case 'b':
            file = fopen(filename, "rb");
            break;
        case 't':
            file = fopen(filename, "rt");
            break;
        default:
            printf("Invalid format. Only binary ('b') or text ('t') formats are supported.\n");
            return;
    }

    if (!file) {
        printf("Error opening file.\n");
        return;
    }

    // Deserialize data
    record_t** records = (record_t**)malloc(1000 * sizeof(record_t*)); // Assuming 1000 is the maximum number of records
    for (int i = 0; i < 1000; i++) {
        int key, value;
        fread(&key, sizeof(int), 1, file);
        fread(&value, sizeof(int), 1, file);

        printf("Record %d: Key = %d, Value = %d\n", i, key, value);
    }

    fclose(file);
}
