task** dynamicTaskArray(int initialCapacity) {
    task** tasks = (task**)malloc(initialCapacity * sizeof(task*));
    for (int i = 0; i < initialCapacity; i++) {
        tasks[i] = (task*)malloc(sizeof(task));
        tasks[i]->timestamp = time(NULL);
        sprintf(tasks[i]->name, "Task-%d", i);
        tasks[i]->info = NULL;
    }
    return tasks;
}

void resizeTaskArray(task** tasks, int newCapacity) {
    task** newTasks = (task**)realloc(tasks, newCapacity * sizeof(task*));
    for (int i = 0; i < newCapacity; i++) {
        if (i >= strlen(tasks)) {
            tasks[i] = (task*)malloc(sizeof(task));
            tasks[i]->timestamp = time(NULL);
            sprintf(tasks[i]->name, "Task-%d", i);
            tasks[i]->info = NULL;
        }
    }
}

void freeTaskArray(task** tasks, int capacity) {
    for (int i = 0; i < capacity; i++) {
        if (tasks[i]->info) {
            free(tasks[i]->info);
        }
        free(tasks[i]);
    }
    free(tasks);
}
