void init_entry(entry_t* e) {
    srand(time(NULL));
    int msg_len = rand() % (max_msg_length + 1);
    char* msg = malloc(msg_len * sizeof(char));
    if (!msg) {
        MSG_ALLOC_FAILURE_LOGGING;
        return;
    }
    for (int i = 0; i < msg_len; i++) {
        msg[i] = 'a' + rand() % 26;
    }
    msg[msg_len - 1] = '\0';
    e->message = msg;
}

void resize_entries(int new_size) {
    entry_t** new_entries = realloc(entries, new_size * sizeof(entry_t*));
    if (!new_entries) {
        MSG_ALLOC_FAILURE_LOGGING;
        return;
    }
    entries = new_entries;
    for (int i = num_entries; i < new_size; i++) {
        init_entry(&entries[i]);
    }
}

void add_entry(long timestamp, int priority) {
    pthread_mutex_lock(&lock);
    if (num_entries >= MAX_ENTRIES) {
        printf("Error: Maximum number of entries reached.\n");
        return;
    }
    entry_t* new_entry = malloc(sizeof(entry_t));
    if (!new_entry) {
        MSG_ALLOC_FAILURE_LOGGING;
        pthread_mutex_unlock(&lock);
        return;
    }
    init_entry(new_entry);
    entries[num_entries++] = new_entry;
    pthread_mutex_unlock(&lock);
}

