#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <libxml/parser.h>
#include <libxml/tree.h>

void InitializeAndConfigurePhyLayerFramePduListWithXmlSync(const char* xml_file_path) {
    // Load XML file using libxml2
    xmlDoc *doc = xmlReadFile(xml_file_path, NULL, XML_PARSE_NOERROR);

    if (doc == NULL) {
        return;
    }

    // Initialize a list of PHY Layer Frame PDU structures
    PhyLayerFramePduList* phy_list = malloc(sizeof(PhyLayerFramePduList));

    // Parse XML document and populate the list
    xmlNode *root_node = xmlDocGetRootElement(doc);
    xmlNode *current_node = root_node->children;

    while (current_node != NULL) {
        if (strcmp(current_node->name, "phy_layer_frame_pdu") == 0) {
            PhyLayerFramePdu* pdu = malloc(sizeof(PhyLayerFramePdu));

            // Populate PDU structure from XML node
            pdu->field1 = atoi(xmlGetProp(current_node, "field1"));
            pdu->field2 = xmlTextChildElement(current_node)->content;

            // Add PDU to the list
            phy_list->pdu_count++;
            phy_list->pdus = realloc(phy_list->pdus, (phy_list->pdu_count + 1) * sizeof(PhyLayerFramePdu*));
            phy_list->pdus[phy_list->pdu_count - 1] = pdu;
        }

        current_node = current_node->next;
    }

    // Free XML document and list memory
    xmlFreeDoc(doc);
    free(phy_list);
}
