use reqwest;
use tokio::time;

pub mod http_client {
    use reqwest::blocking::{get, post};
    use std::sync::Arc;
    use tokio::sync::Mutex;

    pub struct HttpClient {
        timeout: u64,
        backoff_strategy: Box<dyn Fn() -> (u64, u64)>,
        retry_attempts: usize,
    }

    impl HttpClient {
        pub async fn get(&self, url: &str) -> Result<String, reqwest::Error> {
            let client = Arc::new(Mutex::new(reqwest::blocking::get(url).await?));
            self.retry_request(&client, url).await
        }

        pub async fn post(&self, url: &str, body: String) -> Result<String, reqwest::Error> {
            let client = Arc::new(Mutex::new(reqwest::blocking::post(url, &body).await?));
            self.retry_request(&client, url).await
        }

        async fn retry_request(&self, client: &Arc<Mutex<reqwest::blocking::Response>>, url: &str) -> Result<String, reqwest::Error> {
            let mut attempts = 0;
            while attempts < self.retry_attempts {
                match client.lock().clone().try_streaming_get(url).await {
                    Ok(response) => return Ok(response.text().await?),
                    Err(err) => {
                        if err.status() == 429 {
                            // Handle rate limiting
                            thread::sleep(self.backoff_strategy());
                        } else {
                            return Err(err);
                        }
                    }
                }
                attempts += 1;
            }
            Err(reqwest::Error::new(503, "Too many retries"))
        }
    }
}
