typedef struct {
    int key;
    char data[256];
} Record;

Record* create_record(int key, char* data) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }
    record->key = key;
    strcpy(record->data, data);
    return record;
}

int insert_record(Record** head, int count, size_t max_size) {
    Record* current = *head;
    Record* prev = NULL;
    for (int i = 0; i < count && current != NULL; i++) {
        Record* new_rec = create_record(rand(), "/tmp/rand_string");
        if (!new_rec) {
            return -1; // Allocation failure
        }
        size_t total_size = sizeof(Record) + strlen(new_rec->data);
        if (total_size > max_size) {
            free(new_rec);
            return 0; // Max size exceeded
        }
        prev = current;
        current = new_rec;
    }
    if (!prev) *head = current;
    else prev->next = current;
    return 1; // Successful insertion
}

void free_records(Record* head) {
    Record* current = head;
    while (current != NULL) {
        Record* next = current->next;
        free(current);
        current = next;
    }
}
