    public static SqlDataReader ExecuteParameterizedQuery(SqlConnection connection, string commandText, List<Record> records)
    {
        try
        {
            using (SqlCommand cmd = new SqlCommand(commandText, connection))
            {
                foreach (var record in records)
                {
                    cmd.Parameters.AddWithValue("@Offset", record.offset);
                    cmd.Parameters.AddWithValue("@Key", record.key);
