#define MAX_NODES 1000000
#define BLOCK_SIZE 1024

typedef struct {
    int value;
    char* strRef;
} Node;

void* my_malloc(size_t size) {
    // Implement custom dynamic memory allocator here
    return malloc(size);
}

void my_free(void* ptr) {
    // Implement custom deallocator to release allocated memory
    free(ptr);
}

Node* createNode(int value, char* strRef) {
    Node* node = (Node*)my_malloc(sizeof(Node));
    node->value = value;
    node->strRef = strRef;
    return node;
}

void addNode(Node** head, int value, char* strRef) {
    Node* newNode = createNode(value, strRef);
    if (*head == NULL) {
        *head = newNode;
    } else {
        Node* current = *head;
        while (current->strRef != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
}

void freeNodes(Node** head, void (*free_func)(void*)) {
    Node* current = *head;
    Node* next;
    while (current != NULL) {
        next = current->next;
        free_func(current);
        current = next;
    }
    *head = NULL;
}

int main() {
    json_object* root;
    FILE* file = fopen("data.json", "r");
    if (file == NULL) {
        printf("Error opening JSON file.\n");
        return 1;
    }
    root = json_load_file(file, JSON_OBJECT_USE_BACKSLASH_ESCAPING);
    fclose(file);

    if (root == NULL) {
        printf("Error parsing JSON file.\n");
        return 1;
    }

    Node* head = NULL;

    // Process JSON data to construct linked list
    for (int i = 0; i < MAX_NODES; i++) {
        json_object* node_obj = json_object_object_get(root, "node");
        int value = json_object_get_int(node_obj, "value");
        char* strRef = json_object_get_string(node_obj, "strRef");

        if (strRef == NULL) {
            printf("Error: Missing 'strRef' field.\n");
            continue;
        }

        addNode(&head, value, strRef);

        // Periodically flush unused memory blocks
        if ((i + 1) % BLOCK_SIZE == 0) {
            Node* current = head;
            while (current != NULL) {
                Node* next = current->next;
                my_free(current);
                current = next;
            }
            head = NULL;
        }
    }

    freeNodes(&head, &my_free);

    return 0;
}
