Record* create_record(int key, const char* data) {
    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        // Handle memory allocation failure
        return NULL;
    }
    new_record->key = key;
    strcpy(new_record->data, data);
    new_record->next = NULL;
    return new_record;
}

void destroy_records(Record* head) {
    Record* current = head;
    while (current) {
        Record* next = current->next;
        free(current);
        current = next;
    }
}

