    for (int i = 0; i < length; i++) {
        buffer[i] = (char)(rand() % 26 + 'a');
    }
    buffer[length] = '\0';
    return buffer;
}

void populate_records(Record** head, int num_records, int max_size) {
    *head = NULL;
    Record* current = NULL;
    for (int i = 0; i < num_records && !(*head); i++) {
