        const char* data = generate_random_data(rand() % 256);
        Record* new_record = create_record(key, data);
        if (!new_record) {
            // Handle memory allocation failure
            return;
        }
        if (!current) {
            *head = current = new_record;
        } else {
            current->next = new_record;
            current = new_record;
        }
    }
}

