typedef struct {
    int key;
    int value;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} Records;

Records* init_records(size_t initial_capacity) {
    Records* records = (Records*)malloc(sizeof(Records));
    records->records = (Record*)calloc(initial_capacity, sizeof(Record));
    records->capacity = initial_capacity;
    records->size = 0;
    if(pthread_mutex_init(&records->mutex, NULL) != 0) {
        free(records);
        return NULL;
    }
    return records;
}

void resize_records(Records* records, size_t new_capacity) {
    Record* temp = (Record*)calloc(new_capacity, sizeof(Record));
    pthread_mutex_lock(&records->mutex);
    if(records->size > 0) {
        memcpy(temp, records->records, records->size * sizeof(Record));
    }
    free(records->records);
    records->records = temp;
    records->capacity = new_capacity;
    pthread_mutex_unlock(&records->mutex);
}

void add_record(Records* records, int key, int value) {
    if(records->size >= records->capacity) {
        resize_records(records, (records->capacity * 2) + 1);
    }
    Record record = {key, value};
    pthread_mutex_lock(&records->mutex);
    records->records[records->size++] = record;
    pthread_mutex_unlock(&records->mutex);
}

Record* get_record(Records* records, int key) {
    for(size_t i = 0; i < records->size; i++) {
        if(records->records[i].key == key) {
            return &records->records[i];
        }
    }
    return NULL;
}

void free_records(Records* records) {
    pthread_mutex_lock(&records->mutex);
    free(records->records);
    pthread_mutex_unlock(&records->mutex);
    free(records);
}
