void* resize_thread_func(void* arg) {
    size_t new_capacity = capacity * 2;
    record* new_records = (record*)malloc(new_capacity * sizeof(record));

    pthread_mutex_lock(&mutex);

    // Copy existing records to the new array
    for (int i = 0; i < num_records; i++) {
        memcpy(&new_records[i], &records[i], sizeof(record));
    }

    free(records);
    records = new_records;
    capacity = new_capacity;
    pthread_mutex_unlock(&mutex);

    return NULL;
}

void resize() {
    pthread_t thread;
    pthread_create(&thread, NULL, resize_thread_func, NULL);
    pthread_join(thread);
