    records = NULL;
    capacity = 0;
    num_records = 0;
}

void* batch_set_values(void* arg) {
    int* values = (int*)arg;
    for (int i = 0; i < *values / BATCH_SIZE + 1; i++) {
        int start = i * BATCH_SIZE;
        int end = min(start + BATCH_SIZE, *values);

        for (int j = start; j < end; j++) {
            record* record = get_record(j);
            if (record != NULL) {
                set_record_value(record, values[j]);
                free(record);
            }
        }
    }

    return NULL;
