#include <iostream>
#include <vector>
#include <mutex>
#include <functional>

class DynamicRecordManager {
public:
    DynamicRecordManager(int initialCapacity) : 
        records_(new std::vector<std::pair<int, int>>(initialCapacity)), 
        lock_(), 
        capacity_(initialCapacity), 
        nextAvailable_(0)
    {}

    ~DynamicRecordManager() {
        delete[] records_;
    }

    void addRecord(int key, int value) {
        if (nextAvailable_ >= capacity_) {
            resize();
        }
        records_[nextAvailable_] = std::make_pair(key, value);
        nextAvailable_++;
    }

    void updateRecord(int key, int value) {
        for (int i = 0; i < nextAvailable_; i++) {
            if (records_[i].first == key) {
                records_[i] = std::make_pair(key, value);
                return;
            }
        }
    }

    int getRecordValue(int key) {
        for (int i = 0; i < nextAvailable_; i++) {
            if (records_[i].first == key) {
                return records_[i].second;
            }
        }
        return -1;
    }

    void resetRange(int min, int max) {
        capacity_ = max - min + 1;
        records_.reset(new std::vector<std::pair<int, int>>(capacity_));
        nextAvailable_ = 0;
    }

    std::string toString() {
        std::string str;
        for (int i = 0; i < nextAvailable_; i++) {
            str += "Key: " + std::to_string(records_[i].first) +
                   ", Value: " + std::to_string(records_[i].second) + "\n";
        }
        return str;
    }

private:
    void resize() {
        int newCapacity = capacity_ * 2;
        std::vector<std::pair<int, int>> newData(newCapacity);
        for (int i = 0; i < nextAvailable_; i++) {
            newData[i] = records_[i];
        }
        delete[] records_;
        records_.reset(&newData[0]);
        capacity_ = newCapacity;
    }

    std::mutex lock_;
    int* records_;
    int capacity_;
    int nextAvailable_;
};
