typedef struct {
    int val;
} record;

record* create_records(int size) {
    if (size <= 0) {
        return NULL; // Handle edge case where size is zero or negative
    }

    record* records = (record*)malloc(size * sizeof(record));
    if (!records) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < size; i++) {
        records[i].val = rand() % 100; // Populate record values with random numbers
    }

    return records;
}

int get_record_count(record* records) {
    int count = 0;
    while (records != NULL) {
        count++;
        records = records->next;
    }
    return count;
}

void release_records(record** records) {
    if (!(*records)) {
        return; // Handle edge case where there are no records to free
    }

    record* current = *records;
    record* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *records = NULL;
}

int main() {
    int size;
    printf("Enter the number of records: ");
    scanf("%d", &size);

    // Create and populate record arrays
    long* offsets = (long*)malloc(size * sizeof(long));
    int* keys = (int*)malloc(size * sizeof(int));
    record* records = create_records(size);

    for (int i = 0; i < size; i++) {
        offsets[i] = i;
        keys[i] = i;
    }

    // Log each record creation event
    FILE* log_file = fopen("record_log.txt", "w");
    if (!log_file) {
        printf("Failed to open log file\n");
        return -1;
    }
    for (int i = 0; i < size; i++) {
        fprintf(log_file, "Record %d created with value: %d\n", i, records[i].val);
    }
    fclose(log_file);

    // Release all allocated memory
    release_records(&records);

    return 0;
}
