#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define a structure for system events
typedef struct {
    int timestamp;
    char description[100];
} Event;

// Define a linked list node for efficient insertion and deletion
typedef struct Node {
    Event event;
    struct Node* next;
} Node;

// Define the dynamic array to store system events
Node** events = NULL;

// Function to allocate memory for the events array
void* my_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    return ptr;
}

// Function to initialize the events array
int init_events(int capacity) {
    events = (Node**)my_malloc(sizeof(Node*) * capacity);
    for (int i = 0; i < capacity; i++) {
        events[i] = NULL;
    }
    return 1;
}

// Function to add a new event to the dynamic array
void add_event(int timestamp, char* description) {
    Node* newNode = (Node*)my_malloc(sizeof(Node));
    if (newNode == NULL) return;

    newNode->event.timestamp = timestamp;
    strcpy(newNode->event.description, description);

    // Insert the new node at the end of the linked list
    int index = 0;
    for (; events[index] != NULL; index++);
    events[index] = newNode;
}

// Function to retrieve events by timestamp range
void get_events_by_range(int start, int end) {
    Node* current = NULL;
    for (int i = 0; i < 100000; i++) { // Assuming max capacity is 100,000
        if (events[i] == NULL || events[i]->event.timestamp > end) break;

        current = events[i];
        while (current != NULL && current->event.timestamp <= start) {
            current = current->next;
        }
        if (current == NULL) continue;

        printf("Timestamp: %d, Description: %s\n", current->event.timestamp, current->event.description);

        // Move to the next event in the linked list
        while (current->next != NULL && current->next->event.timestamp <= end) {
            current = current->next;
        }
    }
}

// Function to serialize events to a file
void serialize_events(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) return;

    Node* current = NULL;
    for (int i = 0; i < 100000; i++) { // Assuming max capacity is 100,000
        if (events[i] == NULL) break;

        current = events[i];
        while (current != NULL && current->event.timestamp <= 0) {
            current = current->next;
        }
        if (current == NULL) continue;

        fwrite(&current->event, sizeof(Event), 1, file);

        // Move to the next event in the linked list
        while (current->next != NULL && current->next->event.timestamp <= 0) {
            current = current->next;
        }
    }

    fclose(file);
}

// Function to deserialize events from a file
int deserialize_events(const char* filename, int capacity) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) return -1;

    Node** new_events = (Node**)my_malloc(sizeof(Node*) * capacity);
    for (int i = 0; i < capacity; i++) {
        new_events[i] = NULL;
    }

    Event event;
    int index = 0;
    while (fread(&event, sizeof(Event), 1, file) == 1) {
        Node* newNode = (Node*)my_malloc(sizeof(Node));
        if (newNode == NULL) return -1;

        newNode->event.timestamp = event.timestamp;
        strcpy(newNode->event.description, event.description);

        // Insert the new node at the end of the linked list
        new_events[index] = newNode;
        index++;
    }

    fclose(file);
    free(events);
    events = new_events;
    return 1;
}
