#include <stdlib.h>
#include <string.h>

typedef struct Node {
    char* str;
    struct Node* next;
} Node;

Node* node_new(const char* str) {
    Node* node = malloc(sizeof(Node));
    if (!node) return NULL;

    node->str = strdup(str);
    if (!node->str) {
        free(node);
        return NULL;
    }

    node->next = NULL;

    return node;
}

void list_insert(Node** head, const char* str) {
    Node* new_node = node_new(str);
    if (*head == NULL || strcmp((*head)->str, new_node->str) > 0) {
        new_node->next = *head;
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next && strcmp(current->next->str, new_node->str) < 0) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
}

void list_free(Node** head) {
    Node* current = *head;
    while (current) {
        Node* next = current->next;
        free(current->str);
        free(current);
        current = next;
    }
    *head = NULL;
}

void list_print(Node* head) {
    for (; head; head = head->next) {
        printf("%s\n", head->str);
    }
}
