#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 1000
#define MEMORY_LIMIT (1024 * 1024) // 1 MB limit

typedef struct {
    int value;
    char buffer[256]; // Assuming max string length is 256
} record_t;

record_t* records[MAX_RECORDS];
int keys[MAX_RECORDS];

pthread_mutex_t hash_table_lock = PTHREAD_MUTEX_INITIALIZER;
int num_records = 0;

void* hash_table_lookup(int key) {
    int index = key % MAX_RECORDS;
    if (records[index] && records[index]->value == key)
        return &records[index]->buffer[0];
    else
        return NULL;
}

void add_record(record_t* new_record, int key) {
    pthread_mutex_lock(&hash_table_lock);
    int index = key % MAX_RECORDS;
    if (!keys[index])
        keys[index] = key;
    records[index] = new_record;
    num_records++;
    pthread_mutex_unlock(&hash_table_lock);
}

void release_resources() {
    for (int i = 0; i < num_records; i++) {
        free(records[i]);
        records[i] = NULL;
    }
    free(keys);
    keys = NULL;
    num_records = 0;
}

// Function to manage memory for and initialize the components
int manage_memory(int num_keys) {
    if (num_records > 0)
        return -1; // Memory already allocated, cannot reallocate

    records[0] = malloc(sizeof(record_t));
    if (!records[0])
        return -2; // Memory allocation failed

    for (int i = 1; i < MAX_RECORDS; i++) {
        records[i] = NULL;
    }
    keys[0] = 0;

    if (num_keys > 0) {
        int allocated_bytes = sizeof(record_t) * num_records + sizeof(int) * num_records;
        if ((allocated_bytes / (1024 * 1024)) > MEMORY_LIMIT)
            return -3; // Exceeding memory limit

        for (int i = 1; i < num_keys; i++) {
            records[i] = malloc(sizeof(record_t));
            if (!records[i])
                return -2; // Memory allocation failed
        }
    }

    return 0;
}

// Example usage:
int main() {
    int num_records_to_allocate = 10;
    int status = manage_memory(num_records_to_allocate);
    if (status < 0) {
        printf("Error allocating memory: %d\n", -status);
        release_resources();
    } else {
        for (int i = 0; i < num_records_to_allocate; i++) {
            record_t* new_record = malloc(sizeof(record_t));
            new_record->value = i;
            add_record(new_record, i);
        }
        // Example usage:
        int key = 5;
        char* retrieved_buffer = hash_table_lookup(key);
        if (retrieved_buffer) {
            printf("Record with key %d found: %s\n", key, retrieved_buffer);
        } else
            printf("Record with key %d not found.\n", key);

        release_resources();
    }

    return 0;
}
