// Structure to represent a node in the linked list
typedef struct {
    char* str;
    struct node* next;
    int ref_count;
} Node;

// Function to create a new node with given string and initial reference count 1
Node* newNode(char* str) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->str = strdup(str);
    node->next = NULL;
    node->ref_count = 1;
    return node;
}

// Function to insert a new node at the end of the list
void insertNode(Node** head, char* str) {
    Node* newNode = newNode(str);
    if (*head == NULL) {
        *head = newNode;
    } else {
        Node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
}

// Function to print the string values of all nodes in the list
void printNodes(Node* head) {
    while (head != NULL) {
        printf("%s\n", head->str);
        head = head->next;
    }
}

// Function to decrement the reference count and free the node if it reaches 0
void freeNode(Node** head, Node* node) {
    node->ref_count--;
    if (node->ref_count == 0) {
        // Reuse the node by resetting its contents
        node->str = NULL;
        node->next = NULL;
        node->ref_count = 1;
    } else {
        // Find and decrement the reference count of nodes pointing to this node
        Node* current = *head;
        while (current != NULL) {
            if (current == node) break;
            current = current->next;
        }
        if (current == NULL) return; // Node not found in list, ignore
        current->ref_count--;
    }
}

int main() {
    Node* head = NULL;

    // Example usage:
    insertNode(&head, "Hello");
    insertNode(&head, "World");
    insertNode(&head, "Coding");

    printNodes(head);

    freeNode(&head, head->next); // Decrement reference count of second node

    return 0;
}
