#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a struct to represent each node in the linked list
typedef struct Node {
    char* str;
    struct Node* next;
} Node;

// Function prototypes
Node* create_node(const char* str);
void insert_node(Node** head, const char* str);
void print_list(Node* head);
int remove_substring(Node** head, const char* substring);

// Custom memory allocator functions (optional)
void* custom_malloc(size_t size);
void custom_free(void* ptr);

// Main struct to represent the linked list
typedef struct LinkedList {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

// Create a new node with the given string value
Node* create_node(const char* str) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->str = strdup(str);
    node->next = NULL;
    return node;
}

// Insert a new node at the end of the list
void insert_node(Node** head, const char* str) {
    Node* new_node = create_node(str);
    if (*head == NULL) {
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

// Print the contents of each node in the list
void print_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        printf("%s\n", current->str);
        current = current->next;
    }
}

// Remove nodes with a substring present in their string values
int remove_substring(Node** head, const char* substring) {
    Node* prev = NULL;
    Node* current = *head;
    while (current != NULL) {
        if (strstr(current->str, substring) != NULL) {
            if (prev == NULL) {
                *head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current->str);
            free(current);
            return 1; // Node removed
        }
        prev = current;
        current = current->next;
    }
    return 0; // No nodes removed
}

// Custom memory allocator functions (optional)
void* custom_malloc(size_t size) {
    // Implement a custom allocator or use the standard library's malloc
}

void custom_free(void* ptr) {
    // Implement a custom free function or use the standard library's free
}

// Initialize and destroy the linked list
LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current->str);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Usage example
int main() {
    LinkedList* list = create_linked_list();
    insert_node(&list->head, "Hello");
    insert_node(&list->head, "World");
    print_list(list->head); // Output: Hello World
    remove_substring(&list->head, "or"); // Remove nodes with substring "or"
    print_list(list->head); // Output: Hello
    destroy_linked_list(list);
    return 0;
}

