void manage_memory(int n, int seed, int random_range_min, int random_range_max) {
    // Allocate memory for arrays
    long* offsets = (long*)malloc(n * sizeof(long));
    int* keys = (int*)malloc(n * sizeof(int));
    record* records = (record*)malloc(n * sizeof(record));

    if (!offsets || !keys || !records) {
        printf("Memory allocation failed.\n");
        return;
    }

    // Initialize offsets and keys
    for (int i = 0; i < n; i++) {
        offsets[i] = i;
        keys[i] = i;
    }

    // Generate random values for records
    srand(seed);
    int unique_values[n];
    for (int i = 0; i < n; i++) {
        int value;
        do {
            value = rand() % ((random_range_max - random_range_min + 1) + 1) + random_range_min;
        } while (unique_values[value % (n - 1)]++ == 0);
        records[i].value = value;
    }

    // Use offsets and keys to index other critical components
    printf("Offsets: ");
    for (int i = 0; i < n; i++) {
        printf("%ld ", offsets[i]);
    }
    printf("\n");
    printf("Keys: ");
    for (int i = 0; i < n; i++) {
        printf("%d ", keys[i]);
    }
    printf("\n");

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
}
