#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct {
    long offset;
    int key;
    double value;
    char* label;
} Record;

Record* initialize_list(int num_records) {
    Record* list = (Record*)malloc(num_records * sizeof(Record));
    for (int i = 0; i < num_records; i++) {
        list[i].key = rand() % 100;
        time_t now = time(NULL);
        char timestamp[32];
        strftime(timestamp, 32, "%Y%m%d%H%M%S", localtime(&now));
        char label[50] = {'\0'};
        sprintf(label, "Record_%ld_%s", i, timestamp);
        list[i].label = (char*)malloc(strlen(label) + 1);
        strcpy(list[i].label, label);
    }
    return list;
}

void process_list(Record* list, int num_records, long threshold) {
    int removed_count = 0;
    double total_offset = 0.0;
    int min_key = INT_MAX;
    int max_key = INT_MIN;

    for (int i = 0; i < num_records; i++) {
        if (list[i].offset > threshold) {
            free(list[i].label);
            removed_count++;
            total_offset += list[i].offset;
            if (list[i].key < min_key)
                min_key = list[i].key;
            if (list[i].key > max_key)
                max_key = list[i].key;
        }
    }

    printf("Removed records: %d\n", removed_count);
    printf("Average offset: %.2f\n", total_offset / removed_count);
    printf("Min key: %d, Max key: %d\n", min_key, max_key);

    Record* new_list = (Record*)malloc((num_records - removed_count) * sizeof(Record));
    int j = 0;
    for (int i = 0; i < num_records; i++) {
        if (list[i].offset <= threshold) {
            new_list[j] = list[i];
            j++;
        }
    }

    // free the original list
    for (int i = 0; i < removed_count; i++)
        free(&list[i]);

    free(list);
    list = new_list;
}

int main() {
    int num_records = 10;
    int threshold = 50000000;

    Record* list = initialize_list(num_records);

    process_list(list, num_records, threshold);

    return 0;
}
