typedef struct {
    char* timestamp;
    double amount;
} Transaction;

Transaction* process_csv_file(char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        return NULL;
    }

    int record_count = 0;
    Transaction* transactions = (Transaction*)calloc(MAX_RECORDS, sizeof(Transaction));

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        char* token = strtok(line, ",");
        transactions[record_count].timestamp = strdup(token);
        token = strtok(NULL, ",");
        transactions[record_count].amount = atof(token);

        // Validate transaction details
        if (transactions[record_count].amount > THRESHOLD) {
            printf("Flagged for review: %s - %.2f\n", transactions[record_count].timestamp, transactions[record_count].amount);
        }

        record_count++;
    }

    fclose(file);

    return transactions;
}

void log_discrepancies(Transaction* transactions, int record_count) {
    for (int i = 0; i < record_count; i++) {
        if (!transactions[i].timestamp || !transactions[i].timestamp[0]) {
            printf("Invalid timestamp: %s\n", transactions[i].timestamp);
        }
        if (transactions[i].amount < 0.0) {
            printf("Invalid amount: %.2f\n", transactions[i].amount);
        }
    }
}

