        return -1;
    }

    // Execute parameterized query
    char* query = "SELECT name, city, address FROM Employees WHERE supervisor_id = ?";
    MYSQL_STMT *stmt;
    stmt = mysql_prepare_stmt(conn, query, NULL);
    if (!stmt) {
        printf("Error preparing statement: %s\n", mysql_error(conn));
        return -1;
    }

    // Bind parameter
    int param_id = mysql_bind_param(stmt, "%d");

    // Execute query with retrieved ID
    mysql_execute_stmt(stmt, &param_id);

    mysql_free_result(stmt);
    mysql_close(conn);
    return 0;
}

// Function to handle database connectivity errors and retries
void retryDBConnection(char* host, char* user, char* password, char* db) {
    int attempts = 1;
    while (attempts <= 5) {
        if (!connectDB(host, user, password, db)) {
            printf("Database connection established successfully.\n");
            return;
        }
        printf("Error connecting to database. Retrying in %d seconds...\n", attempts * 2);
        sleep(attempts * 2);
        attempts++;
    }
}

// Function to free allocated resources
void freeResources(Record* records, int count) {
    if (records) {
        free(records);
    }
}

int main() {
    // Example usage
    Record* records;
    int totalSize = 0;
    records = createRecords(100, &totalSize);
    initRecords(records, 100);

    // Perform operations on the records array
    safeAccess(records, 100);

    // Establish database connection and execute query
    retryDBConnection("localhost", "username", "password", "database");

    freeResources(records, 100);

    return 0;
}
