#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

struct Graph {
    int numVertices;
    struct Vertex** vertices;
    struct Edge* edges;
};

struct Vertex {
    float weight;
    bool visited;
    int id;
    struct Vertex** neighbors;
};

struct Edge {
    int source;
    int destination;
};

void initGraph(struct Graph* graph, int numEdges) {
    graph->numVertices = 0;

    while (graph->numVertices < numVertices && !memoryError()) {
        // Allocate vertex memory
        struct Vertex* vertex = malloc(sizeof(struct Vertex));
        if (!vertex) return; // Handle memory allocation failure

        vertex->weight = 1.0f;
        vertex->visited = false;
        vertex->id = graph->numVertices;

        // Initialize adjacency list with null pointers
        vertex->neighbors = malloc(numEdges * sizeof(struct Vertex*));
        if (!vertex->neighbors) return; // Handle memory allocation failure

        for (int i = 0; i < numEdges; i++) {
            vertex->neighbors[i] = NULL;
        }

        graph->vertices[graph->numVertices++] = vertex;
    }
}

void addEdge(struct Graph* graph, int source, int destination) {
    // Find source and destination vertices
    struct Vertex* srcVert = graph->vertices[source];
    struct Vertex* destVert = graph->vertices[destination];

    // Create edge struct and allocate memory
    struct Edge* edge = malloc(sizeof(struct Edge));
    if (!edge) return; // Handle memory allocation failure

    edge->source = source;
    edge->destination = destination;

    // Link the edge to the source vertex's adjacency list
    srcVert->neighbors[srcVert->numNeighbors++] = destVert;

    // Update neighbor count for destination vertex
    destVert->numNeighbors++;
}

void updateVertex(struct Graph* graph, int id) {
    // Find vertex and mark as visited
    struct Vertex* vertex = graph->vertices[id];
    if (!vertex) return; // Handle null pointer

    vertex->visited = true;
}

bool hasBeenVisited(struct Graph* graph, int id) {
