    if (!node) {
        perror("Memory allocation failed");
        return NULL;
    }
    node->label = malloc(strlen(label) + 1);
    strcpy(node->label, label);
    node->next = NULL;
    return node;
}

void graph_node_free(graph_node* node) {
    if (node == NULL)
        return;
    free(node->label);
    free(node);
}

// Function to manage dynamic datasets and graph nodes
void dataset_mgmt() {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    void* ptr;
    int i, j, k;

    // Initialize the dataset
    init_dataset();

    // Allocate memory for graph nodes
    graph_node* head = NULL;
    for (i = 0; i < MAX_DATA_SET_SIZE; i++) {
        graph_node* node = graph_node_create("node_label");
        if (!node) {
            perror("Memory allocation failed");
            return;
        }
        // Add the node to the linked list
        if (head == NULL)
            head = node;
        else {
            for (j = 0; j < i && head->next != NULL; j++)
                head = head->next;
            node->next = head->next;
            head->next = node;
        }
    }

    // Print the dataset and graph nodes
    for (i = 0; i < MAX_DATA_SET_SIZE; i++) {
        printf("Data set: %f, ID: %s\n", dataset[i].value, dataset[i].id);
        ptr = &dataset[i];
        pthread_mutex_lock(&mutex);
        // Simulate concurrent access and modification
        for (j = 0; j < i; j++) {
            ((element*)ptr)->ref_count++;
            ptr = &dataset[j];
        }
        pthread_mutex_unlock(&mutex);

        // Print the graph nodes
        for (k = 0; head != NULL && k < i; k++)
            printf("Graph node: %s\n", head->label);
    }

    // Release memory resources
    graph_node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        graph_node_free(temp);
    }
}

