#include <stdlib.h>
#include <string.h>

// Define a struct to represent each node in the list
typedef struct {
    char* str;
    int val;
    struct node* next;
} Node;

// Function prototypes
Node* add_node(Node** head, char* str, int val);
Node* find_node(Node** head, char* str);
void update_node(Node** head, char* str, int val);
void cleanup(Node** head);

// Add a new node to the list with specified string and integer values
Node* add_node(Node** head, char* str, int val) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->str = (char*)malloc(strlen(str) + 1);
    strcpy(new_node->str, str);
    new_node->val = val;
    new_node->next = *head;
    *head = new_node;
    return *head;
}

// Search for a node by its string value
Node* find_node(Node** head, char* str) {
    Node* current = *head;
    while (current != NULL) {
        if (strcmp(current->str, str) == 0) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

// Update an existing node with new string and integer values
void update_node(Node** head, char* str, int val) {
    Node* node = find_node(head, str);
    if (node != NULL) {
        free(node->str);
        node->str = (char*)malloc(strlen(str) + 1);
        strcpy(node->str, str);
        node->val = val;
    }
}

// Cleanup the list by releasing all allocated memory
void cleanup(Node** head) {
    Node* current = *head;
    Node* next;
    while (current != NULL) {
        next = current->next;
        free(current->str);
        free(current);
        current = next;
    }
    *head = NULL;
}

