typedef struct subscription {
    user_profile* profile;
    enum subscription_status status;
    time_t expiration_date;
    struct subscription* next;
} subscription;

typedef struct user_profile {
    uint64_t id;
    time_t last_update;
    char* session_token;
    activity_log* log;
    int log_length;
    struct subscription* subscriptions;
    int subscription_count;
} user_profile;

user_profile* create_user_profile(uint64_t id) {
    user_profile* profile = (user_profile*)malloc(sizeof(user_profile));
    profile->id = id;
    profile->last_update = time(NULL);
    profile->session_token = NULL;
    profile->log = NULL;
    profile->log_length = 0;
    profile->subscriptions = NULL;
    profile->subscription_count = 0;
    return profile;
}

void free_user_profile(user_profile* profile) {
    if (profile == NULL) return;

    // Free session token
    free(profile->session_token);
    profile->session_token = NULL;

    // Free activity log entries
    for (int i = 0; i < profile->log_length; i++) {
        free(profile->log[i].description);
        profile->log[i].description = NULL;
    }
    free(profile->log);
    profile->log = NULL;

    // Free subscription list
    subscription* current = profile->subscriptions;
    while (current != NULL) {
        subscription* next = current->next;
        free(current);
        current = next;
    }
    profile->subscriptions = NULL;

    free(profile);
}

subscription* create_subscription(user_profile* profile, enum subscription_status status, time_t expiration_date) {
    subscription* subscription = (subscription*)malloc(sizeof(subscription));
    subscription->profile = profile;
    subscription->status = status;
    subscription->expiration_date = expiration_date;
    subscription->next = NULL;
    return subscription;
}

void free_subscription(subscription* subscription) {
    if (subscription == NULL) return;

    // Free subscription and its next
    free_subscription(subscription->next);
    subscription->next = NULL;

    free(subscription);
}

