    void* ptr = malloc(size);
    if (!ptr && size > 1024*1024*1024) { // 1GB
        printf("Memory allocation failed due to memory constraint\n");
        return NULL;
    }
    return ptr;
}

void my_free(void* ptr) {
    free(ptr);
}

data_entry* create_data_entry(int id, float value, char *description) {
    data_entry* entry = (data_entry*)my_malloc(sizeof(data_entry));
    if (!entry) return NULL;

    entry->id = id;
    entry->value = value;
    entry->description = my_malloc(strlen(description)+1);
    strcpy(entry->description, description);

    return entry;
}

processed_data* create_processed_data(size_t size) {
    processed_data* data = (processed_data*)my_malloc(sizeof(processed_data));
    if (!data) return NULL;

    data->size = size;
    data->data = my_malloc(size * sizeof(data_entry));

    for (size_t i=0; i<size; i++) {
        data->data[i] = create_data_entry(i, 0.0f, "Unknown");
    }

    return data;
}

void free_processed_data(processed_data* data) {
    if (!data) return;

    for (size_t i=0; i<data->size; i++) {
        my_free(data->data[i].description);
        my_free(&data->data[i]);
    }
    my_free(data->data);
    my_free(data);
}

int main() {
    // Example usage
    processed_data* data = create_processed_data(10);

    for (size_t i=0; i<data->size; i++) {
        printf("Data entry %zu: id=%d, value=%.2f, description=%s\n", i+1, data->data[i]->id, data->data[i]->value, data->data[i]->description);
    }

    free_processed_data(data);

    return 0;
}
