#include <sys/stat.h>
#include <fcntl.h>
#include <inttypes.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

typedef struct {
    int key;
    long offset;
} record_t;

record_t* create_records(int num_records) {
    int i, alloc_size = sizeof(record_t) * num_records;
    void* ptr = malloc(alloc_size);

    if (ptr == NULL) {
        perror("malloc failed");
        return NULL;
    }

    for (i = 0; i < num_records; i++) {
        record_t* rec = ptr + i * sizeof(record_t);
        rec->key = rand() % 100;
        rec->offset = rand();
    }

    return ptr;
}

int main(int argc, char** argv) {
    int num_records = atoi(argv[1]);
    int fd;
    struct sockaddr_in addr;

    record_t* records = create_records(num_records);

    if (records == NULL)
        exit(1);

    // Initialize the socket
    int sock = socket(AF_INET, SOCK_STREAM, 0);

    if (sock < 0) {
        perror("socket failed");
        free(records);
        return -1;
    }

    // Connect to the remote service
    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(8080);
    inet_pton(AF_INET, "192.168.1.100", &server_addr.sin_addr);
    connect(sock, (struct sockaddr*)&server_addr, sizeof(server_addr));

    // Write the records to a file
    int file_fd = open("records.txt", O_WRONLY | O_CREAT, 0644);

    if (file_fd < 0) {
        perror("open failed");
        close(sock);
        free(records);
        return -1;
    }

    for (int i = 0; i < num_records; i++) {
        record_t* rec = records + i;
        write(file_fd, &rec->key, sizeof(rec->key));
        write(file_fd, &rec->offset, sizeof(rec->offset));
    }

    close(file_fd);

    // Close the socket
    close(sock);

    free(records);
    return 0;
}
