#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PROJECTS 100
#define MAX_TASKS_PER_PROJECT 50
#define MAX_PRIORITY_LEVEL 5

typedef struct {
    int priority;
    char* description;
} task;

typedef struct {
    int num_tasks;
    task* tasks[MAX_TASKS_PER_PROJECT];
} project;

void manage_task_system(int num_projects, int max_priority, int threshold) {
    project projects[MAX_PROJECTS];
    for (int i = 0; i < num_projects; i++) {
        projects[i].num_tasks = 0;
        for (int j = 0; j < MAX_TASKS_PER_PROJECT; j++) {
            projects[i].tasks[j] = NULL;
        }
    }

    // Initialize random seed
    srand(time(NULL));

    // Allocate memory for tasks and descriptions
    char** task_descriptions = (char**)malloc(num_projects * sizeof(char*));
    int** priorities = (int**)malloc(num_projects * sizeof(int*));
    for (int i = 0; i < num_projects; i++) {
        task_descriptions[i] = (char*)malloc(strlen("Task Description") + 1);
        strcpy(task_descriptions[i], "Task Description");
        priorities[i] = (int*)malloc(sizeof(int));
        *priorities[i] = rand() % max_priority;
    }

    // Initialize projects and tasks
    for (int i = 0; i < num_projects; i++) {
        project* current_project = &projects[i];
        int task_count = 0;
        while (task_count < MAX_TASKS_PER_PROJECT) {
            task new_task;
            new_task.priority = *priorities[i];
            new_task.description = task_descriptions[i];
            current_project->tasks[task_count] = &new_task;
            task_count++;
            if (current_project->num_tasks >= threshold) break;
        }
    }

    // Free resources
    for (int i = 0; i < num_projects; i++) {
        free(task_descriptions[i]);
        free(priorities[i]);
    }
    free(task_descriptions);
    free(priorities);
}

int main() {
    manage_task_system(MAX_PROJECTS, MAX_PRIORITY_LEVEL, 3);
    return 0;
}
