#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Structure representing a node in the linked list
typedef struct Node {
    double value;
    struct Node* next;
} Node;

// Structure representing the linked list itself
typedef struct LinkedList {
    Node* head;
    pthread_mutex_t lock; // Lock for thread-safe operations
} LinkedList;

// Function to create a new node with the given value and return its address
Node* newNode(double value) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    node->value = value;
    node->next = NULL;
    return node;
}

// Function to initialize the linked list
LinkedList* initLinkedList() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL); // Initialize lock for thread-safe operations
    return list;
}

// Function to insert a new node at the beginning of the linked list
void insertAtHead(LinkedList* list, double value) {
    Node* newNode = newNode(value);
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock); // Unlock after insertion
}

// Function to remove a node from the beginning of the linked list
void removeHead(LinkedList* list) {
    if (list->head != NULL) {
        Node* temp = list->head;
        list->head = list->head->next;
        free(temp);
        pthread_mutex_unlock(&list->lock); // Unlock after removal
    }
}

// Function to print the linked list for debugging purposes
void printList(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        printf("%f ", current->value);
        current = current->next;
    }
    printf("\n");
}
