['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1000
#define CACHE_SIZE 100
#define LOGGING_LEVEL 3

typedef struct {
    int value;
} record_t;

record_t* records;
int record_count = 0;
int cache_hit_rate = 0;
int cache_miss_rate = 0;
int memory_usage = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_rwlock_t cache_lock = PTHREAD_RWLOCK_INITIALIZER;

void* allocate_array(int size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed!\n");
        exit(1);
    }
    return ptr;
}

int initialize_records() {
    record_t* new_records = (record_t*)allocate_array(MAX_RECORDS * sizeof(record_t));
    records = new_records;
    for (int i = 0; i < MAX_RECORDS; i++) {
        int random_value = rand() % 100 + 1;
        records[i].value = random_value;
        record_count++;
    }
    return 0;
}

void* read_record(int key) {
    pthread_rwlock_rdlock(&cache_lock);
    for (int i = 0; i < record_count; i++) {
        if (records[i].value == key) {
            // Cache hit
            cache_hit_rate++;
            void* cached_ptr = malloc(sizeof(record_t));
            memcpy(cached_ptr, &records[i], sizeof(record_t));
            pthread_rwlock_unlock(&cache_lock);
            return cached_ptr;
        }
    }
    pthread_rwlock_unlock(&cache_lock);

    for (int i = 0; i < record_count; i++) {
        if (records[i].value == key) {
            // Not in cache, but present in memory
            void* ptr = malloc(sizeof(record_t));
            memcpy(ptr, &records[i], sizeof(record_t));
            return ptr;
        }
    }

    // Record not found in memory or cache
    pthread_rwlock_unlock(&cache_lock);
    return NULL;
}

void write_record(int key, int value) {
    pthread_rwlock_wrlock(&cache_lock);
    for (int i = 0; i < record_count; i++) {
        if (records[i].value == key) {
            records[i].value = value;
            break;
        }
    }
    pthread_rwlock_unlock(&cache_lock);

    // Update cache and memory
    int new_key = rand() % MAX_RECORDS + 1;
    for (int i = record_count; i < record_count + CACHE_SIZE; i++) {
        if (i >= MAX_RECORDS) break;
        records[i].value = new_key++;
    }
}

void* persistent_storage() {
    FILE* file = fopen("records.txt", "wb");
    fwrite(&record_count, sizeof(int), 1, file);
    for (int i = 0; i < record_count; i++) {
        fwrite(&records[i], sizeof(record_t), 1, file);
    }
    fclose(file);

    return NULL;
}

void log_stats() {
    printf("Cache hit rate: %d\n", cache_hit_rate);
    printf("Cache miss rate: %d\n", cache_miss_rate);
    printf("Memory usage: %d\n", memory_usage);
}

int main() {
    srand(time(NULL));
    initialize_records();

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, &read_record, rand() % MAX_RECORDS + 1);
        pthread_create(&threads[i], NULL, &write_record, rand() % MAX_RECORDS + 1);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    persistent_storage();
    log_stats();

    return 0;
}

```']

