    ops->buffers = (buffer*)calloc(num_files, sizeof(buffer));
    ops->metadatas = (metadata*)calloc(num_files, sizeof(metadata));

    for (int i = 0; i < num_files; i++) {
        FILE* file = fopen("file_name.txt", "r");
        if (!file) continue;

        fseek(file, 0, SEEK_END);
        long size = ftell(file);
        rewind(file);

        uint8_t* data = (uint8_t*)malloc(size);
        fread(data, sizeof(uint8_t), size, file);
        fclose(file);

        ops->buffers[i].length = size;
        ops->buffers[i].data = data;

        metadata meta;
        // initialize metadata fields...
        ops->metadatas[i] = meta;

        free(data);
    }

    return ops;
