void *transaction_manager(void *arg) {
    while (1) {
        // Allocate memory for new transaction structure
        transaction_t *new_txn = malloc(sizeof(transaction_t));
        if (!new_txn) {
            // Handle memory allocation failure gracefully
            perror("Transaction manager: Memory allocation failed");
            continue;
        }

        // Initialize transaction fields
        time(&new_txn->timestamp);
        new_txn->amount = 0.0;
        new_txn->account_id = 0;

        // Add new transaction to pool and cache (if necessary)
        pthread_mutex_lock(&pool_lock);
