#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    int value;
    char id;
    struct {
        time_t timestamp;
        size_t reference_count;
    } data;
} node;

node* list = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* allocate_node(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        perror("Memory allocation failed");
        return NULL;
    }
    return ptr;
}

int insert_node(node** head, int value, char id) {
    node* new_node = (node*)allocate_node(sizeof(node));
    if (!new_node) {
        return -1; // Allocation failed
    }

    new_node->value = value;
    new_node->id = id;

    pthread_mutex_lock(&lock);
    new_node->data.timestamp = time(NULL);
    new_node->data.reference_count = 0;
    pthread_mutex_unlock(&lock);

    if (*head) {
        node* current = *head;
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
    } else {
        *head = new_node;
    }
    return 0; // Insertion successful
}

int remove_node(node** head, char id) {
    node* current = *head;
    node* prev = NULL;

    pthread_mutex_lock(&lock);
    while (current && current->id != id) {
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&lock);

    if (!current) {
        return -1; // Node not found
    }

    node* temp = current;
    current = current->next;

    *head = current;

    free(temp);
    return 0; // Removal successful
}

void print_list(node* head) {
    pthread_mutex_lock(&lock);
    while (head) {
        printf("Value: %d, ID: %c\n", head->value, head->id);
        head = head->next;
    }
    pthread_mutex_unlock(&lock);
}
