// Function to initialize and manage linked lists
void init_linked_lists(node** head, int max_size) {
    *head = (node*)malloc(sizeof(node));
    (*head)->next = NULL;
    for (int i = 1; i < max_size; i++) {
        node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        node* new_node = (node*)malloc(sizeof(node));
        new_node->value = rand() % 100; // Assign random value
        new_node->id = (char*)malloc(20);
        sprintf(new_node->id, "Node_%d", i); // Assign unique id
        new_node->next = NULL;
        current->next = new_node;
    }
}

// Function to initialize and manage cache sets
void init_cache_sets(cache_set* set, int max_size) {
    set->entries = (cache_entry**)malloc(max_size * sizeof(cache_entry));
    for (int i = 0; i < max_size; i++) {
        set->entries[i] = (cache_entry*)malloc(sizeof(cache_entry));
        set->entries[i]->data = NULL;
        set->entries[i]->timestamp = time(NULL); // Assign current timestamp
    }
    pthread_mutex_init(&set->lock, NULL);
}

