// Define a pool allocator for memory management
typedef struct {
    void** objects;
    size_t capacity;
    size_t used;
} pool_allocator;

// Initialize the pool allocator with a given initial capacity and maximum size
pool_allocator* init_pool_allocator(size_t initial_capacity, size_t max_size) {
    pool_allocator* allocator = malloc(sizeof(pool_allocator));
    allocator->objects = (void*)malloc(initial_capacity * sizeof(void*));
    allocator->capacity = initial_capacity;
    allocator->used = 0;
    return allocator;
}

// Allocate a new object from the pool and initialize it
void* alloc_object(pool_allocator* allocator) {
    if (allocator->used >= allocator->capacity) {
        // Reallocate the objects array with double the capacity
        allocator->objects = realloc(allocator->objects, 2 * allocator->capacity * sizeof(void*));
        allocator->capacity *= 2;
    }
    return allocator->objects[allocator->used++];
}

