typedef struct {
    int value;
    int* key;
} record;

record* allocateRecords(int numRecords) {
    record* records = (record*)malloc(numRecords * sizeof(record));
    if (!records) {
        fprintf(stderr, "Error: memory allocation failed for records.\n");
        exit(1);
    }
    return records;
}

int* allocateKeys(int numKeys) {
    int* keys = (int*)malloc(numKeys * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Error: memory allocation failed for keys.\n");
        exit(1);
    }
    return keys;
}

long* allocateOffsets(int numOffsets) {
    long* offsets = (long*)malloc(numOffsets * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Error: memory allocation failed for offsets.\n");
        exit(1);
    }
    return offsets;
}

void readDataFromFile(record** records, int** keys, long** offsets, FILE* file) {
    char line[1024];
    int numRecords = 0;
    while (fgets(line, sizeof(line), file)) {
        int recordValue;
        int key;
        sscanf(line, "%d %d", &recordValue, &key);
        (*records)[numRecords].value = recordValue;
        (*keys)[numRecords] = &key;
        if (!--line[0]) break;  // End of file reached
    }
    *numRecords = numRecords + 1;
}

void freeResources(record* records, int* keys, long* offsets) {
    free(records);
    free(keys);
    free(offsets);
}

int main(int argc, char** argv) {
    int numRecords = 0;
    int numKeys = 0;
    FILE* file = fopen(argv[1], "r");
    if (!file) {
        fprintf(stderr, "Error: cannot open file '%s' for reading.\n", argv[1]);
        return 1;
    }

    // Read data from file
    record* records = NULL;
    int* keys = NULL;
    long* offsets = NULL;
    while (fgets(line, sizeof(line), file)) {
        int recordValue;
        long offset;
        sscanf(line, "%d %ld", &recordValue, &offset);
        numRecords++;
        if (!--line[0]) break;  // End of file reached
    }

    numKeys = numRecords;
    records = allocateRecords(numRecords);
    keys = allocateKeys(numKeys);
    offsets = allocateOffsets(numRecords);

    readDataFromFile(&records, &keys, &offsets, file);

    freeResources(records, keys, offsets);

    return 0;
}
