    // Allocate memory for the data structures
    while (fscanf(input_stream, "%ld %d", &num_records, &keys) == 2) {
        // Check if there's enough memory to store all keys
        if (!keys || num_records * sizeof(int) > (size_t)(keys + 1 - keys)) {
            free(keys);
            keys = NULL;
        }

        // Allocate memory for the record structures and offsets
        if (!records || num_records * sizeof(record_t) > (size_t)(records + 1 - records)) {
            free(records);
            records = NULL;
        }
        if (!offsets || num_records * sizeof(long) > (size_t)(offsets + 1 - offsets)) {
            free(offsets);
            offsets = NULL;
        }

        // Process each record
        for (int i = 0; i < num_records; i++) {
            // Set the value of each record to a random value within a given range
            records[i].value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
            records[i].key = &keys[i];

