            FILE* log_stream = fopen(log_file, "a");
            if (!log_stream) {
                printf("Error writing to log file.\n");
            } else {
                fprintf(log_stream, "%lu: Processed %d records with keys {%d...}%d and values {%d...}%d\n",
                        now, num_records, MIN_KEY, num_records - 1, MIN_VALUE, MAX_VALUE);
                fclose(log_stream);
            }
        }

        // Update the number of records
        num_records = 0;

        // Check for memory allocation errors and handle them gracefully
        if (!records || !keys || !offsets) {
            printf("Memory allocation error.\n");
            return NULL;
        }
    }

    // Clean up allocated resources
    free(keys);
    keys = NULL;
    free(offsets);
    offsets = NULL;

    return records;
}

