extern crate reqwest;

use reqwest::blocking::{get, post};
use std::sync::Arc;
use std::thread;

pub struct HttpClient {
    url: String,
    timeout: u64,
    backoff_strategy: Box<dyn Fn(u64) -> u64>,
}

impl HttpClient {
    pub fn new(url: &str, timeout: u64, backoff_strategy: Box<dyn Fn(u64) -> u64>) -> Arc<Self> {
        Arc::new(HttpClient {
            url: url.to_string(),
            timeout,
            backoff_strategy,
        })
    }

    async fn make_request(&self, method: &str, body: Option<&[u8]>) -> Result<String, reqwest::Error> {
        let client = reqwest::blocking::get(self.url.clone())
            .timeout(std::time::Duration::from_millis(self.timeout))
            .send()
            .await?
            .text();

        Ok(client)
    }
}
