#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_STRING_LENGTH 255
#define MAX_UNIQUE_ENTRIES 1000000

typedef struct {
    char* string;
    time_t timestamp;
    int is_interesting;
} StringEntry;

int main() {
    FILE* input_file = fopen("input.txt", "r");
    if (input_file == NULL) {
        printf("Error opening file.\n");
        return 1;
    }

    int unique_entry_count = 0;
    char** strings = (char**)malloc(MAX_UNIQUE_ENTRIES * sizeof(char*));
    time_t timestamps[MAX_UNIQUE_ENTRIES];
    for (int i = 0; i < MAX_UNIQUE_ENTRIES; i++) {
        strings[i] = NULL;
        timestamps[i] = 0;
    }

    StringEntry* entries = (StringEntry*)malloc(MAX_UNIQUE_ENTRIES * sizeof(StringEntry));

    char buffer[MAX_STRING_LENGTH + 1];
    while (fgets(buffer, sizeof(buffer), input_file) != NULL) {
        int string_length = strlen(buffer);
        if (string_length >= MAX_STRING_LENGTH || !isascii(buffer)) {
            continue;
        }
        if (unique_entry_count >= MAX_UNIQUE_ENTRIES) {
            break;
        }

        strings[unique_entry_count] = strdup(buffer);
        timestamps[unique_entry_count] = time(NULL);

        for (int i = 0; i < unique_entry_count; i++) {
            if (strcmp(strings[i], buffer) == 0) {
                free(strings[i]);
                strings[i] = NULL;
                break;
            }
        }

        entries[unique_entry_count].string = strings[unique_entry_count];
        entries[unique_entry_count].timestamp = timestamps[unique_entry_count];
        entries[unique_entry_count].is_interesting = 0;

        unique_entry_count++;
    }

    fclose(input_file);

    // Process the data
    int max_frequency = 0;
    char* most_frequent_string = NULL;
    int min_frequency = MAX_UNIQUE_ENTRIES;
    char* least_frequent_string = NULL;
    double average_length = 0.0;

    for (int i = 0; i < unique_entry_count; i++) {
        // Calculate frequency
        // ...

        if (frequency > max_frequency) {
            max_frequency = frequency;
            most_frequent_string = entries[i].string;
        } else if (frequency < min_frequency) {
            min_frequency = frequency;
            least_frequent_string = entries[i].string;
        }

        average_length += strlen(entries[i].string);
    }
    average_length /= unique_entry_count;

    // Print the results
    printf("Most frequent string: %s\n", most_frequent_string);
    printf("Least frequent string: %s\n", least_frequent_string);
    printf("Average length: %.2f characters\n", average_length);

    for (int i = 0; i < unique_entry_count; i++) {
        free(strings[i]);
    }
    free(strings);
    free(entries);

    return 0;
}

int isascii(char* string) {
    for (char c : string) {
        if (c < ' ' || c > '~') {
            return 0;
        }
    }
    return 1;
}
