        if (!keys) {
            free(records);
            free(offsets);
            throw "Memory allocation failed for keys.";
        }

        dataValues = (float*)malloc(count * sizeof(float));
        if (!dataValues) {
            free(records);
            free(offsets);
            free(keys);
            throw "Memory allocation failed for data values.";
        }

        for (int i = 0; i < count; i++) {
            keys[i] = rand() % 100;
            offsets[i] = (long)rand();
            dataValues[i] = (float)rand() / RAND_MAX;

            records[i].key = keys[i];
            records[i].offset = offsets[i];
            records[i].data = dataValues[i];
        }
