#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
    int priority;
    char* name;
} Node;

typedef struct {
    Node* node;
    char command[20];
    time_t timestamp;
} Operation;

Operation* create_operation(int value, int priority, char* name) {
    Operation* op = (Operation*)malloc(sizeof(Operation));
    if (!op) return NULL;
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        free(op);
        return NULL;
    }
    node->value = value;
    node->priority = priority;
    node->name = name;
    op->node = node;
    strcpy(op->command, "unknown");
    op->timestamp = time(NULL);
    return op;
}

void* process_operations(void* arg) {
    Operation* queue[100];
    int front = 0;
    int rear = 0;

    while (1) {
        if (rear == front) {
            sleep(1); // no operations in the queue
        } else {
            Operation* op = queue[front++ % 100];
            printf("Processing operation: %s, value: %d, priority: %d\n", op->node->name, op->node->value, op->node->priority);
            free(op->node);
            free(op);
        }
    }

    pthread_exit(NULL);
}

int main() {
    srand(time(NULL));

    pthread_t threads[10];

    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, process_operations, NULL);
    }

    // populate queue with operations
    Operation* queue[100];
    int front = 0;
    int rear = 0;

    for (int i = 0; i < 100; i++) {
        Node* node = (Node*)malloc(sizeof(Node));
        if (!node) break;
        node->value = rand() % 10;
        node->priority = rand() % 5 + 1;
        char name[20];
        sprintf(name, "operation-%d", i);
        node->name = name;

        Operation* op = create_operation(node->value, node->priority, node->name);

        if (op) {
            queue[rear++] = op;
        } else {
            break;
        }
    }

    // process operations concurrently
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, process_operations, NULL);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
