#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define RECORDS_PER_PAGE 1000
#define PAGE_SIZE sizeof(record) * RECORDS_PER_PAGE
#define RANDOM_VALUE_RANGE 10000
#define MAX_THREADS 10

typedef struct {
    int value;
} record;

record* records = NULL;
size_t records_size = 0, page_count = 1;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void init_records(size_t capacity) {
    size_t pages_needed = (capacity + RECORDS_PER_PAGE - 1) / RECORDS_PER_PAGE;
    if ((pages_needed * PAGE_SIZE) > (size_t)(-1)) return;

    records = realloc(records, pages_needed * PAGE_SIZE);
    for (size_t i = 0; i < pages_needed; i++) {
        record* page = (record*)records + i * RECORDS_PER_PAGE;
        for (int j = 0; j < RECORDS_PER_PAGE; j++) {
            page[j].value = rand() % RANDOM_VALUE_RANGE;
        }
    }
}

void* writer_thread(void* arg) {
    size_t offset, key;
    // Simultaneously update the data structures: one for 'long' offsets and another for 'int' keys
    pthread_mutex_lock(&lock);
    while (records_size < MAX_RECORDS) {
        record* current = &records[records_size++ % RECORDS_PER_PAGE];
        // Update the data structures with offset and key values
        offset = records_size / RECORDS_PER_PAGE;
        key = current->value;
        pthread_cond_signal(&cond);
    }
    pthread_mutex_unlock(&lock);

    return NULL;
}

int main() {
    pthread_t threads[MAX_THREADS];
    int i;

    for (i = 0; i < MAX_THREADS; ++i) {
        pthread_create(&threads[i], NULL, writer_thread, NULL);
    }

    // Perform other tasks concurrently...

    for (i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
