typedef struct {
    int value;
    float weight;
    char* identifier;
} record;

record* allocate_records(int count, int min_value, int max_value, int string_length) {
    record* records = (record*)malloc(count * sizeof(record));
    if (!records) {
        return NULL;
    }

    for (int i = 0; i < count; i++) {
        records[i].value = rand() % ((max_value - min_value) + 1) + min_value;
        records[i].weight = (float)rand() / RAND_MAX;

        // Generate a unique, randomly generated alphanumeric string of fixed length
        char* identifier = (char*)malloc((string_length + 1) * sizeof(char));
        if (!identifier) {
            for (int j = 0; j < i; j++) {
                free(records[j].identifier);
            }
            free(records);
            return NULL;
        }

        identifier[string_length] = '\0';
        for (int j = 0; j < string_length; j++) {
            identifier[j] = (char)(rand() % ('Z' - 'A' + 1) + 'A');
        }

        records[i].identifier = identifier;
    }

    return records;
}

void free_records(record* records, int count) {
    for (int i = 0; i < count; i++) {
        if (records[i].identifier) {
            free(records[i].identifier);
        }
    }

    free(records);
}
