#include <string.h>

typedef struct {
    float val;
    char *id;
} element;

typedef struct {
    double dval;
    char *key;
    element *elem_list;
    size_t elem_count;
    data_group *group;
} data_set;

data_set* create_data_set() {
    data_set* ds = (data_set*)malloc(sizeof(data_set));
    if (!ds) return NULL; // handle allocation failure

    ds->dval = 0.0;
    ds->key = (char*)malloc(10 * sizeof(char)); // initialize with default key
    strcpy(ds->key, "default_key");

    ds->elem_list = (element*)malloc(sizeof(element) * 5); // allocate space for 5 elements
    if (!ds->elem_list) return NULL; // handle allocation failure

    ds->elem_count = 0;
    ds->group = NULL;

    return ds;
}

void free_data_set(data_set* ds) {
    if (!ds) return; // handle null pointer

    free(ds->key);
    for (size_t i = 0; i < ds->elem_count; i++) {
        free(ds->elem_list[i].id);
        free((char*)ds->elem_list[i].val);
    }
    free(ds->elem_list);

    if (ds->group) {
        // recursively free the linked list of data_groups
        data_group* curr = ds->group;
        while (curr) {
            data_set* next_group = curr->next;
            free_data_set(curr);
            curr = next_group;
        }
    }

    free(ds);
}
