metadata* enrich_data_set(data_set* ds) {
    // use the web scraping library to extract metadata from external APIs
    CURL *curl = curl_easy_init();
    if (!curl) return NULL; // handle allocation failure

    // set up the request and fetch the metadata
    char *url = "https://api.example.com/metadata";
    curl_easy_setopt(curl, CURLOPT_URL, url);
    char *data = curl_easy_perform(curl);

    if (data) {
        // parse the metadata into a structure
        metadata* meta = (metadata*)malloc(sizeof(metadata));
        if (!meta) return NULL; // handle allocation failure

        meta->title = strndup(data, strlen(data)); // extract title from metadata
        meta->description = strndup(data, strlen(data)); // extract description from metadata

        free(data);
    }

    curl_easy_cleanup(curl);

    return meta;
}

void free_metadata(metadata* meta) {
    if (!meta) return; // handle null pointer

    free(meta->title);
    free(meta->description);
}
