        node->value = rand() % ((max_value - min_value) + 1) + min_value;
        if (rand() / (double)RAND_MAX < active_probability) {
            node->status = ACTIVE;
        } else {
            node->status = INACTIVE;
        }
    }

    return array;
}

void print_nodes(Node* nodes, int size) {
