#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    char* name;
    int priority;
    time_t deadline;
} Task;

typedef struct {
    Task* tasks;
    size_t size;
} TaskList;

void task_list_init(TaskList* list) {
    list->tasks = NULL;
    list->size = 0;
}

Task* task_create(const char* name, int priority, time_t deadline) {
    Task* task = malloc(sizeof(Task));
    task->name = strdup(name);
    task->priority = priority;
    task->deadline = deadline;
    return task;
}

void task_list_add(TaskList* list, Task* task) {
    if (list->size == 0) {
        list->tasks = task;
    } else {
        Task** tasks = malloc((list->size + 1) * sizeof(Task*));
        memcpy(tasks, list->tasks, list->size * sizeof(Task*));
        tasks[list->size] = task;
        free(list->tasks);
        list->tasks = tasks;
    }
    list->size++;
}

void task_list_remove(TaskList* list, Task* task) {
    size_t i;
    for (i = 0; i < list->size; i++) {
        if (list->tasks[i] == task) {
            break;
        }
    }
    if (i < list->size) {
        memmove(&list->tasks[i], &list->tasks[i+1], (list->size - i - 1) * sizeof(Task*));
        free(task);
        list->size--;
    }
}

void task_list_update(TaskList* list, Task* task, int priority, time_t deadline) {
    size_t i;
    for (i = 0; i < list->size; i++) {
        if (list->tasks[i] == task) {
            task->priority = priority;
            task->deadline = deadline;
            return;
        }
    }
}

void task_list_sort(TaskList* list) {
    qsort(list->tasks, list->size, sizeof(Task*), (int (*)(const void*, const void*))task_compare);
}

int task_compare(const void* a, const void* b) {
    Task* ta = *(Task**)a;
    Task* tb = *(Task**)b;
    if (ta->priority < tb->priority) return -1;
    if (ta->priority > tb->priority) return 1;
    return 0;
}

void task_list_serialize(TaskList* list, FILE* file) {
    fwrite(&list->size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < list->size; i++) {
        fwrite(&list->tasks[i]->name, sizeof(char), strlen(list->tasks[i]->name)+1, file);
        fwrite(&((Task*)list->tasks[i])->priority, sizeof(int), 1, file);
        fwrite(&((Task*)list->tasks[i])->deadline, sizeof(time_t), 1, file);
    }
}

void task_list_deserialize(TaskList* list, FILE* file) {
    size_t size;
    fread(&size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < size; i++) {
        char* name = malloc((sizeof(char)*64)+1);
        int priority;
        time_t deadline;
        fread(name, sizeof(char), strlen(list->tasks[i]->name)+1, file);
        fread(&priority, sizeof(int), 1, file);
        fread(&deadline, sizeof(time_t), 1, file);
        task_list_add(list, task_create(name, priority, deadline));
    }
}

void task_list_cleanup(TaskList* list) {
    size_t i;
    for (i = 0; i < list->size; i++) {
        free(list->tasks[i]->name);
        free(list->tasks[i]);
    }
    free(list->tasks);
}

// External data source update mechanism (omitted for brevity)
