record* allocateRecords(int numOffsets, long minOffset, int numKeys, int minValue, int maxValue) {
    if (numOffsets <= 0 || numKeys <= 0) {
        return NULL; // Handle error
    }

    // Calculate the total number of records needed
    size_t numRecords = numOffsets * numKeys;

    // Allocate memory for offsets array
    long* offsets = malloc(numOffsets * sizeof(long));
    if (!offsets) {
        return NULL; // Handle error
    }
    for (size_t i = 0; i < numOffsets; ++i) {
        offsets[i] = minOffset + i;
    }

    // Allocate memory for keys array
    int* keys = malloc(numKeys * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL; // Handle error
    }
    for (size_t i = 0; i < numKeys; ++i) {
        keys[i] = i;
    }

    // Allocate memory for records array
    record* records = malloc(numRecords * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        return NULL; // Handle error
    }
    for (size_t i = 0; i < numRecords; ++i) {
        int idx = i % numKeys;
        long offsetIdx = i / numKeys;
        records[i].value = malloc(sizeof(int));
        *records[i].value = rand() % (maxValue - minValue + 1) + minValue;
        records[i].offset = &offsets[offsetIdx];
        records[i].key = &keys[idx];
    }

    return records;
}
