conn_record* initialize_connections(int num_connections, int min_timeout, int max_timeout, 
        void (*random_num_generator)(int*, int), void (*buffer_allocator)(void**), 
        void (*connection_manager)(void*)) {

    conn_record* connections = (conn_record*)malloc(num_connections * sizeof(conn_record));

    if (!connections) {
        printf("Memory allocation failed!\n");
        return NULL;
    }

    for (int i = 0; i < num_connections; i++) {
        connections[i].fd = -1;
        connections[i].timeout = -1;

        int* random_number = (int*)malloc(sizeof(int));
        (*random_num_generator)(random_number, min_timeout);
        connections[i].timeout = *random_number;

        void** buffer_ptr = (void**)malloc(sizeof(void*));
        (*buffer_allocator)(buffer_ptr);
        connections[i].buffer = (char*)*buffer_ptr;

        connections[i].status = -1;
    }

    return connections;
}
