#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the task structure
typedef struct {
    char* name;
    int priority;
    time_t deadline;
    enum { ACTIVE, COMPLETED, PENDING } status;
} Task;

// Define the task list structure
typedef struct {
    Task** tasks;
    size_t capacity;
    size_t count;
} TaskList;

// Function to create a new task
Task* create_task(const char* name, int priority, time_t deadline, enum { ACTIVE, COMPLETED, PENDING } status) {
    Task* task = (Task*)malloc(sizeof(Task));
    task->name = strdup(name);
    task->priority = priority;
    task->deadline = deadline;
    task->status = status;
    return task;
}

// Function to create a new task list
TaskList* create_task_list(size_t capacity) {
    TaskList* task_list = (TaskList*)malloc(sizeof(TaskList));
    task_list->tasks = (Task**)calloc(capacity, sizeof(Task*));
    task_list->capacity = capacity;
    task_list->count = 0;
    return task_list;
}

// Function to add a task to the task list
void add_task(TaskList* task_list, Task* task) {
    if (task_list->count >= task_list->capacity) {
        // Reallocate and resize the task list when full
        size_t new_capacity = task_list->capacity * 2;
        Task** new_tasks = (Task**)realloc(task_list->tasks, new_capacity * sizeof(Task*));
        task_list->tasks = new_tasks;
        task_list->capacity = new_capacity;
    }
    task_list->tasks[task_list->count++] = task;
}

// Function to sort the task list by priority and deadline
void sort_task_list(TaskList* task_list) {
    int i, j;
    Task* temp;

    for (i = 0; i < task_list->count - 1; i++) {
        for (j = 0; j < task_list->count - i - 1; j++) {
            if (task_list->tasks[j]->priority > task_list->tasks[j + 1]->priority ||
                (task_list->tasks[j]->priority == task_list->tasks[j + 1]->priority &&
                 task_list->tasks[j]->deadline > task_list->tasks[j + 1]->deadline)) {
                temp = task_list->tasks[j];
                task_list->tasks[j] = task_list->tasks[j + 1];
                task_list->tasks[j + 1] = temp;
            }
        }
    }
}

// Function to print the tasks in the task list
void print_tasks(TaskList* task_list) {
    for (int i = 0; i < task_list->count; i++) {
        Task* task = task_list->tasks[i];
        printf("Task %s (Priority: %d, Deadline: %ld, Status: ", task->name, task->priority, task->deadline);
        switch (task->status) {
            case ACTIVE:
                printf("ACTIVE");
                break;
            case COMPLETED:
                printf("COMPLETED");
                break;
            case PENDING:
                printf("PENDING");
                break;
        }
        printf(")\n");
    }
}

// Function to filter and print pending or completed tasks by deadline
void filter_tasks(TaskList* task_list) {
    for (int i = 0; i < task_list->count; i++) {
        Task* task = task_list->tasks[i];
        if (task->status == PENDING || task->status == COMPLETED) {
            printf("Task %s (Priority: %d, Deadline: %ld)\n", task->name, task->priority, task->deadline);
        }
    }
}

int main() {
    // Create a new task list with initial capacity of 10 tasks
    TaskList* task_list = create_task_list(10);

    // Add some sample tasks to the task list
    add_task(task_list, create_task("Task 1", 3, time(NULL) + 3600, PENDING));
    add_task(task_list, create_task("Task 2", 2, time(NULL) + 7200, COMPLETED));
    add_task(task_list, create_task("Task 3", 1, time(NULL) + 10800, PENDING));

    // Sort the task list by priority and deadline
    sort_task_list(task_list);

    // Print all tasks in the task list
    print_tasks(task_list);

    // Filter and print pending or completed tasks by deadline
    filter_tasks(task_list);

    return 0;
}
