#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the user profile structure
typedef struct {
    int id;
    char username[64];
    char picture_url[256];
    time_t last_seen;
} UserProfile;

// Define the distributed user list structure
typedef struct {
    UserProfile* profiles;
    int size;
    pthread_mutex_t lock;
} UserList;

// Function to create a new user profile
UserProfile* create_profile(int id, const char* username, const char* picture_url) {
    UserProfile* profile = (UserProfile*)malloc(sizeof(UserProfile));
    profile->id = id;
    strcpy(profile->username, username);
    strcpy(profile->picture_url, picture_url);
    return profile;
}

// Function to add a user profile to the list
void addUserList(UserList* list, UserProfile* profile) {
    pthread_mutex_lock(&list->lock);
    list->profiles = (UserProfile*)realloc(list->profiles, (list->size + 1) * sizeof(UserProfile));
    list->profiles[list->size] = *profile;
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

// Function to update a user profile in the list
void updateUserList(UserList* list, int id, const char* username, const char* picture_url) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->size; i++) {
        if (list->profiles[i].id == id) {
            strcpy(list->profiles[i].username, username);
            strcpy(list->profiles[i].picture_url, picture_url);
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to delete a user profile from the list
void deleteUserList(UserList* list, int id) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->size; i++) {
        if (list->profiles[i].id == id) {
            memmove(&list->profiles[i], &list->profiles[i + 1], (list->size - i - 1) * sizeof(UserProfile));
            list->size--;
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to sort the user profiles by last seen timestamp
void sortUserList(UserList* list) {
    pthread_mutex_lock(&list->lock);
    qsort(list->profiles, list->size, sizeof(UserProfile), (int(*)(const void*, const void*))compare_user_profiles);
    pthread_mutex_unlock(&list->lock);
}

// Comparison function for qsort to sort user profiles by last seen timestamp
int compare_user_profiles(const void* a, const void* b) {
    UserProfile* profile1 = *(UserProfile*)a;
    UserProfile* profile2 = *(UserProfile*)b;
    return (profile1->last_seen > profile2->last_seen) - (profile1->last_seen < profile2->last_seen);
}

// Function to serialize the user list to disk
void serializeUserList(UserList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file != NULL) {
        for (int i = 0; i < list->size; i++) {
            fwrite(&list->profiles[i], sizeof(UserProfile), 1, file);
        }
        fclose(file);
    }
}

// Function to deserialize the user list from disk
UserList* deserializeUserList(const char* filename) {
    FILE* file = fopen(filename, "rb");
    UserList* list = (UserList*)malloc(sizeof(UserList));
    if (file != NULL) {
        list->profiles = (UserProfile*)malloc(sizeof(UserProfile));
        int size;
        fread(&size, sizeof(int), 1, file);
        list->size = size;
        for (int i = 0; i < size; i++) {
            fread(&list->profiles[i], sizeof(UserProfile), 1, file);
        }
        fclose(file);
    } else {
        free(list);
        return NULL;
    }
    return list;
}

// Function to monitor the user list size and trigger cleanup when necessary
void monitorUserList(UserList* list) {
    pthread_mutex_lock(&list->lock);
    if (list->size > 1000) { // Set the threshold as needed
        for (int i = 0; i < list->size - 100; i++) {
            deleteUserList(list, i); // Implement the cleanup logic here
        }
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to handle periodic updates of user activity statuses from an external API
void updateActivityStatuses(UserList* list) {
    // Implement the API call and data processing logic here
    // ...
}

int main() {
    UserList* list = (UserList*)malloc(sizeof(UserList));
    pthread_mutex_init(&list->lock, NULL);

    // Add user profiles to the list
    addUserList(list, create_profile(1, "user1", "https://example.com/picture1"));
    addUserList(list, create_profile(2, "user2", "https://example.com/picture2"));

    // Update a user profile
    updateUserList(list, 1, "newusername", "https://example.com/newpicture");

    // Delete a user profile
    deleteUserList(list, 2);

    // Sort the user profiles by last seen timestamp
    sortUserList(list);

    // Serialize and deserialize the user list to/from disk
    serializeUserList(list, "userlist.bin");
    UserList* deserialized_list = deserializeUserList("userlist.bin");

    // Monitor the user list size and trigger cleanup when necessary
    monitorUserList(list);

    // Handle periodic updates of user activity statuses from an external API
    updateActivityStatuses(list);

    return 0;
}
