```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int float_value;
    char string_id[16];
} item;

typedef struct {
    int* int_array;
    item* items;
    size_t array_size, item_count;
} data_block;

data_block* init_data_blocks(size_t num_blocks) {
    data_block* blocks = (data_block*)malloc(num_blocks * sizeof(data_block));
    if (!blocks) return NULL; // memory allocation failed

    for (size_t i = 0; i < num_blocks; i++) {
        size_t array_size = 10 + rand() % 20; // random array size
        blocks[i].int_array = (int*)malloc(array_size * sizeof(int));
        if (!blocks[i].int_array) return NULL; // memory allocation failed

        for (size_t j = 0; j < array_size; j++) {
            blocks[i].int_array[j] = rand() % 100;
        }

        size_t item_count = 5 + rand() % 10; // random number of items
        blocks[i].items = (item*)malloc(item_count * sizeof(item));
        if (!blocks[i].items) return NULL; // memory allocation failed

        for (size_t j = 0; j < item_count; j++) {
            strcpy(blocks[i].items[j].string_id, "unique_string");
            blocks[i].items[j].float_value = (float)(rand() % 10000 / 100.0);
        }

        blocks[i].array_size = array_size;
        blocks[i].item_count = item_count;
    }

    return blocks;
}

void free_data_blocks(data_block* blocks, size_t num_blocks) {
    for (size_t i = 0; i < num_blocks; i++) {
        if (blocks[i].int_array) free(blocks[i].int_array);
        if (blocks[i].items) free(blocks[i].items);
    }
    free(blocks);
}
```
Note that this code assumes a specific structure and naming convention for the data blocks, which may need to be adjusted based on your application's requirements.']

