['Here is the C code for managing a dynamic list of media streams and transcoding tasks in a distributed CDN application:
```c
#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    uint32_t id;
    char metadata[1024];
    struct codec_params *params;
} media_stream;

media_stream *media_streams = NULL;
int stream_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void add_media_stream(media_stream *stream) {
    pthread_mutex_lock(&mutex);
    media_streams = realloc(media_streams, (stream_count + 1) * sizeof(media_stream));
    media_streams[stream_count] = *stream;
    stream_count++;
    pthread_mutex_unlock(&mutex);
}

media_stream *get_media_stream(uint32_t id) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < stream_count; i++) {
        if (media_streams[i].id == id) {
            return &media_streams[i];
        }
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void remove_media_stream(uint32_t id) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < stream_count; i++) {
        if (media_streams[i].id == id) {
            memmove(&media_streams[i], &media_streams[i + 1], (stream_count - i - 1) * sizeof(media_stream));
            stream_count--;
            free(media_streams);
            media_streams = realloc(media_streams, stream_count * sizeof(media_stream));
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

int main() {
    // Initialize the media streams array
    int *stream_ids = (int *)malloc(1024 * sizeof(int));
    uint32_t *timestamps = (uint32_t *)malloc(1024 * sizeof(uint32_t));
    char **file_paths = (char **)malloc(1024 * sizeof(char *));

    // Add media streams
    add_media_stream((media_stream){.id = 1, .metadata = "Stream 1", .params = NULL});
    add_media_stream((media_stream){.id = 2, .metadata = "Stream 2", .params = NULL});
    add_media_stream((media_stream){.id = 3, .metadata = "Stream 3", .params = NULL});

    // Remove a media stream
    remove_media_stream(1);

    return 0;
}
