pthread_cond_t task_queue_cond = PTHREAD_COND_INITIALIZER;
int task_queue_head = 0;
task* task_queue[100];

void enqueue_task(task* t) {
    pthread_mutex_lock(&task_queue_lock);
    task_queue[task_queue_head++] = t;
    pthread_cond_signal(&task_queue_cond);
    pthread_mutex_unlock(&task_queue_lock);
}

task* dequeue_task() {
    task* result = NULL;
    pthread_mutex_lock(&task_queue_lock);
    if (task_queue_head > 0) {
        result = task_queue[0];
        memmove(task_queue, &task_queue[1], (task_queue_head - 1) * sizeof(task));
        task_queue_head--;
    }
    pthread_mutex_unlock(&task_queue_lock);
    return result;
