#include <stdlib.h>
#include <stdio.h>

typedef struct {
    double value;
    short id;
    struct {
        uint64_t timestamp;
        enum { IDLE, BUSY } state;
    } status;
} sensor_t;

typedef struct {
    int size;
    int capacity;
    sensor_t* sensors;
} data_stream_t;

void init_data_stream(data_stream_t* stream) {
    stream->size = 0;
    stream->capacity = 10; // Initial capacity
    stream->sensors = (sensor_t*)malloc(stream->capacity * sizeof(sensor_t));
}

int resize_data_stream(data_stream_t* stream, int new_capacity) {
    sensor_t* old_sensors = stream->sensors;
    stream->sensors = (sensor_t*)realloc(stream->sensors, new_capacity * sizeof(sensor_t));
    if (!stream->sensors) {
        // Handle memory allocation failure
        free(old_sensors);
        return -1; // Failure to resize the data stream
    }
    stream->capacity = new_capacity;
    return 0; // Success in resizing the data stream
}

void add_sensor(data_stream_t* stream, double value, short id) {
    if (stream->size >= stream->capacity) {
        int new_capacity = stream->capacity * 2 + 1; // Increase capacity by a factor of two
        if (resize_data_stream(stream, new_capacity)) {
            // Handle failure to resize the data stream
            return;
        }
    }
    sensor_t* sensor = &stream->sensors[stream->size];
    sensor->value = value;
    sensor->id = id;
    sensor->status.timestamp = 0; // Initialize timestamp
    sensor->status.state = IDLE; // Initialize state
    stream->size++;
}

void remove_sensor(data_stream_t* stream, short id) {
    int i;
    for (i = 0; i < stream->size; i++) {
        if (stream->sensors[i].id == id) {
            // Shift remaining sensors to fill the gap and reset size
            memmove(&stream->sensors[i], &stream->sensors[i + 1], (stream->size - i - 1) * sizeof(sensor_t));
            stream->size--;
            return;
        }
    }
}

void print_sensors(data_stream_t* stream) {
    int i;
    for (i = 0; i < stream->size; i++) {
        printf("Sensor %d: Value = %.2f, ID = %d\n", i + 1, stream->sensors[i].value, stream->sensors[i].id);
    }
}

int main() {
    data_stream_t stream;
    init_data_stream(&stream);

    add_sensor(&stream, 10.5, 1);
    add_sensor(&stream, 20.2, 2);
    add_sensor(&stream, 30.8, 3);

    print_sensors(&stream);

    remove_sensor(&stream, 2);

    print_sensors(&stream);

    return 0;
}
