    int numSets;
    DataSet* sets;
} BatchData;

typedef struct {
    int numBatches;
    BatchData* batches;
} StreamData;

typedef struct {
    // config
    int timeout;
    int retryCount;
    int backoffTime;

    // monitoring
    double latency;
    int cacheSize;
    int connectionPoolSize;
} Config;

// Create a new PDU structure and dynamically allocate memory for it
PDU* createPDU(char* pcGroup, int tcId) {
    PDU* pdu = (PDU*)malloc(sizeof(PDU));
    pdu->pcGroup = strdup(pcGroup);
    pdu->tcId = tcId;
    return pdu;
}

// Create a new Element structure and dynamically allocate memory for it
Element* createElement(double val, char* key) {
    Element* element = (Element*)malloc(sizeof(Element));
    element->val = val;
    element->key = strdup(key);
    return element;
}

// Create a new DataGroup structure and dynamically allocate memory for it
DataGroup* createDataGroup() {
    DataGroup* dataGroup = (DataGroup*)malloc(sizeof(DataGroup));
    dataGroup->head = NULL;
    dataGroup->size = 0;
    return dataGroup;
}

// Add an element to the data group
void addElementToDataGroup(Element* element, DataGroup* dataGroup) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->element = *element;
    newNode->next = dataGroup->head;
    dataGroup->head = newNode;
    dataGroup->size++;
}

// Create a new DataSet structure and dynamically allocate memory for it
DataSet* createDataSet(double val, char* str) {
    DataSet* dataSet = (DataSet*)malloc(sizeof(DataSet));
    dataSet->val = val;
    dataSet->str = strdup(str);
    return dataSet;
}

// Add the data set to the batch data
void addDataSetToBatchData(DataSet* dataSet, BatchData* batchData) {
    batchData->sets = realloc(batchData->sets, (batchData->numSets + 1) * sizeof(DataSet));
    batchData->sets[batchData->numSets] = *dataSet;
    batchData->numSets++;
}

// Create a new StreamData structure and dynamically allocate memory for it
StreamData* createStreamData(int numBatches) {
    StreamData* streamData = (StreamData*)malloc(sizeof(StreamData));
    streamData->numBatches = numBatches;
    streamData->batches = malloc(numBatches * sizeof(BatchData));
    return streamData;
}

// Create a new Config structure and dynamically allocate memory for it
Config* createConfig() {
    Config* config = (Config*)malloc(sizeof(Config));
    config->timeout = 1000; // default timeout in milliseconds
    config->retryCount = 3; // default retry count
    config->backoffTime = 500; // default backoff time in milliseconds
    return config;
}

int main() {
    PDU* pdu1 = createPDU("PCG1", 1);
    PDU* pdu2 = createPDU("PCG2", 2);

    Element* element1 = createElement(1.0, "Key1");
    Element* element2 = createElement(2.0, "Key2");

    DataGroup* dataGroup1 = createDataGroup();
    addElementToDataGroup(element1, dataGroup1);
    addElementToDataGroup(element2, dataGroup1);

    DataSet* dataSet1 = createDataSet(3.14, "String1");
    BatchData* batchData = malloc(sizeof(BatchData));
    batchData->numSets = 1;
    batchData->sets = &dataSet1;

    StreamData* streamData = createStreamData(2);
    addDataSetToBatchData(dataSet1, batchData);

    Config* config = createConfig();

    return 0;
}
