#define RECORDS 1000
#define OFFSET_RANGE 1000000
#define KEY_RANGE 100
#define FLOAT_RANGE 10.0
#define STRING_SIZE 20

typedef struct {
    int key;
    float value;
    char* string;
} record;

record* createRecords(int count) {
    record* records = (record*)malloc(count * sizeof(record));
    if (!records) return NULL; // handle allocation failure

    for (int i = 0; i < count; i++) {
        int key = rand() % KEY_RANGE;
        float value = ((float)rand()) / RAND_MAX * FLOAT_RANGE;
        char* string = (char*)malloc(STRING_SIZE);
        if (!string) return NULL; // handle allocation failure

        strcpy(string, "Record_"); // populate random strings
        strcat(string, itoa(key));

        records[i].key = key;
        records[i].value = value;
        records[i].string = string;
    }

    return records;
}

void writeRecords(record* records, int count) {
    FILE* file = fopen("records.bin", "wb");
    if (!file) return; // handle file failure

    fwrite(&count, sizeof(int), 1, file);
    for (int i = 0; i < count; i++) {
        fwrite(&records[i], sizeof(record), 1, file);
    }

    fclose(file);
}

void readRecords() {
    FILE* file = fopen("records.bin", "rb");
    if (!file) return; // handle file failure

    int count;
    fread(&count, sizeof(int), 1, file);

    record* records = (record*)malloc(count * sizeof(record));
    for (int i = 0; i < count; i++) {
        fread(&records[i], sizeof(record), 1, file);
    }

    fclose(file);
}

int main() {
    srand(time(NULL)); // seed random number generator

    record* records = createRecords(RECORDS);
    if (!records) return -1; // handle allocation failure

    writeRecords(records, RECORDS);

    readRecords();

    for (int i = 0; i < RECORDS; i++) {
        free(records[i].string);
        free(&records[i]);
    }

    free(records);

    return 0;
}
