    if (lookup == NULL) {
        printf("Memory allocation failed\n");
        exit(-1);
    }
    return lookup;
}

int validate_parameters(int records_count, int min_value, int max_value) {
    if (records_count < MIN_RECORDS || records_count > MAX_RECORDS) {
        fprintf(stderr, "Invalid number of records: %d. Must be between 1 and %d.\n", records_count, MAX_RECORDS);
        return -1;
