    offset_array = malloc(sizeof(long)*OFFSET_ARRAY_SIZE);
    key_array = malloc(sizeof(int)*KEY_ARRAY_SIZE);
    lookup_array = malloc(sizeof(lookup_t)*LOOKUP_ARRAY_SIZE);
}
