#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>

#define RECORD_SIZE sizeof(record_t)
#define CACHE_SIZE 1024
#define BLOCK_SIZE 4096

typedef struct {
    int i;
    float f;
    bool b;
} record_t;

record_t* create_dataset(int num_records, int min_int, int max_int, float min_float, float max_float, double threshold) {
    // Create cache
    void* cache = mmap(NULL, CACHE_SIZE * RECORD_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    if (cache == MAP_FAILED) {
        return NULL;
    }

    record_t* records = (record_t*)cache;

    // Initialize records
    for (int i = 0; i < num_records; i++) {
        records[i].i = rand() % (max_int - min_int + 1) + min_int;
        records[i].f = ((double)rand()) / RAND_MAX * (max_float - min_float) + min_float;
        records[i].b = (records[i].f > threshold);
    }

    // Create binary file
    int fd = open("dataset.bin", O_CREAT | O_RDWR, 0666);
    if (fd == -1) {
        munmap(cache, CACHE_SIZE * RECORD_SIZE);
        return NULL;
    }

    // Write records to binary file
    write(fd, &records, num_records * RECORD_SIZE);

    // Close and unmap cache
    close(fd);
    munmap(cache, CACHE_SIZE * RECORD_SIZE);

    return records;
}
