    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(minInt, maxInt);

    std::vector<DataSet> dataSets(numSets);
    for (int i = 0; i < numSets; ++i) {
        dataSets[i].id.resize(setIdLen);
        std::generate(dataSets[i].id.begin(), dataSets[i].id.end(), [this](char& c){c = 'a' + gen() % 26; return c;});

        for (int j = 0; j < vectorSize; ++j) {
            dataSets[i].intVector.push_back(dis(gen));
        }

        dataSets[i].map.reserve(vectorSize);
        for (int k = 0; k < vectorSize; ++k) {
            dataSets[i].map[std::to_string(k)] = dis(gen);
        }

        std::shared_ptr<CustomObject> customObject = std::make_shared<CustomObject>();
