                    std::unique_lock<std::mutex> lock(mtx);
                    cv.wait_for(lock, std::chrono::seconds(1));
                }

                // Process the record
                sensorData_->processRecord(record);

                // Unlock and notify other threads
                lock.unlock();
                cv.notify_all();
            });

            // Notify all threads to start processing the record
            cv.notify_all();
        }
    }
};

int main() {
    int numThreads = 10; // Number of worker nodes
    SensorData sensorData;

    DataProcessor dataProcessor(numThreads, &sensorData);
    dataProcessor.startProcessing();

    return 0;
}
