#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    double value;
    char* str;
} node;

typedef struct {
    node* nodes;
    int num_nodes;
} graph;

void initGraph(graph* g, int num_nodes) {
    g->num_nodes = num_nodes;
    g->nodes = (node*)malloc(num_nodes * sizeof(node));
}

void freeGraph(graph* g) {
    if (g->nodes != NULL) {
        for (int i = 0; i < g->num_nodes; i++) {
            if (g->nodes[i].str != NULL) {
                free(g->nodes[i].str);
            }
        }
        free(g->nodes);
    }
}

void serializeGraph(graph* g, FILE* file) {
    fwrite(&g->num_nodes, sizeof(int), 1, file);
    for (int i = 0; i < g->num_nodes; i++) {
        fwrite(&g->nodes[i].value, sizeof(double), 1, file);
        size_t str_len = strlen(g->nodes[i].str);
        fwrite(&str_len, sizeof(size_t), 1, file);
        fwrite(g->nodes[i].str, sizeof(char), str_len + 1, file);
    }
}

void deserializeGraph(graph* g, FILE* file) {
    int num_nodes;
    fread(&num_nodes, sizeof(int), 1, file);
    initGraph(g, num_nodes);
    for (int i = 0; i < num_nodes; i++) {
        fread(&g->nodes[i].value, sizeof(double), 1, file);
        size_t str_len;
        fread(&str_len, sizeof(size_t), 1, file);
        g->nodes[i].str = malloc(str_len + 1);
        fread(g->nodes[i].str, sizeof(char), str_len + 1, file);
    }
}

int main() {
    srand(time(NULL));
    graph g;
    initGraph(&g, 10);

    for (int i = 0; i < g.num_nodes; i++) {
        g.nodes[i].value = ((double)rand()) / RAND_MAX;
        char buffer[16];
        sprintf(buffer, "node_%d", i);
        g.nodes[i].str = malloc(strlen(buffer) + 1);
        strcpy(g.nodes[i].str, buffer);
    }

    // Serialize and deserialize the graph
    FILE* file = fopen("graph.bin", "wb");
    serializeGraph(&g, file);
    fclose(file);

    file = fopen("graph.bin", "rb");
    deserializeGraph(&g, file);
    fclose(file);

    for (int i = 0; i < g.num_nodes; i++) {
        printf("Node %d: value = %.2f, str = %s\n", i, g.nodes[i].value, g.nodes[i].str);
    }

    freeGraph(&g);

    return 0;
}
