#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Custom binary format for persistent storage
typedef struct {
    int type;
    union {
        char *str;
        int num;
        void *data;
    } payload;
} Payload;

typedef struct {
    time_t timestamp;
    int clientId;
    Payload payload;
} Request;

typedef struct {
    int requestId;
    Request requests[];
} Session;

// Dynamic pool of session objects
sessionPool {
    int size; // Current number of sessions
    int capacity; // Maximum number of sessions
    session* sessions; // Array of session structures
};

// Function to manage the dynamic pool of sessions
int initSessionPool(int initialCapacity) {
    sessionPool = (sessionPool*)malloc(sizeof(sessionPool));
    if (!sessionPool) return -1;

    sessionPool->size = 0;
    sessionPool->capacity = initialCapacity;
    sessionPool->sessions = (session*)malloc(initialCapacity * sizeof(session));

    return 0;
}

// Function to add a new session
int addSession() {
    // Check if the pool needs to be resized
    if (sessionPool->size >= sessionPool->capacity) {
        int newCapacity = sessionPool->capacity + 16; // Example: increase capacity by 16%
        session* newSessions = (session*)realloc(sessionPool->sessions, newCapacity * sizeof(session));
        if (!newSessions) return -1;

        sessionPool->sessions = newSessions;
        sessionPool->capacity = newCapacity;
    }

    // Create a new session structure
    Session* newSession = &sessionPool->sessions[sessionPool->size++];
    newSession->requests = (Request*)malloc(16 * sizeof(Request)); // Example: initial capacity for requests

    return 0;
}

// Function to process a request
int processRequest(int sessionId, Request* request) {
    Session* session = &sessionPool->sessions[sessionId];

    // Check if the session exists and has available space for the request
    if (session && session->requests->size < session->capacity) {
        // Add the request to the session's list of requests
        memcpy(&session->requests[requestId], request, sizeof(Request));

        return 0;
    }

    return -1;
}

// Function to free the dynamic pool of sessions
void freeSessionPool() {
    for (int i = 0; i < sessionPool->size; i++) {
        Session* session = &sessionPool->sessions[i];
        if (session) {
            free(session->requests);
            free(session);
        }
    }

    free(sessionPool->sessions);
    free(sessionPool);

    sessionPool = NULL;
}
