// Define asynchronous HTTP client
async fn make_request(url: &str) -> Result<String, Box<dyn Error>> {
    let client = Client::new();
    let response = client.get(url).send().await?;

    Ok(response.text().await?)
}

// Define connection pooling and multiplexing
async fn issue_requests(urls: Vec<&str>) -> Result<(), Box<dyn Error>> {
    for url in urls {
