    int performance_metrics;
    int system_health;
} MonitoringObject;

// Function to dynamically allocate memory for and initialize data structures
DataStruct* create_data_struct(int id) {
    DataStruct* ds = (DataStruct*)malloc(sizeof(DataStruct));
    ds->float_data = rand() / (double)RAND_MAX;
    char buffer[32];
    sprintf(buffer, "key_%d", id);
    ds->string_key = malloc(strlen(buffer) + 1);
    strcpy(ds->string_key, buffer);
    return ds;
}

// Function to create a data group
DataGroup* create_data_group(int size) {
    DataGroup* dg = (DataGroup*)malloc(sizeof(DataGroup));
    dg->count = size;
    dg->elements = malloc(size * sizeof(DataStruct*));
    for (int i = 0; i < size; i++) {
        dg->elements[i] = create_data_struct(i);
    }
    return dg;
}

// Function to create a batch of data
BatchData* create_batch_data(int size) {
    BatchData* bd = (BatchData*)malloc(sizeof(BatchData));
    bd->count = size;
    bd->sets = malloc(size * sizeof(DataSet*));
