        char buffer[32];
        sprintf(buffer, "string_%d", i);
        ds->string_key = malloc(strlen(buffer) + 1);
        strcpy(ds->string_key, buffer);
        ds->group = create_data_group(i);
        bd->sets[i] = ds;
    }
    return bd;
}

// Function to create a stream of data
StreamData* create_stream_data(int size) {
    StreamData* sd = (StreamData*)malloc(sizeof(StreamData));
    sd->size = size;
    sd->data_sets = malloc(size * sizeof(DataSet*));
    for (int i = 0; i < size; i++) {
        // Create a data set
        DataSet* ds = (DataSet*)malloc(sizeof(DataSet));
        ds->float_data = rand() / (double)RAND_MAX;
        char buffer[32];
        sprintf(buffer, "string_%d", i);
        ds->string_key = malloc(strlen(buffer) + 1);
        strcpy(ds->string_key, buffer);
        ds->group = create_data_group(i);
        sd->data_sets[i] = ds;
    }
    return sd;
}

// Function to free memory for data structures
void free_data_structs(DataStruct* ds, int size) {
    for (int i = 0; i < size; i++) {
        free(ds[i].string_key);
        free(ds[i]);
    }
    free(ds);
}

// Function to free memory for a data group
void free_data_group(DataGroup* dg, int size) {
    for (int i = 0; i < size; i++) {
        free_data_structs(dg->elements[i], dg->count);
    }
    free(dg->elements);
    free(dg);
}

// Function to free memory for a batch of data
void free_batch_data(BatchData* bd, int size) {
    for (int i = 0; i < size; i++) {
        // Free the data set and its group
        DataSet* ds = bd->sets[i];
        free(ds->string_key);
        free(ds->group->elements);
        free(ds->group);
        free(ds);
    }
    free(bd->sets);
    free(bd);
}

// Function to free memory for a stream of data
void free_stream_data(StreamData* sd, int size) {
    for (int i = 0; i < size; i++) {
        // Free the data set and its group
        DataSet* ds = sd->data_sets[i];
        free(ds->string_key);
        free(ds->group->elements);
        free(ds->group);
        free(ds);
    }
    free(sd->data_sets);
    free(sd);
}

int main() {
    // Create a batch of data
    BatchData* bd = create_batch_data(5);

    // Free the memory for the batch
    free_batch_data(bd, 5);

    return 0;
}
