use reqwest::blocking::{get, ClientBuilder};
use std::sync::{Arc, Mutex};
use chrono::prelude::*;

mod async_http_client {
    use actix_web::http::header;
    use futures::stream;
    use reqwest::blocking::{get, ClientBuilder};

    #[derive(Debug)]
    pub struct HttpClient {
        client: Arc<Mutex<ClientBuilder>>,
    }

    impl HttpClient {
        pub fn new() -> Self {
            let client = Arc::new(Mutex::new(ClientBuilder::new()));
            HttpClient { client }
        }

        pub async fn get(&self, url: &str) -> Result<reqwest::blocking::Response, reqwest::Error> {
            let mut client = self.client.lock().unwrap();
            client = client.timeout(5000); // 5 seconds
            let response = get(url).send()?;
            Ok(response)
        }
    }
}

mod async_file_transfer {
    use futures::stream;
    use std::fs::{File, OpenOptions};
    use std::path::Path;

    pub struct FileTransfer {
        file: Arc<Mutex<File>>,
    }

    impl FileTransfer {
        pub fn new(file_path: &str) -> Self {
            let file = Arc::new(Mutex::new(OpenOptions::new()
                .read(true)
                .open(Path::new(file_path))?
            ));
            FileTransfer { file }
        }

        pub async fn transfer(&self, url: &str) -> Result<(), reqwest::Error> {
