        records[i].value = rand() % (MAX - MIN + 1) + MIN;
    }

    // Check if the Java library is available before calling the generateMD5Hash method
    JNIEnv* env = NULL;
    jint retcode = (*JavaDetachCurrentThread)(env);
    if (retcode != JNI_OK) {
        printf("Error detaching current thread.\n");
        return -1;
    }

    // Convert input string to UTF-8 encoded bytes
    jstring javaString = (*env)->NewStringUTF(env, inputString);

    // Check for Java exceptions
    jobjectArray result = (jobjectArray)(*env)->CallObjectMethod(env, generateMD5HashMethod, javaString);
    if (result == NULL) {
        printf("Error generating MD5 hash.\n");
        return -1;
    }

    // Clean up and return the result
    (*env)->DeleteLocalRef(env, javaString);
    free(offsets);
    free(keys);
