void init_tasks() {
    if (tasks != NULL) {
        free(tasks);
    }
    tasks = NULL;
    task_count = 0;
}

task* add_task(const char* name, int priority) {
    task* new_task = (task*)malloc(sizeof(task));
    new_task->name = strdup(name);
    new_task->priority = priority;
    new_task->status = TODO;
    tasks = realloc(tasks, sizeof(task) * ++task_count);
    tasks[task_count - 1] = new_task;
    return new_task;
}

void remove_task(int index) {
    if (index >= task_count || index < 0) {
        printf("Invalid task index\n");
        return;
    }
    free(tasks[index]->name);
    free(tasks[index]);
    memmove(&tasks[index], &tasks[index + 1], sizeof(task) * (task_count - index - 1));
    task_count--;
}

void update_task(int index, const char* name, int priority, task_status status) {
    if (index >= task_count || index < 0) {
        printf("Invalid task index\n");
        return;
    }
    free(tasks[index]->name);
    tasks[index]->name = strdup(name);
    tasks[index]->priority = priority;
    tasks[index]->status = status;
}

void sort_tasks() {
    int i, j;
    for (i = 0; i < task_count - 1; i++) {
        for (j = i + 1; j < task_count; j++) {
            if (tasks[i]->priority > tasks[j]->priority) {
                task* temp = tasks[i];
                tasks[i] = tasks[j];
                tasks[j] = temp;
            }
        }
    }
}

