// Asynchronous message queue system functions
void message_queue_init(message_queue_t* q, int size) {
    q->size = size;
    q->head = 0;
    q->tail = 0;
    q->messages = (void**)malloc(size * sizeof(void*));
    pthread_mutex_init(&q->lock, NULL);
    pthread_cond_init(&q->cond, NULL);
}

int message_queue_enqueue(message_queue_t* q, void* msg) {
    int ret = -1;
    pthread_mutex_lock(&q->lock);
    if (q->tail == q->size) {
        // Queue is full, handle error...
    } else {
        q->messages[q->tail] = msg;
        (q->tail)++;
        ret = 0;
    }
    pthread_mutex_unlock(&q->lock);
    return ret;
}

void* message_queue_dequeue(message_queue_t* q) {
    void* ret = NULL;
    pthread_mutex_lock(&q->lock);
    if (q->head == q->tail) {
        // Queue is empty, handle error...
    } else {
        ret = q->messages[q->head];
        (q->head)++;
    }
    pthread_mutex_unlock(&q->lock);
    return ret;
}

int main() {
    // Create a multi-threaded environment
    int num_threads = 4;
    pthread_t threads[num_threads];

