        records[i].key = rand() % MAX_INT_VALUE;
        records[i].value = (double)rand() / RAND_MAX * MAX_DOUBLE_VALUE;
    }

    return records;
}

void* write_records(void* arg) {
    int count = RECORDS;
    record_t* records = init_records(count);

    if (!records) {
        pthread_exit(NULL);
    }

    FILE* file = fopen("records.bin", "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file\n");
        free(records);
        pthread_exit(NULL);
    }

    fwrite(&count, sizeof(int), 1, file);
    fwrite(records, sizeof(record_t), count, file);

    fclose(file);
    free(records);
    pthread_exit(NULL);
}

int main() {
