void* allocate_array(int size, size_t element_size) {
    void* ptr = malloc(size * element_size);
    if (ptr == NULL) {
        // Handle memory allocation failure
        printf("Memory allocation failed.\n");
        return NULL;
    }
    return ptr;
}

int main() {
    int num_records = 1000; // Change this value as needed

    // Allocate array of OffsetRecord
    OffsetRecord* offset_records = (OffsetRecord*) allocate_array(num_records, sizeof(OffsetRecord));
    if (offset_records == NULL) return -1;

    // Initialize each OffsetRecord to zero
    for (int i = 0; i < num_records; i++) {
        offset_records[i].offset = 0;
    }

    // Allocate array of KeyRecord
    int max_key = 1000000; // Change this value as needed
    int key_range = 1000; // Change this value as needed
    KeyRecord* key_records = (KeyRecord*) allocate_array(max_key, sizeof(KeyRecord));
    if (key_records == NULL) return -1;

    // Initialize each KeyRecord with random keys without duplicates
    for (int i = 0; i < max_key; i++) {
        int new_key;
        do {
            new_key = rand() % key_range + 1;
        } while (new_key <= i); // Ensure no duplicate keys
        key_records[i].key = new_key;
    }

    // Allocate array of Record
    int record_count = num_records * key_range; // Change this value as needed
    Record* records = (Record*) allocate_array(record_count, sizeof(Record));
    if (records == NULL) return -1;

    // Initialize each Record with random values within a specified range
    for (int i = 0; i < record_count; i++) {
        int new_value = rand() % 1000 + 1;
        records[i].value = new_value;
    }

    // Free allocated memory
    free(offset_records);
    free(key_records);
    free(records);

    return 0;
}
