class ImageProcessorCache {
public:
    ImageProcessorCache(size_t cacheSize) : cache_(cacheSize), lastAccessTime_(nullptr) {}

    void put(const std::string& key, const std::shared_ptr<void>& value) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (lastAccessTime_) {
            cache_.erase(lastAccessTime_);
            lastAccessTime_ = nullptr;
        }
        cache_[key] = value;
    }

    std::shared_ptr<void> get(const std::string& key) {
        std::unique_lock<std::shared_mutex> lock(mutex_, std::defer_lock);
        auto it = cache_.find(key);
        if (it != cache_.end()) {
            // Update last access time
            lastAccessTime_ = &it->first;
            return it->second;
        }
        return nullptr;
    }

private:
    struct CacheEntry {
        size_t timestamp;
        std::shared_ptr<void> value;
    };

    std::mutex mutex_;
    std::shared_mutex sharedMutex_;
    std::unordered_map<std::string, CacheEntry> cache_;
    std::weak_ptr<std::string> lastAccessTime_;

    // Helper functions
    void invalidate(size_t timeout) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (lastAccessTime_.expired()) return;
        auto it = cache_.find(lastAccessTime_.lock());
        if (it != cache_.end()) {
            cache_.erase(it);
            lastAccessTime_ = nullptr;
        }
    }

    // Synchronization mechanism for concurrent access
    void synchronize() {
        std::unique_lock<std::mutex> lock(mutex_);
        std::cv_status status = cv_.wait_for(lock, std::chrono::milliseconds(10));
        if (status == std::cv_status::timeout) {
