record* allocate_records(int num_records) {
    return (record*)malloc(num_records * sizeof(record));
}

void serialize_records(const record* records, int num_records, FILE* file) {
    fwrite(&num_records, sizeof(int), 1, file);
    for (int i = 0; i < num_records; i++) {
        fwrite(&records[i].offset, sizeof(long), 1, file);
        fwrite(&records[i].key, sizeof(int), 1, file);
        fwrite(&records[i].value, sizeof(float), 1, file);
    }
}

record* deserialize_records(FILE* file) {
    int num_records;
    fread(&num_records, sizeof(int), 1, file);
    record* records = (record*)malloc(num_records * sizeof(record));
    for (int i = 0; i < num_records; i++) {
        fread(&records[i].offset, sizeof(long), 1, file);
        fread(&records[i].key, sizeof(int), 1, file);
        fread(&records[i].value, sizeof(float), 1, file);
    }
    return records;
}

void* thread_safe_function(void* arg) {
    // Perform thread-safe operations
    return NULL;
}

int main() {
    pthread_t threads[5];
    for (int i = 0; i < 5; i++) {
        pthread_create(&threads[i], NULL, thread_safe_function, NULL);
    }

