#include <pthread.h>

#define MAX_STREAMS 1000
#define MAX_RECORDS 10000
#define RANGE_MIN 10
#define RANGE_MAX 50

typedef struct {
    int sampling_rate;
    int bit_depth;
    int channel_config;
} audio_stream;

typedef struct record {
    int value;
    struct record* next;
} record;

audio_stream streams[MAX_STREAMS];
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
record* records[MAX_RECORDS] = {0};

void* add_record(void* arg) {
    int stream_id = *((int*)arg);
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (!records[i]) {
            record* new_rec = malloc(sizeof(record));
            new_rec->value = rand() % (RANGE_MAX - RANGE_MIN + 1) + RANGE_MIN;
            new_rec->next = NULL;
            records[i] = new_rec;
            break;
        }
    }
    return NULL;
}

void print_stream(int stream_id) {
    pthread_mutex_lock(&mutex);
    audio_stream* current_stream = &streams[stream_id];
    printf("Stream %d: sampling_rate=%d, bit_depth=%d, channel_config=%d\n", 
           stream_id, current_stream->sampling_rate, current_stream->bit_depth, current_stream->channel_config);

    for (int i = 0; i < MAX_RECORDS; i++) {
        if (records[i]) {
            record* current_rec = records[i];
            printf("Record %d: %d\n", i, current_rec->value);
            free(current_rec);
            break;
        }
    }

    pthread_mutex_unlock(&mutex);
}

void remove_stream(int stream_id) {
    pthread_mutex_lock(&mutex);
    audio_stream* current_stream = &streams[stream_id];
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (records[i]) {
            record* current_rec = records[i];
            free(current_rec);
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

int main() {
    pthread_t threads[MAX_STREAMS];

    for (int i = 0; i < MAX_STREAMS; i++) {
        pthread_create(&threads[i], NULL, add_record, &i);
    }

    // Simulate adding records
    sleep(2);

    // Print streams and records
    for (int i = 0; i < MAX_STREAMS; i++) {
        print_stream(i);
        remove_stream(i);
    }

    return 0;
}
