    if (!*offsets) return; // handle error

    *keys = (int*)calloc(size, sizeof(int));
    if (!*keys) { free(*offsets); return; } // handle error

    *records = (Record**)calloc(size, sizeof(Record*));
    if (!*records) { free(*offsets); free(*keys); return; } // handle error

    for (int i = 0; i < size; i++) {
        (*records)[i] = (Record*)malloc(sizeof(Record));
        if (!(*records)[i]) { // handle error
            while (i > 0) {
                free((*records[--i])->str);
                free((*records[i])->str);
                free((*records[i]));
            }
            free(*offsets);
            free(*keys);
            return;
        }

        (*records)[i]->value = set_value(i, external_data[i] ? external_data[i] : "", i * 1.0); // handle error
        (*records)[i]->str = (char*)malloc(strlen(external_data[i]) + 1);
        if (!(*records)[i]->str) { // handle error
            free((*records[i])->str);
            free((*records[i]));
