public:
    static std::unique_ptr<Configuration> createConfig(int maxSections, int minSectionId, int maxSectionId,
                                                         int minSettingNameLength, int maxSettingNameLength,
                                                         double minSettingValue, double maxSettingValue);

private:
    // Helper functions to handle memory allocation failures
    void releaseResources();

    // Third-party logging library for auditing configuration changes
    void logConfigurationChange(Configuration& config);
};

std::unique_ptr<Configuration> ConfigurationManager::createConfig(int maxSections, int minSectionId, int maxSectionId,
                                                                 int minSettingNameLength, int maxSettingNameLength,
                                                                 double minSettingValue, double maxSettingValue) {
    try {
        // Allocate memory for the configuration object
        std::unique_ptr<Configuration> config = std::make_unique<Configuration>(minSectionId);

        // Initialize settings and version number
        config->settings.reserve(maxSections);
        for (int i = 0; i < maxSections; ++i) {
            int sectionId = minSectionId + i;
            if (sectionId > maxSectionId) break;

            std::string settingName = "Setting_" + std::to_string(i);
            double settingValue = minSettingValue + (maxSettingValue - minSettingValue) * (double)i / (maxSections - 1);

            config->settings[settingName] = settingValue;
        }

        config->version = maxSections;

        // Log configuration changes
        logConfigurationChange(*config.get());

        return std::move(config);
    } catch (...) {
        // Release resources in case of memory allocation failure
        releaseResources();
        throw;
    }
}

