// Define a record structure
typedef struct {
    int key;
} Record;

// Function to manage memory for records
Record* allocateRecords(int count) {
    Record* records = (Record*)malloc(count * sizeof(Record));
    if (!records) {
        return NULL; // Handle memory allocation error
    }
    return records;
}

// Function to deallocate record memory
void freeRecords(Record* records, int count) {
    if (records) {
        free(records);
    }
}

// Function to initialize records with random values within a specified range
void initRecords(Record* records, int count, int minVal, int maxVal) {
    srand(time(NULL));
    for (int i = 0; i < count; i++) {
        records[i].key = rand() % (maxVal - minVal + 1) + minVal;
    }
}

// Function to sort records based on their keys
void sortRecords(Record* records, int count) {
    qsort(records, count, sizeof(Record), compareRecords);
}

// Comparison function for qsort()
int compareRecords(const void* a, const void* b) {
    Record* rec1 = (Record*)a;
    Record* rec2 = (Record*)b;
    return (rec1->key - rec2->key);
}

// Function to persist records to file system
void writeRecordsToFile(Record* records, int count, char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        return; // Handle file I/O error
    }
    fwrite(records, sizeof(Record), count, file);
    fclose(file);
}

int main() {
    int count = 1000;
    Record* records = allocateRecords(count);
    initRecords(records, count, 1, 100);
    sortRecords(records, count);
    writeRecordsToFile(records, count, "records.bin");
    freeRecords(records, count);
    return 0;
}
