#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int key;
    double weight;
} value;

typedef struct node {
    value* values;
    int count;
    double total_weight;
    struct node* next;
} node;

node* create_node();
void add_value(node**, value*, double*);
double get_total_weight(node**);
int hash_function(int, int);

// Function to create a new node
node* create_node() {
    node* n = (node*)malloc(sizeof(node));
    n->values = NULL;
    n->count = 0;
    n->total_weight = 0.0;
    n->next = NULL;
    return n;
}

// Function to add a value to a node
void add_value(node** nodes, value* val, double* total_weight) {
    int index = hash_function(val->key, 10000);
    node* current = nodes[index];
    while (current) {
        if (!current->values || current->count < 10) {
            // Allocate memory for the new value
            value* new_val = (value*)malloc(sizeof(value));
            memcpy(new_val, val, sizeof(value));

            // Add the new value to the node's list
            new_val->next = current->values;
            current->values = new_val;

            current->count++;
            current->total_weight += val->weight;
            *total_weight += val->weight;
            return;
        }
        current = current->next;
    }

    // If no suitable node is found, create a new one
    node* new_node = create_node();
    value* new_val = (value*)malloc(sizeof(value));
    memcpy(new_val, val, sizeof(value));
    new_val->next = new_node->values;
    new_node->values = new_val;

    new_node->count++;
    new_node->total_weight += val->weight;
    *total_weight += val->weight;

    // Add the new node to the hash table
    nodes[index] = new_node;
}

// Function to get the total weight of all values across all nodes
double get_total_weight(node** nodes) {
    double total_weight = 0.0;
    for (int i = 0; i < 10000; i++) {
        node* current = nodes[i];
        while (current) {
            total_weight += current->total_weight;
            current = current->next;
        }
    }
    return total_weight;
}

// Hash function to distribute values across nodes
int hash_function(int key, int max_nodes) {
    return key % max_nodes;
}
