#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the status flag enum
typedef enum {
    ONLINE,
    OFFLINE,
    UNKNOWN
} sensor_status;

// Define a structure to hold sensor data
typedef struct {
    long timestamp;
    float reading;
    sensor_status status;
} sensor_data;

// Define a structure to manage memory for sensor data
typedef struct {
    int capacity;
    int size;
    sensor_data* entries;
    pthread_mutex_t lock;
} sensor_memory;

// Initialize the sensor memory manager
sensor_memory* init_sensor_memory(int capacity) {
    sensor_memory* mem = (sensor_memory*)malloc(sizeof(sensor_memory));
    mem->capacity = capacity;
    mem->size = 0;
    mem->entries = (sensor_data*)calloc(capacity, sizeof(sensor_data));
    pthread_mutex_init(&mem->lock, NULL);
    return mem;
}

// Add a new sensor data entry
void add_sensor_entry(sensor_memory* mem, long timestamp, float reading, sensor_status status) {
    pthread_mutex_lock(&mem->lock);
    if (mem->size >= mem->capacity) {
        // Handle memory allocation failure
        printf("Memory full. Cannot add new entry.\n");
        return;
    }
    mem->entries[mem->size].timestamp = timestamp;
    mem->entries[mem->size].reading = reading;
    mem->entries[mem->size].status = status;
    (mem->size)++;
    pthread_mutex_unlock(&mem->lock);
}

// Retrieve a sensor data entry
void get_sensor_entry(sensor_memory* mem, int index, long* timestamp, float* reading, sensor_status* status) {
    pthread_mutex_lock(&mem->lock);
    if (index >= mem->size || index < 0) {
        printf("Invalid entry index.\n");
        return;
    }
    *timestamp = mem->entries[index].timestamp;
    *reading = mem->entries[index].reading;
    *status = mem->entries[index].status;
    pthread_mutex_unlock(&mem->lock);
}

// Delete a sensor data entry
void delete_sensor_entry(sensor_memory* mem, int index) {
    pthread_mutex_lock(&mem->lock);
    if (index >= mem->size || index < 0) {
        printf("Invalid entry index.\n");
        return;
    }
    for (int i = index; i < mem->size - 1; i++) {
        mem->entries[i] = mem->entries[i + 1];
    }
    (mem->size]--;
    pthread_mutex_unlock(&mem->lock);
}

// Print all sensor data entries
void print_sensor_data(sensor_memory* mem) {
    pthread_mutex_lock(&mem->lock);
    for (int i = 0; i < mem->size; i++) {
        printf("Timestamp: %ld, Reading: %.2f, Status: %s\n", mem->entries[i].timestamp, mem->entries[i].reading, ((mem->entries[i].status == ONLINE) ? "Online" : (mem->entries[i].status == OFFLINE) ? "Offline" : "Unknown"));
    }
    pthread_mutex_unlock(&mem->lock);
}

// Define a function to log errors and operations
void log_operation(const char* message) {
    // Implement logging functionality here
}
