// Define the event structure
typedef struct {
    long timestamp;
    double measurement;
    int type;
} Event;

// Define the hash table structure
typedef struct {
    int* keys;
    int* values;
    int size;
    int capacity;
} HashTable;

// Initialize and populate data structures for events management
int initialize_events_management(int initial_capacity, int growth_rate) {
    srand(time(NULL));

    // Initialize array of offset values
    long* offsets = (long*)malloc(initial_capacity * sizeof(long));
    if (!offsets) return -1;  // Handle memory allocation error

    // Initialize hash table for fast lookups
    HashTable* events_by_type = (HashTable*)malloc(sizeof(HashTable));
    events_by_type->keys = (int*)malloc(initial_capacity * sizeof(int));
    events_by_type->values = (int*)malloc(initial_capacity * sizeof(int));
    events_by_type->size = 0;
    events_by_type->capacity = initial_capacity;
    if (!events_by_type->keys || !events_by_type->values) {
        free(offsets);
        return -1;  // Handle memory allocation error
    }

    // Initialize linked list of event objects
    Event** events = (Event**)malloc(initial_capacity * sizeof(Event*));
    if (!events) {
        free(offsets);
        free(events_by_type->keys);
        free(events_by_type->values);
        return -1;  // Handle memory allocation error
    }

    // Initialize binary tree for sorting and retrieval
    EventNode** tree = (EventNode**)malloc(initial_capacity * sizeof(EventNode*));
    if (!tree) {
        free(offsets);
        free(events_by_type->keys);
        free(events_by_type->values);
        free(events);
        return -1;  // Handle memory allocation error
    }

    int num_events = 0;
    double total_measurement_sum = 0.0;
    double avg_measurement_per_event_type[10];  // Initialize with zeros

    for (int i = 0; i < initial_capacity; i++) {
        Event* event = (Event*)malloc(sizeof(Event));
        if (!event) return -1;  // Handle memory allocation error

        event->timestamp = rand() % 10000000;
        event->measurement = (double)rand() / RAND_MAX;
        int type = rand() % 10;

        // Validate timestamp-measurement pairs against event type constraints
        if (type == 0 && event->timestamp < 5000000) {
            free(event);
            continue;  // Skip invalid events
        } else if (type > 1 && event->measurement > 5.0) {
            free(event);
            continue;  // Skip invalid events
        }

        // Add event to linked list and binary tree
        events[i] = event;
        tree[i] = event;

        num_events++;
        total_measurement_sum += event->measurement;
        avg_measurement_per_event_type[type]++;
    }

    // Update hash table with event types
    for (int i = 0; i < initial_capacity; i++) {
        events_by_type->keys[events_by_type->size] = events[i]->type;
        events_by_type->values[events_by_type->size++] = i;
    }

    printf("Initialized %d events with total measurement sum %.2f and average measurement per event type:\n", num_events, total_measurement_sum);
    for (int i = 0; i < 10; i++) {
        printf("%.2f ", avg_measurement_per_event_type[i]);
    }
    printf("\n");

    // Return the number of successfully initialized events
    return num_events;
}

// Free all allocated memory after use
void free_events_management(int num_events) {
    for (int i = 0; i < num_events; i++) {
        free(events[i]);
    }

    free(events);
    free(tree);
    free(events_by_type->keys);
    free(events_by_type->values);
    free(events_by_type);

    printf("Memory freed successfully.\n");
}

int main() {
    int initial_capacity = 100000;
    int growth_rate = 2;

    int num_events = initialize_events_management(initial_capacity, growth_rate);

    if (num_events < 0) {
        // Handle memory allocation error
        printf("Error allocating memory. Exiting...\n");
        return -1;
    }

    // Query the number of successfully initialized events and their total measurement sum
    printf("Number of events: %d\n", num_events);
    double total_measurement_sum = totalMeasurementSum(num_events);
    printf("Total measurement sum: %.2f\n", total_measurement_sum);

    // Query the average measurement value per event type
    double avg_measurement_per_event_type[10];
    for (int i = 0; i < 10; i++) {
        double sum = 0.0;
        int count = 0;
        for (Event* event : events) {
            if (event->type == i) {
                sum += event->measurement;
                count++;
            }
        }
        avg_measurement_per_event_type[i] = sum / count;
    }

    // Print average measurement values per event type
    printf("Average measurement per event type:\n");
    for (int i = 0; i < 10; i++) {
        printf("%.2f ", avg_measurement_per_event_type[i]);
    }
    printf("\n");

    free_events_management(num_events);

    return 0;
}

