        events[i].device_id = rand() % 10000;
        events[i].temperature = (double)(rand() % 170.0 - 50.0);
        events[i].priority = (priority_levels)((rand() % 3) + 1);
        events[i].status = (status_flags)((rand() % 4) + 1);
        events[i].timestamp = time(NULL);
