};

// Class representing a user profile entry
class UserProfileEntry {
public:
    UserProfileEntry(int userId, const std::string& userName, const std::string& userEmail, const std::string& userPhoneNumber, AccountMetadata metadata)
        : userId_(userId), userName_(userName), userEmail_(userEmail), userPhoneNumber_(userPhoneNumber), metadata_(metadata) {}

    int getUserId() const { return userId_; }
    const std::string& getUserName() const { return userName_; }
    const std::string& getUserEmail() const { return userEmail_; }
    const std::string& getUserPhoneNumber() const { return userPhoneNumber_; }
    AccountMetadata getMetadata() const { return metadata_; }

private:
    int userId_;
    std::string userName_;
    std::string userEmail_;
    std::string userPhoneNumber_;
    AccountMetadata metadata_;
};

// Class managing user profiles
class UserProfileManager {
public:
    UserProfileManager();

    // Initialize the profile manager
    void initialize();

    // Add a new user profile entry
    void addUserProfileEntry(const UserProfileEntry& entry);

    // Retrieve a user profile entry by ID
    std::shared_ptr<UserProfileEntry> getUserProfileEntry(int userId) const;

private:
    // Map of user profiles, where each key is a unique user ID
    std::map<int, std::shared_ptr<UserProfileEntry>> userProfileMap_;
    mutable std::mutex mutex_; // Mutex for thread-safe access

    // Custom allocator for memory management (optional)
    class UserProfileAllocator {
    public:
        void* allocate(size_t size) { return ::operator new(size); }
        void deallocate(void* ptr, size_t size) { ::operator delete(ptr); }
    } profileAllocator_;
};

// Implementation of the UserProfileManager class
UserProfileManager::UserProfileManager() : mutex_{} {}

void UserProfileManager::initialize() {
    // Initialize any necessary resources or data structures
}

void UserProfileManager::addUserProfileEntry(const UserProfileEntry& entry) {
    std::lock_guard<std::mutex> lock(mutex_);
    userProfileMap_[entry.getUserId()] = std::make_shared<UserProfileEntry>(entry);
}

std::shared_ptr<UserProfileEntry> UserProfileManager::getUserProfileEntry(int userId) const {
    std::lock_guard<std::mutex> lock(mutex_);
    auto it = userProfileMap_.find(userId);
    if (it == userProfileMap_.end()) {
        return nullptr; // User profile entry not found
    }
    return it->second;
}

