#include <iostream>
#include <vector>
#include <string>
#include <random>
#include <memory>
#include <mutex>

struct Product {
    std::string name;
    double price;
    std::vector<int> inventory;
};

struct Order {
    std::string id;
    double totalAmount;
    std::shared_ptr<Product> product;
};

std::vector<Order> allocateAndInitializeProducts(int numProducts, int minPrice, int maxPrice) {
    std::vector<Order> products;

    for (int i = 0; i < numProducts; ++i) {
        Product* product = new Product();

        // Generate random name
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_real_distribution<double> dis(1.0, 10.0);
        std::string productName = "Product_" + std::to_string(i);

        product->name = productName;
        product->price = dis(gen) * (maxPrice - minPrice) + minPrice;

        // Initialize inventory levels
        for (int j = 0; j < 5; ++j) {
            product->inventory.push_back((int)(dis(gen) * 100));
        }

        Order order;
        order.id = "Order_" + std::to_string(i);
        order.totalAmount = 1.0;
        order.product = std::make_shared<Product>(*product);

        products.push_back(order);
    }

    return products;
}

void deallocateProducts(std::vector<Order>& products) {
    for (auto& product : products) {
        delete product.product.get();
    }
}
