    int i;
    for(i = 0; i < num_sets; i++) {
        data_set* set = (data_set*)malloc(sizeof(data_set));
        pthread_mutex_lock(&mutex);
        set->d = rand() / (double)RAND_MAX;
        set->s = (char*)malloc(strlen("set_") + strlen("/thread_") + 10);
        sprintf(set->s, "set_%d_thread_%d", i, getpid());
        set->e = (element*)malloc(sizeof(element));
        set->e->f = rand() / (double)RAND_MAX;
        set->e->s = (char*)malloc(strlen("elem_") + strlen("/thread_") + 10);
        sprintf(set->e->s, "elem_%d_thread_%d", i, getpid());
        pthread_mutex_unlock(&mutex);
    }
    return (data_set**)malloc(sizeof(data_set*) * num_sets);
}
