#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct SensorData {
    double temperature;
    time_t timestamp;
    int qualityFlag;
    int identifier;
} SensorData;

SensorData* sensorDataArray = NULL;
int sensorDataCount = 0;
long long offsetValues[1000000];
int identifiers[1000000];

void initSensorData(int numSensors) {
    // Initialize arrays
    for (int i = 0; i < numSensors; i++) {
        offsetValues[i] = rand() % 1000000;
        identifiers[i] = rand() % 10000 + 1;
    }

    // Create and initialize the sensor data array
    sensorDataArray = malloc(numSensors * sizeof(SensorData));
    for (int i = 0; i < numSensors; i++) {
        sensorDataArray[i].temperature = 0.0;
        sensorDataArray[i].timestamp = time(NULL);
        sensorDataArray[i].qualityFlag = 1;
        sensorDataArray[i].identifier = identifiers[i];
    }

    // Initialize the count
    sensorDataCount = numSensors;
}

void addSensorData(double temperature, int qualityFlag) {
    // Check for duplicate data entries by identifier
    int found = 0;
    for (int i = 0; i < sensorDataCount; i++) {
        if (sensorDataArray[i].identifier == qualityFlag) {
            found = 1;
            break;
        }
    }

    if (!found) {
        // Allocate memory and initialize a new SensorData structure
        SensorData* newData = malloc(sizeof(SensorData));
        newData->temperature = temperature;
        newData->timestamp = time(NULL);
        newData->qualityFlag = qualityFlag;
        newData->identifier = qualityFlag;

        // Add the new data to the array
        sensorDataArray = realloc(sensorDataArray, (sensorDataCount + 1) * sizeof(SensorData));
        sensorDataArray[sensorDataCount].temperature = temperature;
        sensorDataArray[sensorDataCount].timestamp = time(NULL);
        sensorDataArray[sensorDataCount].qualityFlag = qualityFlag;
        sensorDataArray[sensorDataCount++].identifier = qualityFlag;

        // Free the memory
        free(newData);
    }
}

void logSensorData() {
    for (int i = 0; i < sensorDataCount; i++) {
        printf("Temperature: %f, Timestamp: %ld, Quality Flag: %d, Identifier: %d\n",
               sensorDataArray[i].temperature, sensorDataArray[i].timestamp, sensorDataArray[i].qualityFlag, sensorDataArray[i].identifier);
    }
}

void freeSensorData() {
    for (int i = 0; i < sensorDataCount; i++) {
        free(&sensorDataArray[i]);
    }

    free(sensorDataArray);

    // Free the offsetValues and identifiers arrays
    free(offsetValues);
    free(identifiers);
}
