typedef struct {
    double num;
    char* str;
} MyStruct;

MyStruct* allocate_struct_array(int size) {
    srand(time(NULL));

    int min_len = 5; // adjust the minimum length of alphanumeric strings
    int max_len = 15; // adjust the maximum length of alphanumeric strings

    MyStruct* arr = (MyStruct*)malloc(size * sizeof(MyStruct));

    for (int i = 0; i < size; i++) {
        char* str = (char*)malloc((rand() % (max_len - min_len + 1)) + min_len);

        for (int j = 0; j < rand() % (max_len - min_len + 1) + min_len; j++) {
            if (j % 2 == 0) {
                str[j] = (rand() % 26) + 'a'; // generate lowercase letters
            } else {
                str[j] = (rand() % 26) + 'A' || (rand() % 10) + '0'; // generate uppercase letters, digits
            }
        }

        arr[i].num = (double)i; // assign random numbers to the structure fields

        arr[i].str = str;
    }

    return arr;
}

void deallocate_struct_array(MyStruct* arr, int size) {
    for (int i = 0; i < size; i++) {
        free(arr[i].str);
    }

    free(arr);
}
