#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define RECORD_SIZE (sizeof(record_t))
#define LOG_FILE_MAX_SIZE 1024
#define MAX_RECORDS 1000
#define LOCK_SCOPE 1 // Fine-grained locking scope: thread-level
#define FLUSH_INTERVAL 10 // Flush records every 10 seconds

// Record structure
typedef struct {
    int value;
    char status;
    double timestamp;
} record_t;

// Logging function
void *logging_function(void *arg) {
    // Allocate memory for the dynamic array of records
    record_t **records = (record_t **)malloc(MAX_RECORDS * sizeof(record_t *));
    if (!records) {
        fprintf(stderr, "Memory allocation failure.\n");
        return NULL;
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // Initialize mutex

    int record_count = 0;

    while (1) {
        // Acquire the lock
        pthread_mutex_lock(&lock);

        // Allocate memory for a new record
        record_t *new_record = (record_t *)malloc(RECORD_SIZE);
        if (!new_record) {
            fprintf(stderr, "Memory allocation failure.\n");
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        // Initialize the record structure
        new_record->value = 1;
        new_record->status = 'A';
        new_record->timestamp = time(NULL);

        // Add the record to the array
        records[record_count++] = new_record;

        // Release the lock
        pthread_mutex_unlock(&lock);

        // Periodically flush the log file
        if (record_count % FLUSH_INTERVAL == 0) {
            FILE *log_file = fopen("log.txt", "a");
            if (!log_file) {
                fprintf(stderr, "Error opening log file.\n");
                continue;
            }

            for (int i = 0; i < record_count; i++) {
                fwrite(records[i], RECORD_SIZE, 1, log_file);
            }

            fclose(log_file);
        }
    }

    // Free allocated memory
    for (int i = 0; i < record_count; i++) {
        free(records[i]);
    }
    free(records);

    return NULL;
}

int main() {
    pthread_t thread;

    if (pthread_create(&thread, NULL, &logging_function, NULL)) {
        fprintf(stderr, "Error creating thread.\n");
        return 1;
    }

    // Wait for the thread to finish
    pthread_join(thread, NULL);

    return 0;
}
