// Define the struct Record type
typedef struct {
    long* val;
    int key;
} Record;

// Function to generate random values for initialization
long rand_long() {
    static const unsigned int range = 2000000; // 2,000,000
    return (rand() % (range + 1)) - (range / 2);
}

int main() {
    srand(time(NULL)); // Initialize the random number generator

    int num_records = 10;
    Record* records = malloc(num_records * sizeof(Record));

    for (int i = 0; i < num_records; i++) {
        Record record;
        record.val = malloc(sizeof(long));
        *record.val = rand_long();
        record.key = rand() % 101; // Random value between 0 and 100

        records[i] = record;
    }

    // Validate initialization
    for (int i = 0; i < num_records; i++) {
        if (!records[i].val) {
            printf("Memory allocation failed at index %d\n", i);
            return -1;
        }
    }

    // Sort the records based on key values
    qsort(records, num_records, sizeof(Record), compareRecords);

    for (int i = 0; i < num_records; i++) {
        printf("Key: %d, Value: %ld\n", records[i].key, *records[i].val);
    }

    // Free dynamically allocated memory
    for (int i = 0; i < num_records; i++) {
        free(records[i].val);
    }
    free(records);

    return 0;
}

// Sorting function using qsort()
int compareRecords(const void* a, const void* b) {
    Record* record1 = *(Record*)a;
    Record* record2 = *(Record*)b;

    if (record1->key < record2->key) {
        return -1;
    } else if (record1->key > record2->key) {
        return 1;
    }
    return 0;
}
