// Function to manage a dynamic list of 'transaction' objects
int manage_transactions(int num_transactions) {
    Transaction* transactions = NULL;
    int error_code = 0;

    // Allocate memory for and initialize an array of transaction objects
    if ((transactions = (Transaction*)malloc(num_transactions * sizeof(Transaction))) == NULL) {
        error_code = 1; // Allocation failed
    } else {
        // Initialize the transactions array
        for (int i = 0; i < num_transactions; i++) {
            transactions[i].timestamp = 0;
            transactions[i].transaction_id = 0;
            strcpy(transactions[i].type, "");
            transactions[i].amount = 0.0;
        }
    }

    return error_code;
