#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define RECORD_SIZE 24 // long + int + float + timestamp
#define BLOCK_SIZE 4096
#define MAX_RECORDS_PER_MINUTE 10000000
#define THREAD_SAFE_RW_MUTEX pthread_mutex_t

typedef struct {
    long offset;
    int key;
    float weight;
    time_t timestamp;
} Record;

Record* recordPool = NULL; // cache of recently accessed records
int recordPoolSize = 0; // number of cached records
pthread_mutex_t recordPoolMutex = PTHREAD_MUTEX_INITIALIZER;

// Custom binary format for recording data
void writeRecord(FILE* file, Record* record) {
    fwrite(&record->offset, sizeof(long), 1, file);
    fwrite(&record->key, sizeof(int), 1, file);
    fwrite(&record->weight, sizeof(float), 1, file);
    fwrite(&record->timestamp, sizeof(time_t), 1, file);
}

void* writeThread(void* arg) {
    int* threadID = (int*)arg;
    FILE* file = fopen("dataset.bin", "wb");
    if (!file) {
        return NULL; // handle memory allocation failure
    }

    pthread_mutex_lock(&recordPoolMutex);

    Record* record = recordPool;
    for (int i = 0; i < *threadID * BLOCK_SIZE && i < recordPoolSize; i++) {
        writeRecord(file, &record[i]);
        record++;
    }

    pthread_mutex_unlock(&recordPoolMutex);
    fclose(file);
    return NULL;
}

void recordWrite(int threadCount) {
    int recordsPerThread = MAX_RECORDS_PER_MINUTE / threadCount;
    for (int i = 0; i < threadCount; i++) {
        pthread_t thread;
        int* arg = malloc(sizeof(int));
        *arg = i;
        pthread_create(&thread, NULL, writeThread, (void*)arg);
        pthread_join(thread, NULL);
        free(arg);
    }
}

// Function to manage the dynamic dataset
int recordWriteFunc(Record* records, int size) {
    if (!records) {
        return -1; // handle invalid input
    }

    pthread_mutex_init(&recordPoolMutex, NULL);

    for (int i = 0; i < size; i++) {
        Record* record = &records[i];
        writeRecord(stdout, record); // write to stdout for testing purposes
    }

    int threadCount = (size + BLOCK_SIZE - 1) / BLOCK_SIZE;
    recordWrite(threadCount);

    return 0;
}

int main() {
    // Example usage:
    Record records[1000000]; // create a large dataset
    int size = sizeof(records) / sizeof(Record);
    recordWriteFunc(records, size); // write the dataset using multiple threads

    return 0;
}
