    int num_elements;
    element_t** elements;
} data_set_t;

// Initialize data set
data_set_t* data_set_init(int num_elements) {
    data_set_t* ds = (data_set_t*)malloc(sizeof(data_set_t));
    ds->num_elements = num_elements;
    ds->elements = (element_t**)malloc(num_elements * sizeof(element_t*));
    return ds;
}

// Free data set
void data_set_free(data_set_t* ds) {
    for (int i = 0; i < ds->num_elements; i++) {
        free(ds->elements[i]->label);
        free(ds->elements[i]);
    }
    free(ds->elements);
    free(ds);
}

// Allocate and deallocate memory for arrays
void* allocate_array(size_t size, int num_elements) {
    return malloc(num_elements * size);
}
void deallocate_array(void* ptr, size_t size, int num_elements) {
    free(ptr);
}

