#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>

typedef struct {
    long offset;
    int key;
    float weight;
    time_t timestamp;
} Record;

int create_records(int num_records) {
    srand(time(NULL));

    // Allocate memory for arrays
    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));
    float* weights = (float*)malloc(num_records * sizeof(float));
    Record* records = (Record*)malloc(num_records * sizeof(Record));

    // Initialize arrays
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % 10000;
        keys[i] = rand() % 100;
        weights[i] = (float)rand() / RAND_MAX;

        time_t timestamp = time(NULL);
        records[i].offset = offsets[i];
        records[i].key = keys[i];
        records[i].weight = weights[i];
        records[i].timestamp = timestamp;
    }

    // Store records in a file
    int fd = open("records.bin", O_CREAT | O_RDWR, S_IRUSR | S_IWUSR);
    if (fd == -1) {
        free(offsets);
        free(keys);
        free(weights);
        free(records);
        return -1; // Error allocating memory for file
    }

    void* map = mmap(NULL, num_records * sizeof(Record), PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (map == MAP_FAILED) {
        close(fd);
        free(offsets);
        free(keys);
        free(weights);
        free(records);
        return -1; // Error mapping file
    }

    for (int i = 0; i < num_records; i++) {
        memcpy((char*)map + i * sizeof(Record), &records[i], sizeof(Record));
    }

    munmap(map, num_records * sizeof(Record));
    close(fd);

    free(offsets);
    free(keys);
    free(weights);
    free(records);

    return 0;
}
