// 3. Persistence

#include <sqlite3.h>

int save_data(sqlite3 *db, MyData* data) {
    sqlite3_stmt *stmt;
    const char *query = "INSERT INTO my_table (value, id) VALUES (?, ?)";
    int rc;

    // Bind the values and execute the query
    rc = sqlite3_prepare_v2(db, query, -1, &stmt, NULL);
    if (rc != SQLITE_OK) {
        printf("Error preparing SQL statement: %s\n", sqlite3_errmsg(db));
        return 1;
    }

    for (int i = 0; i < sizeof(data) / sizeof(data[0]); i++) {
        // Bind the values
        sqlite3_bind_float(stmt, 1, data[i].value);
        sqlite3_bind_text(stmt, 2, data[i].id, -1, SQLITE_STATIC);

        // Execute the query
        rc = sqlite3_step(stmt);
        if (rc != SQLITE_DONE) {
            printf("Error executing SQL statement: %s\n", sqlite3_errmsg(db));
            return 1;
        }
    }

    // Clean up
    sqlite3_finalize(stmt);
    return 0;
}

