    for(int i=0; i<5; i++) {
        if(i % 2 == 0) {
            // heap allocation for even-numbered stages
            engine_config* config = (struct engine_config*)malloc(sizeof(struct engine_config));
            stages[i]->config = config;
        } else {
            // stack allocation for odd-numbered stages
            struct engine_config config;
            stages[i]->config = &config;
        }
    }

    free(pool);
