    int value;
} Record;

OffsetRecord* allocateOffsetRecords(int numRecords) {
    OffsetRecord* records = (OffsetRecord*)malloc(numRecords * sizeof(OffsetRecord));
    if (!records) {
        printf("Memory allocation failed for offset records.\n");
        return NULL;
    }
    for (int i = 0; i < numRecords; i++) {
        records[i].offset = 0;
    }
    return records;
}

KeyRecord* allocateKeyRecords(int numRecords) {
    KeyRecord* records = (KeyRecord*)malloc(numRecords * sizeof(KeyRecord));
    if (!records) {
        printf("Memory allocation failed for key records.\n");
        return NULL;
    }
    int startKey = 1;
    for (int i = 0; i < numRecords; i++) {
        records[i].key = startKey + i;
    }
    return records;
}

Record* allocateRandomUniqueRecords(int numRecords, int minValue, int maxValue) {
    Record* records = (Record*)malloc(numRecords * sizeof(Record));
    if (!records) {
        printf("Memory allocation failed for random unique records.\n");
        return NULL;
    }
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        int value = rand() % (maxValue - minValue + 1) + minValue;
        // Check if the value is already allocated
        while (records[i].value != -1 && records[i].value == value) {
            value = rand() % (maxValue - minValue + 1) + minValue;
        }
        records[i].value = value;
    }
    return records;
}

void freeMemory(OffsetRecord* offsetRecords, int numOffsetRecords,
                KeyRecord* keyRecords, int numKeyRecords,
                Record* randomUniqueRecords, int numRandomUniqueRecords) {
    if (offsetRecords) {
        free(offsetRecords);
    }
    if (keyRecords) {
        free(keyRecords);
    }
