#include <time.h>

// Define record structure with timestamp field
typedef struct {
    int value;
    long* offsets;
    int* keys;
    time_t timestamp;
} Record;

// Function to allocate and initialize a dynamically sized array of record structures
Record** initRecords(int capacity) {
    Record** records = (Record**)malloc(capacity * sizeof(Record*));
    for (int i = 0; i < capacity; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
        records[i]->value = rand() % 1000 + 1;
        records[i]->offsets = (long*)malloc(5000 * sizeof(long));
        records[i]->keys = (int*)malloc(5000 * sizeof(int));
        for (int j = 0; j < 5000; j++) {
            records[i]->offsets[j] = j;
            records[i]->keys[j] = j + 1;
        }
        records[i]->timestamp = time(NULL);
    }
    return records;
}

// Function to update timestamp for a specific record based on its key
void updateTimestamp(Record** records, int capacity, int key) {
    for (int i = 0; i < capacity; i++) {
        if (records[i]->keys[0] == key) {
            records[i]->timestamp = time(NULL);
            return;
        }
    }
    // Update default timestamp
    for (int i = 0; i < capacity; i++) {
        records[i]->timestamp = time(NULL);
    }
}

// Function to serialize the records to disk
void serializeRecords(Record** records, int capacity) {
    FILE* file = fopen("records.bin", "wb");
    if (!file) {
        printf("Error opening file\n");
        return;
    }
    for (int i = 0; i < capacity; i++) {
        fwrite(&records[i]->value, sizeof(int), 1, file);
        fwrite(records[i]->offsets, sizeof(long), 5000, file);
        fwrite(records[i]->keys, sizeof(int), 5000, file);
    }
    fclose(file);
}

int main() {
    int capacity = 100;
    Record** records = initRecords(capacity);
    for (int i = 0; i < capacity; i++) {
        printf("Record %d: value=%d, timestamp=%ld\n", i, records[i]->value, records[i]->timestamp);
    }
    updateTimestamp(records, capacity, 500);
    serializeRecords(records, capacity);
    return 0;
}
