use reqwest;
use tokio::time;

struct HttpClient {
    timeout: time::Duration,
    backoff_strategy: Box<dyn Fn() -> time::Duration>,
    max_retries: u32,
}

impl HttpClient {
    async fn new(timeout: time::Duration, backoff_strategy: Box<dyn Fn() -> time::Duration>, max_retries: u32) -> Self {
        HttpClient { timeout, backoff_strategy, max_retries }
    }

    async fn send_request(&self, url: &str) -> reqwest::Response {
        let mut retries = 0;
        loop {
            match reqwest::get(url).timeout(self.timeout).send().await {
                Ok(response) => return response,
                Err(e) if retries < self.max_retries => {
                    retries += 1;
                    tokio::time::sleep(self.backoff_strategy()).await;
                }
                _ => return reqwest::Response::default(),
            }
        }
    }
}
