#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <time.h>

// Configuration parameters
#define MAX_RECORDS 10000
#define RECORD_VALUE_RANGE 100
#define SEED 42

typedef struct {
    int value;
} record_t;

record_t* records = NULL;
int* keys = NULL;
long* offsets = NULL;

void* thread_function(void* arg) {
    // Generate a random key and find the corresponding offset
    int key = rand() % MAX_RECORDS;
    long offset = keys[key];

    // Check if the record already exists at this offset
    bool found = false;
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (offsets[i] == offset) {
            found = true;
            break;
        }
    }

    if (!found) {
        // Allocate a new record and initialize its value
        record_t* new_record = malloc(sizeof(record_t));
        new_record->value = rand() % RECORD_VALUE_RANGE;

        // Store the new record at the given offset
        offsets[key] = (long) records + key;
        records[key] = *new_record;
        free(new_record);
    }

    return NULL;
}

void init_records(int num_threads) {
    // Allocate memory for arrays
    records = malloc(MAX_RECORDS * sizeof(record_t));
    keys = malloc(MAX_RECORDS * sizeof(int));
    offsets = malloc(MAX_RECORDS * sizeof(long));

    if (!records || !keys || !offsets) {
        printf("Memory allocation failed\n");
        exit(-1);
    }

    // Initialize random seed
    srand(SEED);

    // Initialize arrays with zeros
    for (int i = 0; i < MAX_RECORDS; i++) {
        keys[i] = i;
        records[i].value = 0;
        offsets[i] = -1;
    }
}

void* log_thread(void* arg) {
    FILE* log_file = fopen("log.txt", "w");

    pthread_mutex_lock(&mutex);
    // Write logs to file
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (offsets[i] != -1) {
            fprintf(log_file, "Offset: %ld, Key: %d, Value: %d\n", offsets[i], keys[i], records[i].value);
        }
    }

    pthread_mutex_unlock(&mutex);

    fclose(log_file);
    return NULL;
}

int main() {
    // Initialize arrays
    init_records(4);

    // Create threads for concurrent access
    pthread_t threads[4];
    for (int i = 0; i < 4; i++) {
        pthread_create(&threads[i], NULL, thread_function, NULL);
    }

    // Wait for threads to finish
    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }

    // Log the results
    pthread_t log_thread_id;
    pthread_create(&log_thread_id, NULL, log_thread, NULL);
    pthread_join(log_thread_id, NULL);

    return 0;
}
