#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int id;
    int priority;
    char status[10];
} task;

typedef struct {
    int taskId;
    dependency* next;
} dependency;

task* tasks = NULL;
int taskCount = 0;
dependency* dependencies = NULL;
int dependencyCount = 0;

// Function to dynamically allocate and initialize an array of 'task' structures
task* allocateTasks(int count) {
    if (count <= 0) return NULL;

    task* newTasks = (task*)malloc(count * sizeof(task));
    for (int i = 0; i < count; i++) {
        newTasks[i].id = i + 1;
        strcpy(newTasks[i].status, "not started");
    }

    return newTasks;
}

// Function to dynamically allocate and initialize a linked list of 'dependency' structures
dependency* allocateDependencies(int count) {
    if (count <= 0) return NULL;

    dependency* newDependencies = (dependency*)malloc(count * sizeof(dependency));
    for (int i = 0; i < count; i++) {
        newDependencies[i].taskId = i + 1;
        newDependencies[i].next = &newDependencies[i];
    }

    return newDependencies;
}

// Function to persist tasks and dependencies in a file
void persistTasksAndDependencies() {
    FILE* file = fopen("tasks.txt", "w");
    if (file) {
        for (int i = 0; i < taskCount; i++) {
            fprintf(file, "%d: %s\n", tasks[i].id, tasks[i].status);
        }
        fclose(file);
    } else {
        printf("Error opening file.\n");
    }
}

// Function to load tasks and dependencies from a file
void loadTasksAndDependencies() {
    FILE* file = fopen("tasks.txt", "r");
    if (file) {
        char line[100];
        while (fgets(line, sizeof(line), file)) {
            int id;
            sscanf(line, "%d: %s\n", &id, tasks[id-1].status);
        }
        fclose(file);
    } else {
        printf("Error opening file.\n");
    }
}

// Function to manage memory allocation failures gracefully
void* allocateMemory(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        free(ptr);
        return NULL;
    }

    return ptr;
}

int main() {
    // Initialize tasks and dependencies
    tasks = allocateTasks(10);
    dependencies = allocateDependencies(5);

    // Load tasks and dependencies from file (if available)
    loadTasksAndDependencies();

    // Persist tasks and dependencies to file
    persistTasksAndDependencies();

    return 0;
}
