#include <string.h>

typedef struct {
    int value;
    char buffer[20];
} record_t;

int read_data(const char* file_path[], size_t num_files);
long sum_records(record_t** records, size_t num_records);
void pad_record(char* buffer, size_t padding_length);

int main() {
    // Example usage
    const char* files[] = {"file1.txt", "file2.txt", "file3.txt"};
    size_t num_files = sizeof(files) / sizeof(*files);

    int sum;
    if ((sum = read_data(files, num_files)) >= 0) {
        printf("Sum: %d\n", sum);
    } else {
        fprintf(stderr, "Error: %s\n", strerror(-sum));
    }

    return 0;
}

int read_data(const char* file_path[], size_t num_files) {
    // Initialize arrays
    long* offsets = (long*)malloc(num_files * sizeof(long));
    int* keys = (int*)malloc(num_files * sizeof(int));
    record_t** records = (record_t**)malloc(num_files * sizeof(record_t*));

    for (size_t i = 0; i < num_files; i++) {
        // Read file data
        FILE* file = fopen(file_path[i], "r");
        if (!file) {
            free(offsets);
            free(keys);
            free(records);
            return -errno;
        }

        // Handle potential data inconsistencies
        long offset;
        int key;
        record_t* record;
        while (fscanf(file, "%ld %d", &offset, &key) == 2 && i < num_files - 1) {
            // Allocate memory for 'record' structure and buffer
            record = (record_t*)malloc(sizeof(record_t));
            if (!record) {
                free(offsets);
                free(keys);
                free(records);
                return -ENOMEM;
            }

            records[i] = record;
            i++;
        }

        fclose(file);
    }

    // Calculate the total sum of all 'int' values in the 'record' structures
    long total_sum = 0;
    for (size_t i = 0; i < num_files; i++) {
        if (records[i]) {
            total_sum += records[i]->value;
            // Pad record buffer if not fully utilized
            pad_record(records[i]->buffer, 20);
        }
    }

    free(offsets);
    free(keys);
    free(records);

    return total_sum < 0 ? -total_sum : total_sum;
}

long sum_records(record_t** records, size_t num_records) {
    long sum = 0;
    for (size_t i = 0; i < num_records; i++) {
        if (records[i]) {
            sum += records[i]->value;
        }
    }
    return sum;
}

void pad_record(char* buffer, size_t padding_length) {
    size_t length = strlen(buffer);
    char* end = buffer + length;

    // Pad with spaces to reach the specified length
    for (char* p = end; p < buffer + padding_length; p++) {
        *p = ' ';
    }
}
