#include <stdlib.h>
#include <string.h>

typedef struct {
    long offset;
    int key;
    unsigned char* byte_array;
} data_block;

void* init_data_block(size_t initial_capacity) {
    size_t total_size = sizeof(data_block) + initial_capacity;
    void* mem = malloc(total_size);
    if (!mem) return NULL;

    data_block* block = mem;
    block->offset = 0;
    block->key = 0;
    block->byte_array = (unsigned char*)(((char*)block) + sizeof(data_block));
    return block;
}

void resize_data_block(void** block, size_t new_capacity) {
    data_block* old_block = *block;
    if (!old_block) return;

    size_t total_size = sizeof(data_block) + new_capacity;
    void* mem = realloc(old_block, total_size);
    if (!mem) {
        free(old_block);
        *block = NULL;
        return;
    }

    data_block* new_block = mem;
    memcpy(new_block, old_block, sizeof(data_block));
    new_block->byte_array = (unsigned char*)(((char*)new_block) + sizeof(data_block));

    free(old_block);
    *block = new_block;
}

void free_data_block(void** block) {
    data_block* block_ptr = *block;
    if (!block_ptr) return;

    free(block_ptr);
    *block = NULL;
}
