use reqwest::blocking::{get, post};
use tokio::sync::{mpsc, oneshot};
use std::time::{Duration, Instant};

struct HttpClient {
    timeout: Duration,
    backoff_strategy: Box<dyn Fn(Instant) -> (Duration, bool)>,
}

impl HttpClient {
    fn new(timeout: Duration, backoff_strategy: Box<dyn Fn(Instant) -> (Duration, bool)>) -> Self {
        HttpClient { timeout, backoff_strategy }
    }

    async fn get(&self, url: &str) -> Result<String, reqwest::Error> {
        let start = Instant::now();
        let response = get(url).timeout(self.timeout).send().await;
        if response.is_err() {
            let retry_time = self.backoff_strategy(start);
            tokio::time::sleep(retry_time).await;
            self.get(url).await
        } else {
            response.map(|res| res.text()).map_err(reqwest::Error::new)
        }
    }

    async fn post(&self, url: &str) -> Result<String, reqwest::Error> {
        // ...
    }
}
