void* allocate_memory(int size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }
    return ptr;
}

Node* init_node() {
    Node* node = allocate_memory(sizeof(Node));
    srand(time(NULL));
    node->value = rand() % 1000;
    strcpy(node->identifier, "node_");
    int i;
    for (i = 0; i < 5; i++) {
        char c = 'a' + rand() % 26;
        strcat(node->identifier, &c);
    }
    node->next = NULL;
    return node;
}

CacheEntry* init_cache_entry() {
    CacheEntry* entry = allocate_memory(sizeof(CacheEntry));
    entry->key = rand() % 1000;
    entry->node = init_node();
    entry->timestamp = time(NULL) + (rand() % 3600);
    return entry;
}

