    // Initialize entry values with random double values
    for (int i = 0; i < num_entries; i++) {
        srand(time(NULL));
        entries[i].value = (double)srand();
    }
}

// Function to integrate with external data source and handle asynchronous updates
void update_entry_data(entry* entries, int num_entries) {
    // Simulate receiving new keys from the external data source in batches
    for (int i = 0; i < num_entries; i++) {
        char key[key_length + 1];
        // Receive new key from data source and assign to entry structure
        strcpy(entries[i].key, key);
    }
}

