#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <sys/mman.h>
#include <pthread.h>

// Define the structure for an entry
typedef struct {
    char* key;
    double value;
} entry_t;

// Define the structure for the array and its metadata
typedef struct {
    int capacity;
    int size;
    entry_t** entries;
    pthread_mutex_t lock;
} array_t;

// Initialize and populate the array with user-specified strings and random double values
void* initialize_array(int capacity) {
    array_t* arr = (array_t*)malloc(sizeof(array_t));
    arr->capacity = capacity;
    arr->size = 0;
    arr->entries = (entry_t**)calloc(capacity, sizeof(entry_t*));

    pthread_mutex_init(&arr->lock, NULL);

    return arr;
}

// Free the allocated memory
void free_array(array_t* arr) {
    for (int i = 0; i < arr->size; i++) {
        free(arr->entries[i]->key);
        free((char*) &arr->entries[i]);
    }

    free(arr->entries);
    free(arr);
}

// Allocate a new entry and add it to the array
void* add_entry(array_t* arr, char* key, double value) {
    pthread_mutex_lock(&arr->lock);

    if (arr->size >= arr->capacity) {
        printf("Array is full. Cannot add more entries.\n");
        pthread_mutex_unlock(&arr->lock);
        return NULL;
    }

    entry_t* new_entry = (entry_t*)malloc(sizeof(entry_t));
    new_entry->key = strdup(key);
    new_entry->value = value;

    arr->entries[arr->size++] = new_entry;

    pthread_mutex_unlock(&arr->lock);

    return new_entry;
}

// Print the contents of the array
void print_array(array_t* arr) {
    for (int i = 0; i < arr->size; i++) {
        printf("Key: %s, Value: %.2f\n", arr->entries[i]->key, arr->entries[i]->value);
    }
}

// Define a cache to store recently allocated entries
typedef struct {
    int capacity;
    entry_t** cache;
} cache_t;

// Initialize the cache
void* initialize_cache(int capacity) {
    cache_t* cache = (cache_t*)malloc(sizeof(cache_t));
    cache->capacity = capacity;
    cache->cache = (entry_t**)calloc(capacity, sizeof(entry_t*));

    return cache;
}

// Add an entry to the cache
void add_to_cache(cache_t* cache, entry_t* entry) {
    for (int i = 0; i < cache->capacity; i++) {
        if (cache->cache[i] == NULL) {
            cache->cache[i] = entry;
            return;
        }
    }
}

// Free the allocated memory in the cache
void free_cache(cache_t* cache) {
    for (int i = 0; i < cache->capacity; i++) {
        if (cache->cache[i] != NULL) {
            free((char*) &cache->cache[i]);
        }
    }

    free(cache);
}

// Define a logging mechanism to track memory usage and allocation patterns
void log_memory(array_t* arr, cache_t* cache) {
    // Log the size of the array and cache
    printf("Array size: %d, Cache size: %d\n", arr->size, cache->capacity);

    // Log the memory usage of each entry in the array
    for (int i = 0; i < arr->size; i++) {
        printf("Entry %d: Key - %s, Value - %.2f, Memory Usage - %zu bytes\n", i, arr->entries[i]->key, arr->entries[i]->value, sizeof(entry_t));
    }

    // Log the memory usage of each entry in the cache
    for (int i = 0; i < cache->capacity; i++) {
        if (cache->cache[i] != NULL) {
            printf("Cache Entry %d: Key - %s, Value - %.2f, Memory Usage - %zu bytes\n", i, cache->cache[i]->key, cache->cache[i]->value, sizeof(entry_t));
        }
    }
}

int main() {
    // Initialize the array and cache
    array_t* arr = initialize_array(10);
    cache_t* cache = initialize_cache(5);

    // Add entries to the array and cache
    add_entry(arr, "Entry 1", 10.0);
    add_entry(arr, "Entry 2", 20.0);
    add_to_cache(cache, arr->entries[0]);

    // Print the contents of the array and cache
    print_array(arr);
    printf("Cache:\n");
    for (int i = 0; i < cache->capacity; i++) {
        if (cache->cache[i] != NULL) {
            printf("Key: %s, Value: %.2f\n", cache->cache[i]->key, cache->cache[i]->value);
        }
    }

    // Log the memory usage and allocation patterns
    log_memory(arr, cache);

    // Free the allocated memory
    free_array(arr);
    free_cache(cache);

    return 0;
}

