#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define structure for 'entry'
typedef struct {
    char* key;
    double value;
    void* metadata;
} entry;

// Function to dynamically manage memory for an array of 'entry' structures
int manageMemory(int numEntries, int maxKeyLength, int minVal, int maxVal) {
    // Initialize variables
    int i, j, err;
    srand(time(NULL));  // Seed random number generator

    // Allocate memory for the main array
    entry** entries = (entry**)malloc(numEntries * sizeof(entry*));
    if (!entries) {
        printf("Error: Failed to allocate memory for 'entries' array.\n");
        return -1;
    }

    // Initialize metadata index array
    void** metaIndices = (void**)calloc(numEntries, sizeof(void*));
    if (!metaIndices) {
        printf("Error: Failed to allocate memory for 'metaIndices' array.\n");
        free(entries);
        return -1;
    }

    // Allocate memory for each entry's metadata index
    for (i = 0; i < numEntries; i++) {
        metaIndices[i] = (void*)malloc(sizeof(int));
        if (!metaIndices[i]) {
            printf("Error: Failed to allocate memory for 'metadata' pointer.\n");
            err = -1;
            break;
        }
    }

    // Initialize key and value arrays
    char** keys = (char**)calloc(numEntries, sizeof(char*));
    double* values = (double*)malloc(numEntries * sizeof(double));

    if (!keys || !values) {
        printf("Error: Failed to allocate memory for 'keys' and 'values' arrays.\n");
        err = -1;
        free(entries);
        free(metaIndices);
    }

    // Initialize entries with random keys and values
    for (i = 0; i < numEntries; i++) {
        int keyLen = rand() % maxKeyLength + 1;
        char* tempKey = (char*)malloc(keyLen * sizeof(char));
        sprintf(tempKey, "Entry-%d", i);
        keys[i] = tempKey;

        values[i] = ((double)rand() / RAND_MAX) * (maxVal - minVal) + minVal;
    }

    // Assign metadata indices to each entry
    for (i = 0; i < numEntries; i++) {
        *(int*)metaIndices[i] = i;
    }

    // Free allocated memory upon completion or error
    if (!err) {
        free(entries);
        free(metaIndices);
        free(keys);
        free(values);
    } else {
        printf("Error: Unable to manage memory for array of 'entry' structures.\n");
    }

    return err;
}

int main() {
    int numEntries = 10000, maxKeyLength = 16, minVal = 0.0, maxVal = 10.0;

    int result = manageMemory(numEntries, maxKeyLength, minVal, maxVal);

    if (result == -1) {
        printf("Failed to manage memory.\n");
    } else {
        printf("Memory managed successfully.\n");
    }

    return 0;
}
