typedef struct {
    int num;
    double dbl;
    char *id;
} record;

record *allocateRecords(int size, int num_range, int max_id_len) {
    record *records = (record *)malloc(sizeof(record) * size);
    for (int i = 0; i < size; i++) {
        records[i].num = rand() % num_range;
        records[i].dbl = (double)(rand()) / RAND_MAX;
        char id[16];
        sprintf(id, "Record-%d", i);
        records[i].id = (char *)malloc(strlen(id) + 1);
        strcpy(records[i].id, id);
    }
    return records;
}

void serializeRecords(record *records, int size, FILE *fp) {
    for (int i = 0; i < size; i++) {
        fwrite(&records[i], sizeof(record), 1, fp);
    }
}

int main() {
    srand(time(NULL));
    const int RECORDS_SIZE = 100;
    const int NUM_RANGE = 100;
    const int MAX_ID_LEN = 16;

    record *records = allocateRecords(RECORDS_SIZE, NUM_RANGE, MAX_ID_LEN);

    // Open file for writing
    int fd = open("records.dat", O_RDWR | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR);
    if (fd == -1) {
        printf("Error opening file.\n");
        return 1;
    }

    FILE *fp = fdopen(fd, "wb");

    serializeRecords(records, RECORDS_SIZE, fp);

    // Close file
    fclose(fp);
    close(fd);

    // Free allocated memory
    for (int i = 0; i < RECORDS_SIZE; i++) {
        free(records[i].id);
    }
    free(records);

    return 0;
}

