['Here is the C code for a distributed hash table (DHT) supporting a cluster of nodes:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

typedef struct node {
    int id;
    void* memory;
    int available_memory;
} Node;

typedef struct key_value_pair {
    char* key;
    int value;
    struct key_value_pair* next;
} KeyValuePair;

typedef struct hash_table {
    int size;
    Node** nodes;
    int num_nodes;
} HashTable;

// Custom hash function
int custom_hash(char* key, int size) {
    int hash = 0;
    for (int i = 0; i < strlen(key); i++) {
        hash += key[i];
    }
    return hash % size;
}

// Create a new node with the given ID and memory allocation
Node* create_node(int id, int memory_size) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->id = id;
    node->memory = malloc(memory_size);
    node->available_memory = memory_size;
    return node;
}

// Create a new key-value pair with the given key and value
KeyValuePair* create_key_value_pair(char* key, int value) {
    KeyValuePair* pair = (KeyValuePair*)malloc(sizeof(KeyValuePair));
    pair->key = strdup(key);
    pair->value = value;
    pair->next = NULL;
    return pair;
}

// Initialize a new hash table with the given number of nodes
HashTable* create_hash_table(int num_nodes, int size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->size = size;
    table->nodes = (Node**)malloc(num_nodes * sizeof(Node*));
    for (int i = 0; i < num_nodes; i++) {
        table->nodes[i] = create_node(i, size);
    }
    table->num_nodes = num_nodes;
    return table;
}

// Add a key-value pair to the hash table
void add_to_hash_table(HashTable* table, char* key, int value) {
    int hash = custom_hash(key, table->size);
    Node* node = table->nodes[hash % table->num_nodes];
    KeyValuePair* pair = create_key_value_pair(key, value);
    if (node->memory == NULL) {
        // Handle collision by chaining
        pair->next = node->memory;
        node->memory = pair;
    } else {
        // Insert into existing linked list
        pair->next = node->memory;
        node->memory = pair;
    }
}

// Query the hash table for a key-value pair
int query_hash_table(HashTable* table, char* key) {
    int hash = custom_hash(key, table->size);
    Node* node = table->nodes[hash % table->num_nodes];
    KeyValuePair* pair = node->memory;
    while (pair != NULL) {
        if (strcmp(pair->key, key) == 0) {
            return pair->value;
        }
        pair = pair->next;
    }
    return -1; // Not found
}

// Remove a key-value pair from the hash table
void remove_from_hash_table(HashTable* table, char* key) {
    int hash = custom_hash(key, table->size);
    Node* node = table->nodes[hash % table->num_nodes];
    KeyValuePair* pair = node->memory;
    while (pair != NULL) {
        if (strcmp(pair->key, key) == 0) {
            node->memory = pair->next;
            free(pair->key);
            free(pair);
            return;
        }
        pair = pair->next;
    }
}
