['Here is the C code for the distributed hash table (DHT):

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Custom hash function
unsigned int custom_hash(const char* key, int key_len) {
    unsigned int hash = 0;
    for (int i = 0; i < key_len; i++) {
        hash = (hash << 4) ^ ((unsigned int)key[i]);
    }
    return hash % 10000; // Assuming a maximum table size of 10,000 slots
}

// Structure to represent a node in the DHT
typedef struct Node {
    char* key;
    int value;
    struct Node* next; // Linked list for collision resolution
} Node;

// Function to allocate memory and initialize a new node
Node* create_node(const char* key, int value) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->key = strdup(key);
    node->value = value;
    node->next = NULL;
    return node;
}

// Function to dynamically allocate memory for the DHT
void* dht_alloc(int size) {
    void* ptr = malloc(size);
    if (!ptr) {
        printf("Memory allocation failed.\n");
        exit(1);
    }
    return ptr;
}

// Function to insert a key-value pair into the DHT
int insert(const char* key, int value) {
    // Calculate the hash value for the given key
    unsigned int hash = custom_hash(key, strlen(key));

    // Initialize the current node and the collision list
    Node* curr_node = NULL;
    Node* head = NULL;

    // Traverse the DHT to find the corresponding slot or handle collisions
    for (int i = 0; i < 10000; i++) {
        if (!curr_node) { // If this is the first node in the chain
            head = curr_node = create_node(NULL, 0);
        } else {
            curr_node->next = create_node(NULL, 0);
            curr_node = curr_node->next;
        }
        if (i == hash) break; // Found the correct slot or handled collision
    }

    // Insert the key-value pair into the found slot or collision list
    Node* node = create_node(key, value);
    node->next = curr_node->next;
    curr_node->next = node;

    return 0;
}

// Function to retrieve a value from the DHT given a key
int get(const char* key) {
    // Calculate the hash value for the given key
    unsigned int hash = custom_hash(key, strlen(key));

    // Traverse the DHT to find the corresponding slot or handle collisions
    Node* curr_node = NULL;
    for (int i = 0; i < 10000; i++) {
        if (!curr_node) { // If this is the first node in the chain
            curr_node = head;
        } else {
            curr_node = curr_node->next;
        }
        if (i == hash) break; // Found the correct slot or handled collision
    }

    // Return the value associated with the given key
    while (curr_node) {
        if (!strcmp(curr_node->key, key)) return curr_node->value;
        curr_node = curr_node->next;
    }
    return -1; // Key not found in the DHT
}

// Function to free dynamically allocated memory for the DHT
void dht_free() {
    Node* node = head;
    while (node) {
        Node* next = node->next;
        free(node);
        node = next;
    }
}
