['Here is the C function that manages memory allocation and initialization for multiple data structures under strict performance and resource constraints:
```c
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

#define RECORD_SIZE sizeof(record_t)

struct record {
    int value;
    long offset;
    size_t ref_count;
    time_t timestamp;
};

void* mempool_init(size_t N) {
    void* base = malloc(N * (sizeof(long) + sizeof(int)) + N * RECORD_SIZE);
    if (!base) return NULL;

    long* offsets = (long*) ((char*) base);
    int* keys = (int*) ((char*) base + N * sizeof(long));
    struct record* records = (struct record*) ((char*) base + N * (sizeof(long) + sizeof(int)));

    for (size_t i = 0; i < N; i++) {
        offsets[i] = 0;
        keys[i] = 0;
        records[i].value = 0;
        records[i].offset = 0;
        records[i].ref_count = 1;
        records[i].timestamp = time(NULL);
    }

    return base;
}

void mempool_reset(void* mempool, size_t N) {
    long* offsets = (long*) ((char*) mempool + N * sizeof(long));
    int* keys = (int*) ((char*) mempool + 2 * N * sizeof(int));
    struct record* records = (struct record*) ((char*) mempool + 3 * N * (sizeof(long) + sizeof(int)));

    for (size_t i = 0; i < N; i++) {
        offsets[i] = 0;
        keys[i] = 0;
        if (records[i].ref_count > 1) {
            // Decrement reference count and mark for deletion
            records[i].ref_count--;
        }
    }
}

void* mempool_set_record(void* mempool, size_t N, int min_value, int max_value) {
    struct record* records = (struct record*) ((char*) mempool + 3 * N * (sizeof(long) + sizeof(int)));

    for (size_t i = 0; i < N; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    return mempool;
}

void* mempool_get_record(void* mempool, size_t index) {
    struct record* records = (struct record*) ((char*) mempool + 3 * N * (sizeof(long) + sizeof(int)));

    if (index >= N) return NULL;

    return &records[index];
}
