// Define the log_entry structure
typedef struct {
    time_t timestamp;
    int status_code;
    char* message;
} log_entry;

// Function to initialize and manage an array of log entries
void init_log_array(log_entry** log_entries, int num_entries) {
    // Initialize the random seed for generating random messages
    srand(time(NULL));

    // Allocate memory for each log entry
    *log_entries = (log_entry*)malloc(num_entries * sizeof(log_entry));

    // Initialize and assign random values to timestamp, status_code, and message for each log entry
    for(int i=0; i<num_entries; i++) {
        (*log_entries)[i].timestamp = time(NULL);
        (*log_entries)[i].status_code = rand() % 100;

        // Generate a random message of length between 10 and 50 characters
        int message_len = rand() % 40 + 10;
        char* message = (char*)malloc(message_len * sizeof(char));
        for(int j=0; j<message_len; j++) {
            message[j] = (rand() % 26) + 'a';
        }
        message[message_len-1] = '\0';

        (*log_entries)[i].message = message;
    }
}

// Function to add a new log entry
void add_log_entry(log_entry** log_entries, int* num_entries, char* message) {
    // Check if there is enough space left in the array
    if(*num_entries >= sizeof(log_entry) / sizeof(log_entry[0])) {
        printf("Array full. Cannot add more entries.\n");
        return;
    }

    // Allocate memory for the new log entry
    (*log_entries)[*num_entries].timestamp = time(NULL);
    (*log_entries)[*num_entries].status_code = 0;

    int message_len = strlen(message) + 1; // +1 for null terminator
    char* temp_message = (char*)malloc(message_len * sizeof(char));
    strcpy(temp_message, message); // copy the message

    (*log_entries)[*num_entries].message = temp_message;
    (*num_entries)++;
}

// Function to remove a log entry
void remove_log_entry(log_entry** log_entries, int* num_entries) {
    if(*num_entries <= 0) {
        printf("Array empty. Cannot remove entries.\n");
        return;
    }

    // Deallocate memory for the removed log entry
    free((*log_entries)[--*num_entries].message);
}

// Function to print all log entries in the array
void print_log_entries(log_entry* log_entries, int num_entries) {
    for(int i=0; i<num_entries; i++) {
        printf("Timestamp: %ld, Status Code: %d, Message: %s\n", 
               (long)log_entries[i].timestamp, log_entries[i].status_code, 
               log_entries[i].message);
    }
}

int main() {
    int num_entries = 10;
    log_entry* log_entries;

    init_log_array(&log_entries, num_entries);

    add_log_entry(&log_entries, &num_entries, "This is a test message");
    add_log_entry(&log_entries, &num_entries, "Another test message");

    print_log_entries(log_entries, num_entries);

    remove_log_entry(&log_entries, &num_entries);

    print_log_entries(log_entries, num_entries);
}
```']

