// Allocate memory for and initialize an array of records with random values
Record* allocate_records(int numRecords) {
    Record* records = (Record*)malloc(numRecords * sizeof(Record));
    if (!records) return NULL;  // Handle allocation failure

    srand(time(NULL));  // Seed random number generator

    for (int i = 0; i < numRecords; i++) {
        Record record;
        record.i = rand() % 100;  // Random integer within range [0, 99]
        record.d = (double)rand() / RAND_MAX;  // Random double within range [0.0, 1.0]
        record.id = (char*)malloc(32 * sizeof(char));  // Dynamically allocate space for ID
        sprintf(record.id, "Record-%d", i);  // Initialize unique identifier

        records[i] = record;
    }

    return records;
}

// Serialize and store records in a file using custom serialization format
void serialize_records(const Record* records, int numRecords) {
    FILE* file = fopen("records.dat", "wb");  // Open file for binary write
    if (!file) {
        printf("Error opening file.\n");
        return;  // Handle error
    }

    fwrite(&numRecords, sizeof(int), 1, file);  // Write record count to file

    for (int i = 0; i < numRecords; i++) {
        Record record = records[i];
        fwrite(&record.i, sizeof(int), 1, file);  // Write integer field
        fwrite(&record.d, sizeof(double), 1, file);  // Write double field
        size_t idLen = strlen(record.id);
        fwrite(&idLen, sizeof(size_t), 1, file);  // Write ID length to file
        fwrite(record.id, sizeof(char), idLen + 1, file);  // Write unique identifier
    }

    fclose(file);
}

// Load records from a file using custom serialization format
Record* deserialize_records() {
    FILE* file = fopen("records.dat", "rb");  // Open file for binary read
