    for (int i = 0; i < numRecords; i++) {
        Record record;
        fread(&record.i, sizeof(int), 1, file);  // Read integer field
        fread(&record.d, sizeof(double), 1, file);  // Read double field
        size_t idLen;
        fread(&idLen, sizeof(size_t), 1, file);  // Read ID length from file
        record.id = (char*)malloc((idLen + 1) * sizeof(char));  // Allocate space for ID
        fread(record.id, sizeof(char), idLen + 1, file);  // Read unique identifier

        records[i] = record;
    }

    fclose(file);
    return records;
}

// Define a thread-safe mechanism to manage concurrent access and serialization
void* threadsafe_serialize(void* arg) {
    Record* records = (Record*)arg;

    // Acquire lock for synchronization
    pthread_mutex_lock(&lock);

    serialize_records(records, 10);  // Serialize and store records

