#include <stdio.h>
#include <stdlib.h>
#include <math.h>

typedef struct {
    double d;
    char *s;
    struct element *e;
    struct nested_element *ne;
} data_set;

typedef struct {
    float f;
    char *id;
} struct element;

typedef struct {
    struct element *e;
    char **ids;
} struct nested_element;

data_set* allocate_data_set(int size) {
    data_set *data = (data_set *)malloc(sizeof(data_set));
    if (!data) return NULL;

    data->d = 0.0; // Initialize with default value
    data->s = (char *)malloc(10); // Allocate space for string
    if (!data->s) {
        free(data);
        return NULL;
    }
    strcpy(data->s, "default_string");

    data->e = (struct element *)malloc(sizeof(struct element));
    if (!data->e) {
        free(data->s);
        free(data);
        return NULL;
    }

    data->ne = (struct nested_element *)malloc(sizeof(struct nested_element));
    if (!data->ne) {
        free(data->s);
        free(data->e);
        free(data);
        return NULL;
    }

    // Initialize other fields
    data->e->f = 0.5; // Random float value
    data->e->id = (char *)malloc(10); // Allocate space for string
    if (!data->e->id) {
        free(data->s);
        free(data->e);
        free(data);
        return NULL;
    }
    sprintf(data->e->id, "random_id");

    // Initialize nested element fields
    data->ne->e = (struct element *)malloc(sizeof(struct element));
    if (!data->ne->e) {
        free(data->s);
        free(data->e);
        free(data);
        return NULL;
    }

    data->ne->ids = (char **)malloc(size * sizeof(char *));
    if (!data->ne->ids) {
        free(data->s);
        free(data->e);
        free(data);
        return NULL;
    }
    for (int i = 0; i < size; i++) {
        data->ne->ids[i] = (char *)malloc(10); // Allocate space for string
        if (!data->ne->ids[i]) {
            for (int j = i - 1; j >= 0; j--) {
                free(data->ne->ids[j]);
            }
            free(data->s);
            free(data->e);
            free(data);
            return NULL;
        }
    }

    // Initialize other fields
    data->ne->e->f = 0.25; // Random float value
    for (int i = 0; i < size; i++) {
        sprintf(data->ne->ids[i], "random_id_%d", i);
    }

    return data;
}

void free_data_set(data_set *data) {
    if (!data) return;

    free(data->s);
    free(data->e);
    free(data->ne);

    for (int i = 0; i < strlen(data->ne->ids); i++) {
        free(data->ne->ids[i]);
    }
}

